///
/// # Arguments
///
/// * `mapping`: A mapping of identifiers to sequences of numeric values.
///
/// # Returns
///
/// A new mapping that associates each identifier with the sum of its sequence of values.
pub fn compute_sequence_sums(mapping: HashMap<String, Vec<f64>>) -> HashMap<String, f64> {
    let mut result = HashMap::new();

    for (identifier, sequence) in mapping {
        let sum: f64 = sequence.into_iter().sum();
        result.insert(identifier, sum);
    }

