/// map1.insert("b", 3);
/// map1.insert("c", 4);
/// 
/// let common = common_keys(&map0, &map1);
/// assert_eq!(common, vec!["b"]);
/// ```
pub fn common_keys<K: Hash + Eq + Clone>(map0: &HashMap<K, ()>, map1: &HashMap<K, ()>) -> Vec<K> {
