use polars::prelude::*;
use chrono::NaiveDate;

/// Filter df0 to rows where column `var0` is between `date0` and `date1` (inclusive).
///
/// - `df`: input DataFrame (df0)
/// - `var0`: name of the column containing date strings
/// - `date0`, `date1`: inclusive bounds as strings
/// - `fmt`: strptime format for parsing the column and bounds (e.g. "%Y-%m-%d")
///
/// Returns a new DataFrame containing only the rows that satisfy date0 <= var0 <= date1.
///
/// Notes:
/// - This implementation assumes `var0` is a UTF8 (string) column with parsable dates.
/// - Rows with missing/invalid dates are treated as not matching (i.e., dropped).
pub fn filter_between_dates(
    df: &DataFrame,
    var0: &str,
    date0: &str,
    date1: &str,
    fmt: &str,
) -> PolarsResult<DataFrame> {
    // Ensure the column exists and is a UTF8 column
    let col = df.column(var0)?;
    let utf8_col = col.utf8().map_err(|_| {
        PolarsError::ComputeError(
            format!("Column '{}' must be UTF8 (string) containing date strings", var0).into(),
        )
    })?;

    // Parse the boundary dates once
    let d0 = NaiveDate::parse_from_str(date0, fmt).map_err(|e| {
        PolarsError::ComputeError(format!("Failed to parse date0 ('{}'): {}", date0, e).into())
    })?;
    let d1 = NaiveDate::parse_from_str(date1, fmt).map_err(|e| {
        PolarsError::ComputeError(format!("Failed to parse date1 ('{}'): {}", date1, e).into())
    })?;

    // Build a Vec<Option<bool>> mask: Some(true) for rows within range, Some(false) for rows outside,
    // and None for original nulls (we treat nulls as not matching by mapping to Some(false)).
    let mask_vec: Vec<Option<bool>> = utf8_col.into_iter().map(|opt_s| {
        match opt_s {
            Some(s) => {
                match NaiveDate::parse_from_str(s, fmt) {
                    Ok(d) => Some(d >= d0 && d <= d1),
                    // If a particular cell fails to parse, treat as not matching
                    Err(_) => Some(false),
                }
            }
            // preserve null as Some(false) to drop it; if you prefer to keep nulls, change to None
            None => Some(false),
        }
    }).collect();

    // Create a boolean Series from the mask and filter the dataframe
    let mask_series = Series::new("__date_mask", mask_vec);
    let mask_bool = mask_series.bool().ok_or_else(|| {
        PolarsError::ComputeError("Failed to construct boolean mask series".into())
    })?;

    df.filter(mask_bool)
}

