use polars::prelude::*;

/// Compute the average of the values in `df` for the specified column indices `col_indices`
/// and row indices `row_indices`.
///
/// - Ignores nulls and non-numeric values (but attempts to parse strings as f64).
/// - Booleans are treated as 1.0 (true) and 0.0 (false).
/// - Returns Ok(f64) with NaN if there are no numeric values in the selection.
/// - Returns Err(PolarsError) if a supplied row/column index is out of bounds.
pub fn average_over_selection(
    df: &DataFrame,
    col_indices: &[usize],
    row_indices: &[usize],
) -> Result<f64, PolarsError> {
    // Quick bounds checks
    let n_rows = df.height();
    let n_cols = df.width();

    for &c in col_indices {
        if c >= n_cols {
            return Err(PolarsError::ComputeError(
                format!("column index {} out of bounds (width={})", c, n_cols).into(),
            ));
        }
    }
    for &r in row_indices {
        if r >= n_rows {
            return Err(PolarsError::ComputeError(
                format!("row index {} out of bounds (height={})", r, n_rows).into(),
            ));
        }
    }

    let mut sum = 0f64;
    let mut count = 0usize;

    for &c in col_indices {
        let series = df.select_at_idx(c).expect("checked bounds above");

        for &r in row_indices {
            match series.get(r) {
                Some(av) => {
                    match av {
                        AnyValue::Null => { /* skip */ }
                        AnyValue::Int8(v) => { sum += v as f64; count += 1; }
                        AnyValue::Int16(v) => { sum += v as f64; count += 1; }
                        AnyValue::Int32(v) => { sum += v as f64; count += 1; }
                        AnyValue::Int64(v) => { sum += v as f64; count += 1; }
                        AnyValue::UInt8(v) => { sum += v as f64; count += 1; }
                        AnyValue::UInt16(v) => { sum += v as f64; count += 1; }
                        AnyValue::UInt32(v) => { sum += v as f64; count += 1; }
                        AnyValue::UInt64(v) => { sum += v as f64; count += 1; }
                        AnyValue::Float32(v) => { sum += v as f64; count += 1; }
                        AnyValue::Float64(v) => { sum += v; count += 1; }
                        AnyValue::Boolean(b) => { sum += if b { 1.0 } else { 0.0 }; count += 1; }
                        AnyValue::Utf8(s) => {
                            if let Ok(parsed) = s.parse::<f64>() {
                                sum += parsed;
                                count += 1;
                            }
                            // otherwise skip non-parsable strings
                        }
                        AnyValue::Utf8Owned(s) => {
                            if let Ok(parsed) = s.parse::<f64>() {
                                sum += parsed;
                                count += 1;
                            }
                        }
                        // For other types (e.g., List, Object), skip
                        _ => {}
                    }
                }
                None => { /* shouldn't happen with bounds checked, but skip if it does */ }
            }
        }
    }

    if count == 0 {
        Ok(f64::NAN)
    } else {
        Ok(sum / (count as f64))
    }
}

fn main() -> PolarsResult<()> {
