/// let rows = vec![0, 1, 3];
/// let columns = vec!["A", "B"];
/// let avg = compute_average(&df, rows, columns)?;
/// println!("Average: {}", avg);
/// ```
fn compute_average(
    df: &DataFrame,
    rows: Vec<usize>,
    columns: Vec<&str>,
) -> PolarsResult<f64> {
    // Filter the DataFrame to include only specified columns
    let selected = df.select(columns)?;

    // Filter to include only specified rows
    let indices = rows.iter().map(|&i| i as u32).collect::<Vec<_>>();
    let filtered = selected.filter(&Series::new("", &indices).cast(&DataType::UInt32)?)?;

    // Compute mean for all numeric columns and calculate overall average
    let mut sum = 0.0;
    let mut count = 0usize;

    for series in filtered.iter() {
        if let Ok(ca) = series.f64() {
            sum += ca.mean().unwrap_or(0.0) * ca.len() as f64;
            count += ca.len();
        } else if let Ok(ca) = series.i64() {
            let values: Vec<f64> = ca.iter().map(|opt| opt.unwrap_or(0) as f64).collect();
            sum += values.iter().sum::<f64>();
            count += values.len();
        }
    }

    Ok(if count > 0 { sum / count as f64 } else { 0.0 })
}

