```

Rust code:
```rust
use regex::Regex;

/// Return a Vec<char> containing every character that immediately follows a '/' in `input`.
///
/// Example:
/// let input: Vec<char> = "/a/bc/".chars().collect();
/// assert_eq!(following_chars(&input), vec!['a', 'b']);
pub fn following_chars(input: &[char]) -> Vec<char> {
    // Build a String from the char slice.
    let s: String = input.iter().copied().collect();

    // (?s) makes '.' match newline as well; we want the literal "next character" regardless.
    let re = Regex::new(r"(?s)/(.)").expect("regex is valid");

    re.captures_iter(&s)
        .map(|cap| cap[1].chars().next().unwrap()) // capture group 1 contains the single char
        .collect()
}

fn main() {
    let input: Vec<char> = "/a/bc/\n/x".chars().collect();
    let result = following_chars(&input);
    println!("{:?}", result); // prints: ['a', 'b', '\n', 'x']
}
```

Notes:
- The function takes &[char] and returns Vec<char>.
- It skips slashes that are at the end of the input (no following character).
- Using the regex crate lets us concisely find "/" followed by any character (including newline via (?s)). If you prefer not to use regex, an equally simple and faster approach is to iterate the slice and collect the next element when you see '/'.

