use itertools::Itertools; // Ensure you have itertools as a dependency in your Cargo.toml
use std::collections::HashMap;

/// Groups a list of two-element items by their first component.
///
/// # Arguments
///
/// * `items` - A slice of tuples, where each tuple contains two elements.
///
/// # Returns
///
/// A HashMap where the keys are unique first elements and the values are vectors containing the corresponding second elements.
fn group_by_first_component<T: Eq + std::hash::Hash, U>(
    items: &[(T, U)],
) -> HashMap<T, Vec<U>> {
    items.iter().fold(HashMap::new(), |mut acc, (first, second)| {
        acc.entry(first.clone()).or_insert_with(Vec::new).push(second.clone());
        acc
    })
}

fn main() {
    let items = vec![
        ("apple", 1),
        ("banana", 2),
        ("apple", 3),
        ("banana", 4),
        ("orange", 5),
    ];

    let grouped = group_by_first_component(&items);

    // Displaying the result
    for (key, value) in grouped {
        println!("{:?}: {:?}", key, value);
    }
}
```

