use itertools::Itertools;
use std::collections::HashMap;

/// Groups a list of two-element tuples by their first component.
/// 
/// Takes a vector of tuples where each tuple has two elements, and produces
/// a HashMap mapping each unique first element to a vector of corresponding
/// second elements.
/// 
/// # Example
/// ```
/// let items = vec![
///     ("fruit", "apple"),
///     ("vegetable", "carrot"),
///     ("fruit", "banana"),
///     ("vegetable", "broccoli"),
///     ("fruit", "orange"),
/// ];
/// 
/// let result = group_by_first(items);
/// 
/// assert_eq!(result.get("fruit"), Some(&vec!["apple", "banana", "orange"]));
/// assert_eq!(result.get("vegetable"), Some(&vec!["carrot", "broccoli"]));
/// ```
fn group_by_first<K, V>(items: Vec<(K, V)>) -> HashMap<K, Vec<V>>
where
    K: Eq + std::hash::Hash + Clone,
    V: Clone,
{
    items
        .into_iter()
        .into_group_map_by(|(key, _)| key.clone())
        .into_iter()
        .map(|(key, group)| (key, group.into_iter().map(|(_, value)| value).collect()))
        .collect()
}

fn main() {
    let items = vec![
        ("fruit", "apple"),
        ("vegetable", "carrot"),
        ("fruit", "banana"),
        ("vegetable", "broccoli"),
        ("fruit", "orange"),
    ];

    let result = group_by_first(items);

    println!("Grouped items:");
    for (key, values) in &result {
        println!("  {}: {:?}", key, values);
    }

    // Output:
    // Grouped items:
    //   fruit: ["apple", "banana", "orange"]
    //   vegetable: ["carrot", "broccoli"]
