use ndarray::{Array, ArrayD, IxDyn};

/// Remove every `var0`-th element (1-based) from `arr0` along axis `var1`.
///
/// - arr0: input n-dimensional array (ArrayD)
/// - var0: step (every var0-th element is removed). Must be >= 1.
/// - var1: axis index along which removal happens (0-based).
///
/// Returns a new ArrayD with the specified elements removed.
pub fn delete_every_kth<T: Clone>(arr0: &ArrayD<T>, var0: usize, var1: usize) -> ArrayD<T> {
    assert!(var0 >= 1, "var0 must be >= 1");
    let ndim = arr0.ndim();
    assert!(var1 < ndim, "var1 (axis) out of range");

    // If array is empty along that axis, just clone and return
    let shape = arr0.shape().to_vec();
    let len_along = shape[var1];
    if len_along == 0 {
        return arr0.clone();
    }

    // Calculate new length along the axis after removal
    let removed_per_axis = len_along / var0;
    let new_len = len_along - removed_per_axis;

    // Permute axes so that var1 becomes the last axis.
    // This makes it easy to treat the array as shape (other_count, len_along).
    let mut perm: Vec<usize> = (0..ndim).filter(|&i| i != var1).collect();
    perm.push(var1);

    let permuted = arr0.view().permuted_axes(perm.clone());
    let other_count = permuted.len() / len_along;
    // reshape to 2D view: (other_count, len_along)
    let reshaped = permuted
        .into_shape((other_count, len_along))
        .expect("reshape to (other_count, len_along) should succeed");

    // Collect filtered rows into a single Vec (row-major w.r.t permuted axes).
    let mut out_vec: Vec<T> = Vec::with_capacity(other_count * new_len);
    for row in reshaped.outer_iter() {
        for (i, item) in row.iter().enumerate() {
            // Keep elements whose 1-based position is not a multiple of var0
            if (i + 1) % var0 == 0 {
                continue;
            }
            out_vec.push(item.clone());
        }
    }

    // Build new shape for permuted array (same as reshaped shape but last dim -> new_len)
    let mut permuted_new_shape = reshaped.shape().to_vec();
    permuted_new_shape[1] = new_len;

    // Create an ArrayD that has the permuted axes ordering
    let arr_permuted =
        Array::from_shape_vec(IxDyn(&permuted_new_shape), out_vec).expect("shape/vec size mismatch");

    // Invert the permutation to restore original axis order
    let mut inv_perm = vec![0usize; ndim];
    for (i, &p) in perm.iter().enumerate() {
        inv_perm[p] = i;
    }

    arr_permuted.permuted_axes(inv_perm)
}

fn main() {
    // Example usage
    use ndarray::array;

    // 2x7 example: remove every 3rd element along axis 1
    let a: ArrayD<i32> = array![[1, 2, 3, 4, 5, 6, 7], [10, 11, 12, 13, 14, 15, 16]].into_dyn();
