fn reorder_rows_by_name(df: &DataFrame, order: &[&str]) -> Result<DataFrame> {
    // Ensure the name column exists
    let name_col = df.column("name")?;

    // Create a mapping for the intended order
    let order_map: HashMap<_, _> = order.iter().enumerate().map(|(idx, &name)| (name, idx)).collect();

    // Create a rank vector based on the order
    let mut ranks: Vec<Option<usize>> = Vec::with_capacity(name_col.len());

