use polars::prelude::*;
use std::collections::HashMap;

/// Reorder rows of `df` according to `order` applied to the `name_col`.
/// - Rows whose name is listed in `order` appear first in the same sequence as `order`.
/// - Rows with names not in `order` come after, preserving their original relative order.
/// - Nulls in the name column are treated as "not present in order" (so they go to the end).
///
/// Returns a new DataFrame with rows reordered.
fn reorder_by_name(
    df: &DataFrame,
    order: &[&str],
    name_col: &str,
) -> PolarsResult<DataFrame> {
    // Ensure the name column exists and is a Utf8 column (strings)
    let names = df.column(name_col)?.utf8()?;

    let n = df.height();
    // Map each ordered name -> its position index
    let mut order_map: HashMap<&str, usize> = HashMap::with_capacity(order.len());
    for (pos, &nm) in order.iter().enumerate() {
        order_map.insert(nm, pos);
    }

    // For each row, compute a sort-key:
    // - If name in order_map: key = position (small)
    // - Else: key = order.len() + original_row_index (so unlisted rows keep original relative order and come after ordered ones)
    let mut keys_and_indices: Vec<(usize, usize)> = Vec::with_capacity(n);
    for idx in 0..n {
        let pos = names.get(idx)
            .and_then(|s| order_map.get(s).copied())
            .unwrap_or(order.len() + idx);
        keys_and_indices.push((pos, idx));
    }

    // Sort by computed key (stable with respect to original index because keys include original index for unlisted names)
    keys_and_indices.sort_by_key(|(key, _idx)| *key);

    // Build an index vector and take rows in that order
    let take_idxs: Vec<u32> = keys_and_indices.into_iter().map(|(_k, idx)| idx as u32).collect();
    let idx_chunk = UInt32Chunked::new_from_slice("reorder_idx", &take_idxs);

    df.take(&idx_chunk)
}

fn main() -> PolarsResult<()> {
    // Example dataset
    let df = df![
        "name" => &["apple", "banana", "cherry", "date", "banana", "elderberry"],
        "value" => &[5, 3, 7, 2, 11, 1]
    ]?;

    // Desired order for names
    let order = ["banana", "date", "apple"];

    let reordered = reorder_by_name(&df, &order, "name")?;
    println!("{:?}", reordered);

    Ok(())
}
```

Behavior notes:
