use hashbrown::HashMap;
use std::hash::Hash;

/// Merges all key-value mappings from a list of maps into a single map.
/// If duplicate keys exist, the value from the later map in the list takes precedence.
///
/// # Arguments
/// * `lst0` - A slice of references to HashMaps to be merged
///
/// # Returns
/// A new HashMap containing all key-value pairs from all input maps
///
/// # Example
/// ```
/// use hashbrown::HashMap;
///
/// let map1: HashMap<&str, i32> = [("a", 1), ("b", 2)].into_iter().collect();
/// let map2: HashMap<&str, i32> = [("b", 3), ("c", 4)].into_iter().collect();
/// let lst0 = vec![&map1, &map2];
///
/// let merged = merge_maps(&lst0);
/// assert_eq!(merged.get("a"), Some(&1));
/// assert_eq!(merged.get("b"), Some(&3)); // Later value takes precedence
/// assert_eq!(merged.get("c"), Some(&4));
/// ```
pub fn merge_maps<K, V>(lst0: &[&HashMap<K, V>]) -> HashMap<K, V>
where
    K: Clone + Eq + Hash,
    V: Clone,
{
    let mut result = HashMap::new();

    for map in lst0 {
        for (key, value) in map.iter() {
            result.insert(key.clone(), value.clone());
        }
    }

    result
}

// Alternative version that takes ownership of the maps (if you prefer)
pub fn merge_maps_owned<K, V>(lst0: Vec<HashMap<K, V>>) -> HashMap<K, V>
where
    K: Eq + Hash,
    V: Clone,
{
    let mut result = HashMap::new();

    for map in lst0 {
        for (key, value) in map {
            result.insert(key, value);
        }
    }

    result
}

