use itertools::Itertools;
use std::collections::HashMap;

/// Merges all key-value mappings from a list of HashMaps into a single HashMap
/// 
/// # Arguments
/// * `lst0` - A list of HashMaps with String keys and values
/// 
/// # Returns
/// A single HashMap containing all merged key-value pairs
fn merge_mappings(lst0: Vec<HashMap<String, String>>) -> HashMap<String, String> {
    lst0.into_iter()
        .flat_map(|map| map.into_iter())
        .collect()
}

// Alternative implementation using a more functional approach
fn merge_mappings_alt(lst0: Vec<HashMap<String, String>>) -> HashMap<String, String> {
    lst0.into_iter()
        .flat_map(HashMap::into_iter)
        .into_group_map()
        .into_iter()
        .map(|(k, mut v)| (k, v.pop().unwrap()))
        .collect()
}

fn main() {
    // Example usage
    let map1: HashMap<String, String> = 
        [("a".to_string(), "1".to_string()), ("b".to_string(), "2".to_string())]
            .into_iter()
            .collect();

    let map2: HashMap<String, String> = 
        [("c".to_string(), "3".to_string()), ("d".to_string(), "4".to_string())]
            .into_iter()
            .collect();

    let map3: HashMap<String, String> = 
        [("e".to_string(), "5".to_string())]
            .into_iter()
            .collect();

    let lst0 = vec![map1, map2, map3];

    let merged = merge_mappings(lst0);

    println!("Merged mapping: {:?}", merged);
    // Output: Merged mapping: {"a": "1", "b": "2", "c": "3", "d": "4", "e": "5"}
}
