/// assert!(earliest.is_some());
/// assert!(latest.is_some());
/// ```
pub fn find_extreme_dates(df: &DataFrame) -> Result<(Option<DateTime<Utc>>, Option<DateTime<Utc>>), Box<dyn Error>> {
    // Check if the "Date" column exists
    if !df.column("Date").is_ok() {
        return Err("Column 'Date' not found in DataFrame".into());
    }

    // Convert the Date column to a datetime type
    let date_series = df.column("Date")?
        .utf8()?
        .into_datetime(chrono::format::Parsed, None)?;

