/// Finds the earliest and latest dates in the "Date" column of a DataFrame.
/// 
/// # Arguments
/// * `df0` - A reference to a Polars DataFrame containing a "Date" column
/// 
/// # Returns
/// * `Result<(NaiveDate, NaiveDate), PolarsError>` - A tuple of (earliest_date, latest_date)
/// 
/// # Panics
/// * If the "Date" column doesn't exist or contains non-date values
pub fn find_date_range(df0: &DataFrame) -> Result<(NaiveDate, NaiveDate), PolarsError> {
    // Ensure the "Date" column exists
    let date_col = df0.column("Date")?;

    // Convert to Date type if needed and get min/max
    let date_series = date_col.cast(&DataType::Date)?;

    let min_date = date_series.min::<NaiveDate>()
        .ok_or_else(|| PolarsError::ComputeError("Date column is empty".into()))?;

    let max_date = date_series.max::<NaiveDate>()
        .ok_or_else(|| PolarsError::ComputeError("Date column is empty".into()))?;

    Ok((min_date, max_date))
}

// Example usage:
fn main() -> Result<(), PolarsError> {
    // Create sample data
    let dates = df!(
        "Date" => &[
            "2024-01-15",
            "2024-03-20",
            "2024-01-01",
            "2024-12-31",
            "2024-06-15",
        ],
    )?;

    // Convert string dates to Date type
    let df0 = dates.lazy()
        .with_column(
            col("Date").str().to_date(StrptimeOptions::default())
        )
        .collect()?;

    // Find the date range
    let (earliest, latest) = find_date_range(&df0)?;

    println!("Earliest date: {}", earliest);
    println!("Latest date: {}", latest);

    Ok(())
}
