            [col("A"), col("B"), col("C_max").alias("C")],
            [col("A"), col("B"), col("C")],
            JoinType::Inner,
        )
        .select([
            col("A"),
            col("B"),
            col("C"),
            // Include any other columns from the original dataframe
            col("*").exclude(["A", "B", "C"]),
        ])
        .collect()?;

    Ok(result)
