use ndarray::{Array2, Axis};

/// Normalize each row of a 2D numeric table so each row sums to exactly 1.
///
/// - `input_data` is a slice of rows (Vec<f64> per row). All rows must have the same length.
/// - If a row's sum is zero, that row is replaced by a uniform distribution (1 / ncols each).
///
/// Returns an Array2<f64> with shape (nrows, ncols).
///
/// Panics if rows have inconsistent lengths.
pub fn normalize_rows(input_data: &[Vec<f64>]) -> Array2<f64> {
    let nrows = input_data.len();
    let ncols = if nrows == 0 {
        0
    } else {
        input_data[0].len()
    };

    // Check that all rows have the same length
    for row in input_data {
        if row.len() != ncols {
            panic!("All rows must have the same number of columns");
        }
    }

    // Flatten the input into a single Vec<f64> in row-major order
    let mut flat: Vec<f64> = Vec::with_capacity(nrows * ncols);
    for row in input_data {
        flat.extend_from_slice(row);
    }

    // Create ndarray Array2
    let mut arr = if nrows == 0 || ncols == 0 {
        Array2::zeros((nrows, ncols))
    } else {
        Array2::from_shape_vec((nrows, ncols), flat).expect("shape matches data length")
    };

    // Compute row sums and normalize each row in place
    for mut row_view in arr.axis_iter_mut(Axis(0)) {
        let sum: f64 = row_view.sum();
        if sum == 0.0 {
            // Replace with uniform distribution so the row sums to 1
            if ncols > 0 {
                let val = 1.0 / (ncols as f64);
                for elem in row_view.iter_mut() {
                    *elem = val;
                }
            }
        } else {
            // Divide each element in the row by the sum
            row_view.mapv_inplace(|x| x / sum);
        }
    }

    arr
}

