        vec![0.0, 0.0, 0.0], // zero-sum row -> becomes uniform [1/3, 1/3, 1/3]
        vec![5.0, 5.0, 0.0],
    ];

    let normalized = normalize_rows(&input_data);
    println!("{:.6}", normalized); // each row will sum to 1.0
}

