///
/// # Errors
/// Returns an error if the DataFrames have incompatible schemas
pub fn append_and_reset_index(df1: DataFrame, df2: DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Append the DataFrames
    let combined = df1.lazy().union(df2.lazy())?.collect()?;

    // Reset the index to sequential integers starting from 0
    let df = combined.lazy().with_column(
        col("__index__")
            .cast(&DataType::Int64)
            .alias("__index__"),
