```rust
use polars::prelude::*;

/// Append `b` into `a` (a may be empty) and reset/create a row index column named `index_name`
/// that runs 0..(n_rows-1). Returns the new DataFrame.
///
/// Notes:
/// - If `a` has no columns (width == 0), this clones `b` and then adds the index column.
/// - If `a` and `b` have incompatible schemas, vstack will return an error.
pub fn append_and_reset_index(
    mut a: DataFrame,
    b: &DataFrame,
    index_name: &str,
) -> PolarsResult<DataFrame> {
    // If `a` is completely empty (no columns), take `b` as the base.
    // Otherwise, vertically stack b onto a (in-place).
    let mut out = if a.width() == 0 && a.height() == 0 {
        b.clone()
    } else {
        // vstack_mut requires schemas to match; use vstack (consumes/returns) here by using a temporary.
        a.vstack(b)?;
        a
    };

    // Create the sequential index 0,1,2,... as i64
    let n = out.height();
    let idx_vec: Vec<i64> = (0..n).map(|i| i as i64).collect();
    let idx_series = Series::new(index_name, idx_vec);

    // If an index column with that name already exists, drop it first to "reset" it.
    if out.find_idx_by_name(index_name).is_some() {
        out.drop_in_place(index_name)?;
    }

    // Add the new index column (appends to the right). Return the new DataFrame.
    out.with_column(idx_series)
}

