use itertools::Itertools; // For convenient iterator methods
use std::collections::HashMap;

fn unique_elements<T: Eq + std::hash::Hash + Clone>(elements: &[T]) -> Vec<T> {
    let mut counts = HashMap::new();

    // Count the occurrences of each element
    for element in elements {
        *counts.entry(element.clone()).or_insert(0) += 1;
    }

    // Filter elements that occur exactly once while preserving original order
    elements.iter()
        .filter_map(|element| {
            if counts[element] == 1 {
                Some(element.clone())
            } else {
                None
            }
        })
        .collect()
}

