use itertools::Itertools;
use std::collections::HashMap;

/// Returns a new list containing only elements that appear exactly once in the input,
/// preserving their original order.
///
/// # Arguments
/// * `input` - A slice of elements to filter
///
/// # Returns
/// * `Vec<T>` - A vector containing elements that appear exactly once, in original order
///
/// # Example
/// ```
/// let input = vec![1, 2, 3, 2, 4, 1, 5];
/// let result = unique_once(&input);
/// assert_eq!(result, vec![3, 4, 5]);
/// ```
pub fn unique_once<T: Clone + Eq + std::hash::Hash>(input: &[T]) -> Vec<T> {
    // Count occurrences of each element
    let counts: HashMap<&T, usize> = input.iter().fold(HashMap::new(), |mut acc, item| {
        *acc.entry(item).or_insert(0) += 1;
        acc
    });

    // Filter elements that appear exactly once, preserving order
    input
        .iter()
        .filter(|item| counts.get(item) == Some(&1))
        .cloned()
        .collect()
}

/// Alternative implementation using itertools for a more functional approach
pub fn unique_once_itertools<T: Clone + Eq + std::hash::Hash>(input: &[T]) -> Vec<T> {
    input
        .iter()
        .counts()  // Returns HashMap<&T, usize>
        .into_iter()
        .filter(|(_, count)| *count == 1)
        .map(|(item, _)| item.clone())
        .sorted_by(|a, b| {
            // Preserve original order by finding positions in input
            let pos_a = input.iter().position(|x| x == a).unwrap();
            let pos_b = input.iter().position(|x| x == b).unwrap();
            pos_a.cmp(&pos_b)
        })
        .collect()
}

