/// Assigns ranks to elements in a list based on their order of first appearance.
/// Elements with equal values receive the same rank.
/// The original list order is preserved.
///
/// # Arguments
/// * `lst0` - A slice of elements to rank
///
/// # Returns
/// A vector of ranks (1-based) corresponding to each element in the original list
///
/// # Example
/// ```
/// let items = vec![3, 1, 4, 1, 5, 9, 2, 6, 5, 3];
/// let ranks = assign_ranks(&items);
/// assert_eq!(ranks, vec![1, 2, 3, 2, 4, 5, 6, 7, 4, 1]);
/// ```
pub fn assign_ranks<T: Clone + std::hash::Hash + Eq>(lst0: &[T]) -> Vec<usize> {
    // Use IndexSet to track unique elements in order of first appearance
    let mut unique_elements: IndexSet<T> = IndexSet::new();

    // First pass: collect unique elements in order of appearance
    for item in lst0 {
        unique_elements.insert(item.clone());
    }

    // Create a mapping from element to its rank (1-based)
    let rank_map: std::collections::HashMap<&T, usize> = unique_elements
        .iter()
        .enumerate()
        .map(|(idx, item)| (item, idx + 1))
        .collect();

    // Second pass: assign ranks to each element in the original list
    lst0.iter()
        .map(|item| *rank_map.get(item).unwrap())
        .collect()
}

