fn rank_elements(lst0: Vec<f64>) -> Vec<usize> {
    let n = lst0.len();

    // Create indices paired with values
    let mut indexed: Vec<(usize, f64)> = lst0
        .iter()
        .enumerate()
        .map(|(i, &val)| (i, val))
        .collect();

    // Sort only once by values, keeping track of original indices
