## Alternative Version with Tie Handling (Average Rank)

```rust
fn rank_elements_avg_ties(lst0: Vec<f64>) -> Vec<f64> {
    let n = lst0.len();

    // Create indices paired with values
    let mut indexed: Vec<(usize, f64)> = lst0
        .iter()
        .enumerate()
        .map(|(i, &val)| (i, val))
        .collect();

    // Sort once
    indexed.sort_by(|a, b| {
        a.1.partial_cmp(&b.1)
            .unwrap_or(Ordering::Equal)
    });

    // Assign ranks with tie averaging
    let mut ranks = vec![0.0; n];
    let mut i = 0;

    while i < n {
        let mut j = i;
        // Find all equal values
        while j < n && indexed[j].1 == indexed[i].1 {
            j += 1;
        }

        // Average rank for this group
        let avg_rank = (i + j) as f64 / 2.0 + 0.5;

        for k in i..j {
            ranks[indexed[k].0] = avg_rank;
        }

        i = j;
    }

