/// Reorders a collection of items to match a specified sequence of identifiers.
///
/// This function takes a vector of items (each containing an identifier) and a
/// separate list of identifier values defining the desired order. Items not
/// present in the order list are appended at the end in their original relative order.
///
/// # Type Parameters
///
/// * `T` - The item type, must implement `Clone` and contain an identifier accessible via `AsRef`
/// * `Id` - The identifier type, must implement `Hash + Eq + Clone`
///
/// # Arguments
///
/// * `items` - A vector of items to reorder
/// * `order` - A slice of identifiers defining the desired sequence
///
/// # Returns
///
/// A new `Vec<T>` with items reordered according to the specified sequence
///
/// # Example
///
/// ```
/// use indexmap::IndexMap;
///
/// #[derive(Debug, Clone, PartialEq)]
/// struct Item {
///     id: u32,
///     name: String,
/// }
///
/// let items = vec![
///     Item { id: 3, name: "Charlie".to_string() },
///     Item { id: 1, name: "Alpha".to_string() },
///     Item { id: 2, name: "Bravo".to_string() },
///     Item { id: 4, name: "Delta".to_string() },
/// ];
///
/// let order = vec![1, 2, 3];
/// let reordered = reorder_by_id(items, &order);
///
/// assert_eq!(reordered[0].id, 1);
/// assert_eq!(reordered[1].id, 2);
/// assert_eq!(reordered[2].id, 3);
/// assert_eq!(reordered[3].id, 4); // Not in order, appended at end
/// ```
pub fn reorder_by_id<T, Id>(items: Vec<T>, order: &[Id]) -> Vec<T>
where
    T: Clone + AsRef<Id>,
    Id: Hash + Eq + Clone,
{
    // Build an IndexMap to preserve insertion order while allowing O(1) lookups
    let mut item_map: IndexMap<Id, Vec<T>> = IndexMap::new();

    // Group items by their identifier
    for item in items {
        let id = item.as_ref().clone();
        item_map.entry(id).or_default().push(item);
    }

    let mut result = Vec::with_capacity(item_map.len());

    // Add items in the specified order
    for id in order {
        if let Some(items_with_id) = item_map.remove(id) {
            result.extend(items_with_id);
        }
    }

    // Append remaining items (not in the order list) in their original relative order
    for (_, items_with_id) in item_map {
        result.extend(items_with_id);
    }

    result
}

