            Some(value) => {
                if let Ok(attr_value) = serde_json::from_value(value.clone()) {
                    attribute_values.push(attr_value);
                }
            }
            None => {
                eprintln!("Attribute '{}' not found in item", attr_name);
            }
        }
    }

    attribute_values
}

