use nalgebra::{DMatrix, DVector};

/// Sum the outer products of corresponding vectors in `a_seq` and `b_seq`.
///
/// Given sequences:
///   a_seq = [a1, a2, ..., ak] where each ai is a vector of length m
///   b_seq = [b1, b2, ..., bk] where each bi is a vector of length n
/// returns the m x n matrix:
///   sum_{i=1..k} (ai * bi^T)
///
/// Returns Err on shape mismatches.
pub fn sum_outer_products(
    a_seq: &[Vec<f64>],
    b_seq: &[Vec<f64>],
) -> Result<DMatrix<f64>, String> {
    if a_seq.len() != b_seq.len() {
        return Err("Input sequences must have the same number of vectors".into());
    }

    let k = a_seq.len();
    if k == 0 {
        // No pairs; return an empty 0x0 matrix
        return Ok(DMatrix::from_element(0, 0, 0.0));
    }

    let m = a_seq[0].len();
    let n = b_seq[0].len();

    // Ensure all a vectors have length m and all b vectors have length n
    for (i, v) in a_seq.iter().enumerate() {
        if v.len() != m {
            return Err(format!("All vectors in a_seq must have the same length; mismatch at index {}", i));
        }
    }
    for (i, v) in b_seq.iter().enumerate() {
        if v.len() != n {
            return Err(format!("All vectors in b_seq must have the same length; mismatch at index {}", i));
        }
    }

    let mut sum = DMatrix::zeros(m, n);

    for i in 0..k {
        let av = DVector::from_column_slice(&a_seq[i]);
        let bv = DVector::from_column_slice(&b_seq[i]);
        // outer product: DVector * DVector^T -> DMatrix
        let outer = &av * bv.transpose();
        sum += outer;
    }

    Ok(sum)
}

