/// Calculate the sum of outer products of corresponding pairs of lists.
///
/// Given two sequences of numeric lists of equal length, this function
/// computes the outer product of each pair of corresponding lists and
/// returns their element-wise sum.
///
/// # Arguments
///
/// * `seq1` - A slice of vectors representing the first sequence
/// * `seq2` - A slice of vectors representing the second sequence
///
/// # Returns
///
/// A 2D vector representing the sum of all outer products
///
/// # Panics
///
/// Panics if the sequences have different lengths or if any pair of
/// corresponding lists have different lengths.
///
/// # Example
///
/// ```
/// let a = vec![vec![1.0, 2.0], vec![3.0, 4.0]];
/// let b = vec![vec![5.0, 6.0], vec![7.0, 8.0]];
/// let result = sum_outer_products(&a, &b);
/// // result[0][0] = 1*5 + 3*7 = 26
/// // result[0][1] = 1*6 + 3*8 = 30
/// // result[1][0] = 2*5 + 4*7 = 38
/// // result[1][1] = 2*6 + 4*8 = 44
/// ```
pub fn sum_outer_products(seq1: &[Vec<f64>], seq2: &[Vec<f64>]) -> Vec<Vec<f64>> {
    assert_eq!(
        seq1.len(),
        seq2.len(),
        "Sequences must have the same length"
    );

    if seq1.is_empty() {
        return Vec::new();
    }

    // Determine dimensions from the first pair
    let n = seq1[0].len();
    let m = seq2[0].len();

    // Initialize result matrix with zeros
    let mut result = Array2::<f64>::zeros((n, m));

    // Accumulate outer products
    for (v1, v2) in seq1.iter().zip(seq2.iter()) {
        assert_eq!(
            v1.len(),
            n,
            "All vectors in seq1 must have the same length"
        );
        assert_eq!(
            v2.len(),
            m,
            "All vectors in seq2 must have the same length"
        );

        let arr1 = Array1::from_vec(v1.clone());
        let arr2 = Array1::from_vec(v2.clone());

        // Outer product: arr1 (n x 1) * arr2 (1 x m) = (n x m)
        result += &arr1.into_shape((n, 1)).unwrap() * &arr2.into_shape((1, m)).unwrap();
    }

    // Convert back to Vec<Vec<f64>>
    result.outer_iter().map(|row| row.to_vec()).collect()
}

