/// let lst0 = vec![1, 2, 6];
/// let lst1 = vec![1, 2, 3, 4, 5];
/// assert!(!is_subset(&lst0, &lst1));
/// ```
fn is_subset<T: Eq + std::hash::Hash>(lst0: &[T], lst1: &[T]) -> bool {
    let set1: HashSet<_> = lst1.iter().collect();
    lst0.iter().all(|item| set1.contains(item))
}

