    let lst1 = vec!["a", "b", "c", "d"];
    println!(
        "Is {:?} a subset of {:?}? {}",
        lst0,
        lst1,
        is_subset(&lst0, &lst1)
    );
    // Output: true

    // Example 4: empty set is a subset of any set
    let lst0: Vec<i32> = vec![];
    let lst1 = vec![1, 2, 3];
    println!(
        "Is {:?} a subset of {:?}? {}",
        lst0,
        lst1,
        is_subset(&lst0, &lst1)
    );
    // Output: true
}
```

## How It Works

