pub fn insert_column_at_position(
    df0: DataFrame,
    var0: usize,
    var1: &str,
    var2: Vec<i32>,
) -> Result<DataFrame, Box<dyn Error>> {
    // Validate position
    let num_cols = df0.width();
    if var0 > num_cols {
        return Err(format!(
            "Position {} is out of bounds. DataFrame has {} columns.",
            var0, num_cols
        )
        .into());
