use polars::prelude::*;
use std::collections::HashSet;

/// Converts categorical columns in a DataFrame to one-hot encoded binary columns
///
/// # Arguments
/// * `df` - Input DataFrame containing categorical columns to encode
/// * `categorical_cols` - Optional vector of column names to specifically encode.
///   If None, all categorical columns will be encoded.
///
/// # Returns
/// A new DataFrame with one-hot encoded columns replacing the original categorical columns
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df![
///     "category" => &["A", "B", "A", "C"],
///     "value" => &[1.0, 2.0, 3.0, 4.0]
/// ];
///
/// let encoded = one_hot_encode(&df, None).unwrap();
/// ```
pub fn one_hot_encode(df: &DataFrame, categorical_cols: Option<Vec<String>>) -> Result<DataFrame, PolarsError> {
    // Get all categorical columns if none specified
    let cols_to_encode = match categorical_cols {
        Some(cols) => cols,
        None => df
            .columns()
            .iter()
            .filter(|col| df.column(col.name())?.dtype() == &DataType::Categorical)
            .map(|col| col.name().to_string())
            .collect(),
    };

    if cols_to_encode.is_empty() {
        return Ok(df.clone());
    }

    // Create a new DataFrame builder
    let mut new_df = DataFrame::default_builder();

    // Copy all non-categorical columns as-is
    for col_name in df.columns() {
        if !cols_to_encode.contains(&col_name.name().to_string()) {
            new_df = new_df.with_column(df.column(col_name.name())?.clone());
        }
    }

    // Process each categorical column
    for col_name in cols_to_encode {
        let col = df.column(&col_name)?;
        let categorical = col.cast(&DataType::Categorical)?;

        // Get unique categories
        let categories = categorical
            .utf8()?
            .unique(true)?
            .into_iter()
            .map(|s| s.unwrap_or_default())
            .collect::<HashSet<_>>();

        // Create one-hot columns
        for (i, category) in categories.iter().enumerate() {
            let new_col_name = format!("{}_{}", col_name, category);
            let binary_col = categorical
                .utf8()?
                .eq(&category)?
                .cast(&DataType::Int64)?;

            new_df = new_df.with_column(binary_col.rename(&new_col_name)?);
        }
    }

    Ok(new_df.build()?)
}
