```rust
use polars::prelude::*;
use std::collections::HashSet;

/// Convert all columns containing discrete category labels into multiple binary integer columns.
/// 
/// This function identifies columns with string/categorical data and creates binary (0/1) 
/// indicator columns for each unique value in those columns. The original categorical columns 
/// are removed from the result.
///
/// # Arguments
/// * `df0` - Input DataFrame
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with categorical columns replaced by binary indicator columns
///
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "color" => &["red", "blue", "red", "green"],
///     "size" => &["small", "large", "medium", "small"],
///     "value" => &[1, 2, 3, 4]
/// ).unwrap();
///
/// let result = one_hot_encode_categoricals(df).unwrap();
/// println!("{:?}", result);
/// ```
pub fn one_hot_encode_categoricals(df0: DataFrame) -> PolarsResult<DataFrame> {
    let mut new_columns: Vec<Series> = Vec::new();
    let mut categorical_column_names: Vec<&str> = Vec::new();

    // First pass: identify categorical columns and collect their unique values
    for column_name in df0.get_column_names() {
        let series = df0.column(column_name)?;

        // Check if column contains string/categorical data
        if matches!(series.dtype(), DataType::String | DataType::Categorical(None, _)) {
            categorical_column_names.push(column_name);

            // Get unique values from this column
            let unique_values: Vec<String> = series
                .unique()?
                .str()?
                .into_iter()
                .flatten()
                .map(|s| s.to_string())
                .collect();

            // Create binary columns for each unique value
            for unique_value in &unique_values {
                let binary_series: Series = series
                    .str()?
                    .into_iter()
                    .map(|opt_val| {
                        match opt_val {
                            Some(val) if val == unique_value => 1i32,
                            _ => 0i32,
                        }
                    })
                    .collect::<Vec<i32>>()
                    .into_series();

                // Name the new column as "column_name_value"
                let new_column_name = format!("{}_{}", column_name, unique_value);
                let mut named_series = binary_series;
                named_series.rename(&new_column_name);
                new_columns.push(named_series);
            }
        }
    }

    // Add non-categorical columns to the result
    for column_name in df0.get_column_names() {
        if !categorical_column_names.contains(&column_name) {
            new_columns.push(df0.column(column_name)?.clone());
        }
    }

    // Construct the new DataFrame
    DataFrame::new(new_columns)
}

