# One-hot encoding using Polars (2024+)

```rust
use polars::prelude::*;

fn one_hot_encode(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut result = df.clone();

    // Get all column names to iterate over
    let col_names: Vec<String> = result
        .get_columns()
        .iter()
        .map(|s| s.name().to_string())
        .collect();

    for col_name in col_names {
        let col = result.column(&col_name)?;

        // Check if column is categorical/string type
        if matches!(col.dtype(), DataType::String | DataType::Categorical(_, _)) {
            // Drop the original categorical column
            result = result.drop(&col_name)?;

            // One-hot encode using Polars' built-in method
            let encoded = col
                .str()?
                .to_categorical(None)
                .to_dummies(true, true)?;

            // Add encoded columns to result
            for encoded_col in encoded.get_columns() {
                result = result.with_columns([encoded_col.clone()])?;
            }
        }
    }

    Ok(result)
}

#[cfg(test)]
mod tests {
