        assert!(encoded.column("blue").is_ok());
        assert!(encoded.column("green").is_ok());
        assert!(encoded.column("S").is_ok());
        assert!(encoded.column("M").is_ok());
        assert!(encoded.column("L").is_ok());
        assert!(encoded.column("price").is_ok());
        assert!(encoded.column("color").is_err());
        assert!(encoded.column("size").is_err());
    }
}

