use ndarray::{Array, ArrayBase, IxDyn, Axis};

/// Clones a vector `n` times along the specified axis.
///
/// # Examples
/// ```
/// use ndarray::array;
///
/// let vec = array![1, 2, 3];
/// let cloned = clone_along_axis(&vec, 1, 0); // Clone along axis 0 (1D)
/// assert_eq!(cloned, array![[1, 2, 3]]);
///
