/// let cloned = clone_along_axis(&mat, 2, 0); // Clone rows
/// assert_eq!(cloned, array![[1, 2], [3, 4], [1, 2], [3, 4]]);
/// ```
pub fn clone_along_axis<T: Clone>(
    input: &ArrayBase<IxDyn, T>,
    n: usize,
    axis: usize,
) -> ArrayBase<IxDyn, T> {
    // Validate axis
    if axis >= input.ndim() {
        panic!("Axis {} is out of bounds for array with {} dimensions", axis, input.ndim());
    }

    // Create a new array with the same shape but expanded along the specified axis
    let mut new_shape = input.shape().to_vec();
    new_shape.insert(axis, n);

    // Initialize the new array with default values
    let mut result = Array::zeros(new_shape);

    // Fill the new array by cloning the original along the specified axis
    for i in 0..n {
        let offset = if axis == 0 {
            i
        } else {
            // Calculate the offset for higher dimensions
            let mut offset = 0;
            for (j, dim) in new_shape.iter().enumerate() {
                if j < axis {
                    offset = offset * dim + i;
                } else if j == axis {
                    offset = offset * dim + i;
                } else {
                    offset = offset * dim;
                }
            }
            offset
        };

        result.slice_mut(s![offset..offset + 1]).assign(&input);
    }

    result
}
