use ndarray::Array2;

/// Clone a 1-D slice `v` `times` times along `axis`.
///
/// - If axis == 0: returns an Array2 with shape (times, v.len()) — `times` rows, each a copy of `v`.
/// - If axis == 1: returns an Array2 with shape (v.len(), times) — `times` columns, each a copy of `v`.
///
/// Returns Err if axis is not 0 or 1. Works with zero-length inputs and/or times == 0.
///
/// T must implement Clone because elements are duplicated.
pub fn clone_vector_along_axis<T: Clone>(
    v: &[T],
    times: usize,
    axis: usize,
) -> Result<Array2<T>, String> {
    let n = v.len();

    if axis > 1 {
        return Err("axis must be 0 or 1".to_owned());
    }

    // Handle special-case zero sizes by constructing empty storage of the right shape.
    if times == 0 {
        // shape (0, n) or (n, 0)
        let shape = if axis == 0 { (0usize, n) } else { (n, 0usize) };
        return Array2::from_shape_vec(shape, Vec::new()).map_err(|e| e.to_string());
    }

    if n == 0 {
        // v empty, produce (times,0) or (0,times)
        let shape = if axis == 0 { (times, 0usize) } else { (0usize, times) };
        return Array2::from_shape_vec(shape, Vec::new()).map_err(|e| e.to_string());
    }

    // Build a 1xN or N x1 array and broadcast it to desired shape, then to_owned() to materialize.
    if axis == 0 {
        // make shape (1, n) then broadcast to (times, n)
        let base = Array2::from_shape_vec((1, n), v.to_vec()).map_err(|e| e.to_string())?;
        let view = base.broadcast((times, n)).ok_or("broadcast failed")?;
        Ok(view.to_owned())
    } else {
        // axis == 1: make shape (n, 1) then broadcast to (n, times)
        let base = Array2::from_shape_vec((n, 1), v.to_vec()).map_err(|e| e.to_string())?;
        let view = base.broadcast((n, times)).ok_or("broadcast failed")?;
        Ok(view.to_owned())
    }
}

fn main() {
    // Example usage
    let v = vec![1, 2, 3];

    let rows = clone_vector_along_axis(&v, 4, 0).unwrap();
    println!("4 rows (4x3):\n{}", rows);

    let cols = clone_vector_along_axis(&v, 4, 1).unwrap();
    println!("4 columns (3x4):\n{}", cols);
}
```

