        (Value::Object(map_a), Value::Object(map_b)) => {
            if map_a.len() != map_b.len() {
                return false;
            }

            // Convert to BTreeMap for consistent ordering
            let sorted_a: BTreeMap<_, _> = map_a.iter().collect();
            let sorted_b: BTreeMap<_, _> = map_b.iter().collect();

            sorted_a.iter().all(|(key, val_a)| {
                sorted_b.get(key).map_or(false, |val_b| {
                    deep_equal_ordered(val_a, val_b)
                })
            })
        }

        // Compare arrays element by element (order matters for arrays)
        (Value::Array(arr_a), Value::Array(arr_b)) => {
            if arr_a.len() != arr_b.len() {
                return false;
            }
            arr_a.iter().zip(arr_b.iter()).all(|(a, b)| {
                deep_equal_ordered(a, b)
            })
        }

        // Compare primitive values directly
        _ => a == b,
    }
