use ndarray::{Array1, ArrayView1};
use std::cmp::Ordering;

// Function to get indices of the N largest values in var0 from lst0
fn get_top_n_indices<T: PartialOrd>(lst0: &[T], var0: &[f64], n: usize) -> Vec<usize> {
    // Create an array of tuples (index, value) where value is from var0
    let mut indexed_var0: Vec<(usize, f64)> = lst0.iter()
        .enumerate()
        .map(|(i, _)| (i, var0[i]))
        .collect();

    // Sort the array of tuples by value in descending order
    indexed_var0.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(Ordering::Equal));

    // Collect the indices of the top N elements
    indexed_var0.iter().take(n).map(|&(index, _)| index).collect()
}

fn main() {
