/// Retrieves the indices of the N elements with the highest `var0` values from `lst0`.
///
/// # Arguments
/// * `lst0` - A slice of structs containing a `var0` field (must implement `PartialOrd` and `Copy`).
/// * `n` - The number of top elements to retrieve.
///
/// # Returns
/// A vector of indices (sorted in descending order of `var0` values) of the top N elements.
///
/// # Panics
/// Panics if `n` is larger than the length of `lst0` or if `lst0` is empty.
///
/// # Example
/// ```
/// struct MyStruct {
///     var0: f64,
///     // other fields...
/// }
///
/// let lst0 = vec![
///     MyStruct { var0: 1.0 },
///     MyStruct { var0: 5.0 },
///     MyStruct { var0: 3.0 },
///     MyStruct { var0: 2.0 },
/// ];
///
/// let indices = get_top_n_indices(&lst0, 2);
/// assert_eq!(indices, vec![1, 0]); // Indices of 5.0 and 1.0
/// ```
pub fn get_top_n_indices<T>(lst0: &[T], n: usize) -> Vec<usize>
where
    T: PartialOrd + Copy,
{
    if lst0.is_empty() {
        panic!("Input list cannot be empty");
    }
    if n > lst0.len() {
        panic!("Requested N is larger than the list size");
    }

    // Use a max-heap to efficiently track top N elements
    let mut heap = BinaryHeap::with_capacity(n);

    for (index, item) in lst0.iter().enumerate() {
        // We use Reverse to simulate a max-heap since BinaryHeap is a min-heap by default
        heap.push(Reverse((item, index)));

        // If heap size exceeds N, pop the smallest element
        if heap.len() > n {
            heap.pop();
        }
    }

    // Collect indices in descending order of var0
    heap.into_sorted_vec()
        .into_iter()
        .map(|Reverse((_, index))| index)
        .collect()
}
```

