/// Structure to hold the index and var0 value of an element
#[derive(PartialEq, Eq)]
struct Element {
    index: usize,
    var0: f64,
}

impl PartialOrd for Element {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        self.var0.partial_cmp(&other.var0)
    }
}

impl Ord for Element {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.var0.cmp(&other.var0)
    }
}

/// Retrieves the indices of the N elements with the highest var0 values from a large collection
