        let element = Element { index, var0: *var0 };
        if heap.len() < n {
            heap.push(element);
        } else if element > *heap.peek().unwrap() {
            heap.pop();
            heap.push(element);
        }
    }

    let mut result: Vec<usize> = heap.into_iter().map(|element| element.index).collect();
    result.sort_unstable();
    result
}

