    );

    // Return indices of top N, sorted by var0 descending
    let mut result: Vec<usize> = indexed[..n.min(indexed.len())]
        .iter()
        .map(|(idx, _)| *idx)
        .collect();

    result.sort_by(|&a, &b| {
