        index: usize,
        value: f64,
    }

    impl Eq for IndexedValue {}

    impl PartialEq for IndexedValue {
        fn eq(&self, other: &Self) -> bool {
            (self.value - other.value).abs() < 1e-10
        }
    }

    impl Ord for IndexedValue {
        fn cmp(&self, other: &Self) -> Ordering {
            self.value.partial_cmp(&other.value).unwrap_or(Ordering::Equal)
        }
    }

    impl PartialOrd for IndexedValue {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

