///
/// let grid = cartesian_grid(0.0, 1.0, 0.0, 1.0, 5);
/// assert_eq!(grid.shape(), [4, 2]); // 4 points (5 steps - 1) × 2 dimensions
/// ```
fn cartesian_grid<T: Into<f64> + Copy>(
    var0: T,
    var1: T,
    var2: T,
    var3: T,
    steps: usize,
) -> Array2<f64> {
