    let x_coords = ndarray::linspace(x0, x1, steps);
    let y_coords = ndarray::linspace(y0, y1, steps);

    // Create grid by combining x and y coordinates
    let mut grid = Array2::zeros((steps - 1, 2));
    for (i, x) in x_coords.iter().enumerate() {
        for (j, y) in y_coords.iter().enumerate() {
            if i != steps - 1 && j != steps - 1 {
                grid[[i, 0]] = *x;
                grid[[i, 1]] = *y;
            }
        }
    }

    grid
