use ndarray::{Array2, s};

/// Generates a grid of points representing the Cartesian product of two intervals.
///
/// # Arguments
/// * `var0` - Start of the first interval
/// * `var1` - End of the first interval
/// * `var2` - Start of the second interval
/// * `var3` - End of the second interval
/// * `points_per_interval` - Number of points to generate in each interval
///
/// # Returns
/// A 2D array where each row is a point [x, y] in the Cartesian product
///
/// # Example
/// ```
/// let grid = cartesian_product_grid(-1.0, 1.0, -1.0, 1.0, 3);
/// // Returns 9 points: (-1,-1), (-1,0), (-1,1), (0,-1), (0,0), (0,1), (1,-1), (1,0), (1,1)
/// ```
fn cartesian_product_grid(
    var0: f64,
    var1: f64,
    var2: f64,
    var3: f64,
    points_per_interval: usize,
) -> Array2<f64> {
    // Generate linearly spaced points for each interval
    let x_points = linspace(var0, var1, points_per_interval);
    let y_points = linspace(var2, var3, points_per_interval);

    let total_points = points_per_interval * points_per_interval;
    let mut grid = Array2::zeros((total_points, 2));

    // Create Cartesian product
    let mut idx = 0;
    for &x in &x_points {
        for &y in &y_points {
            grid[[idx, 0]] = x;
            grid[[idx, 1]] = y;
            idx += 1;
        }
    }

    grid
}

/// Helper function to generate linearly spaced points
fn linspace(start: f64, end: f64, num: usize) -> Vec<f64> {
    if num == 0 {
        return vec![];
    }
    if num == 1 {
        return vec![(start + end) / 2.0];
    }

    let step = (end - start) / (num - 1) as f64;
    (0..num).map(|i| start + step * i as f64).collect()
}

fn main() {
    let grid = cartesian_product_grid(-1.0, 1.0, -2.0, 2.0, 3);

    println!("Grid shape: {:?}", grid.dim());
    println!("Grid points:");
    for row in grid.rows() {
        println!("  ({:.2}, {:.2})", row[0], row[1]);
    }
}
