use hashbrown::HashMap;

/// Merges two hash maps by matching keys from the first map to their respective values in the second map.
///
/// # Arguments
///
/// * `map1` - A reference to the first HashMap with keys of type K and values of type V.
/// * `map2` - A reference to the second HashMap with keys of type K and values of type U.
///
/// # Returns
///
/// A new HashMap where each key from `map1` maps to the corresponding value from `map2`.
///
/// # Panics
///
/// The function panics if a key in `map1` is not found in `map2`.
fn merge_mappings<K: Eq + std::hash::Hash, V, U>(map1: &HashMap<K, V>, map2: &HashMap<K, U>) -> HashMap<K, U> {
    let mut result = HashMap::new();

    for (key, value) in map1 {
        // Ensure the key exists in map2 and insert the corresponding value into the result
        if let Some(&value2) = map2.get(key) {
            result.insert(key.clone(), value2);
        } else {
            panic!("Key {:?} not found in map2", key);
        }
    }

    result
}

