/// second.insert("a", 10);
/// second.insert("c", 30);
/// 
/// let result = match_mappings(&first, &second);
/// assert_eq!(result.get("a"), Some(&10));  // matched from second
/// assert_eq!(result.get("b"), Some(&2));   // not in second, kept from first
/// ```
pub fn match_mappings<K, V1, V2>(
    first_map: &IndexMap<K, V1>,
    second_map: &IndexMap<K, V2>,
) -> IndexMap<K, V2>
where
    K: Hash + Eq + Clone,
    V1: Clone,
    V2: Clone,
{
    first_map
        .iter()
        .map(|(key, _)| {
            let value = match second_map.get(key) {
                Some(val) => val.clone(),
                None => {
                    // If key not in second map, we need a default or handle differently
                    // For this implementation, we'll skip entries not in second map
                    return None;
                }
            };
            Some((key.clone(), value))
        })
        .flatten()
        .collect()
}

