pub fn match_mappings_with_fallback<K, V1, V2>(
    first_map: &IndexMap<K, V1>,
    second_map: &IndexMap<K, V2>,
) -> IndexMap<K, V2>
where
    K: Hash + Eq + Clone,
    V1: Clone + Into<V2>,
    V2: Clone,
{
    first_map
        .iter()
        .map(|(key, value)| {
            let new_value = match second_map.get(key) {
                Some(val) => val.clone(),
                None => value.clone().into(),
            };
            (key.clone(), new_value)
        })
        .collect()
}

