use regex::Regex;

/// Parse a slice of textual items (lst0) into numeric equivalents.
/// Returns a Vec<Option<f64>> where each element is Some(number) on success, or None on failure.
///
/// Strategy:
/// 1. Normalize string (trim, remove grouping commas).
/// 2. Handle parentheses as negative, currency symbols, percentages.
/// 3. Try direct parse as f64.
/// 4. Fallback to `numtext::parse` which converts worded numbers ("one hundred twenty-three") -> f64.
///
/// Example:
/// let lst0 = vec![
///     "42".to_string(),
///     "one hundred and twenty-three".to_string(),
///     "(1,234)".to_string(),
///     "$5.67".to_string(),
///     "twelve point five".to_string(),
///     "nope".to_string(),
/// ];
/// let nums = convert_lst0_to_numbers(&lst0);
/// // nums => [Some(42.0), Some(123.0), Some(-1234.0), Some(5.67), Some(12.5), None]
pub fn convert_lst0_to_numbers(lst0: &[String]) -> Vec<Option<f64>> {
    // Regexes precompiled for common normalizations
    // Remove common currency symbols and whitespace around them
    let re_currency = Regex::new(r#"^[\s\p{Sc}]*(?P<body>.*?)[\s\p{Sc}]*$"#).unwrap();
    // Remove thousands separators (commas) but keep decimal points
    let re_commas = Regex::new(r#",(?=\d{3}\b)"#).unwrap();
    // Remove any non-digit/decimal/separator characters except signs and parentheses at ends
    let re_strip = Regex::new(r"[^\d\.\-eE\+\(\)%]").unwrap();

    lst0.iter().map(|s| {
        let mut txt = s.trim().to_string();

        // Quick reject empty
        if txt.is_empty() {
            return None;
        }

        // Handle parentheses for negative numbers: "(123)" -> -123
        let mut negative = false;
        if txt.starts_with('(') && txt.ends_with(')') {
            negative = true;
            txt = txt[1..txt.len()-1].trim().to_string();
        }

        // Remove surrounding currency symbols (e.g. "$5", "€ 5")
        if let Some(caps) = re_currency.captures(&txt) {
            if let Some(body) = caps.name("body") {
                txt = body.as_str().to_string();
            }
        }

        // Remove grouping commas like "1,234,567" -> "1234567"
        txt = re_commas.replace_all(&txt, "").to_string();

        // Handle trailing percent: "12.5%" -> 0.125
        let mut is_percent = false;
        if txt.ends_with('%') {
            is_percent = true;
            txt = txt[..txt.len()-1].trim().to_string();
        }

        // Try direct parse as f64 after stripping stray characters (keeps ., e, +, -)
        let cleaned_for_number = re_strip.replace_all(&txt, "").to_string();

        if !cleaned_for_number.is_empty() {
