use nom::IResult;
use nom::branch::alt;
use nom::bytes::complete::{tag, take_while1};
use nom::character::complete::{digit1, space0};
use nom::combinator::{map, opt, recognize};
use nom::sequence::tuple;

/// Converts text representations of numbers into their numeric equivalents.
/// Supports integers and floating-point numbers in various formats.
fn convert_text_to_numbers(lst0: Vec<&str>) -> Vec<f64> {
    lst0.into_iter()
        .filter_map(|s| parse_number(s.trim()).ok())
        .map(|(_, num)| num)
        .collect()
}

/// Parses a string into a numeric value (f64)
/// Supports formats like: "123", "-45.67", "+89", ".5", "1e10", etc.
fn parse_number(input: &str) -> IResult<&str, f64> {
    let (input, _) = space0(input)?;

    let sign = opt(alt((tag("+"), tag("-"))));
    let integer_part = opt(digit1);
    let decimal_part = opt(tuple((tag("."), digit1)));
    let exponent_part = opt(tuple((
        alt((tag("e"), tag("E"))),
        opt(alt((tag("+"), tag("-")))),
        digit1,
    )));

    let number_parser = tuple((
        sign,
        integer_part,
        decimal_part,
        exponent_part,
    ));

    let (input, (sign, int_part, dec_part, exp_part)) = number_parser(input)?;
    let (input, _) = space0(input)?;

    // Reconstruct the number string and parse it
    let mut num_str = String::new();
    if let Some(s) = sign {
        num_str.push_str(s);
    }
    if let Some(i) = int_part {
        num_str.push_str(i);
    }
    if let Some((dot, dec)) = dec_part {
        num_str.push_str(dot);
        num_str.push_str(dec);
    }
    if let Some((e, sign_opt, exp)) = exp_part {
        num_str.push_str(e);
        if let Some(s) = sign_opt {
            num_str.push_str(s);
        }
        num_str.push_str(exp);
    }

    match num_str.parse::<f64>() {
        Ok(num) => Ok((input, num)),
        Err(_) => Err(nom::Err::Error(nom::error::Error::new(
            input,
            nom::error::ErrorKind::Char,
        ))),
    }
}

fn main() {
    // Example usage
    let input = vec!["123", "-45.67", "+89", ".5", "1e10", "3.14E-2"];
    let result = convert_text_to_numbers(input);

    println!("Converted numbers: {:?}", result);
    // Output: Converted numbers: [123.0, -45.67, 89.0, 0.5, 10000000000.0, 0.0314]
}

