use polars::prelude::*;
use std::error::Error;

fn add_sum_column(df: &DataFrame, cols_to_sum: Vec<&str>) -> Result<DataFrame, Box<dyn Error>> {
    // Ensure that columns exist in the DataFrame
    let existed_cols: Vec<&str> = df.get_column_names().iter().filter(|&&col| cols_to_sum.contains(&col)).copied().collect();

    if existed_cols.len() != cols_to_sum.len() {
        return Err("One or more specified columns do not exist in the DataFrame".into());
    }

    // Calculate the row-wise sum across specified columns
    let sum_series = df
        .select(&existed_cols)?
        .sum()?;

    // Add the summed values as a new column "var0"
    let mut df_with_sum = df.clone();
    df_with_sum.with_column(sum_series.rename("var0"))?;

    Ok(df_with_sum)
}

