Code:

```rust
use polars::prelude::*;

/// Add a new column `var0` to `df0` that is the row-wise sum of the columns in `lst0`.
///
/// - df0: input DataFrame
/// - lst0: slice of column names to sum
/// - var0: name of the output column
///
/// Returns a new DataFrame (PolarsResult<DataFrame>) or an error if a column in lst0 is missing.
pub fn add_row_sum(df0: &DataFrame, lst0: &[&str], var0: &str) -> PolarsResult<DataFrame> {
    // Verify all requested columns exist
    for &col_name in lst0 {
        if df0.find_idx_by_name(col_name).is_none() {
            return Err(PolarsError::NotFound(format!("Column '{}' not found", col_name).into()));
        }
    }

    // If no columns requested, just add a zero column
    if lst0.is_empty() {
        return df0
            .clone()
            .lazy()
            .with_column(lit(0.0).alias(var0))
            .collect();
    }

    // Build an expression that casts each column to Float64, fills nulls with 0.0,
    // and then sums them together.
    let mut expr_iter = lst0
        .iter()
        .map(|name| col(name).cast(DataType::Float64).fill_null(lit(0.0)));
    let first_expr = expr_iter.next().unwrap();
    let sum_expr = expr_iter.fold(first_expr, |acc, e| acc + e);

    // Apply expression using lazy API and collect result as a DataFrame
    df0.clone()
        .lazy()
        .with_column(sum_expr.alias(var0))
        .collect()
}

fn main() -> PolarsResult<()> {
