/// - `dict` is any HashMap-like mapping with keys K and values V.
/// - `len_fn` is a closure that, given &V, returns the length (usize) to sort by.
/// 
/// Keys are cloned into the returned Vec, so K must implement Clone.
///
/// Example:
/// let mut m = HashMap::new();
/// m.insert("a", "one".to_string());
/// m.insert("b", "three".to_string());
/// m.insert("c", "two".to_string());
