fn sorted_keys_by_value_len_desc<K, V, F>(dict: &HashMap<K, V>, len_fn: F) -> Vec<K>
where
    K: Clone + Eq + std::hash::Hash,
    F: Fn(&V) -> usize,
{
    dict.iter()
        // Sort by Reverse(length) so the longest values come first (descending).
        .sorted_by_key(|(_, v)| Reverse(len_fn(v)))
        .map(|(k, _)| k.clone())
        .collect()
}

