mod new_sort_2024 {
    /// Return a new Vec<T> containing the elements of `iter`, sorted by the
    /// key produced by `key_fn`. The key function is called exactly once per
    /// element (keys are cached). Sorting is stable: original order is preserved
    /// for equal keys.
    ///
    /// Usage:
