        F: Fn(&T) -> K,
        K: Ord,
    {
        let mut keyed: Vec<(K, usize, T)> = iter
            .into_iter()
            .enumerate()
            .map(|(idx, item)| {
                // compute key once and store along with original index for stability
                let k = key_fn(&item);
