pub fn sort_by_key<T, K, F>(items: Vec<T>, key_fn: F) -> Vec<T>
where
    T: Clone + Send + Sync + 'static,
    K: Into<bson::Bson> + Send + Sync,
    F: Fn(&T) -> K + Send + Sync,
{
    if items.is_empty() {
        return items;
    }

    // Create an in-memory database
    let db = Database::open_memory().expect("Failed to create in-memory database");
    let collection = db.collection::<Document>("items");

    // Insert items with their computed keys
    for (index, item) in items.iter().enumerate() {
        let key_value = key_fn(item);
        let doc = doc! {
            "index": index as i32,
            "key": key_value.into(),
        };
        collection.insert_one(doc).expect("Failed to insert document");
    }

    // Create an index on the key field for efficient sorting
    collection
        .create_index(doc! { "key": 1 })
        .expect("Failed to create index");

    // Retrieve sorted documents
    let sorted_docs: Vec<Document> = collection
        .find(doc! {})
        .sort(doc! { "key": 1 })
        .run()
        .expect("Failed to query sorted documents")
        .collect();

    // Reconstruct the sorted items
    let mut sorted_items: Vec<T> = Vec::with_capacity(items.len());
    for doc in sorted_docs {
        let index = doc.get_i32("index").expect("Missing index field") as usize;
        sorted_items.push(items[index].clone());
