use ndarray::{Array2, s};

/// Extract columns with indices in the half-open range [var0, var1)
/// from a 2-D row-major collection `arr0` (Vec of rows).
///
/// - arr0: slice of rows, each row must have the same length.
/// - var0: start column index (inclusive).
/// - var1: end column index (exclusive).
///
/// Returns Err(String) on invalid input (inconsistent row lengths or out-of-bounds).
pub fn extract_columns(
    arr0: &[Vec<f64>],
    var0: usize,
    var1: usize,
) -> Result<Vec<Vec<f64>>, String> {
    // Empty input: nothing to extract
    if arr0.is_empty() {
        return Ok(vec![]);
    }

    let nrows = arr0.len();
    let ncols = arr0[0].len();

    // Check all rows have the same length
    if !arr0.iter().all(|r| r.len() == ncols) {
        return Err("inconsistent row lengths in input".to_string());
    }

    if var0 > var1 {
        return Err("var0 must be <= var1".to_string());
    }
    if var1 > ncols {
        return Err(format!(
            "var1 out of bounds: var1={} but ncols={}",
            var1, ncols
        ));
    }

    // Flatten rows into a single contiguous vector (row-major)
    let flat: Vec<f64> = arr0.iter().flat_map(|r| r.iter().cloned()).collect();

    // Build an Array2 from shape (nrows, ncols)
    let arr = Array2::from_shape_vec((nrows, ncols), flat)
        .map_err(|e| format!("failed to create array: {}", e))?;

    // Slice columns var0..var1 (half-open)
    let view = arr.slice(s![.., var0..var1]);

    // Convert back to Vec<Vec<f64>> (rows)
    let mut result: Vec<Vec<f64>> = Vec::with_capacity(nrows);
    for row in view.rows() {
        result.push(row.to_vec());
    }

    Ok(result)
}

