use itertools::Itertools; // from the itertools crate (0.11+)

/// Return the indices of elements in `seq` whose values lie within the inclusive
/// range defined by `bound1` and `bound2`. The bounds may be provided in any
/// order (the function treats them as min/max).
///
/// Generic over any iterator of items implementing `PartialOrd`.
