Rust code:
```rust
use polars::prelude::*;
use regex::Regex;

/// Cleanse the column `col_name` in DataFrame `df0` by removing every character
/// that is not a letter or a digit (Unicode-aware).
///
/// Returns a new DataFrame with the same columns but with `col_name` replaced
/// by the cleaned string column. Nulls are preserved. Non-string columns are
/// first cast to Utf8 (string) before cleansing.
///
/// Example:
/// let df2 = cleanse_column(&df0, "col_name")?;
pub fn cleanse_column(df0: &DataFrame, col_name: &str) -> PolarsResult<DataFrame> {
    // Unicode-aware regex: keep letters (\p{L}) and decimal digits (\p{Nd})
    let re = Regex::new(r"[^\p{L}\p{Nd}]+").unwrap();

    // DataFrame::apply executes a per-column transformation and returns a new DF
    df0.apply(col_name, |s| {
        // Ensure we operate on a Utf8 series; cast if necessary.
        let series_utf8 = if s.dtype() == &DataType::Utf8 {
            s.clone()
        } else {
            s.cast(&DataType::Utf8)?
        };

        let ca = series_utf8.utf8()?;

        // Map over the iterator of Option<&str>, preserve nulls
        let iter = ca.into_iter().map(|opt| {
            opt.map(|v| {
                // replace all non-letter/digit runs with empty string
                re.replace_all(v, "").into_owned()
            })
        });

        // Build a new Utf8Chunked from the iterator and return as Series
        let cleaned = Utf8Chunked::from_iter_options(col_name, iter);
        Ok(cleaned.into_series())
    })
}
```

Notes:
- The regex r"[^\p{L}\p{Nd}]+" removes any run of characters that are not Unicode letters (\p{L}) or Unicode decimal digits (\p{Nd}).
- Nulls are preserved.
- Non-string columns are cast to strings first (so numbers will be converted to their string form, then non-letter/digit characters removed).
- The function returns a PolarsResult<DataFrame> so you can use `?` to propagate errors.

