/// Calculates the Mean Squared Error (MSE) between two 1D arrays.
///
/// # Arguments
/// * `lst0` - First array of numeric values
/// * `lst1` - Second array of numeric values (must have same length as `lst0`)
///
/// # Returns
/// The average of squared differences between corresponding elements
///
/// # Panics
/// Panics if the input arrays have different lengths
pub fn mean_squared_error<T>(lst0: ArrayView1<T>, lst1: ArrayView1<T>) -> f64
where
    T: ndarray::Scalar + std::ops::Sub<Output = T> + std::ops::Mul<Output = T> + std::ops::Add<Output = T>,
    T::Output: std::ops::Div<Output = T> + std::ops::Add<Output = T>,
    f64: From<T>,
