    let squared_diffs = lst0
        .iter()
        .zip(lst1.iter())
        .map(|(a, b)| (a - b).powi(2))
        .collect::<Array1<T>>();

    // Calculate mean of squared differences
    let sum: T = squared_diffs.iter().sum();
    let mean = sum / T::from(lst0.len()).unwrap_or(T::zero());

    // Convert to f64 for consistent return type
    f64::from(mean)
