/// produce a single row whose numeric columns are the sums across those rows.
///
/// - `df`: input DataFrame. Must contain a column named `key`.
/// - `key`: the column name to group by (e.g. "var0").
/// Returns a DataFrame with one row per unique key and summed numeric columns.
pub fn group_rows_sum_by_key(df: &DataFrame, key: &str) -> PolarsResult<DataFrame> {
    // Ensure key column exists
    if df.column(key).is_err() {
        return Err(PolarsError::NotFound(format!("key column '{}' not found", key).into()));
