/// let result = group_and_sum(df).unwrap();
/// println!("{:?}", result);
/// ```
pub fn group_and_sum(df: DataFrame) -> PolarsResult<DataFrame> {
    // Get all column names except var0
    let sum_cols: Vec<&str> = df
        .get_column_names()
        .iter()
        .filter(|&&name| name != "var0")
        .map(|s| s.as_str())
        .collect();

    // Group by var0 and sum all other columns
    df.group_by(["var0"])?
        .agg(sum_cols.iter().map(|col| col.sum().alias(col)))
        .collect()
}

// Alternative implementation using lazy API (more efficient for large datasets)
pub fn group_and_sum_lazy(df: DataFrame) -> PolarsResult<DataFrame> {
    let sum_cols: Vec<&str> = df
        .get_column_names()
        .iter()
        .filter(|&&name| name != "var0")
        .map(|s| s.as_str())
        .collect();

    df.lazy()
        .group_by(["var0"])
        .agg(sum_cols.iter().map(|col| col.sum().alias(col)))
        .collect()
}

