/// Returns true if every element of `items` is an array of length 2 where:
/// - the first component can be parsed as a BigInt (wide-range integer)
/// - the second component can be parsed as an i64 (standard integer)
///
/// Accepted input shapes for each component:
/// - JSON number (e.g. 123) or JSON string (e.g. "12345678901234567890")
/// - Decimal / fractional numbers will be rejected (BigInt/i64 parsing fails)
pub fn all_two_item_wide_first_standard_second(items: &[Value]) -> bool {
    for item in items {
        let arr = match item {
            Value::Array(a) if a.len() == 2 => a,
            _ => return false,
        };

        let first = &arr[0];
        let second = &arr[1];

        // Parse first as a BigInt. Accept either a JSON string or a JSON number
        // (but reject floats / decimals because BigInt::from_str will fail).
        let first_str = match first {
            Value::String(s) => s.as_str(),
            Value::Number(n) => n.to_string().as_str(),
            _ => return false,
        };
        // Because to_string() on a temporary creates a String we need to own it.
        // So handle Number separately to keep a String around if needed.
        let first_ok = match first {
            Value::String(s) => BigInt::from_str(s).is_ok(),
            Value::Number(n) => {
                // n.to_string() may produce "123" or "1.23"; FromStr will fail on floats.
                BigInt::from_str(&n.to_string()).is_ok()
            }
            _ => false,
        };
        if !first_ok {
            return false;
        }

        // Parse second as i64. Accept either JSON number or JSON string.
        let second_ok = match second {
            Value::Number(n) => n.as_i64().is_some(),
            Value::String(s) => s.parse::<i64>().is_ok(),
            _ => false,
        };
        if !second_ok {
            return false;
        }
    }

    true
}

