/// Attempts to parse an item as a (i128, i32) pair
fn try_parse_as_pair<T: Display>(item: &T) -> Option<(i128, i32)> {
    let item_str = item.to_string();

    // Try to parse as a tuple string like "(123, 456)"
    if let Some(inner) = item_str.strip_prefix('(').and_then(|s| s.strip_suffix(')')) {
