use polars::prelude::*;
use std::collections::HashMap;
use std::io::Read;

/// Read a CSV from `reader`, take the first column, and count occurrences of each unique value.
/// - `has_header` indicates whether the CSV has a header row.
/// Returns a HashMap mapping value -> count.
///
/// Errors are returned as Polars Err variants if reading/parsing fails.
pub fn count_first_column_occurrences_from_csv<R: Read>(
    mut reader: R,
    has_header: bool,
) -> PolarsResult<HashMap<String, usize>> {
    // Create CSV reader from any Read
    let mut csv_reader = CsvReader::new(&mut reader)
        .has_header(has_header)
        // infer schema (you can tune with `with_schema` etc.)
        .with_skip_rows(0);

    let df = csv_reader.finish()?;

    if df.width() == 0 {
        return Ok(HashMap::new());
    }

    // Get the first column as Series
    let first_series = df.select_at_idx(0).ok_or_else(|| {
        PolarsError::NoData("DataFrame has no first column".into())
    })?;

    // Cast to Utf8 to ensure string representation of each value
    let s_utf8 = first_series.cast(&DataType::Utf8)?;

    // Get Utf8Chunked and iterate, counting values (including explicit nulls as "<NULL>")
    let utf8 = s_utf8.utf8()?;
    let mut counts: HashMap<String, usize> = HashMap::new();

    for opt in utf8.into_iter() {
        let key = match opt {
            Some(v) => v.to_string(),
            None => "<NULL>".to_string(),
        };
        *counts.entry(key).or_insert(0) += 1;
    }

    Ok(counts)
}

