///
/// A sorted vector of tuples.
fn sort_entries(entries: Vec<(&str, i32)>) -> Vec<(&str, i32)> {
    let mut sorted_entries = entries;
    sorted_entries.sort_unstable_by(|a, b| {
        let cmp = b.1.cmp(&a.1); // Compare second elements in descending order
        if cmp == Ordering::Equal {
            a.0.cmp(b.0) // If tied, compare first elements in ascending order
        } else {
            cmp
        }
    });
    sorted_entries
}

