// Self-contained Rust code: extract a subset of text entries from a slice.
// Uses only the standard library; start is inclusive, end is exclusive.

#[derive(Debug, PartialEq, Eq)]
pub enum ExtractError {
    StartGreaterThanEnd { start: usize, end: usize },
    EndOutOfBounds { end: usize, len: usize },
    StartOutOfBounds { start: usize, len: usize },
}

/// Extracts a subset of text entries from `input`, returning a Vec<String>.
///
/// - `start` is inclusive, `end` is exclusive (like `&input[start..end]`).
/// - Returns Err if indices are invalid.
///
/// The function accepts any slice of items convertible to &str (AsRef<str>), and
/// clones the entries into returned Strings.
pub fn extract_subset<T: AsRef<str> + Clone>(
    input: &[T],
    start: usize,
    end: usize,
) -> Result<Vec<String>, ExtractError> {
    let len = input.len();
    if start > end {
        return Err(ExtractError::StartGreaterThanEnd { start, end });
    }
    if end > len {
        return Err(ExtractError::EndOutOfBounds { end, len });
    }
    if start > len {
        // start == len is allowed only if start == end == len (empty slice at end)
        return Err(ExtractError::StartOutOfBounds { start, len });
    }

    Ok(input[start..end]
        .iter()
        .map(|item| item.as_ref().to_string())
        .collect())
}

