```rust
use unicode_segmentation::UnicodeSegmentation;

/// Given a 2D list of text values (rows of columns), return a Vec<String>
/// containing the longest text for each column (measured in grapheme clusters).
///
/// - If rows are ragged, missing cells are ignored for that column.
/// - If no cells exist for a column, an empty string is returned for that column.
/// - If multiple entries tie for longest, the first encountered is returned.
///
/// Input: slice of rows, each row is Vec<String>.
pub fn longest_in_columns(rows: &[Vec<String>]) -> Vec<String> {
    // Determine the maximum number of columns present across all rows
    let max_cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);
    let mut result = Vec::with_capacity(max_cols);

    for col_idx in 0..max_cols {
        let mut best_text: Option<&str> = None;
        let mut best_len: usize = 0;

        for row in rows {
            if let Some(cell) = row.get(col_idx) {
                let s = cell.as_str();
                // Count grapheme clusters (user-perceived characters)
                let len = s.graphemes(true).count();
                if best_text.is_none() || len > best_len {
                    best_text = Some(s);
                    best_len = len;
                }
            }
        }

        result.push(best_text.unwrap_or("").to_string());
    }

    result
}

#[cfg(test)]
