    use super::*;

    #[test]
    fn basic_usage() {
        let rows = vec![
            vec!["apple".into(), "banana".into(), "x".into()],
            vec!["pear".into(), "blueberry".into()],
            vec!["pineapple".into(), "kiwi".into(), "longer-than-x".into()],
        ];

        let longest = longest_in_columns(&rows);
        assert_eq!(longest, vec![
            "pineapple".to_string(),   // column 0
            "blueberry".to_string(),   // column 1
            "longer-than-x".to_string(), // column 2
        ]);
    }

    #[test]
    fn ragged_and_unicode() {
        let rows = vec![
            vec!["a".into(), "🇺🇳".into()],                   // flag is two codepoints but one grapheme
            vec!["abc".into(), "🙂🙂".into()],               // two emojis
            vec!["á".into()],                                // accented char
        ];

        let longest = longest_in_columns(&rows);
        // column 0: "abc" (3 graphemes)
        // column 1: "🙂🙂" (2 graphemes) vs "🇺🇳" (1 grapheme)
        assert_eq!(longest, vec!["abc".to_string(), "🙂🙂".to_string()]);
    }

    #[test]
    fn empty_input() {
        let rows: Vec<Vec<String>> = vec![];
        let longest = longest_in_columns(&rows);
        assert!(longest.is_empty());
    }
}
```

Notes:
- Using unicode-segmentation avoids surprises where byte length or codepoint count doesn't match what a user perceives as length.
- The function returns the first string having maximal grapheme length for each column. Change the tie-breaking logic if you prefer a different rule (e.g., pick lexicographically greatest).

