/// assert_eq!(result, vec!["short", "longest", "abc"]);
/// ```
pub fn longest_per_column<'a>(data: &Array2<&'a str>) -> Vec<&'a str> {
    if data.is_empty() {
        return Vec::new();
    }

    let (rows, cols) = data.dim();
    let mut result: Vec<&str> = Vec::with_capacity(cols);

    for col in 0..cols {
        let mut longest = data[[0, col]];
        for row in 1..rows {
            let current = data[[row, col]];
            if current.len() > longest.len() {
                longest = current;
            }
        }
        result.push(longest);
    }

    result
}

