///
/// - `df`: reference to the input DataFrame
/// - `col_key`: column name to use as dictionary keys
/// - `col_val`: column name to use as dictionary values
///
/// Both columns are cast to Utf8 (strings) before extraction; if a key cell is null,
/// that row is skipped. If a value cell is null, it becomes an empty string.
/// If keys are duplicated, the last seen value overwrites earlier ones.
///
/// Returns a PolarsResult<HashMap<String, String>> so Polars errors (e.g. missing column)
/// are propagated.
pub fn df_to_dict(
    df: &DataFrame,
    col_key: &str,
    col_val: &str,
) -> PolarsResult<HashMap<String, String>> {
    // Get columns and cast to Utf8 so any type becomes string-like
    let key_series = df.column(col_key)?.cast(&DataType::Utf8)?;
    let val_series = df.column(col_val)?.cast(&DataType::Utf8)?;

    let key_utf8 = key_series.utf8()?;
    let val_utf8 = val_series.utf8()?;

    // lengths should match, but assert for safety
    if key_utf8.len() != val_utf8.len() {
        return Err(PolarsError::ShapeMisMatch(
            format!(
                "Column lengths differ: {} has length {}, {} has length {}",
                col_key,
                key_utf8.len(),
                col_val,
                val_utf8.len()
            )
            .into(),
        ));
    }

    let mut map = HashMap::with_capacity(key_utf8.len());

    for (k_opt, v_opt) in key_utf8.into_iter().zip(val_utf8.into_iter()) {
        if let Some(k) = k_opt {
            // If value is None (null), treat as empty string. Change behavior if desired.
            let v = v_opt.unwrap_or("");
