            .parse()
            .expect("Failed to parse element as floating-point number");

        // Convert to ordered representation for sorting
        // Using ordered_float crate would be ideal, but we'll use a manual approach
        // to keep it self-contained
        FloatKey(float_val)
    });
}

/// A wrapper type that implements Ord for f64 values
/// This handles NaN by treating it as greater than all other values
#[derive(Debug, Clone, Copy, PartialEq, PartialOrd)]
struct FloatKey(f64);

impl Eq for FloatKey {}

impl Ord for FloatKey {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        // Handle NaN: treat NaN as greater than all other values
        match (self.0.is_nan(), other.0.is_nan()) {
            (true, true) => std::cmp::Ordering::Equal,
            (true, false) => std::cmp::Ordering::Greater,
            (false, true) => std::cmp::Ordering::Less,
            (false, false) => {
                // For non-NaN values, use partial_cmp which returns None for NaN
                // but we've already handled NaN above
                self.0.partial_cmp(&other.0).unwrap_or(std::cmp::Ordering::Equal)
            }
        }
    }
}

impl PartialOrd<Self> for FloatKey {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

