use polars::prelude::*;

/// Excludes columns from a dataset.
///
/// # Arguments
///
/// * `df0` - The input dataset.
/// * `lst0` - A list of column identifiers to exclude.
///
/// # Returns
///
/// A new dataset that includes all columns from `df0` except those named in `lst0`.
pub fn exclude_columns(df0: &DataFrame, lst0: &[&str]) -> DataFrame {
    let columns = df0.columns();
    let columns_to_keep: Vec<String> = columns
        .iter()
        .filter_map(|col| {
            if lst0.contains(&col.name()) {
                None
            } else {
                Some(col.name().to_string())
            }
        })
        .collect();

    df0.select(columns_to_keep)
}

fn main() {
