    let s1 = Series::new("B", [4, 5, 6]);
    let s2 = Series::new("C", [7, 8, 9]);

    let mut df = DataFrame::new(vec![s, s1, s2]).unwrap();

    // Exclude columns
    let excluded_df = exclude_columns(&df, &["B"]);

    println!("{:?}", excluded_df);
}
