use polars::prelude::*;

/// Updates the values of specific cells in `df0` based on values from corresponding cells in `df1`.
///
/// # Arguments
///
/// * `df0`: The original DataFrame to be updated.
/// * `df1`: The DataFrame containing the new values.
/// * `column_name`: The name of the column to update.
/// * `index_column`: The name of the column used for indexing.
///
/// # Returns
///
/// The updated DataFrame.
fn update_cells(df0: DataFrame, df1: DataFrame, column_name: &str, index_column: &str) -> DataFrame {
    // Ensure both DataFrames have the same index column
    let df0_index = df0.column(index_column).unwrap();
