            let key_series = df1.column(key)?;
            let value_series = df1.column(column_name)?;

            let mut replacement_map: HashMap<AnyValue, AnyValue> = HashMap::new();

            for i in 0..df1.height() {
                let key_val = key_series.get(i)?;
                let val = value_series.get(i)?;
