# Rust Function for Conditional Cell Updates Between DataFrames

Here's a self-contained function using **Polars** (a modern Rust DataFrame library, actively developed in 2024+):

```rust
use polars::prelude::*;

/// Updates specific cells in df0 based on corresponding cells in df1.
/// 
/// # Arguments
/// * `df0` - The primary DataFrame to be modified
/// * `df1` - The DataFrame containing update values
/// * `condition_col` - Column name to match between DataFrames (join key)
/// * `update_col` - Column name in df1 containing new values
/// * `target_col` - Column name in df0 to update
///
/// # Returns
/// * `Result<DataFrame>` - Updated DataFrame
fn update_cells_from_dataframe(
    df0: &DataFrame,
    df1: &DataFrame,
    condition_col: &str,
    update_col: &str,
    target_col: &str,
) -> PolarsResult<DataFrame> {
    // Join df0 with df1 on the condition column
    let joined = df0.join(
        df1,
        [condition_col],
        [condition_col],
        JoinArgs::new(JoinType::Left),
    )?;

    // Get the update values from the joined result
    let update_values = joined.column(update_col)?;

    // Create a new column with updated values:
    // - Use values from df1 (update_col) where they exist (not null)
    // - Keep original values from df0 where df1 has null
    let mask = update_values.is_not_null();
    let original_col = df0.column(target_col)?;

    let updated_col = when(mask)
        .then(update_values.clone())
        .otherwise(original_col)?
        .alias(target_col);

    // Select all columns from df0, replacing the target column
    let mut result = df0.clone();
    result = result.drop(target_col)?;

    let update_series = updated_col.to_series()?;
    result.with_column(update_series)
}

// Example usage
fn main() -> PolarsResult<()> {
    use polars::df;

    // Create sample DataFrame 1 (primary data)
    let df0 = df!(
        "id" => &[1, 2, 3, 4],
        "name" => &["Alice", "Bob", "Charlie", "David"],
