/// * `var2` - The name of the column to update
///
/// # Returns
/// * `Result<DataFrame>` - The modified DataFrame with updated values
///
/// # Example
/// ```
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "var0" => &[1, 2, 3, 2, 5],
///     "var2" => &[10, 20, 30, 40, 50]
