/// // │ 2    ┆ 2    │
/// // │ 3    ┆ 30   │
/// // │ 2    ┆ 2    │
/// // │ 5    ┆ 50   │
/// // └──────┴──────┘
/// ```
pub fn set_column_value_where_equal<T>(
    df0: DataFrame,
    var0: &str,
    var1: T,
    var2: &str,
) -> PolarsResult<DataFrame>
where
    T: PolarsNumericType,
    T::Native: PartialEq,
{
    // Create a boolean mask for rows where var0 equals var1
    let mask = df0.column(var0)?.equal(var1)?;

    // Use when_then_otherwise to conditionally update var2
    df0.lazy()
        .with_column(
            when(mask)
                .then(lit(var1))
                .otherwise(col(var2))
                .alias(var2)
        )
        .collect()
}

// Alternative implementation using eager API (more explicit but less idiomatic)
pub fn set_column_value_where_equal_eager<T>(
    mut df0: DataFrame,
    var0: &str,
    var1: T,
    var2: &str,
) -> PolarsResult<DataFrame>
where
    T: PolarsNumericType,
    T::Native: PartialEq,
{
    // Create a boolean mask
    let mask = df0.column(var0)?.equal(var1)?;

    // Get the current values of var2
    let current_values = df0.column(var2)?.clone();

    // Create new values: where mask is true, use var1; otherwise keep original
    let new_values = current_values.zip_with(&mask, &Series::new(var2, &[var1]))?;

    // Replace the column
    df0.replace(var2, new_values)?;

    Ok(df0)
}

