### Solution
```rust
use nom::{
    branch::alt,
    bytes::complete::{tag, take_while1},
    character::complete::{char, digit1, one_of},
    combinator::{map, opt, recognize},
    multi::many0,
    sequence::{delimited, pair, preceded, separated_pair, terminated, tuple},
    IResult,
};

// Define comparison operators and range expressions
type ComparisonTerm = String;
type NumericalValue = f64;

#[derive(Debug)]
pub enum ComparisonExpression {
    LessThan(NumericalValue, Option<NumericalValue>),
    LessThanOrEqual(NumericalValue, Option<NumericalValue>),
    GreaterThan(NumericalValue, Option<NumericalValue>),
    GreaterThanOrEqual(NumericalValue, Option<NumericalValue>),
    Between(NumericalValue, NumericalValue),
    Equal(NumericalValue),
    NotEqual(NumericalValue),
    // Add more as needed (e.g., "more than", "at least", etc.)
}

fn parse_comparison_term(input: &str) -> IResult<&str, ComparisonTerm> {
    alt((
        tag("less than"),
        tag("less than or equal"),
        tag("greater than"),
        tag("greater than or equal"),
        tag("between"),
        tag("="),
        tag("!="),
        tag(">"),
        tag("<"),
        tag(">="),
        tag("<="),
    ))(input)
}

fn parse_number(input: &str) -> IResult<&str, NumericalValue> {
    map(
        recognize(pair(
            opt(char('-')),
            many0(digit1),
        )),
        |s: &str| s.parse().unwrap_or(0.0),
    )(input)
}

fn parse_comparison_expression(input: &str) -> IResult<&str, ComparisonExpression> {
    alt((
        // Less than (e.g., "less than 10")
        map(
            pair(
                parse_comparison_term,
                opt(preceded(tag(" "), parse_number)),
            ),
            |(term, num)| {
                if term == "less than" {
                    ComparisonExpression::LessThan(num.unwrap_or(0.0), None)
                } else if term == "less than or equal" {
                    ComparisonExpression::LessThanOrEqual(num.unwrap_or(0.0), None)
                } else {
                    unreachable!()
                }
            },
        ),
        // Greater than (e.g., "greater than 10")
        map(
            pair(
                parse_comparison_term,
                opt(preceded(tag(" "), parse_number)),
            ),
            |(term, num)| {
                if term == "greater than" {
                    ComparisonExpression::GreaterThan(num.unwrap_or(0.0), None)
                } else if term == "greater than or equal" {
                    ComparisonExpression::GreaterThanOrEqual(num.unwrap_or(0.0), None)
                } else {
                    unreachable!()
                }
            },
        ),
        // Between (e.g., "between 10 and 20")
        map(
            pair(
                parse_comparison_term,
                separated_pair(
                    parse_number,
                    tag(" and "),
                    parse_number,
                ),
            ),
            |(term, (lower, upper))| {
                if term == "between" {
                    ComparisonExpression::Between(lower, upper)
                } else {
                    unreachable!()
                }
            },
        ),
        // Equality (e.g., "= 10")
        map(
            pair(
                parse_comparison_term,
                parse_number,
            ),
            |(term, num)| {
                if term == "=" {
                    ComparisonExpression::Equal(num)
                } else if term == "!=" {
                    ComparisonExpression::NotEqual(num)
                } else {
                    unreachable!()
                }
            },
        ),
        // Symbolic operators (e.g., "< 10")
        map(
            pair(
                parse_comparison_term,
                parse_number,
            ),
            |(term, num)| {
                match term {
                    "<" => ComparisonExpression::LessThan(num, None),
                    "<=" => ComparisonExpression::LessThanOrEqual(num, None),
                    ">" => ComparisonExpression::GreaterThan(num, None),
                    ">=" => ComparisonExpression::GreaterThanOrEqual(num, None),
                    _ => unreachable!(),
                }
            },
        ),
    ))(input)
}

/// Extracts numerical values with associated comparison terms from a string.
///
/// # Examples
/// ```
/// let input = "age less than 30, weight between 50 and 80";
/// let result = extract_comparison_expressions(input);
/// assert_eq!(
///     result,
///     Ok(vec![
///         ComparisonExpression::LessThan(30.0, None),
///         ComparisonExpression::Between(50.0, 80.0),
///     ])
/// );
/// ```
pub fn extract_comparison_expressions(input: &str) -> Result<Vec<ComparisonExpression>, nom::Err<&str>> {
    let mut remaining = input;
    let mut expressions = Vec::new();

    while let Ok((rest, expr)) = parse_comparison_expression(remaining) {
        expressions.push(expr);
        remaining = rest;
    }

    // Check if there's any remaining input that wasn't parsed
    if !remaining.trim().is_empty() {
        return Err(nom::Err::Incomplete(nom::Needed::new(1)));
    }

    Ok(expressions)
}

