use regex::Regex;

/// Extracts numerical values and comparison terms from a string.
///
/// # Arguments
///
/// * `var0` - The input string to extract from.
///
/// # Returns
///
/// A vector of tuples, where each tuple contains a numerical value and any associated comparison terms.
pub fn extract_numerical_values(var0: &str) -> Vec<(f64, String)> {
    let re = Regex::new(r"(\d+(?:\.\d+)?)\s*(?:([<>=]+)\s*(\d+(?:\.\d+)?))?(?:\s*(between|and)\s*(\d+(?:\.\d+)?))?.*").unwrap();
    let mut results = Vec::new();

    for cap in re.captures_iter(var0) {
        let num: f64 = cap[1].parse().unwrap();
        let comparison = match (cap[2].as_ref(), cap[4].as_ref()) {
            (Some(comparison), Some(range)) => format!("{} {}", comparison, range),
            (Some(comparison), None) => comparison.to_string(),
            (None, Some(range)) => format!("between {} and", range),
            (None, None) => String::new(),
        };

        results.push((num, comparison));
    }

    results
}

