/// assert_eq!(results, vec![
///     ("less than", 100.0, None),
///     ("greater than", 50.0, None),
///     ("between", 20.0, Some(30.0)),
/// ]);
/// ```
pub fn extract_comparisons(text: &str) -> Vec<(&str, f64, Option<f64>)> {
    let mut results = Vec::new();

    // Pattern for "between X and Y"
    let between_re = Regex::new(
        r"(?i)\b(between)\s+(\d+(?:\.\d+)?)\s+(?:and|to|through)\s+(\d+(?:\.\d+)?)"
    ).unwrap();

    // Pattern for single comparison terms
    let single_re = Regex::new(
        r"(?i)\b(less\s+than|greater\s+than|more\s+than|at\s+least|at\s+most|no\s+more\s+than|no\s+less\s+than|over|under|above|below|exactly|approximately|about|around|nearly|roughly|up\s+to)\s+(\d+(?:\.\d+)?)"
    ).unwrap();

    // Pattern for standalone numbers (no comparison)
    let standalone_re = Regex::new(r"\b(\d+(?:\.\d+)?)\b").unwrap();

    // Track which positions we've already matched
    let mut matched_positions: Vec<(usize, usize)> = Vec::new();

    // Find "between" patterns first (they consume more text)
    for cap in between_re.captures_iter(text) {
        let start = cap.get(0).unwrap().start();
        let end = cap.get(0).unwrap().end();
        matched_positions.push((start, end));

        let comparison = cap.get(1).unwrap().as_str();
        let val1: f64 = cap.get(2).unwrap().as_str().parse().unwrap();
        let val2: f64 = cap.get(3).unwrap().as_str().parse().unwrap();

        results.push((comparison, val1, Some(val2)));
    }

    // Find single comparison patterns
    for cap in single_re.captures_iter(text) {
        let start = cap.get(0).unwrap().start();
        let end = cap.get(0).unwrap().end();

        // Skip if this position is already matched
        if matched_positions.iter().any(|&(s, e)| s <= start && e >= end) {
            continue;
        }
        matched_positions.push((start, end));

        let comparison = cap.get(1).unwrap().as_str();
        let val: f64 = cap.get(2).unwrap().as_str().parse().unwrap();

        results.push((comparison, val, None));
    }

    // Find standalone numbers (no comparison)
    for cap in standalone_re.captures_iter(text) {
        let start = cap.get(0).unwrap().start();
        let end = cap.get(0).unwrap().end();

        // Skip if this position is already matched
        if matched_positions.iter().any(|&(s, e)| s <= start && e >= end) {
            continue;
        }
        matched_positions.push((start, end));

        let val: f64 = cap.get(1).unwrap().as_str().parse().unwrap();
        results.push(("", val, None));
    }

    // Sort results by position in original text
    results.sort_by(|a, b| {
        let pos_a = text.find(&a.1.to_string()).unwrap_or(0);
        let pos_b = text.find(&b.1.to_string()).unwrap_or(0);
        pos_a.cmp(&pos_b)
    });

    results
}

