fn add_group_columns(df: &DataFrame) -> PolarsResult<DataFrame> {
    // Check if the DataFrame has the necessary columns
    if !df.get_column("var0")?.is_chunked() || !df.get_column("var1")?.is_numeric() {
        return Err(PolarsError::SchemaError("DataFrame must have columns 'var0' and 'var1'.".into()));
