/// For each row in the DataFrame, find which column holds the highest value
/// and return a Series containing the column names.
///
/// # Arguments
/// * `df` - Input DataFrame with numeric columns
///
/// # Returns
/// * `Result<Series>` - A Series of strings containing the column name with the highest value for each row
///
/// # Panics
/// * If the DataFrame is empty
/// * If any column contains non-numeric data
pub fn get_max_column_per_row(df: &DataFrame) -> Result<Series, PolarsError> {
    // Get column names as a vector of strings
    let column_names: Vec<&str> = df.get_column_names();

    // Convert all columns to f64 for comparison
    let numeric_cols: Vec<Series> = column_names.iter()
        .map(|name| df.column(name).unwrap().cast(&DataType::Float64).unwrap())
        .collect();

    // Stack all columns into a single 2D array for row-wise comparison
    let stacked = DataFrame::new(numeric_cols)?;

    // For each row, find the index of the maximum value
    let max_indices: Vec<usize> = stacked.iter()
        .map(|row| {
            row.f64()
                .unwrap()
                .iter()
                .enumerate()
                .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal))
                .map(|(idx, _)| idx)
                .unwrap_or(0)
        })
        .collect();

    // Convert indices to column names
    let result: Vec<&str> = max_indices.iter()
        .map(|&idx| column_names[idx])
        .collect();

    Ok(Series::new("max_column", result))
}

