use polars::prelude::*;

/// Alternative implementation using Polars expressions
pub fn get_max_column_per_row_expr(df: &DataFrame) -> Result<Series, PolarsError> {
    let column_names = df.get_column_names();

    // Create a list of column expressions
    let cols: Vec<Expr> = column_names.iter()
        .map(|name| col(name))
        .collect();

    // Use concat_list to combine columns, then find max position
    let max_col_expr = concat_list(cols)
        .map(|series| {
            let list = series.list()?;
            let max_positions: Vec<Option<usize>> = list
                .iter()
                .map(|s| {
                    s.unwrap()
                        .f64()
                        .ok()?
                        .iter()
                        .enumerate()
                        .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal))
                        .map(|(idx, _)| idx)
                })
                .collect();

            let result: Vec<Option<&str>> = max_positions.iter()
                .map(|&opt_idx| opt_idx.map(|idx| column_names[idx]))
                .collect();

            Ok(Some(Series::new("max_column", result)))
        })
        .alias("max_column");

    df.clone().lazy()
        .select([max_col_expr])
        .collect()?
        .column("max_column")
        .map(|s| s.clone())
