/// Compares two version strings segment by segment
fn compare_versions(a: &str, b: &str) -> Ordering {
    let a_segments: Vec<u32> = a.split('.')
        .map(|s| s.parse().unwrap_or(0))
        .collect();
    let b_segments: Vec<u32> = b.split('.')
        .map(|s| s.parse().unwrap_or(0))
        .collect();

