///
/// Returns an owned Array2 with the remaining columns in the same row order.
/// Returns Err if any index in `columns_to_delete` is >= number of columns.
pub fn remove_columns<T: Clone>(
    mat0: &Array2<T>,
    columns_to_delete: &[usize],
) -> Result<Array2<T>, String> {
    let ncols = mat0.ncols();

    // Validate indices and build a boolean "delete" mask
    let mut delete_mask = vec![false; ncols];
    for &c in columns_to_delete {
        if c >= ncols {
