```rust
use polars::prelude::*;
use std::collections::HashMap;

/// Counts occurrences of each unique value in specified columns of a DataFrame.
///
/// # Arguments
/// * `df0` - The input DataFrame containing the data
/// * `lst0` - List of column names to analyze
///
/// # Returns
/// A HashMap where keys are column names and values are HashMaps of value counts
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df!(
///     "A" => &[1, 2, 2, 3],
///     "B" => &["x", "y", "x", "z"]
/// ).unwrap();
/// let counts = count_unique_values(&df, &vec!["A", "B"]);
/// ```
pub fn count_unique_values(df0: &DataFrame, lst0: &[&str]) -> HashMap<String, HashMap<String, i64>> {
    let mut result = HashMap::new();

    for col_name in lst0 {
        // Get the column from the DataFrame
        match df0.column(col_name) {
            Some(col) => {
                // Create a new DataFrame with just this column
                let df_col = DataFrame::new(vec![col.clone()]).unwrap();

                // Count unique values
                let counts = df_col
                    .lazy()
                    .group_by([col_name])
                    .agg([col_name.count()])
                    .collect()
                    .unwrap();

                // Convert to HashMap
                let mut col_counts = HashMap::new();
                for row in counts.rows() {
                    let value = row.get(0).unwrap().to_string();
                    let count = row.get(1).unwrap().i64().unwrap();
                    col_counts.insert(value, count);
                }

                result.insert(col_name.to_string(), col_counts);
            }
            None => {
                eprintln!("Warning: Column '{}' not found in DataFrame", col_name);
            }
        }
    }

    result
}

