use polars::prelude::*;
use std::collections::HashMap;

/// Count occurrences of each unique value in each column listed in `lst0` from DataFrame `df0`.
///
/// Returns: HashMap<column_name, HashMap<value_as_string, count>>
pub fn count_values_per_column(
    df0: &DataFrame,
    lst0: &[&str],
) -> PolarsResult<HashMap<String, HashMap<String, u64>>> {
    let mut result: HashMap<String, HashMap<String, u64>> = HashMap::new();

    for &col_name in lst0 {
        // Get column (returns Err if column not found)
        let series = df0.column(col_name)?;

        // Cast everything to Utf8 so we can treat values uniformly as strings
        let s_utf8 = series.cast(&DataType::Utf8)?;
        let ca = s_utf8.utf8().expect("cast to Utf8 should yield Utf8Chunked");

        let mut counts: HashMap<String, u64> = HashMap::new();
        for opt_val in ca.into_iter() {
            let key = match opt_val {
                Some(v) => v.to_string(),
                None => "<NULL>".to_string(),
            };
            *counts.entry(key).or_insert(0) += 1;
        }
        result.insert(col_name.to_string(), counts);
    }

    Ok(result)
}

// Example usage
