use polars::prelude::*;

/// Transforms all entries in a specified column to uppercase.
///
/// # Arguments
/// * `df` - A DataFrame containing the data table
/// * `column_name` - The name of the column to transform
///
/// # Returns
/// A new DataFrame with the specified column converted to uppercase
///
/// # Examples
