///     "age" => &[25, 30, 35]
/// );
///
/// let uppercase_df = transform_column_to_uppercase(df, "name").unwrap();
/// ```
pub fn transform_column_to_uppercase(df: DataFrame, column_name: &str) -> Result<DataFrame, PolarsError> {
    // Check if column exists
    if !df.column(column_name).is_ok() {
        return Err(PolarsError::ColumnNotFound(column_name.to_string()));
    }

    // Get the column data
    let col = df.column(column_name)?;
    let col_name = col.name();

    // Convert to uppercase using Polars' string operations
    let uppercase_col = match col {
        // Handle String type
        DataType::Utf8(_) => {
            let utf8_col = col.utf8()?;
            let uppercase_series = utf8_col.map(|s| s.map(|s| s.to_uppercase()), &col_name)?;
            Series::new(col_name, uppercase_series)
        }
        // Handle NullableUtf8 type
        DataType::NullableUtf8(_) => {
            let nullable_utf8_col = col.nullable_utf8()?;
            let uppercase_series = nullable_utf8_col.map(|s| s.map(|s| s.to_uppercase()), &col_name)?;
