use polars::prelude::*;
use std::collections::BTreeMap;

/// Pivot df0 so each unique value in `var0` becomes a column name and its corresponding
/// `var1` value becomes the value in that column (as a string). If a key appears multiple
/// times, the last value wins. Returns a single-row DataFrame.
pub fn pivot_var0_to_columns(df0: &DataFrame) -> PolarsResult<DataFrame> {
    // Ensure required columns exist
    if !df0.get_column_names().iter().any(|c| c == "var0")
        || !df0.get_column_names().iter().any(|c| c == "var1")
    {
        return Err(PolarsError::NotFound(
            "Input DataFrame must contain columns named 'var0' and 'var1'".into(),
        ));
    }

    // Access var0 as Utf8 (strings) and cast var1 to Utf8 for uniform representation.
    let var0 = df0.column("var0")?.utf8()?;
    let var1 = df0.column("var1")?.cast(&DataType::Utf8)?.utf8()?;

    if var0.len() != var1.len() {
        return Err(PolarsError::ShapeMisMatch(
            "var0 and var1 must have the same length".into(),
        ));
    }

    // Use a BTreeMap so result column order is deterministic (sorted by key).
    let mut map: BTreeMap<String, String> = BTreeMap::new();
    for i in 0..var0.len() {
        if let Some(key) = var0.get(i) {
            let val = var1.get(i).unwrap_or_default();
            map.insert(key.to_string(), val.to_string()); // last value wins for duplicates
        }
    }

    // Build one-element string Series for each key/value pair and create DataFrame
    let cols: Vec<Series> = map
        .into_iter()
        .map(|(k, v)| Series::new(k.as_str(), &[v.as_str()]))
        .collect();

    DataFrame::new(cols)
}

