    str0: &str,
    var0: f64,
) -> Result<DataFrame> {
    // Ensure the DataFrame is sorted by timestamp for correct window calculations
    let df = df0
        .lazy()
        .sort(
            [col(str0)],
            SortOptions {
                descending: false,
                nulls_last: true,
                ..Default::default()
