Code (self-contained function + example):

```rust
use polars::prelude::*;

/// Create a two-level hierarchical index from columns `col0` and `col1`.
///
/// This returns a new DataFrame where a struct column named `index_name`
/// (containing fields `col0` and `col1`) is inserted as the first column,
/// and the original `col0` and `col1` columns are removed.
///
/// Note: Polars does not have a pandas-style MultiIndex; this uses a struct column
/// to represent a two-level index.
///
/// Arguments:
/// - df: DataFrame to transform (cloned inside).
/// - col0: name of first index-level column (e.g., "str0").
/// - col1: name of second index-level column (e.g., "str1").
/// - index_name: name to give the new struct index column (e.g., "multi_index").
///
/// Returns:
/// - PolarsResult<DataFrame> with the new index column as the first column.
pub fn set_two_level_index(
    df: &DataFrame,
    col0: &str,
    col1: &str,
    index_name: &str,
) -> PolarsResult<DataFrame> {
    // Clone the incoming DataFrame to avoid mutating caller's data.
    let mut df = df.clone();

    // Extract the two columns as Series (cloning the series).
    let s0 = df.column(col0)?.clone();
    let s1 = df.column(col1)?.clone();

    // Create a Struct series representing the two-level index.
    // Series::new_struct takes the name and a slice of field Series.
    let idx = Series::new_struct(index_name, &[s0.clone(), s1.clone()])?;

    // Drop the original columns (we drop both; drop_in_place takes one name at a time).
    df.drop_in_place(col0)?;
    df.drop_in_place(col1)?;

    // Insert the struct index as the first column (row "index").
    df.insert_at_idx(0, idx)?;

    Ok(df)
}

// Example usage
