///         ["B", 2, false],
///         ["C", 3, true],
///     ],
///     ["col1", "col2", "col3"]
/// );
///
/// let filtered = filter_rows(
///     df,
///     vec![
///         ("col1", expr("col1 == \"A\"")),
///         ("col2", expr("col2 > 1")),
///     ]
/// );
/// ```
pub fn filter_rows(
    df: DataFrame,
    conditions: Vec<(&str, Expr)>,
) -> Result<DataFrame, PolarsError> {
    let mut filter_expr = None;

    for (col, expr) in conditions {
        let col_expr = df.column(col)?.expr(expr);
        let current_filter = if let Some(f) = filter_expr {
            f & col_expr
