use polars::prelude::*;
use std::collections::HashMap;

/// Filter a DataFrame based on multiple column conditions
/// 
/// # Arguments
/// * `data` - A vector of HashMaps representing rows (column_name -> value)
/// * `conditions` - A vector of tuples (column_name, operator, value)
///   Supported operators: "==", "!=", ">", "<", ">=", "<="
/// 
/// # Returns
/// * `Vec<HashMap<String, String>>` - Filtered rows
fn filter_table(
    data: Vec<HashMap<String, String>>,
    conditions: Vec<(&str, &str, &str)>,
) -> Result<Vec<HashMap<String, String>>, PolarsError> {
    // Convert input data to Polars DataFrame
    if data.is_empty() {
        return Ok(Vec::new());
    }

    // Get all unique column names
    let columns: Vec<&str> = data[0].keys().map(|k| k.as_str()).collect();

    // Build series for each column
    let mut series_vec: Vec<Series> = Vec::new();
    for col in &columns {
        let values: Vec<&str> = data.iter()
            .map(|row| row.get(*col).map(|s| s.as_str()).unwrap_or(""))
            .collect();
        series_vec.push(Series::new(col, values));
    }

    // Create DataFrame
    let df = DataFrame::new(series_vec)?;

    // Build filter expression
    let mut filter_expr: Option<Expr> = None;

    for (column, operator, value) in conditions {
        let col_expr = col(column);
        let condition = match operator {
            "==" => col_expr.eq(lit(value)),
            "!=" => col_expr.neq(lit(value)),
            ">" => col_expr.gt(lit(value)),
            "<" => col_expr.lt(lit(value)),
            ">=" => col_expr.gt_eq(lit(value)),
            "<=" => col_expr.lt_eq(lit(value)),
            _ => return Err(PolarsError::ComputeError(
                format!("Unsupported operator: {}", operator).into()
            )),
        };

        filter_expr = match filter_expr {
            None => Some(condition),
            Some(expr) => Some(expr.and(condition)),
        };
    }

    // Apply filter
    let filtered_df = match filter_expr {
        Some(expr) => df.filter(&expr)?,
        None => df,
    };

    // Convert back to Vec<HashMap>
    let mut result: Vec<HashMap<String, String>> = Vec::new();
    for i in 0..filtered_df.height() {
        let mut row = HashMap::new();
        for col in &columns {
            if let Ok(series) = filtered_df.column(col) {
                if let Ok(val) = series.get(i) {
