        let col = result.column(&column)?;
        let mask = match operator {
            "==" => col.equal(&value)?,
            "!=" => col.not_equal(&value)?,
            ">" => col.gt(&value)?,
            "<" => col.lt(&value)?,
            ">=" => col.gt_eq(&value)?,
            "<=" => col.lt_eq(&value)?,
            _ => unreachable!(),
        };

        result = result.filter(&mask)?;
    }

    Ok(result)
}

