```rust
use indexmap::IndexMap;
use std::hash::Hash;

/// Reorder entries so keys are sorted by the highest number in their associated sequence,
/// descending. Sequences that are empty are treated as having no max and are placed last.
///
/// - `map`: any iterable of (K, Vec<T>) pairs (e.g., HashMap.into_iter()).
/// - Returns an `IndexMap<K, Vec<T>>` where iteration yields entries in the requested order.
///
/// K: key type (must be Eq + Hash)
/// T: element type (must be Ord + Clone)
pub fn reorder_by_max_desc<K, T, I>(map: I) -> IndexMap<K, Vec<T>>
where
    I: IntoIterator<Item = (K, Vec<T>)>,
    K: Eq + Hash,
    T: Ord + Clone,
{
    // Collect pairs with their computed max (Option<T>).
    let mut pairs: Vec<(K, Vec<T>, Option<T>)> = map
        .into_iter()
        .map(|(k, v)| {
            let max = v.iter().max().cloned();
            (k, v, max)
        })
        .collect();

    // Sort by max descending. None (empty sequence) goes last.
    pairs.sort_by(|a, b| match (&a.2, &b.2) {
        (Some(ma), Some(mb)) => mb.cmp(ma), // compare b vs a for descending order
        (Some(_), None) => std::cmp::Ordering::Less,    // a has max -> a comes before b
        (None, Some(_)) => std::cmp::Ordering::Greater, // a empty -> comes after b
        (None, None) => std::cmp::Ordering::Equal,
    });

    // Build an IndexMap in the sorted order
    let mut out = IndexMap::with_capacity(pairs.len());
    for (k, v, _) in pairs {
        out.insert(k, v);
    }
    out
}

