use std::any::Any;
use ndarray::{Array2, Array3, ArrayD};
use polars::prelude::*;

/// The detected category for var0.
#[derive(Debug, PartialEq, Eq)]
pub enum Category {
    NativeSequence,
    MultidimensionalNumeric,
    OneDimLabeled,
}

/// Try to classify `var0` (passed as a `&dyn Any`) into one of the three categories.
/// Returns Some(Category) on a successful match, or None if the value didn't match any known type.
///
/// Notes:
/// - We check a set of commonly used concrete types. Add additional downcast checks if you use
///   different concrete types in your codebase.
/// - For polars::Series we treat it as "one-dimensional labeled" if it has a non-empty name and a numeric dtype.
pub fn classify_var0(var0: &dyn Any) -> Option<Category> {
    // 1) Check for polars::Series -> one-dimensional labeled data sequence
    if let Some(s) = var0.downcast_ref::<Series>() {
        // consider labeled if the series has a non-empty name and is a numeric dtype
        let name_ok = !s.name().is_empty();
        let dtype = s.dtype();
        let numeric = matches!(
            dtype,
            DataType::Int8
                | DataType::Int16
                | DataType::Int32
                | DataType::Int64
                | DataType::UInt8
                | DataType::UInt16
                | DataType::UInt32
                | DataType::UInt64
                | DataType::Float32
                | DataType::Float64
        );
        if name_ok && numeric {
            return Some(Category::OneDimLabeled);
        }
        // a Series that is numeric but unlabeled could arguably also be considered a native sequence,
        // but we keep the logic strict per the user's categories.
    }

    // 2) Check for ndarray multi-dimensional numeric arrays -> multidimensional numeric collection
    // We check Array2, Array3, and dynamic-dimension ArrayD for common numeric element types.
    macro_rules! check_ndarray {
        ($T:ty) => {
            if var0.is::<Array2<$T>>() {
                // Array2 is 2-dimensional
                return Some(Category::MultidimensionalNumeric);
            }
            if var0.is::<Array3<$T>>() {
                return Some(Category::MultidimensionalNumeric);
            }
            if let Some(arr) = var0.downcast_ref::<ArrayD<$T>>() {
                if arr.ndim() >= 2 {
                    return Some(Category::MultidimensionalNumeric);
                }
            }
        };
    }

    check_ndarray!(f64);
    check_ndarray!(f32);
    check_ndarray!(i64);
    check_ndarray!(i32);
    check_ndarray!(u64);
    check_ndarray!(u32);

    // 3) Check for native sequence types (Vec<T>) -> native sequence
    macro_rules! check_vec {
        ($T:ty) => {
            if var0.is::<Vec<$T>>() {
                return Some(Category::NativeSequence);
            }
        };
    }

    check_vec!(f64);
    check_vec!(f32);
    check_vec!(i64);
    check_vec!(i32);
    check_vec!(u64);
    check_vec!(u32);
    check_vec!(String);
    check_vec!(&'static str); // less common but possible in examples

    // No match
    None
}

// Small demonstration of usage:
fn main() -> PolarsResult<()> {
    // Example 1: native sequence (Vec)
    let v: Vec<f64> = vec![1.0, 2.0, 3.0];
    println!("v -> {:?}", classify_var0(&v as &dyn Any)); // Some(Category::NativeSequence)

    // Example 2: ndarray 2D numeric
    let a2: Array2<f64> = ndarray::array![[1., 2.], [3., 4.]];
    println!("a2 -> {:?}", classify_var0(&a2 as &dyn Any)); // Some(Category::MultidimensionalNumeric)

    // Example 3: polars Series (one-dim labeled numeric)
