use polars::prelude::*;

/// Filters rows from `table_a` to only retain those that have matching rows in `table_b`.
///
/// # Arguments
/// * `table_a` - The source DataFrame to filter
/// * `table_b` - The reference DataFrame to match against
/// * `join_key` - The column name(s) to join on (can be a single string or a Vec of strings)
///
/// # Returns
/// A new DataFrame containing only the rows from `table_a` that have matches in `table_b`
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df_a = df![
///     "id" => &[1, 2, 3, 4],
///     "value" => &["a", "b", "c", "d"]
/// ]?;
///
/// let df_b = df![
///     "id" => &[2, 3, 5],
///     "other" => &[100, 200, 300]
/// ]?;
///
/// let result = filter_matching_rows(df_a, df_b, "id")?;
/// assert_eq!(result.get_column("id")?.get_values::<Int64Type>()?.to_vec(), vec![2, 3]);
/// ```
pub fn filter_matching_rows(
    table_a: &DataFrame,
    table_b: &DataFrame,
    join_key: &str,
) -> Result<DataFrame, PolarsError> {
    // Convert join_key to a vector if it's a single string
    let join_keys = if join_key.contains(',') {
        join_key.split(',').map(|s| s.trim().to_string()).collect()
    } else {
        vec![join_key.to_string()]
    };

    // Perform an inner join between the two DataFrames
    let joined = table_a
        .lazy()
        .inner_join(table_b.lazy(), &join_keys, Default::default())?
        .collect()?;

    // Extract only the columns from table_a
    let schema = table_a.schema();
    let columns = schema
        .get_columns()
        .iter()
        .map(|col| col.name())
        .collect::<Vec<_>>();

    Ok(joined.select(&columns)?)
}

