///     "C" => &[10.0, 11.0, 12.0]
/// );
/// let result = calculate_mean_for_duplicate_columns(&df).unwrap();
/// ```
pub fn calculate_mean_for_duplicate_columns(df: &DataFrame) -> Result<DataFrame, PolarsError> {
    // Group columns by their names
    let mut column_groups: HashMap<String, Vec<&Column>> = HashMap::new();
    for col in df.get_columns() {
        let name = col.name().to_string();
        column_groups.entry(name).or_default().push(col);
    }

    // For each group of columns with the same name, compute the mean
    let mut new_columns = Vec::new();
    for (name, columns) in column_groups {
        if columns.len() == 1 {
            // If only one column, keep it as-is
            new_columns.push(columns[0].clone());
        } else {
            // Compute mean for each row across the columns
            let mut means = Vec::with_capacity(columns[0].len());
            for row_idx in 0..columns[0].len() {
                let mut sum = 0.0;
                for col in columns {
                    let val = col.get(row_idx).unwrap().f64().unwrap_or(0.0);
