/// }.unwrap();
/// 
/// let result = calculate_column_means(df).unwrap();
/// // Result will have columns "A" (mean of both A columns) and "B"
/// ```
fn calculate_column_means(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut col_groups: std::collections::BTreeMap<String, Vec<Series>> = 
        std::collections::BTreeMap::new();

    // Group series by column name
    for series in df.iter() {
        let name = series.name().to_string();
        col_groups.entry(name).or_insert_with(Vec::new).push(series.clone());
    }

    // Calculate mean for each group
    let result_series: PolarsResult<Vec<Series>> = col_groups
        .into_iter()
        .map(|(name, series_list)| {
            if series_list.len() == 1 {
                // Single column, return as-is
                Ok(series_list.into_iter().next().unwrap())
            } else {
                // Multiple columns with same name: calculate mean
                let concat_series = concat_list(&series_list)
                    .map_err(|_| PolarsError::ComputeError("Failed to concatenate series".into()))?;

                let mean_series = concat_series
                    .list()
                    .map_err(|_| PolarsError::ComputeError("Failed to convert to list".into()))?
                    .lst_mean()
                    .map_err(|_| PolarsError::ComputeError("Failed to compute mean".into()))?;

                let result = mean_series.with_name(&name);
                Ok(result)
            }
        })
        .collect();

    // Create new DataFrame from result series
    match result_series {
        Ok(series_vec) => {
            if series_vec.is_empty() {
                Ok(DataFrame::empty())
            } else {
                // Ensure all series have the same length
                let first_len = series_vec[0].len();
                for s in &series_vec {
                    if s.len() != first_len {
                        return Err(PolarsError::ComputeError(
                            "All columns must have the same length".into(),
                        ));
                    }
                }

                DataFrame::new(series_vec)
            }
        }
        Err(e) => Err(e),
    }
}

