/// Resets the row index of a DataFrame and converts existing index values into new columns.
/// 
/// This function takes a DataFrame with an existing index column, resets it to a sequential
/// integer index starting from 0, and moves the original index values into a new column.
/// 
/// # Arguments
/// * `df` - Input DataFrame with an index column
/// * `index_col` - Name of the existing index column to reset
/// * `new_index_col` - Name for the new sequential index column (default: "index")
/// * `old_index_col` - Name for the column containing the original index values (default: "old_index")
/// 
/// # Returns
/// * `Result<DataFrame>` - DataFrame with reset index and original index values as a new column
/// 
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df![
///     "id" => &[101, 102, 103],
///     "value" => &[10, 20, 30]
/// ].unwrap();
/// 
/// let result = reset_index(df, "id", Some("new_index"), Some("original_id")).unwrap();
/// println!("{:?}", result);
/// ```
pub fn reset_index(
    df: DataFrame,
    index_col: &str,
    new_index_col: Option<&str>,
    old_index_col: Option<&str>,
) -> Result<DataFrame, Box<dyn Error>> {
    // Set default column names if not provided
    let new_idx = new_index_col.unwrap_or("index");
    let old_idx = old_index_col.unwrap_or("old_index");

    // Validate that the index column exists
    if !df.get_column_names().contains(&index_col) {
        return Err(format!("Column '{}' not found in DataFrame", index_col).into());
    }

    // Extract the index column values
    let index_values = df.column(index_col)?.clone();

    // Remove the old index column from the DataFrame
    let mut df = df.drop(index_col)?;

    // Create a new sequential index column
    let n_rows = df.height();
    let new_index = (0u32..n_rows as u32).collect::<Vec<_>>();
    let new_index_series = Series::new(new_idx, new_index);

    // Add the new index column at the beginning
    let mut columns = vec![new_index_series];

    // Add the original index values as a new column
    let old_index_series = index_values.rename(old_idx);
    columns.push(old_index_series);

    // Add all remaining columns from the original DataFrame
    for col in df.get_column_names() {
        columns.push(df.column(col)?.clone());
    }

    // Create the new DataFrame
    let result = DataFrame::new(columns)?;

    Ok(result)
}

