pub fn df_to_dict_list(df: &DataFrame) -> Result<Vec<HashMap<String, Value>>, PolarsError> {
    let mut result: Vec<HashMap<String, Value>> = Vec::with_capacity(df.height());

    // Get column names
    let column_names: Vec<&str> = df.get_column_names().into_iter().map(|s| s.as_str()).collect();

    // Iterate over each row
    for row_idx in 0..df.height() {
        let mut row_dict = HashMap::new();

        // Add the row index
        row_dict.insert("index".to_string(), Value::Number(serde_json::Number::from(row_idx as u64)));

