// Traverse df0 using the columns in `index_cols` as the hierarchical row index.
// For each row return (vec_of_index_level_strings, Option<string_value_from_column_A>).
// Nulls in the value column become None.
fn extract_hierarchical_index_values(
    df: &DataFrame,
    index_cols: &[&str],
    value_col: &str,
) -> PolarsResult<Vec<(Vec<String>, Option<String>)>> {
    // ensure requested columns exist (this will return an Err if not)
    for &c in index_cols.iter().chain(std::iter::once(value_col)) {
        df.column(c)?; // propagate error if column missing
    }

    let height = df.height();
    let mut out = Vec::with_capacity(height);

    for row_idx in 0..height {
        // build hierarchical index for this row
        let mut index_parts = Vec::with_capacity(index_cols.len());
        for &col in index_cols {
            let any = df.column(col)?.get(row_idx);
            // AnyValue::Null -> display as empty string for index level; adjust if you prefer "null"
            let s = match any {
                AnyValue::Null => "".to_string(),
                _ => any.to_string(),
            };
            index_parts.push(s);
        }

        // get value from column A
        let any_val = df.column(value_col)?.get(row_idx);
        let val_opt = match any_val {
            AnyValue::Null => None,
            _ => Some(any_val.to_string()),
        };

        out.push((index_parts, val_opt));
    }

    Ok(out)
