```rust
use ndarray::Array2;

/// Transpose a two-dimensional data table by swapping its rows and columns.
///
/// # Arguments
/// * `df0` - A 2D array represented as a vector of vectors (rows)
///
/// # Returns
/// * A new 2D array with rows and columns swapped
///
/// # Panics
/// * If the input is empty or has inconsistent row lengths
///
/// # Example
/// ```
/// let data = vec![
///     vec![1, 2, 3],
///     vec![4, 5, 6],
/// ];
/// let transposed = transpose_table(&data);
/// assert_eq!(transposed, vec![
///     vec![1, 4],
///     vec![2, 5],
///     vec![3, 6],
/// ]);
/// ```
fn transpose_table<T: Clone>(df0: &[Vec<T>]) -> Vec<Vec<T>> {
    if df0.is_empty() {
        return Vec::new();
    }

    let rows = df0.len();
    let cols = df0[0].len();

    // Verify all rows have the same length
    for row in df0.iter() {
        assert_eq!(row.len(), cols, "All rows must have the same length");
    }

    // Create ndarray from the input data
    let flat_data: Vec<T> = df0.iter().flat_map(|row| row.iter()).cloned().collect();
    let array = Array2::from_shape_vec((rows, cols), flat_data)
        .expect("Failed to create array from input data");

    // Transpose using ndarray's built-in method
    let transposed = array.t();

    // Convert back to Vec<Vec<T>>
    transposed.rows()
        .into_iter()
        .map(|row| row.iter().cloned().collect())
        .collect()
}

fn main() {
    // Example usage
    let df0 = vec![
        vec!["A", "B", "C"],
        vec!["D", "E", "F"],
        vec!["G", "H", "I"],
    ];

    println!("Original table:");
    for row in &df0 {
        println!("{:?}", row);
    }

    let transposed = transpose_table(&df0);

    println!("\nTransposed table:");
    for row in &transposed {
        println!("{:?}", row);
    }

    // Example with numbers
    let numeric_data = vec![
        vec![1, 2, 3, 4],
        vec![5, 6, 7, 8],
    ];

    println!("\nNumeric example:");
    println!("Original: {:?}", numeric_data);
    println!("Transposed: {:?}", transpose_table(&numeric_data));
}
```

