use polars::prelude::*;
use std::error::Error;

/// Resets the index of a DataFrame and renames it to the specified name.
///
/// # Arguments
/// * `df0` - The input DataFrame whose index will be reset
/// * `index_name0` - The new name for the reset index column
///
/// # Returns
/// * `Result<DataFrame, Box<dyn Error>>` - A new DataFrame with reset index, or an error
///
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "values" => &[1, 2, 3],
///     "names" => &["a", "b", "c"]
/// ).unwrap();
/// 
/// let result = reset_index_and_rename(df, "new_index").unwrap();
/// println!("{:?}", result);
/// ```
fn reset_index_and_rename(df0: DataFrame, index_name0: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Add a row index column (0-based)
    let mut df = df0.clone();
    let n_rows = df.height();

    // Create the index column
    let index_series = Series::new(index_name0, (0..n_rows).collect::<Vec<u32>>());

    // Insert the index as the first column
    df.insert_column(0, index_series)?;

    Ok(df)
}

// Alternative implementation using with_row_index (available in newer polars versions)
fn reset_index_and_rename_v2(df0: DataFrame, index_name0: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Using with_row_index which was stabilized in polars 0.35+ (2024)
    let df = df0.clone().with_row_index(index_name0, None)?;
    Ok(df)
}

fn main() -> Result<(), Box<dyn Error>> {
    // Example usage
    let df = df!(
        "A" => &[1, 2, 3, 4, 5],
        "B" => &["x", "y", "z", "w", "v"]
    )?;

    println!("Original DataFrame:");
    println!("{:?}", df);

    let result = reset_index_and_rename(df.clone(), "my_index")?;
    println!("\nDataFrame with reset index:");
    println!("{:?}", result);

    // Using the v2 implementation
