/// assert_eq!(result.get("c"), Some(&10)); // 4 + 6
/// ```
pub fn combine_mappings<K, V>(mappings: &[HashMap<K, V>]) -> AHashMap<K, V>
where
    K: std::hash::Hash + Eq + Clone,
    V: std::ops::Add<Output = V> + Default + Copy,
