use ndarray::{Array2, Array1, Ix2, Axis};
use std::iter::FromIterator;

fn fill_missing_with_column_average(data: &Array2<f64>) -> Array2<f64> {
    let (rows, cols) = data.dim();
    let mut filled_data = data.clone();

    // Iterate over each column
    for col in 0..cols {
        let column: Array1<f64> = filled_data
            .column(col)
            .to_owned()
            .mapv(|x| if x.is_nan() { 0.0 } else { x });

        // Calculate the mean of the non-missing values
        let sum: f64 = column.iter().sum();
        let count = column.iter().filter(|&&x| x != 0.0).count() as f64;
        let average = if count > 0.0 { sum / count } else { 0.0 };

        // Fill in the missing values with the average
        for row in 0..rows {
            if filled_data[[row, col]].is_nan() {
                filled_data[[row, col]] = average;
            }
        }
    }

    filled_data
}

fn main() {
