use ndarray::{Array2, ArrayView2, ArrayViewMut2, Data, Ix2};
use std::f64;

/// Replaces missing values (NaN) in a 2D dataset with the column-wise mean of non-missing values.
///
/// # Arguments
/// * `data` - A mutable view of the 2D dataset (may contain NaN values)
///
/// # Returns
/// A new 2D dataset with missing values replaced by their column-wise mean.
///
/// # Example
/// ```
/// use ndarray::array;
/// use ndarray::Array2;
///
/// let mut data = array![
///     [1.0, 2.0, 3.0],
///     [4.0, f64::NAN, 6.0],
///     [7.0, 9.0, f64::NAN]
/// ];
///
/// let filled = fill_missing_with_column_mean(&mut data);
/// assert!(!filled.contains(f64::NAN));
/// ```
pub fn fill_missing_with_column_mean(data: &mut Array2<f64>) -> Array2<f64> {
    // Create a copy of the original data to work with
    let mut result = data.clone();

    // Iterate over each column
    for col in 0..result.ncols() {
        // Collect non-NaN values in the current column
        let column_view = result.column(col);
        let non_nan_values: Vec<f64> = column_view
            .iter()
            .filter(|&&x| !x.is_nan())
            .cloned()
            .collect();

        // Calculate the mean of non-NaN values
        let mean = if non_nan_values.is_empty() {
            // If all values are NaN, leave them as NaN
            continue;
        } else {
            non_nan_values.iter().sum::<f64>() / non_nan_values.len() as f64
        };

        // Replace NaN values with the mean
        for row in 0..result.nrows() {
            if result[[row, col]].is_nan() {
                result[[row, col]] = mean;
            }
        }
    }

    result
}

