```rust
use ndarray::{Array2, ArrayBase, Data, Ix2};
use num_traits::Float;

/// Replaces missing values in a 2D array with the average of non-missing values in each column.
///
/// # Arguments
///
/// * `arr` - The input 2D array.
///
/// # Returns
///
/// A new 2D array with missing values replaced.
pub fn replace_missing_with_column_average<S>(arr: ArrayBase<S, Ix2>)
where
    S: Data<Elem = f64>,
{
    let mut result = arr.clone();

    for col in 0..arr.ncols() {
        let column = arr.column(col);
        let sum: f64 = column
            .iter()
            .filter(|&x| !x.is_nan())
            .sum::<f64>();
        let count: f64 = column
            .iter()
            .filter(|&x| !x.is_nan())
            .count() as f64;

        let average = sum / count;

        for row in 0..arr.nrows() {
            if result[(row, col)].is_nan() {
                result[(row, col)] = average;
            }
        }
    }

    result
}

fn main() {
