    use super::*;

    #[test]
    fn test_impute_basic() {
        let data = vec![
            vec![Some(1.0), None, Some(3.0)],
            vec![Some(2.0), Some(4.0), None],
            vec![None, Some(6.0), Some(9.0)],
        ];
        let out = impute_missing_by_column_mean(&data).expect("imputation failed");
        // Column means: col0: (1+2)/2 = 1.5, col1: (4+6)/2 = 5.0, col2: (3+9)/2 = 6.0
        let expected = vec![
            vec![1.0, 5.0, 3.0],
            vec![2.0, 4.0, 6.0],
            vec![1.5, 6.0, 9.0],
        ];
        assert_eq!(out, expected);
    }

    #[test]
    fn test_all_missing_column_errors() {
        let data = vec![
            vec![Some(1.0), None],
            vec![Some(2.0), None],
        ];
        let err = impute_missing_by_column_mean(&data).unwrap_err();
        let msg = format!("{}", err);
        assert!(msg.contains("Column 1 has no non-missing values"));
    }
}
```

