use polars::prelude::*;

/// Replace missing values in each column with the column's mean
///
/// # Arguments
/// * `df` - Input DataFrame with potentially missing numeric values
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with missing values filled with column means
///
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "A" => &[Some(1.0), None, Some(3.0)],
///     "B" => &[None, Some(5.0), Some(6.0)],
/// )?;
/// 
/// let result = fill_missing_with_column_means(&df)?;
/// println!("{:?}", result);
/// ```
pub fn fill_missing_with_column_means(df: &DataFrame) -> Result<DataFrame> {
    // Get column names
    let col_names: Vec<&str> = df.get_column_names();

    // Create expressions for each column
    let expressions: Vec<Expr> = col_names.iter().map(|name| {
        let col_expr = col(name);

        // Calculate mean, ignoring nulls
        let mean_expr = col_expr.mean();

        // Fill nulls with the mean value
        col_expr.fill_null(mean_expr)
    }).collect();

    // Apply all expressions to the DataFrame
    df.lazy()
        .with_columns(expressions)
        .collect()
}

// Alternative implementation using eager API (simpler but less efficient for large datasets)
pub fn fill_missing_with_column_means_eager(df: &DataFrame) -> Result<DataFrame> {
    let mut result = df.clone();

    for col_name in result.get_column_names() {
        let series = result.column(col_name)?;

        // Only process numeric columns
        if series.dtype().is_numeric() {
            let mean = series.mean();

            if let Some(mean_val) = mean {
                // Create a new series with nulls replaced by mean
                let filled = series.fill_null(mean_val)?;
                result.replace(col_name, filled)?;
            }
        }
    }

    Ok(result)
}

