use polars::prelude::*;

/// Imputes missing values in a DataFrame by replacing them with column averages.
///
/// # Arguments
/// * `df` - A Polars DataFrame that may contain null values
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - A new DataFrame with nulls replaced by column means
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "A" => [1.0, 2.0, f64::NAN, 4.0],
///     "B" => [10.0, f64::NAN, 30.0, 40.0],
/// }.unwrap();
///
/// let imputed = impute_missing_with_column_mean(df).unwrap();
/// ```
fn impute_missing_with_column_mean(df: DataFrame) -> Result<DataFrame, PolarsError> {
    let mut result_cols = Vec::new();

    for col_name in df.get_column_names() {
        let series = df.column(col_name)?;

        // Calculate the mean of non-null values in the column
        let mean = match series.dtype() {
            DataType::Float32 => {
                let values: Vec<f32> = series
                    .f32()?
                    .into_iter()
                    .filter_map(|v| v)
                    .collect();
                if values.is_empty() {
                    f32::NAN
                } else {
                    values.iter().sum::<f32>() / values.len() as f32
                }
            }
            DataType::Float64 => {
                let values: Vec<f64> = series
                    .f64()?
                    .into_iter()
                    .filter_map(|v| v)
                    .collect();
                if values.is_empty() {
                    f64::NAN
                } else {
                    values.iter().sum::<f64>() / values.len() as f64
                }
            }
            DataType::Int32 => {
                let values: Vec<i32> = series
                    .i32()?
                    .into_iter()
                    .filter_map(|v| v)
                    .collect();
                if values.is_empty() {
                    f64::NAN
                } else {
                    values.iter().sum::<i32>() as f64 / values.len() as f64
                }
            }
            DataType::Int64 => {
                let values: Vec<i64> = series
                    .i64()?
                    .into_iter()
                    .filter_map(|v| v)
                    .collect();
                if values.is_empty() {
                    f64::NAN
                } else {
                    values.iter().sum::<i64>() as f64 / values.len() as f64
                }
            }
            _ => return Err(PolarsError::ComputeError(
                "Unsupported data type. Only numeric types are supported.".into(),
            )),
        };

        // Fill nulls with the calculated mean
        let filled = series.fill_null(FillNullStrategy::Mean)?;
        result_cols.push(filled);
    }

    DataFrame::new(result_cols)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
