use ndarray::{Array2, Axis};

/// Sorts a 2D table (Array2<f64>) by columns `col0` and `col1` in ascending order.
///
/// # Arguments
/// * `df` - The input 2D table (Array2<f64>)
/// * `col0` - Index of the first column to sort by
/// * `col1` - Index of the second column to sort by
///
/// # Returns
/// A new Array2<f64> with rows sorted by the specified columns
pub fn sort_by_columns(df: &Array2<f64>, col0: usize, col1: usize) -> Array2<f64> {
    // Create a copy of the original data to avoid modifying it
    let mut df = df.clone();

    // Create a vector of indices (0..rows) to sort
    let mut indices = (0..df.nrows()).collect::<Vec<_>>();

    // Sort the indices based on the values in col0 and col1
    indices.sort_by(|&i, &j| {
        // Compare col0 first
        let cmp0 = df[[i, col0]].partial_cmp(&df[[j, col0]]).unwrap_or(std::cmp::Ordering::Equal);

        // If col0 values are equal, compare col1
        if cmp0 == std::cmp::Ordering::Equal {
            df[[i, col1]].partial_cmp(&df[[j, col1]]).unwrap_or(std::cmp::Ordering::Equal)
        } else {
            cmp0
        }
    });

    // Create a new array with rows reordered
    let mut result = Array2::zeros((df.nrows(), df.ncols()));
    for (i, &idx) in indices.iter().enumerate() {
        result.row(i).assign(&df.row(idx));
    }

    result
}

