/// * `Err(String)` - An error message if the points have different lengths
///
/// # Example
/// ```
/// let p1 = vec![1.0, 2.0, 3.0];
/// let p2 = vec![4.0, 5.0, 6.0];
/// let distance = euclidean_distance(&p1, &p2).unwrap();
/// assert!((distance - 5.196152422706632).abs() < 1e-10);
/// ```
pub fn euclidean_distance(point1: &[f64], point2: &[f64]) -> Result<f64, String> {
    if point1.len() != point2.len() {
        return Err(format!(
            "Points must have the same dimensionality. Got {} and {}",
            point1.len(),
            point2.len()
        ));
    }

    if point1.is_empty() {
        return Ok(0.0);
    }

    // Convert slices to ndarray views for efficient computation
    let arr1 = ArrayView1::from(point1);
    let arr2 = ArrayView1::from(point2);

    // Calculate Euclidean distance using vectorized operations
    let diff = &arr1 - &arr2;
    let squared_sum = diff.dot(&diff);

    Ok(squared_sum.sqrt())
}

