use indexmap::IndexMap;
use std::collections::HashMap;

fn sort_dict(dict0: HashMap<String, i32>) -> IndexMap<String, i32> {
    // Convert HashMap to Vec of tuples (key, value)
    let mut vec: Vec<(String, i32)> = dict0.into_iter().collect();

    // Sort the vector first by values and then by keys
    vec.sort_unstable_by(|a, b| {
        let cmp = a.1.cmp(&b.1); // Compare by value
        if cmp == std::cmp::Ordering::Equal {
            a.0.cmp(&b.0) // If values are equal, compare by key
        } else {
            cmp
