```rust
use polars::prelude::*;

/// Return a new DataFrame containing only the rows of `df0` whose elements in
/// each row sum to a non-zero value (treats null as 0; booleans as 1/0).
///
/// Numeric types supported: integers (signed/unsigned), floats. For Utf8
/// values we attempt to parse them as f64; if parsing fails the value is
/// treated as 0. Lists/structs and other complex types are ignored (treated as 0).
///
/// Comparison to zero uses an absolute epsilon to be robust to floating point noise.
pub fn filter_nonzero_row_sums(df0: &DataFrame) -> PolarsResult<DataFrame> {
    const EPS: f64 = 1e-12;
    let height = df0.height();
    let mut keep_idx: Vec<u32> = Vec::with_capacity(height);

    for row_idx in 0..height {
        // get_row returns a Vec<AnyValue<'_>> (owned values), iterate and sum
        let row = df0.get_row(row_idx);
        let mut sum = 0.0_f64;

        for av in row {
            match av {
                AnyValue::Int8(v) => sum += v as f64,
                AnyValue::Int16(v) => sum += v as f64,
                AnyValue::Int32(v) => sum += v as f64,
                AnyValue::Int64(v) => sum += v as f64,
                AnyValue::UInt8(v) => sum += v as f64,
                AnyValue::UInt16(v) => sum += v as f64,
                AnyValue::UInt32(v) => sum += v as f64,
                AnyValue::UInt64(v) => sum += v as f64,
                AnyValue::Float32(v) => sum += v as f64,
                AnyValue::Float64(v) => sum += v,
                AnyValue::Boolean(b) => sum += if b { 1.0 } else { 0.0 },
                AnyValue::Null => {} // treat null as 0
                AnyValue::Utf8(s) => {
                    if let Ok(x) = s.parse::<f64>() {
                        sum += x;
                    }
                    // else treat non-parsable strings as 0
                }
                // fall back: treat unsupported/complex types as 0
                _ => {}
            }
        }

        if sum.abs() > EPS {
            keep_idx.push(row_idx as u32);
        }
    }

