use sqlx::PgPool;
use thiserror::Error;

#[derive(Error, Debug)]
pub enum UpdateError {
    #[error("Database error: {0}")]
    DatabaseError(#[from] sqlx::Error),
}

/// Updates entries in the specified column of a table based on conditions applied to another column.
/// 
/// # Arguments
/// 
/// * `pool`: A connection pool for the database.
/// * `table_name`: The name of the table to update.
/// * `col_update`: The column to set to the new value.
/// * `col_condition`: The column to check the condition against.
/// * `new_val`: The new value to set in `col_update`.
/// * `condition_val`: The value to compare against in `col_condition`.
async fn update_table(
    pool: &PgPool,
    table_name: &str,
    col_update: &str,
    col_condition: &str,
    new_val: &str,
    condition_val: i32,
) -> Result<u64, UpdateError> {
    let query = format!(
        "UPDATE {} SET {} = $1 WHERE {} > $2",
        table_name, col_update, col_condition
    );

    let result = sqlx::query(&query)
        .bind(new_val)
        .bind(condition_val)
        .execute(pool)
        .await?;

    Ok(result.rows_affected())
}
