use polars::prelude::*;
use polars::lazy::dsl::{col, when, lit};

/// Update numeric column `col_update` in-place: set to `new_val` wherever
/// `col_condition` > `condition_val`.
///
/// - df: mutable reference to the DataFrame to update
/// - col_condition: name of the column to test (must be numeric, castable to Float64)
/// - condition_val: numeric threshold
/// - col_update: name of the column to update (must be numeric)
/// - new_val: numeric value to assign when condition matches
///
/// Returns PolarsResult<()> (Ok on success; an error if column names/types are invalid).
fn update_where_gt_numeric(
    df: &mut DataFrame,
    col_condition: &str,
    condition_val: f64,
    col_update: &str,
    new_val: f64,
) -> PolarsResult<()> {
    // Build a lazy expression that replaces col_update with new_val when condition holds
    let lf = df.clone().lazy().with_column(
        when(col(col_condition).gt(lit(condition_val)))
            .then(lit(new_val))
            .otherwise(col(col_update))
            .alias(col_update),
    );

    // Collect back into a DataFrame and overwrite the original
    let new_df = lf.collect()?;
    *df = new_df;
    Ok(())
}

