/// - input: any IntoIterator of (K, V), where K and V implement Serialize.
/// - spec: desired output element type for both key and value (String, i64, f64, bool, Json).
///
/// Returns a Vec<OutputTuple> where every element has the same variant (as chosen by `spec`),
/// or a ConvertError if any item cannot be converted to the requested type.
pub fn mapping_to_tuples<K, V, I>(
    input: I,
    spec: TypeSpec,
) -> Result<Vec<OutputTuple>, ConvertError>
where
    K: Serialize,
    V: Serialize,
    I: IntoIterator<Item = (K, V)>,
{
    let mut out = Vec::new();

    for (idx, (k, v)) in input.into_iter().enumerate() {
        // Serialize to serde_json::Value first; this gives a uniform view of the data.
        let kv = serde_json::to_value(&k).map_err(ConvertError::Serialize)?;
        let vv = serde_json::to_value(&v).map_err(ConvertError::Serialize)?;

        match spec {
            TypeSpec::Json => {
                out.push(OutputTuple::Json((kv, vv)));
            }
            TypeSpec::String => {
                // Strings: prefer actual strings, otherwise use JSON text representation
                let ks = match kv {
                    JsonValue::String(s) => s,
                    other => serde_json::to_string(&other).map_err(ConvertError::Serialize)?,
                };
                let vs = match vv {
                    JsonValue::String(s) => s,
                    other => serde_json::to_string(&other).map_err(ConvertError::Serialize)?,
                };
                out.push(OutputTuple::Str((ks, vs)));
            }
            TypeSpec::I64 => {
                // Try to extract i64 directly, or parse from stringified JSON if needed.
                let ki = match kv {
                    JsonValue::Number(n) => n.as_i64().ok_or(ConvertError::TypeMismatch {
                        wanted: "i64",
                        found: format!("{:?}", JsonValue::Number(n)),
                        index: idx,
                        side: "key",
                    })?,
                    JsonValue::String(s) => {
                        s.parse::<i64>().map_err(ConvertError::ParseInt)?
                    }
                    other => {
                        return Err(ConvertError::TypeMismatch {
                            wanted: "i64",
                            found: format!("{:?}", other),
                            index: idx,
                            side: "key",
                        });
                    }
                };
                let vi = match vv {
                    JsonValue::Number(n) => n.as_i64().ok_or(ConvertError::TypeMismatch {
                        wanted: "i64",
                        found: format!("{:?}", JsonValue::Number(n)),
                        index: idx,
                        side: "value",
                    })?,
                    JsonValue::String(s) => {
                        s.parse::<i64>().map_err(ConvertError::ParseInt)?
                    }
                    other => {
                        return Err(ConvertError::TypeMismatch {
                            wanted: "i64",
                            found: format!("{:?}", other),
                            index: idx,
                            side: "value",
                        });
                    }
                };
                out.push(OutputTuple::I64((ki, vi)));
            }
            TypeSpec::F64 => {
                let kf = match kv {
                    JsonValue::Number(n) => n.as_f64().ok_or(ConvertError::TypeMismatch {
                        wanted: "f64",
                        found: format!("{:?}", JsonValue::Number(n)),
                        index: idx,
                        side: "key",
                    })?,
                    JsonValue::String(s) => s.parse::<f64>().map_err(ConvertError::ParseFloat)?,
                    other => {
                        return Err(ConvertError::TypeMismatch {
                            wanted: "f64",
                            found: format!("{:?}", other),
                            index: idx,
                            side: "key",
                        });
                    }
                };
                let vf = match vv {
                    JsonValue::Number(n) => n.as_f64().ok_or(ConvertError::TypeMismatch {
                        wanted: "f64",
                        found: format!("{:?}", JsonValue::Number(n)),
                        index: idx,
                        side: "value",
                    })?,
                    JsonValue::String(s) => s.parse::<f64>().map_err(ConvertError::ParseFloat)?,
                    other => {
                        return Err(ConvertError::TypeMismatch {
                            wanted: "f64",
                            found: format!("{:?}", other),
                            index: idx,
                            side: "value",
                        });
                    }
                };
                out.push(OutputTuple::F64((kf, vf)));
            }
            TypeSpec::Bool => {
                let kb = match kv {
                    JsonValue::Bool(b) => b,
                    JsonValue::String(s) => match s.as_str() {
                        "true" | "True" | "1" => true,
                        "false" | "False" | "0" => false,
                        _ => {
                            return Err(ConvertError::TypeMismatch {
                                wanted: "bool",
                                found: s,
                                index: idx,
                                side: "key",
                            })
                        }
                    },
                    other => {
                        return Err(ConvertError::TypeMismatch {
                            wanted: "bool",
                            found: format!("{:?}", other),
                            index: idx,
                            side: "key",
                        });
                    }
                };
                let vb = match vv {
                    JsonValue::Bool(b) => b,
                    JsonValue::String(s) => match s.as_str() {
                        "true" | "True" | "1" => true,
                        "false" | "False" | "0" => false,
                        _ => {
                            return Err(ConvertError::TypeMismatch {
                                wanted: "bool",
                                found: s,
                                index: idx,
                                side: "value",
                            })
                        }
                    },
                    other => {
                        return Err(ConvertError::TypeMismatch {
                            wanted: "bool",
                            found: format!("{:?}", other),
                            index: idx,
                            side: "value",
                        });
                    }
                };
                out.push(OutputTuple::Bool((kb, vb)));
            }
        }
    }

    Ok(out)
}

