use dashmap::DashMap;

/// Set `var0` in `dict0` to `new_value` only if the current entry is `None`.
///
/// - dict0: a DashMap storing Option<V> values (None represents "null").
/// - var0: the key to set.
/// - new_value: the value to set if the current entry is None.
///
/// This is thread-safe when `dict0` is shared among threads.
fn set_if_null<K, V>(dict0: &DashMap<K, Option<V>>, var0: K, new_value: V)
where
    K: std::hash::Hash + Eq,
{
    // Get an entry for the key; insert None if the key is absent.
    let mut entry_ref = dict0.entry(var0).or_insert(None);
    // Only replace if the current option is None.
    if entry_ref.is_none() {
        *entry_ref = Some(new_value);
    }
}

fn main() {
