/// assert_eq!(concatenate(&[1, 2, 3]), Some(123));
/// assert_eq!(concatenate(&[0, 0, 0]), Some(0));
/// assert_eq!(concatenate(&[123456789, 987654321]), None); // Would overflow
/// ```
pub fn concatenate(numbers: &[i64]) -> Option<u128> {
    if numbers.is_empty() {
        return Some(0);
    }

    let mut result: u128 = 0;

    for &num in numbers {
        // Handle negative numbers by taking absolute value
        let abs_num = num.unsigned_abs() as u128;

        // Count digits of the current number
        let digits = if abs_num == 0 {
            1
        } else {
            abs_num.ilog10() + 1
