        // Check for overflow before multiplication
        let multiplier = 10u128.pow(digits);
        if result.checked_mul(multiplier).and_then(|r| r.checked_add(abs_num)).is_none() {
            return None;
        }

        result = result * multiplier + abs_num;
    }

    Some(result)
}

