/// ```
pub fn check_sublists<T: PartialEq>(list: &[T]) -> Vec<bool> {
    let mut result = Vec::new();
    let mut current_sublist = Vec::new();

    for (i, &item) in list.iter().enumerate() {
        if i == 0 {
            current_sublist.push(item);
        } else {
