use itertools::Itertools;

/// Generate a new sequence by alternately taking elements from the first input sequence
/// and from the second input sequence in reverse order.
fn alternate_sequences(lst0: Vec<i32>, lst1: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::new();
    let mut iter0 = lst0.into_iter();
    let mut iter1 = lst1.into_iter().rev();

    loop {
        match (iter0.next(), iter1.next()) {
            (Some(x), Some(y)) => {
                result.push(x);
                result.push(y);
            }
            (Some(x), None) => {
                result.push(x);
                result.extend(iter0);
                break;
            }
            (None, Some(y)) => {
                result.push(y);
                result.extend(iter1);
                break;
            }
            (None, None) => break,
        }
    }

    result
}

fn main() {
    let lst0 = vec![1, 2, 3];
    let lst1 = vec![4, 5, 6, 7];

    let result = alternate_sequences(lst0, lst1);
    println!("{:?}", result);  // Output: [1, 7, 2, 6, 3, 5, 4]
}
```

