    let mut result = Vec::new();
    let mut lst1_rev = lst1;
    lst1_rev.reverse();

    let max_len = lst0.len().max(lst1_rev.len());

    for i in 0..max_len {
        if i < lst0.len() {
            result.push(lst0[i].clone());
        }
        if i < lst1_rev.len() {
            result.push(lst1_rev[i].clone());
        }
    }

    result
}

