///
/// let sorted = sort_dataset(data, vec!["name".to_string()]).unwrap();
/// assert_eq!(sorted["name"], vec!["Alice", "Bob", "Charlie"]);
/// ```
pub fn sort_dataset(
    data0: HashMap<String, Vec<&str>>,
    cols0: Vec<String>,
) -> Result<HashMap<String, Vec<String>>, PolarsError> {
    // Convert HashMap to DataFrame
    let mut df_builder = DataFrame::new_no_check(Vec::new());

    // Build series from the HashMap
    let mut series_vec: Vec<Series> = Vec::new();
    for (col_name, values) in &data0 {
        let series = Series::new(col_name, values);
        series_vec.push(series);
    }

    // Create DataFrame from series
    let df = DataFrame::new(series_vec)?;

    // Sort the DataFrame by specified columns
    let sort_columns: Vec<&str> = cols0.iter().map(|s| s.as_str()).collect();
    let sorted_df = df.sort(sort_columns, SortMultipleOptions::default())?;

