use ndarray::{Array2, Axis};

/// Subtracts the mean of each row from every element in that row.
///
/// Input:
/// - df0: 2-D array (rows x cols)
///
/// Returns:
/// - A new Array2<f64> with the same shape as df0 where each row has had its mean subtracted.
/// - If df0 has zero columns, the original array is returned (nothing to center).
pub fn subtract_row_means(mut df0: Array2<f64>) -> Array2<f64> {
    // If there are no columns, mean_axis would return None — just return a clone.
    if df0.ncols() == 0 {
        return df0;
    }

    // mean_axis(Axis(1)) computes the mean along columns for each row -> 1-D array of length nrows
    let means = df0
        .mean_axis(Axis(1))
        .expect("mean_axis failed; this should only happen for empty axis")
        .to_owned();

    // Subtract the corresponding mean from each row in-place on a clone
    // Work on a clone so we return a new array and don't mutate caller data unexpectedly.
    let mut out = df0.clone();
    for (mut row, &m) in out.axis_iter_mut(Axis(0)).zip(means.iter()) {
        // subtract scalar m from every element in the row
        row.mapv_inplace(|x| x - m);
    }

    out
}

fn main() {
    // Example usage:
    let df0 = Array2::from_shape_vec((3, 4), vec![
        1.0, 2.0, 3.0, 4.0,
        10.0, 20.0, 30.0, 40.0,
        -1.0, -2.0, -3.0, -4.0,
    ]).unwrap();

    let centered = subtract_row_means(df0);
    println!("Centered:\n{:#?}", centered);
}

