use polars::prelude::*;

fn center_rows(df: &DataFrame) -> PolarsResult<DataFrame> {
    // Convert DataFrame to iterator of Series (rows)
    let mut centered_cols = Vec::new();

    // Process each column
    for col_name in df.get_column_names() {
        let series = df.column(col_name)?;
        let float_series = series.cast(&DataType::Float64)?;
        let values = float_series.f64()?;

        centered_cols.push((col_name.to_string(), values.into_iter().collect::<Vec<_>>()));
    }

    // Calculate mean for each row and subtract from each element
    let n_rows = df.height();
    let n_cols = df.width();

    let mut result_data: Vec<Vec<f64>> = vec![vec![0.0; n_cols]; n_rows];

    // Fill with original values first
    for (col_idx, (_, col_values)) in centered_cols.iter().enumerate() {
        for (row_idx, val) in col_values.iter().enumerate() {
            if let Some(v) = val {
                result_data[row_idx][col_idx] = *v;
            }
        }
    }

    // Subtract row mean from each element
    for row_idx in 0..n_rows {
        let row_sum: f64 = result_data[row_idx].iter().sum();
        let row_mean = row_sum / n_cols as f64;

        for col_idx in 0..n_cols {
            result_data[row_idx][col_idx] -= row_mean;
        }
    }

    // Convert back to DataFrame
    let mut new_cols = Vec::new();
    for (col_idx, (col_name, _)) in centered_cols.iter().enumerate() {
        let col_data: Vec<f64> = result_data.iter().map(|row| row[col_idx]).collect();
        new_cols.push(Series::new(col_name.clone().into(), col_data));
    }

    DataFrame::new(new_cols)
}

fn main() -> PolarsResult<()> {
