    let new_df = DataFrame::new(new_columns)?;

    // Rename columns to have unique names (original name + "_sum" for duplicates)
    let mut new_columns = Vec::new();
    for (i, col_name) in new_df.get_column_names().into_iter().enumerate() {
        let new_name = if column_groups.get(col_name).unwrap().len() > 1 {
            format!("{}_{}", col_name, "sum")
        } else {
            col_name.clone()
        };
        new_columns.push(new_name);
    }

