use polars::prelude::*;

/// Sum the values of columns with identical headers in a tabular dataset.
///
/// Returns a new DataFrame with each header appearing only once.
fn sum_columns(df: &DataFrame) -> DataFrame {
    let mut result = DataFrame::new(vec![]);
    let mut seen_columns = std::collections::HashSet::new();

    for column in df.columns() {
        if seen_columns.contains(&column.name()) {
            continue;
        }

        let mut series_list = vec![];
        for col in df.columns() {
            if col.name() == column.name() {
                series_list.push(df.column(col.name()).unwrap());
            }
        }

        let sum = series_list
            .into_iter()
            .fold(Series::new(column.name(), &[]), |acc, series| {
                acc + series
            });

        let s = Series::new(column.name(), &[sum.sum().unwrap()]);
        result = result.with_column(s).unwrap();

        seen_columns.insert(column.name().to_string());
    }
    result
}

fn main() {
