use polars::prelude::*;
use std::collections::HashMap;

/// Sum columns with identical headers in `df`, returning a DataFrame where each header appears only once.
/// - Numeric-compatible columns are cast to Float64 and nulls are treated as zero when summing.
/// - If duplicate columns are non-numeric (can't cast to Float64), an error is returned.
pub fn sum_duplicate_columns(df: &DataFrame) -> PolarsResult<DataFrame> {
    let mut map: HashMap<String, Series> = HashMap::new();
    let mut order: Vec<String> = Vec::new();

    for s in df.get_columns() {
        let name = s.name().to_string();

        // Try to cast to float for summation.
        let casted = match s.cast(&DataType::Float64) {
            Ok(mut series_f64) => {
                // Treat nulls as zero for summation (change if you prefer null-propagation)
                series_f64 = series_f64.fill_null(FillNullStrategy::Zero)?;
                series_f64
            }
            Err(_) => {
                // Non-numeric column: if this is a duplicate header we can't sum -> error.
                if map.contains_key(&name) {
                    return Err(PolarsError::Other(
                        format!("Cannot sum duplicate non-numeric column '{}'", name).into(),
                    ));
                } else {
                    // Keep the original non-numeric series (first occurrence) and continue.
                    if !order.contains(&name) {
                        order.push(name.clone());
                    }
                    map.insert(name.clone(), s.clone());
                    continue;
                }
            }
        };

        if !map.contains_key(&name) {
            order.push(name.clone());
            map.insert(name.clone(), casted);
        } else {
            // Sum with existing series (both are Float64 Series).
            let existing = map.get_mut(&name).expect("key present");
            let summed = existing.clone() + &casted; // returns PolarsResult<Series>
            *existing = summed?;
        }
    }

    // Reconstruct DataFrame maintaining the first-seen order of headers.
    let cols: Vec<Series> = order.into_iter().map(|n| map.remove(&n).unwrap()).collect();
    DataFrame::new(cols)
}

fn main() -> PolarsResult<()> {
    // Example CSV with duplicate header "a"
    let csv = "a,b,a\n1,hello,2\n3,world,4\n,foo,5\n";

    // Read CSV from string (has header)
    let df = CsvReader::new(std::io::Cursor::new(csv))
        .has_header(true)
        .finish()?;

    println!("Input DataFrame:\n{}", df);

    let merged = sum_duplicate_columns(&df)?;
    println!("\nMerged DataFrame (duplicate columns summed):\n{}", merged);

    Ok(())
}
