fn sum_duplicate_columns(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut column_groups: std::collections::BTreeMap<String, Vec<Series>> = 
        std::collections::BTreeMap::new();

    // Group columns by their names
    for col_name in df.get_column_names() {
        let series = df.column(col_name)?;
        column_groups
            .entry(col_name.to_string())
            .or_insert_with(Vec::new)
            .push(series.clone());
    }

    // Sum columns with the same name
    let mut result_columns: Vec<Series> = Vec::new();

    for (col_name, series_vec) in column_groups {
