use std::collections::HashMap;
use itertools::Itertools; // partition_map

/// Reorder `lst0` in-place so that all maps where map[var0] == var1
/// come first (preserving relative order), and all other maps come after
/// (also preserving relative order).
///
/// - lst0: mutable vector of HashMap<String, String>
/// - var0: key to look up in each map
/// - var1: value to compare against
///
/// This uses itertools::Itertools::partition_map to perform a stable partition.
pub fn reorder_by_key_value(
    lst0: &mut Vec<HashMap<String, String>>,
    var0: &str,
    var1: &str,
) {
    // Drain to take ownership of elements, partition into two vectors,
    // then extend back into lst0 (first matching, then non-matching).
    let (matching, non_matching): (Vec<_>, Vec<_>) = lst0
        .drain(..)
        .partition_map(|m| {
            if m.get(var0).map(|v| v == var1).unwrap_or(false) {
                itertools::Either::Left(m)
            } else {
                itertools::Either::Right(m)
            }
        });

    lst0.extend(matching);
    lst0.extend(non_matching);
}

