use std::borrow::Borrow;
use std::collections::HashMap;
use std::hash::Hash;
use indexmap::IndexMap;

/// Return a new IndexMap containing only the entries from `input` whose keys
/// appear in `keys_iter`. The returned map preserves the order of `keys_iter`.
///
/// - `input` is the source map (e.g., HashMap).
/// - `keys_iter` is any IntoIterator over items that can borrow a `K`
///   (for example: `&K`, `K`, or `&str` when K = String with appropriate Borrow).
///
/// K and V must be cloneable because the values/keys are copied into the new map.
pub fn pick_keys<K, V, KeysIter, KeyRef>(
    input: &HashMap<K, V>,
    keys_iter: KeysIter,
) -> IndexMap<K, V>
where
    K: Eq + Hash + Clone,
    V: Clone,
    KeysIter: IntoIterator<Item = KeyRef>,
    KeyRef: Borrow<K>,
{
    let mut out = IndexMap::new();
    for key_ref in keys_iter {
        let key_borrow: &K = key_ref.borrow();
        if let Some(value) = input.get(key_borrow) {
            // clone the key (to own it in the new map) and the value
            out.insert(key_borrow.clone(), value.clone());
        }
    }
    out
}

