pub fn iterate_and_apply<F>(df0: Array2<i32>, var0: usize, func: F)
where
    F: Fn(i32) -> i32,
{
    match var0 {
        0 => {
            // Iterate along rows (axis 0)
            for row in df0.axis_iter(Axis(0)) {
