            for col in df0.axis_iter(Axis(1)) {
                for &element in col.iter() {
                    let result = func(element);
                    println!("Applied function to {}: {}", element, result);
                }
            }
        }
        _ => panic!("Invalid axis: {}. Use 0 for rows or 1 for columns.", var0),
    }
}

