/// and return an ordered mapping (IndexMap) with that ordering.
///
/// `dict0` is consumed (moved) into this function and its entries are returned in sorted order.
pub fn sort_by_value_length<K, V>(dict0: HashMap<K, Vec<V>>) -> IndexMap<K, Vec<V>>
