    let mut pairs: Vec<(K, Vec<V>)> = dict0.into_iter().collect();
    pairs.sort_by_key(|(_, v)| v.len());
    let mut ordered = IndexMap::with_capacity(pairs.len());
    for (k, v) in pairs {
