/// assert_eq!(reordered, vec![2, 1, 3]);
pub fn reorder_by_sorted_key<K, V>(lst0: &[K], lst1: &[V]) -> Result<Vec<V>, &'static str>
where
    K: Ord + Clone,
    V: Clone,
{
    if lst0.len() != lst1.len() {
