    let reordered: Vec<V> = lst0
        .iter()
        .cloned()
        .zip(lst1.iter().cloned())
        .sorted_by_key(|(k, _)| k.clone()) // stable sort by the key
        .map(|(_, v)| v)
        .collect();

    Ok(reordered)
}

