/// assert_eq!(result, vec!['b', 'c', 'a']);
/// // Sorting lst0: [3,1,2] -> [1,2,3] at indices [1,2,0]
/// // Apply same reordering to lst1: ['a','b','c'] -> ['b','c','a']
/// ```
fn reorder_by_sort_sequence<T, U>(lst0: &[T], lst1: &[U]) -> Vec<U>
where
    T: Ord,
    U: Clone,
{
    // Create pairs of (index, value) for lst0
    let mut indexed: Vec<(usize, &T)> = lst0.iter().enumerate().collect();

