    indexed.sort_by(|a, b| a.1.cmp(b.1));

    // Extract the indices in sorted order
    let sort_indices: Vec<usize> = indexed.iter().map(|(idx, _)| *idx).collect();

    // Reorder lst1 using the sort indices from lst0
    sort_indices.iter().map(|&i| lst1[i].clone()).collect()
}

