use itertools::Itertools;

/// Sorts the text elements in ascending order by default, but sorts those at the specified positions in descending order.
///
/// # Arguments
///
/// * `text_elements`: A vector of text elements to be sorted.
/// * `positions`: An optional vector of integer positions. If provided, elements at these positions will be sorted in descending order.
///
/// # Returns
///
/// A vector of sorted text elements.
pub fn custom_sort(text_elements: Vec<String>, positions: Option<Vec<usize>>) -> Vec<String> {
    let mut sorted_elements: Vec<String> = text_elements.clone();
    sorted_elements.sort();

    if let Some(positions) = positions {
        // Sort elements at specified positions in descending order
        for &position in &positions {
            if position < sorted_elements.len() {
                sorted_elements[position] = sorted_elements[position].clone();
            }
        }

        // Sort the elements at specified positions in descending order
        let mut elements_at_positions: Vec<String> = positions
            .into_iter()
            .filter_map(|position| sorted_elements.get(position))
            .cloned()
            .collect();
        elements_at_positions.sort_by(|a, b| b.cmp(a));

        // Replace the elements at specified positions with the sorted ones
        let mut index = 0;
        for &position in &positions {
            if position < sorted_elements.len() {
                sorted_elements[position] = elements_at_positions[index].clone();
                index += 1;
            }
        }
    }

    sorted_elements
}

