    let var0 = 3;

    let result = indices_of_largest(&lst0, var0);
    println!("Indices of {} largest elements: {:?}", var0, result);
    println!("Values: {:?}", result.iter().map(|&i| lst0[i]).collect::<Vec<_>>());
}

