fn multiply_vector_matrix(vector: &[f64], matrix: &[Vec<f64>]) -> Result<Vec<f64>, String> {
    // Check for compatibility: vector length must match matrix row count
    if matrix.is_empty() {
        return Err("Matrix is empty.".to_string());
