/// let r = multiply_vector_matrix(&v, &m).unwrap(); // r == [14.0, 32.0]
pub fn multiply_vector_matrix(vec: &[f64], mat: &[Vec<f64>]) -> Result<Vec<f64>, String> {
    let n = mat.len();
    if vec.len() != n {
        return Err(format!(
            "Dimension mismatch: vector length {} != matrix row count {}",
            vec.len(),
            n
        ));
    }

    // Determine number of columns (m). If there are zero rows, treat as zero columns.
    let m = if n == 0 { 0 } else { mat[0].len() };

    // Check that all rows have the same number of columns.
    for (i, row) in mat.iter().enumerate() {
        if row.len() != m {
            return Err(format!(
                "Inconsistent row length at row {}: expected {}, found {}",
                i,
                m,
                row.len()
            ));
        }
    }

    // Result is a row vector of length m, initialize with zeros.
