/// Multiplies a vector by a matrix (vector * matrix)
/// 
/// # Arguments
/// * `vector` - A slice of f64 values (1 × n)
/// * `matrix` - A 2D vector of f64 values (n × m)
///
/// # Returns
/// A vector of f64 values (1 × m) representing the result
///
/// # Panics
/// Panics if the vector length doesn't match the number of rows in the matrix
fn multiply_vector_by_matrix(vector: &[f64], matrix: &[Vec<f64>]) -> Vec<f64> {
    // Validate dimensions
    if vector.is_empty() || matrix.is_empty() {
        panic!("Vector and matrix must not be empty");
    }

    let num_rows = matrix.len();
    let num_cols = matrix[0].len();

    if vector.len() != num_rows {
        panic!(
            "Vector length ({}) must match matrix rows ({})",
            vector.len(),
            num_rows
        );
    }

    // Validate all rows have the same number of columns
    for (i, row) in matrix.iter().enumerate() {
        if row.len() != num_cols {
            panic!(
                "Matrix row {} has {} columns, expected {}",
                i,
                row.len(),
                num_cols
            );
        }
    }

    // Perform multiplication: result[j] = sum(vector[i] * matrix[i][j])
    (0..num_cols)
        .map(|col| {
            (0..num_rows)
                .map(|row| vector[row] * matrix[row][col])
                .sum()
        })
        .collect()
}

