use indexmap::IndexMap;
use num_traits::ToPrimitive;
use std::hash::Hash;

/// For each key present in both `a` and `b`, divide a[key] by b[key] and
/// include the result in the returned IndexMap.
///
/// - Keys present in `a` but not in `b` are ignored.
/// - Keys present in `b` but not in `a` are ignored.
/// - If either value cannot be converted to f64, or the denominator converts
///   to zero, that key is skipped (no division performed).
///
/// Generic over key type K and numeric type V (which must implement ToPrimitive).
pub fn divide_common<K, V>(a: &IndexMap<K, V>, b: &IndexMap<K, V>) -> IndexMap<K, f64>
where
    K: Eq + Hash + Clone,
    V: ToPrimitive + Copy,
{
    let mut out: IndexMap<K, f64> = IndexMap::new();

    for (k, va) in a.iter() {
        if let Some(vb) = b.get(k) {
            if let (Some(af), Some(bf)) = (va.to_f64(), vb.to_f64()) {
                if bf != 0.0 {
                    out.insert(k.clone(), af / bf);
                }
            }
        }
    }

    out
}

