        let a = indexmap! {
            "x" => 10i32,
            "y" => 6i32,
            "z" => 5i32,
        };
        let b = indexmap! {
            "x" => 2i32,
            "y" => 3i32,
            "w" => 1i32,
        };

        let res = divide_common(&a, &b);
        assert_eq!(res.get("x"), Some(&5.0));
        assert_eq!(res.get("y"), Some(&2.0));
        assert!(res.get("z").is_none()); // z not in b
