use indexmap::IndexMap;

/// Inserts a new sublist into an existing list of sublists while maintaining
/// ascending order by the second element of each sublist.
///
/// # Arguments
/// * `list` - A mutable reference to the list of sublists to modify
/// * `new_sublist` - The sublist to insert
///
