/// ```
pub fn strip_currency_from_penultimate_column<R: Read, W: Write>(
    input: &mut R,
    output: &mut W,
) -> Result<(), Box<dyn Error>> {
    let mut reader = ReaderBuilder::new()
        .has_headers(true)
        .flexible(true)
        .from_reader(input);

    let headers = reader.headers()?.clone();
    let column_count = headers.len();

    if column_count < 2 {
        return Err("Table must have at least 2 columns".into());
    }

    let penultimate_index = column_count - 2;

    let mut writer = WriterBuilder::new()
        .has_headers(true)
        .from_writer(output);

    // Write headers
    writer.write_record(&headers)?;

    // Process each record
    for result in reader.records() {
        let record = result?;
        let mut modified_record: Vec<String> = Vec::new();

        for (i, field) in record.iter().enumerate() {
            if i == penultimate_index {
                // Strip currency symbol and convert to float
