use polars::prelude::*;

/// Strips currency symbols from the penultimate column of a DataFrame
/// and converts entries to floating-point values.
///
/// # Arguments
/// * `df` - A DataFrame with at least 2 columns
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - DataFrame with the penultimate column converted to f64
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "name" => &["Alice", "Bob"],
///     "price" => &["$19.99", "£25.50"],
///     "quantity" => &[1, 2],
/// }.unwrap();
///
/// let result = strip_currency_from_penultimate(df).unwrap();
/// ```
fn strip_currency_from_penultimate(mut df: DataFrame) -> Result<DataFrame, PolarsError> {
    let n_cols = df.width();

    if n_cols < 2 {
        return Err(PolarsError::ComputeError(
            "DataFrame must have at least 2 columns".into(),
        ));
    }

    let penultimate_idx = n_cols - 2;
    let col_name = df.get_column_names()[penultimate_idx].to_string();

    // Get the penultimate column as strings
    let col = df.select([&col_name])?.to_series(0).clone();
    let str_col = col.str()?;

    // Strip currency symbols and convert to f64
    let numeric_col = str_col
        .into_iter()
        .map(|opt_str| {
            opt_str.and_then(|s| {
                // Remove common currency symbols and whitespace
                let cleaned = s
                    .chars()
                    .filter(|c| !c.is_whitespace() && !matches!(c, '$' | '£' | '€' | '¥' | '₹' | '₽' | '¢' | '₩' | '₪' | '₦' | '₨' | '₱' | '₹' | '₺'))
                    .collect::<String>();

                cleaned.parse::<f64>().ok()
            })
        })
        .collect::<Vec<_>>();

    let float_series = Series::new(&col_name, numeric_col);

    // Replace the penultimate column
    df.replace(&col_name, float_series)?;

    Ok(df)
}

