    let id_cols: Vec<&str> = match id_vars {
        Some(ids) => ids.to_vec(),
        None => vec![],
    };

    // Get all columns that are not in lst0 or id_vars (to be dropped)
    let all_cols: Vec<&str> = df0.get_column_names()
        .iter()
        .map(|s| s.as_str())
        .collect();

    let drop_cols: Vec<&str> = all_cols
        .iter()
        .filter(|c| !lst0.contains(c) && !id_cols.contains(c))
        .copied()
        .collect();

