use polars::prelude::*;
use std::collections::HashMap;

/// Build a frequency table counting occurrences of each unique value in the
/// column named "variable" of the input DataFrame `var0`.
///
/// Returns a DataFrame with columns:
/// - "variable": the distinct values (stringified)
/// - "count": the frequency (u32)
pub fn frequency_table(var0: &DataFrame) -> PolarsResult<DataFrame> {
    // Get the "variable" column (returns a Series)
    let series = var0.column("variable")?;

    // Count occurrences by stringifying each value (including nulls as "<NULL>")
    let mut counts: HashMap<String, u32> = HashMap::new();
    for i in 0..series.len() {
        let av = series.get(i);
        let key = match av {
            AnyValue::Null => "<NULL>".to_string(),
            _ => av.to_string(),
        };
        *counts.entry(key).or_insert(0) += 1;
    }

    // Build vectors for the resulting Series
    let mut values: Vec<String> = Vec::with_capacity(counts.len());
    let mut counts_vec: Vec<u32> = Vec::with_capacity(counts.len());
    for (k, v) in counts {
        values.push(k);
        counts_vec.push(v);
    }

    // Create Series and DataFrame
    let s_values = Series::new("variable", values);
    let s_counts = Series::new("count", counts_vec);
    DataFrame::new(vec![s_values, s_counts])
}

