use itertools::Itertools;

fn transpose_tuples<T: Clone>(tuples: Vec<(T, T, T)>) -> Vec<(T, T, T)> {
    let mut result: Vec<(T, T, T)> = vec![];

    if tuples.is_empty() {
        return result;
    }

    // Extract all first elements
    let firsts: Vec<T> = tuples.iter().map(|(a, _, _)| a.clone()).collect();

    // Extract all second elements
    let seconds: Vec<T> = tuples.iter().map(|(_, b, _)| b.clone()).collect();

    // Extract all third elements
    let thirds: Vec<T> = tuples.iter().map(|(_, _, c)| c.clone()).collect();

    // Create result tuples
    result.push((firsts[0].clone(), seconds[0].clone(), thirds[0].clone()));
    result.push((firsts[1].clone(), seconds[1].clone(), thirds[1].clone()));
    result.push((firsts[2].clone(), seconds[2].clone(), thirds[2].clone()));

    result
}

// More generic version using itertools
fn transpose_tuples_generic<T: Clone>(tuples: Vec<(T, T, T)>) -> ((Vec<T>, Vec<T>, Vec<T>)) {
    let (firsts, seconds, thirds) = tuples
        .into_iter()
        .multiunzip();

    (firsts, seconds, thirds)
}

