use polars::prelude::*;

/// Add a new column "A_perc" where each entry is A / sum (as Float64).
/// Returns a new DataFrame; errors if columns are missing or other polars errors occur.
pub fn add_a_perc(df: &DataFrame) -> PolarsResult<DataFrame> {
    // Ensure the columns exist (gives a clearer error than a panic later).
    if df.column("A").is_err() || df.column("sum").is_err() {
        return Err(PolarsError::NotFound(
            "both columns 'A' and 'sum' must exist in the input DataFrame".into(),
        ));
    }

    // Cast both columns to Float64 to perform float division.
    let a_series = df.column("A")?.cast(&DataType::Float64)?;
    let s_series = df.column("sum")?.cast(&DataType::Float64)?;

    // Get typed chunked arrays for elementwise division.
    let a_f64 = a_series.f64()?;
    let s_f64 = s_series.f64()?;

    // Element-wise division -> Float64Chunked. Division by zero yields Null values.
    let perc_chunked = &a_f64 / &s_f64;

    // Convert back to Series and name it "A_perc".
    let perc_series = perc_chunked.into_series().rename("A_perc");

    // Clone input DF, append the new column, and return.
    let mut out = df.clone();
    out.with_column(perc_series)?;
    Ok(out)
}

