use polars::prelude::*;

/// Replace every entry in column `col_name` of `df` that satisfies `condition` with `replacement`.
///
/// - `df` is the input DataFrame (not mutated; a new DataFrame is returned).
/// - `col_name` is the name of the column to replace values in.
/// - `condition` is a boolean Expr (for example: col("age").lt(lit(18)) or col("score").gt(col("threshold"))).
/// - `replacement` is an Expr for the new value (for example: lit(0) or lit("unknown")).
///
/// Returns a new DataFrame with the column modified.
pub fn replace_if(
    df: &DataFrame,
    col_name: &str,
    condition: Expr,
    replacement: Expr,
) -> PolarsResult<DataFrame> {
    // Build an expression that yields replacement where condition is true, otherwise the original column value.
    let new_col_expr = when(condition)
        .then(replacement)
        .otherwise(col(col_name))
        .alias(col_name);

    // Use lazy API to add/replace the column, then collect back to an eager DataFrame.
    df.lazy().with_column(new_col_expr).collect()
}

fn main() -> PolarsResult<()> {
    // Example DataFrame
    let df = df![
        "id" => &[1, 2, 3, 4],
        "score" => &[10, 85, 42, 70],
        "status" => &["ok", "ok", "bad", "ok"]
    ]?;

    println!("Original:\n{}", &df);

    // Replace score values < 50 with 0
    let out = replace_if(&df, "score", col("score").lt(lit(50)), lit(0))?;
    println!("\nScores < 50 replaced with 0:\n{}", &out);

    // Replace status == "bad" with "review"
    let out2 = replace_if(&df, "status", col("status").eq(lit("bad")), lit("review"))?;
    println!("\nstatus 'bad' replaced with 'review':\n{}", &out2);

    Ok(())
}
```

How it works
- The function constructs an expression: when(condition).then(replacement).otherwise(col(col_name)).alias(col_name).
- with_column on a LazyFrame will add or replace the column named `col_name` with that expression, and collect() returns a new eager DataFrame.

This approach is flexible: you can use any boolean expression for the condition (including references to other columns) and any expression or literal for the replacement.

