/// splitting each value at its first space. Values without a space
/// are placed entirely in "str1" and "str2" becomes null. Nulls are preserved.
/// Returns a new DataFrame with the two new columns appended.
///
/// Example:
/// df0:
/// +-------------+
/// | str0        |
/// +-------------+
/// | "hello you" |
/// | "alone"     |
/// | null        |
/// +-------------+
/// -> after calling:
/// +-------------+----------+------+
— | str0        | str1     | str2 |
+-------------+----------+------+
| "hello you" | "hello"  | "you"|
| "alone"     | "alone"  | null |
| null        | null     | null |
+-------------+----------+------+
fn split_str0_into_str1_str2(mut df0: DataFrame) -> PolarsResult<DataFrame> {
    // get the utf8 column
    let col = df0.column("str0")?.utf8()?;

    // prepare vectors to collect the parts
    let mut part1: Vec<Option<&str>> = Vec::with_capacity(col.len());
    let mut part2: Vec<Option<&str>> = Vec::with_capacity(col.len());

    // iterate once and split at the first space
    for opt in col.into_iter() {
        match opt {
            Some(s) => {
                if let Some(pos) = s.find(' ') {
                    part1.push(Some(&s[..pos]));
                    part2.push(Some(&s[pos + 1..]));
                } else {
                    // no space -> whole string in part1, part2 is null
                    part1.push(Some(s));
                    part2.push(None);
                }
            }
            None => {
                part1.push(None);
                part2.push(None);
            }
        }
    }

