    let ca1 = Utf8Chunked::from_opt_iter("str1", part1.into_iter());
    let ca2 = Utf8Chunked::from_opt_iter("str2", part2.into_iter());

    // append the new columns and return the DataFrame
    let df0 = df0.with_column(ca1.into_series())?;
    let df0 = df0.with_column(ca2.into_series())?;
    Ok(df0)
}

