use polars::prelude::*;

/// Compute the element-wise mean across multiple 2D numeric tables (DataFrames).
///
/// - `lst0` must be non-empty.
/// - All DataFrames in `lst0` must have identical column names (in the same order) and the same number of rows.
/// - Numeric columns (integer/float) are cast to Float64 before averaging.
/// - Nulls are ignored when averaging; if all inputs for a cell are null, the output cell is null.
///
/// Returns a DataFrame with the same columns and number of rows.
pub fn mean_tables(lst0: &[DataFrame]) -> PolarsResult<DataFrame> {
    if lst0.is_empty() {
        return Err(PolarsError::NoData("mean_tables: input slice is empty".into()));
    }

    let first = &lst0[0];
    let height = first.height();
    let col_names = first.get_column_names();
    let width = first.width();

    // Validate shapes and column names
    for df in lst0.iter().skip(1) {
        if df.height() != height || df.width() != width || df.get_column_names() != col_names {
            return Err(PolarsError::ShapeMisMatch(
                "mean_tables: all DataFrames must have identical shape and column names".into(),
            ));
        }
    }

    let mut out_series: Vec<Series> = Vec::with_capacity(width);

    for name in col_names.iter() {
        // We'll accumulate sum and counts for each row
        let mut sums = vec![0.0_f64; height];
        let mut counts = vec![0_u32; height];

        for df in lst0.iter() {
            // Cast to Float64 so we can handle ints/floats uniformly
            let s = df.column(name)?.cast(&DataType::Float64)?;
            let ca = s.f64()?;
            for (i, opt_val) in ca.into_iter().enumerate() {
                if let Some(v) = opt_val {
                    sums[i] += v;
                    counts[i] += 1;
                }
            }
        }

        // Compute means, producing Option<f64> (None when count==0)
        let means: Vec<Option<f64>> = sums
            .into_iter()
            .zip(counts.into_iter())
            .map(|(sum, cnt)| if cnt == 0 { None } else { Some(sum / (cnt as f64)) })
            .collect();

        out_series.push(Series::new(name.as_str(), means));
    }

    DataFrame::new(out_series)
}

