/// Extracts a contiguous slice of columns from a Polars DataFrame.
///
/// # Arguments
/// * `df0` - The input DataFrame
/// * `start_column0` - The starting column index (inclusive)
/// * `end_column0` - The ending column index (inclusive)
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - The sliced DataFrame or an error
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "A" => &[1, 2, 3],
///     "B" => &[4, 5, 6],
///     "C" => &[7, 8, 9],
///     "D" => &[10, 11, 12],
/// }.unwrap();
///
/// let result = extract_column_slice(&df, 1, 2).unwrap();
/// // Returns DataFrame with columns "B" and "C"
/// ```
fn extract_column_slice(
    df0: &DataFrame,
    start_column0: usize,
    end_column0: usize,
) -> Result<DataFrame, PolarsError> {
    // Validate indices
    let num_cols = df0.width();
    if start_column0 >= num_cols || end_column0 >= num_cols || start_column0 > end_column0 {
        return Err(PolarsError::ComputeError(
            format!(
                "Invalid column indices: start={}, end={}, total_columns={}",
                start_column0, end_column0, num_cols
            )
            .into(),
        ));
    }

    // Extract column names in the specified range
    let column_names: Vec<&str> = df0
        .get_columns()
        .iter()
        .enumerate()
        .filter(|(idx, _)| *idx >= start_column0 && *idx <= end_column0)
        .map(|(_, col)| col.name())
        .collect();

    // Select the columns and return
    df0.select(column_names)
}

fn main() -> Result<(), PolarsError> {
