/// then reset the row index by adding a new "index" column (0..n-1) at the front.
///
/// - df0: input DataFrame (not consumed)
/// - var0: name of the column to check membership for
/// - lst0: slice of values to keep (string values in this example)
///
/// Returns a new DataFrame with only matching rows and a fresh "index" column.
pub fn filter_and_reset_index(
    df0: &DataFrame,
    var0: &str,
    lst0: &[&str],
) -> PolarsResult<DataFrame> {
    // Build a Series from lst0 (lookup values)
    let lookup = Series::new("lookup", lst0);

    // Get column to filter on
    let col = df0.column(var0)?;

    // Compute boolean mask: values in col that are in lookup
    let mask = col.is_in(&lookup)?;

    // Apply filter
    let filtered = df0.filter(&mask)?;

    // Reset the row index by adding a new "index" column starting at 0.
    // with_row_count inserts the new column at position 0.
    // Some(0) indicates starting offset 0.
    let reset = filtered.with_row_count("index", Some(0))?;

    Ok(reset)
}

fn main() -> PolarsResult<()> {
    // Example DataFrame
    let df0 = DataFrame::new(vec![
        Series::new("var0", &["a", "b", "c", "a"]),
        Series::new("value", &[10i32, 20, 30, 40]),
    ])?;

    // Values to keep
    let keep = ["a", "c"];

    // Apply function
    let result = filter_and_reset_index(&df0, "var0", &keep)?;

    println!("{}", &result);
    Ok(())
}
```

