use polars::prelude::*;
use std::error::Error;

/// Groups rows by `group_col` and sums all other numeric columns.
///
/// # Arguments
/// * `df` - Input DataFrame
/// * `group_col` - Column name to group by
///
/// # Returns
/// Result<DataFrame, Box<dyn Error>> - Aggregated DataFrame or error
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "var0" => &[1, 1, 2, 2],
///     "var1" => &[10.0, 20.0, 30.0, 40.0],
///     "var2" => &[100, 200, 300, 400]
/// ).unwrap();
///
/// let result = group_and_sum(&df, "var0").unwrap();
/// println!("{:?}", result);
/// ```
pub fn group_and_sum(df: &DataFrame, group_col: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Get all column names except the group column
    let all_cols: Vec<String> = df.column_names()?.to_vec();
    let other_cols: Vec<String> = all_cols
        .into_iter()
        .filter(|col| col != group_col)
        .collect();

    // Create aggregation expressions for each numeric column
    let mut agg_exprs = Vec::new();
    for col in &other_cols {
        // Check if column is numeric (int or float)
        let col_type = df.column(col)?.dtype();
        if col_type.is_numeric() {
            agg_exprs.push(colars::expr::sum(col));
        }
    }

    // Create the aggregation expression
    let agg_expr = if agg_exprs.is_empty() {
        // If no numeric columns to sum, just return the group column
        colars::expr::all()
    } else {
        // Group by and sum other columns
        colars::expr::all()
            .group_by(group_col)
            .agg(agg_exprs)
    };

    // Execute the aggregation
    let result = df.lazy().select(&[agg_expr])?.collect()?;

    Ok(result)
}

