use polars::prelude::*;
use std::collections::HashMap;

/// Replace nulls in categorical/text columns with the most frequent category (mode) for each column.
///
/// - Only Utf8 (string) and Categorical typed columns are touched.
/// - If a column has no non-null values, it is left unchanged.
/// - Returns a new DataFrame with the replacements applied.
pub fn fill_missing_categorical_with_mode(df0: &DataFrame) -> PolarsResult<DataFrame> {
    // Work on a clone so we can mutate columns
    let mut df = df0.clone();

    for idx in 0..df.width() {
        let s = df.select_at_idx(idx).expect("column index valid").clone();

        // Consider text/categorical columns only
        match s.dtype() {
            DataType::Utf8 | DataType::Categorical => {
                // Get a Utf8 view of the series
                if let Ok(utf8) = s.utf8() {
                    // Count occurrences of each non-null value
                    let mut counts: HashMap<String, usize> = HashMap::new();
                    for opt in utf8.into_iter() {
                        if let Some(v) = opt {
                            *counts.entry(v.to_string()).or_insert(0) += 1;
                        }
                    }

                    // If there are no non-null values, skip this column
                    if counts.is_empty() {
                        continue;
                    }

                    // Find the mode (most frequent string). If tie, picks one arbitrarily.
                    let mode = counts
                        .into_iter()
                        .max_by_key(|&(_, count)| count)
                        .map(|(val, _)| val)
                        .expect("non-empty counts");

                    // Build a new Vec<Option<String>> where nulls are replaced with mode
                    let filled: Vec<Option<String>> = s
                        .utf8()
                        .expect("utf8 view")
                        .into_iter()
                        .map(|opt| match opt {
                            Some(v) => Some(v.to_string()),
                            None => Some(mode.clone()),
                        })
                        .collect();

                    // Construct a new series and replace the column in the DataFrame
                    let new_series = Series::new(s.name(), filled);
                    df.replace(s.name(), &new_series)?;
                }
            }
            _ => {
                // leave other types unchanged
            }
        }
    }

    Ok(df)
}

fn main() -> PolarsResult<()> {
    // Example usage
    let df0 = df![
        "id" => &[1, 2, 3, 4],
        // categorical columns with some missing entries
        "color" => &[Some("red"), None, Some("blue"), Some("red")],
        "shape" => &[None, None, Some("circle"), Some("circle")]
    ]?;

    println!("Original:\n{}", &df0);

    let filled = fill_missing_categorical_with_mode(&df0)?;
    println!("Filled:\n{}", &filled);

    Ok(())
}
```

