///
/// # Returns
/// * Result containing the modified DataFrame with nulls replaced by mode values
fn fill_missing_with_mode(df: &DataFrame) -> PolarsResult<DataFrame> {
    let mut new_df = df.clone();

    // Iterate through each column
    for col_name in df.get_column_names() {
        let series = df.column(col_name)?;

