use polars::prelude::*;
use std::collections::{HashMap, HashSet};

/// Split df0 into subsets by distinct values of column "var0".
/// Returns a HashMap mapping the stringified value of var0 -> subset DataFrame.
/// - The function first casts `var0` to Utf8 (string) so non-string columns are supported.
/// - Nulls are represented by the string "<NULL>" as the map key.
///
/// Example:
/// let subsets = split_by_var0(&df0)?;
/// for (key, sub) in subsets { println!("key={} rows={}", key, sub.height()); }
pub fn split_by_var0(df0: &DataFrame) -> PolarsResult<HashMap<String, DataFrame>> {
    // Ensure the column exists and cast it to Utf8 so we can compare string representations.
    let series = df0
        .column("var0")?
        .cast(&DataType::Utf8)?; // cast to Utf8 if necessary
    let col = series.utf8()?;

    // Collect all values from the column as Option<&str>, preserving row order
    let values: Vec<Option<&str>> = col.into_iter().collect();

    // Determine distinct string keys preserving their first-seen order
    let mut seen: HashSet<String> = HashSet::new();
    let mut keys: Vec<String> = Vec::new();
    for opt in &values {
        let key = match opt {
            Some(s) => s.to_string(),
            None => "<NULL>".to_string(),
        };
        if seen.insert(key.clone()) {
            keys.push(key);
        }
    }

    // For each distinct key build a boolean mask and filter the original DataFrame
    let mut result: HashMap<String, DataFrame> = HashMap::with_capacity(keys.len());
    for key in keys {
        // Build boolean vector mask for this key
        let mask_bools: Vec<bool> = values
            .iter()
            .map(|opt| match opt {
                Some(s) => s == key.as_str(),
                None => key == "<NULL>",
            })
            .collect();

        let mask = BooleanChunked::new_from_slice("mask", &mask_bools);
        let subset = df0.filter(&mask)?;
        result.insert(key, subset);
    }

    Ok(result)
}

