    let df0 = df![
        "var0" => &["apple", "banana", "apple", "orange", "banana",],
        "value" => &[10, 20, 30, 40, 50]
    ]?;

    let subsets = split_by_var0(&df0)?;
    for (k, df) in subsets {
        println!("Key: {} -> {} rows", k, df.height());
        println!("{:?}", df);
    }

    Ok(())
