///
/// Input: df0 - a polars::prelude::DataFrame
/// Output: Result<DataFrame, PolarsError> with columns dropped as required.
fn remove_columns_with_max_gt_zero(mut df0: DataFrame) -> PolarsResult<DataFrame> {
    // Collect column names
    let col_names: Vec<String> = df0.get_column_names().iter().cloned().collect();

    // Build expressions that compute the max for each column, alias them with the same name
    let exprs: Vec<Expr> = col_names.iter().map(|name| col(name).max().alias(name)).collect();

    // Compute maxima as a single-row DataFrame using the lazy API
    let max_df = df0.clone().lazy().select(exprs).collect()?;

