    let new_col = when(df0.column(col0).unwrap())
        .eq(var0)
        .then(lit(var1))
        .otherwise(lit(var0))
        .alias(col0);

    // Replace the original column with the new one
    df0 = df0.with_column(new_col).unwrap();

    df0
}

