use polars::prelude::*;
use polars::lazy::prelude::*;

/// Aggregation choices supported by the function.
#[derive(Copy, Clone, Debug)]
pub enum AggFunction {
    Sum,
    Mean,
    Min,
    Max,
    Median,
    Count,
}

/// Group `df0` by `var0`, aggregate the column `agg_col` using `agg_function`,
/// and convert the resulting 1-D aggregation into a 2-D wide table:
/// - each unique value of `var0` becomes a column name (stringified)
/// - the aggregated value for that group becomes the single-row value in that column
///
/// Returns a DataFrame with a single row and N columns (N = number of distinct groups).
///
/// Example:
/// let wide = group_agg_to_wide(&df0, "category", "value", AggFunction::Mean)?;
pub fn group_agg_to_wide(
    df0: &DataFrame,
    var0: &str,
    agg_col: &str,
    agg_function: AggFunction,
) -> PolarsResult<DataFrame> {
    // Build the aggregation expression for the chosen agg_function.
    let agg_expr = match agg_function {
        AggFunction::Sum => col(agg_col).sum().alias("agg"),
        AggFunction::Mean => col(agg_col).mean().alias("agg"),
        AggFunction::Min => col(agg_col).min().alias("agg"),
        AggFunction::Max => col(agg_col).max().alias("agg"),
        AggFunction::Median => col(agg_col).median().alias("agg"),
        AggFunction::Count => col(agg_col).count().alias("agg"),
    };

    // Use the lazy API to group and aggregate efficiently.
    let lf = df0.clone().lazy();
    let grouped = lf.groupby([col(var0)]).agg([agg_expr]);
    let agg_df = grouped.collect()?; // eager DataFrame result of groupby aggregation

    // Expect columns: var0 and "agg"
    if agg_df.get_column_names().len() < 2 {
        return Err(PolarsError::Other(
            "aggregation did not produce expected columns".into(),
        ));
    }

    let key_series = agg_df.column(var0)?;
    let val_series = agg_df.column("agg")?;

    // Cast aggregated values to Float64 for uniform handling (counts become floats too).
    // This simplifies building Series with single f64 value per column.
    let val_f64 = val_series.cast(&DataType::Float64)?;
    let val_f64 = val_f64.f64()?; // get Float64Chunked for indexing

    // Build a Vec<Series>, one Series per group (each with a single element).
    let mut cols: Vec<Series> = Vec::with_capacity(agg_df.height());

    for i in 0..agg_df.height() {
        // stringify group key to become column name
        let key_name = match key_series.get(i) {
            AnyValue::Utf8(s) => s.to_string(),
            other => format!("{}", other),
        };

        // extract aggregated value as f64 (NaN if null)
        let value = val_f64.get(i).unwrap_or(f64::NAN);

        // create a one-element Series of type Float64 with column name = key_name
        let s = Series::new(&key_name, &[value]);
        cols.push(s);
    }

    DataFrame::new(cols)
}

