    // Step 2: Apply the aggregation function
    let aggregated = agg_function(grouped)?;

    // Step 3: Identify the value column (assume it's the second column after group_by column)
    let columns: Vec<&str> = aggregated
        .get_column_names()
        .iter()
        .map(|s| s.as_str())
        .collect();

    // Find the value column (not the group_by column)
    let value_col = columns
        .iter()
        .find(|&&c| c != var0)
        .ok_or_else(|| PolarsError::ComputeError("No value column found after aggregation".into()))?;

    // Step 4: Create a pivot table
    // First, collect unique values from the group_by column
    let unique_values: Vec<AnyValue> = aggregated
        .column(var0)?
        .unique()?
        .iter()
        .collect();

    // Step 5: Build the two-dimensional table
    let mut pivot_data: HashMap<String, Vec<f64>> = HashMap::new();

    // Initialize rows for each unique value
    for val in &unique_values {
        let key = format!("{}", val);
        pivot_data.entry(key).or_insert_with(Vec::new);
    }

    // Populate the pivot table
    for row_idx in 0..aggregated.height() {
        let group_val = aggregated
            .column(var0)?
            .get(row_idx)?
            .to_string();

        let agg_val = aggregated
            .column(value_col)?
            .get(row_idx)?
            .try_extract::<f64>()
            .unwrap_or(0.0);

        if let Some(vec) = pivot_data.get_mut(&group_val) {
            vec.push(agg_val);
        }
    }

    // Step 6: Convert HashMap to DataFrame
    let mut pivot_df_builder = Vec::new();

    // Create column names from unique values
    let col_names: Vec<String> = unique_values
        .iter()
        .map(|v| format!("{}", v))
        .collect();

    // Build rows (transpose the data)
    let max_len = pivot_data
        .values()
        .map(|v| v.len())
        .max()
        .unwrap_or(0);

    for i in 0..max_len {
        let mut row = Vec::new();
        for col_name in &col_names {
            if let Some(vec) = pivot_data.get(col_name) {
                if i < vec.len() {
                    row.push(Some(vec[i]));
                } else {
                    row.push(None);
                }
            } else {
                row.push(None);
            }
        }
        pivot_df_builder.push(row);
    }

    // Create the final DataFrame
    let mut series_vec = Vec::new();
    for (idx, col_name) in col_names.iter().enumerate() {
        let values: Vec<Option<f64>> = pivot_df_builder
            .iter()
            .map(|row| row[idx])
            .collect();
        series_vec.push(Series::new(col_name, values));
    }

    Ok(DataFrame::new(series_vec)?)
}

