```rust
use indexmap::IndexMap;
use std::hash::Hash;

/// Build a map from a sequence of 2-element groups, using each group's first element as the key
/// and the entire group as the value.
///
/// - If the same key appears multiple times, the later group overwrites the earlier one.
/// - The key type K must implement Eq + Hash + Clone because we store it both as the map key
///   and inside the tuple value.
///
/// Example:
/// let pairs = vec![("a", 1), ("b", 2), ("a", 3)];
/// let m = groups_to_map(pairs);
/// // m will map "b" -> ("b", 2) and "a" -> ("a", 3) (the last occurrence wins)
pub fn groups_to_map<K, V, I>(iter: I) -> IndexMap<K, (K, V)>
where
    K: Eq + Hash + Clone,
    I: IntoIterator<Item = (K, V)>,
{
    let mut map: IndexMap<K, (K, V)> = IndexMap::new();
    for pair in iter {
        // pair.0 is moved; clone it so the key (separate) and the stored tuple both have the key.
        let key = pair.0.clone();
        map.insert(key, pair);
    }
    map
}

#[cfg(test)]
