    use super::*;

    #[test]
    fn basic_usage() {
        let pairs = vec![("a".to_string(), 1), ("b".to_string(), 2), ("a".to_string(), 3)];
        let m = groups_to_map(pairs);
        assert_eq!(m.len(), 2);
        assert_eq!(m.get("a"), Some(&("a".to_string(), 3)));
        assert_eq!(m.get("b"), Some(&("b".to_string(), 2)));
    }

    #[test]
    fn empty() {
        let v: Vec<(u8, u8)> = Vec::new();
        let m = groups_to_map(v);
        assert!(m.is_empty());
    }
}

fn main() {
    // Example usage
    let pairs = vec![("one", 1), ("two", 2), ("one", 11)];
    let map = groups_to_map(pairs.into_iter().map(|(k, v)| (k.to_string(), v)));
    for (k, pair) in map {
        println!("key: {}, value tuple: ({}, {})", k, pair.0, pair.1);
    }
}
```

