/// assert_eq!(result.get(&5), Some(&vec![5, 6]));
/// ```
fn create_pair_map<T: Clone + std::hash::Hash + Eq>(
    items: impl Iterator<Item = T>,
) -> HashMap<T, Vec<T>> {
    items
        .tuples::<(T, T)>()
        .map(|(first, second)| (first.clone(), vec![first, second]))
        .collect()
}

fn main() {
    // Example 1: With integers
    let numbers = vec![1, 2, 3, 4, 5, 6];
    let map = create_pair_map(numbers.into_iter());

    println!("Integer pairs:");
    for (key, value) in &map {
        println!("  {} -> {:?}", key, value);
    }

    // Example 2: With strings
    let words = vec!["hello", "world", "foo", "bar"];
    let word_map = create_pair_map(words.into_iter());

    println!("\nString pairs:");
    for (key, value) in &word_map {
        println!("  {} -> {:?}", key, value);
    }
}
```

