///
///     let count = count_matches(&df, "B", "y")?;
///     assert_eq!(count, 2);
///
///     Ok(())
/// }
/// ```
pub fn count_matches(df: &DataFrame, column_name: &str, value: &dyn std::fmt::Debug) -> Result<usize, Box<dyn Error>> {
    // Get the column from the DataFrame
    let column = df.column(column_name)
        .ok_or_else(|| format!("Column '{}' not found", column_name))?;

