        }
        DataType::Float64 => {
            let val: f64 = std::fmt::debug::Debug::fmt(value, std::fmt::Formatter::debug_list)
                .parse()
                .map_err(|_| format!("Failed to parse value as f64: {:?}", value))?;
            AnyValue::Float64(Some(val))
        }
        DataType::Utf8 => {
            let val: String = std::fmt::debug::Debug::fmt(value, std::fmt::Formatter::debug_list)
                .parse()
                .map_err(|_| format!("Failed to parse value as String: {:?}", value))?;
            AnyValue::Utf8(Some(val))
        }
        DataType::Boolean => {
            let val: bool = std::fmt::debug::Debug::fmt(value, std::fmt::Formatter::debug_list)
                .parse()
                .map_err(|_| format!("Failed to parse value as bool: {:?}", value))?;
            AnyValue::Boolean(Some(val))
