use polars::prelude::*;
use std::path::Path;
use anyhow::Result;

/// Count how many entries in `column` equal `value` in the CSV at `path`.
/// Returns Ok(count) or an error (file/parse/column missing).
pub fn count_matches_in_column<P: AsRef<Path>>(
    path: P,
    column: &str,
    value: &str,
) -> Result<usize> {
    // Read CSV into a DataFrame. Adjust options (delimiter, has_header, infer rows) as needed.
    let df = CsvReader::from_path(path)?
        .infer_schema(Some(100)) // infer from first 100 rows; set None to read without inferring
        .has_header(true)
        .finish()?;

    // Get the series for the requested column (returns an error if missing)
    let s = df.column(column)?;

    // Ensure we have a Utf8 (string) view; cast if necessary.
    let utf8 = if s.dtype() == &DataType::Utf8 {
        s.utf8()?
    } else {
        s.cast(&DataType::Utf8)?.utf8()?
    };

    // Iterate and count exact matches; ignore nulls.
    let count = utf8.into_iter().filter(|opt| match opt {
        Some(v) => v == value,
        None => false,
    }).count();

    Ok(count)
}

fn main() -> Result<()> {
