/// Compute the average row and column indices of non-zero entries in a 2D tensor.
fn compute_nonzero_avg_indices(df0: &Tensor) -> (f64, f64) {
    // Ensure the tensor is 2D
    assert_eq!(df0.size().len(), 2, "Input must be a 2D tensor.");

    // Find non-zero indices
    let nonzero_indices = df0.nonzero();

    // Calculate the number of non-zero elements
    let num_nonzero = nonzero_indices.size()[0];

    // If there are no non-zero entries, return NaN for both indices
    if num_nonzero == 0 {
        return (f64::NAN, f64::NAN);
    }

    // Sum row and column indices
    let (row_sum, col_sum) = nonzero_indices.split_with_sizes(&[1, 1]).iter()
