pub fn average_nonzero_indices(df0: &DataFrame) -> Result<(f64, f64), PolarsError> {
    let ncols = df0.width();

    // Stack all columns into a single column with row and column indices
    let mut row_indices = Vec::new();
    let mut col_indices = Vec::new();

