use polars::prelude::*;
use std::collections::HashMap;

/// Count rows for each distinct combination of values across specified key columns
///
/// # Arguments
/// * `df` - Input DataFrame
/// * `key_columns` - Slice of column names to group by
///
/// # Returns
/// * `Result<HashMap<Vec<String>, usize>>` - Map from value combinations to row counts
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use std::collections::HashMap;
///
/// let df = df!(
///     "city" => &["NYC", "LA", "NYC", "LA", "Chicago"],
///     "year" => &[2020, 2020, 2021, 2021, 2020],
///     "sales" => &[100, 200, 150, 250, 300]
/// ).unwrap();
///
/// let result = count_rows_per_group(&df, &["city", "year"]).unwrap();
/// assert_eq!(result.get(&vec!["NYC".to_string(), "2020".to_string()]), Some(&1));
/// assert_eq!(result.get(&vec!["LA".to_string(), "2021".to_string()]), Some(&1));
/// ```
pub fn count_rows_per_group(
    df: &DataFrame,
    key_columns: &[&str],
) -> Result<HashMap<Vec<String>, usize>, PolarsError> {
    // Validate that all key columns exist
    for col in key_columns {
        if !df.get_column_names().contains(col) {
            return Err(PolarsError::ColumnNotFound(
                format!("Column '{}' not found in DataFrame", col).into(),
            ));
        }
    }

    // Group by the specified columns and count rows
    let grouped = df
        .group_by(key_columns)?
        .agg([col("*").count().alias("count")])?;

    // Convert to HashMap for easier consumption
    let mut result: HashMap<Vec<String>, usize> = HashMap::new();

    // Extract the key columns and count column
    let count_col = grouped.column("count")?;
    let count_series = count_col.u32()?;

    // Build the result map
    for row_idx in 0..grouped.height() {
        let mut key_values: Vec<String> = Vec::with_capacity(key_columns.len());

        for col_name in key_columns {
            let col = grouped.column(*col_name)?;
            let value = match col.dtype() {
                DataType::Utf8 => col.str()?.get(row_idx).unwrap_or("").to_string(),
                DataType::Int32 => col.i32()?.get(row_idx).unwrap_or(0).to_string(),
                DataType::Int64 => col.i64()?.get(row_idx).unwrap_or(0).to_string(),
                DataType::Float64 => col.f64()?.get(row_idx).unwrap_or(0.0).to_string(),
                DataType::UInt32 => col.u32()?.get(row_idx).unwrap_or(0).to_string(),
                DataType::Boolean => col.bool()?.get(row_idx).unwrap_or(false).to_string(),
                _ => format!("{:?}", col.get(row_idx).unwrap_or(AnyValue::Null)),
            };
            key_values.push(value);
        }

        let count = count_series.get(row_idx).unwrap_or(0) as usize;
        result.insert(key_values, count);
    }

    Ok(result)
}

