    if col_indices.iter().any(|&c| c >= ncols) {
        return None;
    }

    let mut sum = 0.0;
    let mut count = 0;

    for &row_idx in row_indices {
        for &col_idx in col_indices {
            sum += data[row_idx][col_idx];
            count += 1;
        }
    }

    if count == 0 {
