/// ];
///
/// let mut order = IndexMap::new();
/// order.insert("a", 0);
/// order.insert("b", 1);
/// order.insert("c", 2);
///
/// let sorted = sort_by_mapping(lists, &order);
/// assert_eq!(sorted, vec![
///     vec!["a", "b", "c"],
///     vec!["a", "b", "c", "d"],
///     vec!["x", "y", "z"],
/// ]);
/// ```
pub fn sort_by_mapping<T: Clone + std::hash::Hash + Eq>(
    lists: Vec<Vec<T>>,
    order_map: &IndexMap<T, usize>,
) -> Vec<Vec<T>> {
    lists
        .into_iter()
        .map(|mut inner_list| {
            inner_list.sort_by(|a, b| {
                let a_pos = order_map.get(a);
                let b_pos = order_map.get(b);

                match (a_pos, b_pos) {
                    (Some(a_idx), Some(b_idx)) => a_idx.cmp(b_idx),
                    (Some(_), None) => std::cmp::Ordering::Less,
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (None, None) => std::cmp::Ordering::Equal,
                }
            });
            inner_list
        })
        .collect()
}

