/// order_map.insert("cat", 3);
/// order_map.insert("dog", 4);
/// 
/// let result = sort_lists_by_mapping(&lists, &order_map);
/// assert_eq!(result[0], vec!["apple", "monkey", "zebra"]);
/// assert_eq!(result[1], vec!["apple", "cat", "dog"]);
/// ```
fn sort_lists_by_mapping<T: Clone + Eq + std::hash::Hash>(
    lists: &[Vec<T>],
    order_map: &IndexMap<T, usize>,
) -> Vec<Vec<T>> {
