use polars::prelude::*;
use serde_json::Value;
use anyhow::{Result, bail};
use std::collections::HashMap;

/// Convert a DataFrame `df0` into a dictionary mapping the identifier in column `var0`
/// to the row's data as a map of column-name -> serde_json::Value.
///
/// - `df0`: input Polars DataFrame.
/// - `var0`: column name that serves as the row identifier (must be present).
///
/// Returns: HashMap<id_string, HashMap<column_name, serde_json::Value>>
pub fn df_to_dict(
    df0: &DataFrame,
    var0: &str,
) -> Result<HashMap<String, HashMap<String, Value>>> {
    // verify identifier column exists
    if !df0.get_column_names().iter().any(|c| c == var0) {
        bail!("identifier column '{}' not found in DataFrame", var0);
    }

    let n_rows = df0.height();
    let col_names = df0.get_column_names();
    let mut out: HashMap<String, HashMap<String, Value>> = HashMap::with_capacity(n_rows);

    for i in 0..n_rows {
        // Get the identifier value and convert to string key
        let id_av = df0.column(var0)?.get(i);
        let id_key = anyvalue_to_string(id_av);

        // Build row map
        let mut row_map: HashMap<String, Value> = HashMap::with_capacity(col_names.len());
        for col_name in col_names.iter() {
            // Grab the value for this column and row
            let v_av = df0.column(col_name)?.get(i);
            row_map.insert(col_name.clone(), anyvalue_to_json(v_av));
        }

        out.insert(id_key, row_map);
    }

    Ok(out)
}

/// Convert a Polars AnyValue into serde_json::Value (best-effort)
fn anyvalue_to_json(av: AnyValue) -> Value {
    match av {
        AnyValue::Null => Value::Null,
        AnyValue::Boolean(b) => Value::Bool(b),
        AnyValue::Utf8(s) => Value::String(s.to_string()),
        AnyValue::Utf8Owned(s) => Value::String(s),
        AnyValue::Float32(f) => serde_json::Number::from_f64(f as f64)
            .map(Value::Number)
            .unwrap_or(Value::String(format!("{}", f))),
        AnyValue::Float64(f) => serde_json::Number::from_f64(f)
            .map(Value::Number)
            .unwrap_or(Value::String(format!("{}", f))),
        AnyValue::Int8(i) => Value::Number(serde_json::Number::from(i as i64)),
        AnyValue::Int16(i) => Value::Number(serde_json::Number::from(i as i64)),
        AnyValue::Int32(i) => Value::Number(serde_json::Number::from(i as i64)),
        AnyValue::Int64(i) => Value::Number(serde_json::Number::from(i)),
        AnyValue::UInt8(u) => Value::Number(serde_json::Number::from(u as u64)),
        AnyValue::UInt16(u) => Value::Number(serde_json::Number::from(u as u64)),
        AnyValue::UInt32(u) => Value::Number(serde_json::Number::from(u as u64)),
        AnyValue::UInt64(u) => Value::Number(serde_json::Number::from(u)),
        // Dates/times: fall back to string (could be formatted differently if needed)
        AnyValue::Date32(v) => Value::String(format!("{}", v)),
        AnyValue::Date64(v) => Value::String(format!("{}", v)),
        AnyValue::Time64(v) => Value::String(format!("{}", v)),
        AnyValue::Duration(v) => Value::String(format!("{}", v)),
        // For List/Struct/Object and unknown variants, fall back to string representation
        other => Value::String(format!("{}", other)),
    }
}

/// Convert AnyValue to a string (used for building the identifier key)
fn anyvalue_to_string(av: AnyValue) -> String {
    match av {
        AnyValue::Null => "null".to_string(),
        AnyValue::Utf8(s) => s.to_string(),
        AnyValue::Utf8Owned(s) => s,
        AnyValue::Boolean(b) => b.to_string(),
        AnyValue::Float32(f) => f.to_string(),
        AnyValue::Float64(f) => f.to_string(),
        AnyValue::Int8(i) => i.to_string(),
        AnyValue::Int16(i) => i.to_string(),
        AnyValue::Int32(i) => i.to_string(),
        AnyValue::Int64(i) => i.to_string(),
        AnyValue::UInt8(u) => u.to_string(),
        AnyValue::UInt16(u) => u.to_string(),
        AnyValue::UInt32(u) => u.to_string(),
        AnyValue::UInt64(u) => u.to_string(),
        other => format!("{}", other),
    }
}

