///
/// let result = extract_substring("Hello", 0, 5);
/// assert_eq!(result, Some("Hello"));
///
/// let result = extract_substring("Hello", 10, 3);
/// assert_eq!(result, None);
/// ```
pub fn extract_substring(text: &str, start: usize, length: usize) -> Option<&str> {
    if length == 0 {
        return Some("");
    }

    // Get the total character count (not byte count)
    let char_count = text.chars().count();

    // Validate start position
    if start >= char_count {
        return None;
    }

    // Find the byte position for the start character
    let start_byte = text
        .char_indices()
        .nth(start)
        .map(|(pos, _)| pos)?;

    // Calculate end position (character index)
    let end_char = start.checked_add(length)?;

    // Validate end position doesn't exceed text length
    if end_char > char_count {
        return None;
    }

    // Find the byte position for the end character
    let end_byte = text
        .char_indices()
        .nth(end_char)
        .map(|(pos, _)| pos)
        .unwrap_or(text.len());

    Some(&text[start_byte..end_byte])
}

