pub fn normalize_columns<T>(df: ArrayViewMut2<T>) -> ArrayView2<f64>
where
    T: Into<f64> + Copy,
{
    // Convert to f64 array for calculations
    let mut df_f64: Array2<f64> = df.mapv(|x| x.into());

    // Normalize each column
    for col in df_f64.axis_iter_mut(ndarray::Axis(1)) {
