/// Normalize each numeric column of `df0` in-place so values are scaled to [0, 1].
/// Non-numeric columns are preserved. Nulls are preserved.
pub fn normalize_df0(df0: &mut DataFrame) -> PolarsResult<()> {
    // Collect normalized columns
    let mut cols: Vec<Series> = Vec::with_capacity(df0.width());

    for s in df0.get_columns() {
        let name = s.name().to_string();

        if s.dtype().is_numeric() {
            // Cast to Float64 for safe arithmetic
            let s_f64 = s.cast(&DataType::Float64)?;
            let ca = s_f64.f64()?;

            // Determine min and max (ignoring nulls)
            let min = ca.min().unwrap_or(0.0);
            let max = ca.max().unwrap_or(0.0);

