                            if range == 0.0 {
                                // Handle constant columns (all same value)
                                col.clone().cast(DataType::Float64).unwrap().lit(0.0)
                            } else {
                                (col - &Series::new("min", &[min_val]))
                                    .unwrap()
                                    .clone()
                                    .cast(DataType::Float64)
                                    .unwrap()
                                    / range
                            }
                            .alias(&col.name())
                        }
                        _ => col.clone().cast(DataType::Float64).unwrap(),
                    }
                })
                .collect::<Vec<_>>(),
        )
        .collect()
}

