use std::collections::HashMap;
use regex::Regex;

/// Return a new HashMap containing all key-value pairs from `map` whose keys contain `needle`.
///
/// - `map` is borrowed; returned map contains cloned keys and values.
/// - `needle` is treated as a literal substring (not a regular expression).
///
/// Example:
/// let mut m = HashMap::new();
/// m.insert("apple".to_string(), 1);
/// m.insert("pineapple".to_string(), 2);
/// m.insert("banana".to_string(), 3);
/// let found = extract_pairs_with_substring(&m, "apple");
/// // found contains "apple" and "pineapple"
fn extract_pairs_with_substring<V: Clone>(
    map: &HashMap<String, V>,
    needle: &str,
) -> HashMap<String, V> {
    if needle.is_empty() {
        // If needle is empty, we treat it as "match everything".
        return map.clone();
    }

    // Escape the needle so it's treated literally when used as a regex pattern.
    let pattern = Regex::new(&regex::escape(needle))
        .expect("failed to compile escaped substring regex");

    map.iter()
        .filter(|(k, _)| pattern.is_match(k))
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect()
}

fn main() {
    let mut items: HashMap<String, i32> = HashMap::new();
    items.insert("apple".to_string(), 1);
    items.insert("pineapple".to_string(), 2);
    items.insert("banana".to_string(), 3);
    items.insert("applet".to_string(), 4);

    let matches = extract_pairs_with_substring(&items, "apple");
    for (k, v) in matches {
        println!("{} => {}", k, v);
    }
}
```

Notes
- The function is intentionally simple and uses regex::escape to handle literal substring queries safely (so a needle like "a.b" won't be treated as a regex).
- If you prefer to avoid a dependency, you can replace the regex check with k.contains(needle) (std method) and remove the regex crate. The regex approach is still useful if you want to extend to real regex patterns later.

