/// Finds the first non-null value in specified columns for each row of a DataFrame.
///
/// # Arguments
/// * `df0` - Input DataFrame
/// * `lst0` - List of column names to check in order
///
/// # Returns
/// A new DataFrame with a single column containing the first non-null value for each row
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df!(
///     "a" => &[Some(1), None, Some(3)],
///     "b" => &[None, Some(2), None],
///     "c" => &[Some(3), Some(4), Some(5)]
/// ).unwrap();
/// let result = find_first_non_null(&df, &["a", "b", "c"]).unwrap();
/// assert_eq!(result, df!("result" => &[Some(1), Some(2), Some(3)]));
/// ```
pub fn find_first_non_null(df0: &DataFrame, lst0: &[&str]) -> Result<DataFrame, PolarsError> {
    // Create a new expression for each column in the order specified
    let mut exprs = Vec::new();
    for col in lst0 {
        exprs.push(colars::expr::col(col).cast(&DataType::Utf8));
    }

    // Combine them with null checks and first non-null selection
    let first_non_null_expr = exprs
        .into_iter()
        .enumerate()
        .fold(
            colars::expr::literal(None::<&str>),
            |acc, (i, expr)| {
                colars::expr::when(
                    colars::expr::is_null(&expr),
                    &acc,
                    &expr,
                )
            },
        )
        .alias("result");

    // Execute the expression and return the result
    let result = df0.lazy().select(&[first_non_null_expr])?.collect()?;
    Ok(result)
}
