use itertools::izip;

/// Produce a Vec<bool> where each element is true iff the elements at the same index in
/// the two input sequences refer to the same object instance.
///
/// - a, b: any IntoIterator of items that implement AsRef<T> (e.g. &T, Box<T>, Rc<T>, Arc<T>, &dyn Trait).
/// - The comparison runs up to the shorter of the two sequences.
///
/// Example:
/// ```
/// use std::rc::Rc;
/// let shared = Rc::new(10);
/// let a = vec![Rc::clone(&shared), Rc::new(20)];
/// let b = vec![Rc::clone(&shared), Rc::new(20)];
/// let result = instance_identity_seq(a, b);
/// assert_eq!(result, vec![true, false]);
/// ```
pub fn instance_identity_seq<T, A, B, IA, IB>(a: IA, b: IB) -> Vec<bool>
where
    T: ?Sized,
    IA: IntoIterator<Item = A>,
    IB: IntoIterator<Item = B>,
    A: AsRef<T>,
    B: AsRef<T>,
{
    let ia = a.into_iter();
    let ib = b.into_iter();
    izip!(ia, ib)
        .map(|(x, y)| std::ptr::eq(x.as_ref(), y.as_ref()))
        .collect()
}

