/// assert_eq!(result, vec![true, true, true]); // Same object instances
/// ```
fn compare_object_identity<T>(seq1: &[T], seq2: &[T]) -> Vec<bool> {
    use std::ptr;

    seq1.iter()
        .zip(seq2.iter())
        .map(|(item1, item2)| {
            // Compare by pointer equality to check if they refer to the same object instance
            ptr::eq(item1, item2)
        })
        .collect()
}

// Example usage demonstrating the function
fn main() {
    // Example 1: Same vector (same object instances)
    let numbers = vec![10, 20, 30];
    let result1 = compare_object_identity(&numbers, &numbers);
    println!("Same vector: {:?}", result1); // [true, true, true]

    // Example 2: Different vectors with same values
    let vec_a = vec![10, 20, 30];
    let vec_b = vec![10, 20, 30];
    let result2 = compare_object_identity(&vec_a, &vec_b);
    println!("Different vectors, same values: {:?}", result2); // [false, false, false]

    // Example 3: References to the same objects in different collections
    let obj1 = Box::new(42);
    let obj2 = Box::new(42);
    let refs_a = vec![&obj1, &obj2];
    let refs_b = vec![&obj1, &obj2];
