use polars::prelude::*;
use std::collections::HashMap;

/// Divides each value in specified columns by the corresponding value in a reference column.
///
/// # Arguments
/// * `df0` - Input DataFrame
/// * `columns_list0` - List of column names to divide
/// * `column_name0` - Reference column name to divide by
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with divided columns (original columns replaced)
///
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "A" => &[10.0, 20.0, 30.0],
///     "B" => &[5.0, 10.0, 15.0],
///     "divisor" => &[2.0, 5.0, 3.0]
/// ).unwrap();
///
/// let result = divide_columns_by_reference(
///     &df,
///     &["A".to_string(), "B".to_string()],
///     "divisor"
/// ).unwrap();
/// println!("{:?}", result);
/// ```
pub fn divide_columns_by_reference(
    df0: &DataFrame,
    columns_list0: &[String],
    column_name0: &str,
) -> Result<DataFrame, PolarsError> {
    // Validate that the reference column exists
    if !df0.get_column_names().contains(&column_name0) {
        return Err(PolarsError::ComputeError(
            format!("Reference column '{}' not found in DataFrame", column_name0).into(),
        ));
    }

    // Validate that all columns in columns_list0 exist
    for col in columns_list0 {
        if !df0.get_column_names().contains(&col.as_str()) {
            return Err(PolarsError::ComputeError(
                format!("Column '{}' not found in DataFrame", col).into(),
            ));
        }
    }

    // Create a lazy expression for each column to divide
    let mut expressions: Vec<Expr> = Vec::new();

    for col in df0.get_column_names() {
        if columns_list0.contains(&col.to_string()) {
            // Divide the column by the reference column
            expressions.push(
                col
                    .cast(DataType::Float64)
                    .divide(
                        column_name0
                            .cast(DataType::Float64)
                    )
                    .alias(col)
            );
        } else {
            // Keep other columns unchanged
            expressions.push(col.alias(col));
        }
    }

    // Apply the transformations
    df0.lazy()
        .with_columns(expressions)
        .collect()
}

