/// Expand the distinct values of "var0" into binary (0/1) indicator columns.
/// Output columns are named "var0__<value>" for non-null values and "var0__NULL" for nulls.
///
/// Returns a new DataFrame consisting only of the indicator columns.
fn expand_var0_to_indicators(df0: &DataFrame) -> PolarsResult<DataFrame> {
    // get a cloned Series for var0
    let series = df0.column("var0")?.clone();

    // Ensure we are working with Utf8 chunked data (strings). If var0 is another type,
    // cast it to Utf8 so we can treat distinct values as textual names.
    let series = if series.dtype() == &DataType::Utf8 {
        series
    } else {
        series.cast(&DataType::Utf8)?
    };

    let utf = series.utf8()?;

    // Get unique values (includes a None entry if there are nulls).
    let unique = utf.unique()?;
    let unique_utf = unique.utf8()?; // Series returned by unique()

    let mut cols: Vec<Series> = Vec::with_capacity(unique_utf.len());

    for opt_val in unique_utf.into_iter() {
        match opt_val {
            Some(v) => {
                // boolean mask where var0 == v
                let mask = utf.equal(v);
                // cast boolean -> UInt8 (true -> 1, false -> 0) and name the column
                let col = mask
                    .into_series()
                    .cast(&DataType::UInt8)?
                    .rename(&format!("var0__{}", v));
                cols.push(col);
            }
            None => {
                // handle null values: mask where var0 is null
                let mask = utf.is_null();
                let col = mask
                    .into_series()
                    .cast(&DataType::UInt8)?
                    .rename("var0__NULL");
                cols.push(col);
            }
        }
    }

    DataFrame::new(cols)
}

