pub fn one_hot_encode(df0: DataFrame) -> Result<DataFrame> {
    // Get unique values from var0 column
    let unique_values: Vec<String> = df0
        .column("var0")?
        .unique()?
        .str()?
        .into_iter()
        .flatten()
        .map(|s| s.to_string())
        .collect();

