/// ).unwrap();
///
/// let result = add_empty_columns(df, &["C", "D", "E"]).unwrap();
/// println!("{:?}", result);
/// ```
pub fn add_empty_columns(
    df0: DataFrame,
    lst0: &[&str],
) -> PolarsResult<DataFrame> {
    // Create a HashMap to track existing columns for quick lookup
    let existing_cols: HashMap<&str, bool> = df0
        .get_column_names()
        .iter()
        .map(|name| (*name, true))
        .collect();

    // Build new columns that don't already exist
    let mut new_columns: Vec<Series> = Vec::with_capacity(lst0.len());

