                col_name,
                &DataType::Null,
            )
            .new_from_index(0, df0.height());

            new_columns.push(null_series);
        }
        // If column already exists, we skip it (could also return error)
    }

    // Horizontally concatenate the new columns to the original DataFrame
    let hstacked = df0.hstack(&new_columns)?;

