/// Compute log_base(x) with arbitrary precision using rug::Float.
///
/// Arguments:
/// - `x`: the value to take the logarithm of (must be > 0)
/// - `base`: the logarithm base (must be > 0 and != 1)
/// - `precision_bits`: requested precision in bits (e.g. 53 for ~f64, 128 or 256 for higher precision)
///
/// Returns:
/// - Ok(Float) with the computed logarithm at the requested precision, or
/// - Err(&'static str) if inputs are invalid.
///
/// Example:
/// ```
/// let res = log_base_highprec(8.0, 2.0, 128).unwrap();
/// // res ≈ 3
/// println!("{}", res.to_string()); // prints "3"
/// ```
pub fn log_base_highprec(x: f64, base: f64, precision_bits: u32) -> Result<Float, &'static str> {
    if !(x > 0.0) {
        return Err("x must be > 0");
    }
    if !(base > 0.0) {
        return Err("base must be > 0");
    }
    if base == 1.0 {
        return Err("base must not be 1");
    }

