/// Sorts list A according to the order defined by list B.
/// Items in A that do not appear in B are placed at the beginning.
pub fn custom_sort(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Create a hash map to store the indices of elements in list B
    let mut index_map: HashMap<i32, usize> = HashMap::new();
    for (i, &x) in b.iter().enumerate() {
        index_map.insert(x, i);
    }

    // Sort list A based on the indices in the hash map
    let mut sorted_a: Vec<(i32, Option<usize>)> = a
        .into_iter()
        .map(|x| (x, index_map.get(&x).cloned()))
        .collect();
    sorted_a.sort_by_key(|&(x, index)| (index.is_none(), index.unwrap_or(usize::MAX)));

    // Extract the sorted elements from the tuple
    sorted_a.into_iter().map(|(x, _)| x).collect()
}

