use indexmap::IndexSet;
use std::cmp::Ordering;

/// Sort list A according to the order defined by list B.
/// Items in A that do not appear in B are placed at the beginning.
/// Efficient even when B is very large.
pub fn sort_by_order<T: Clone + Eq + std::hash::Hash>(a: &mut [T], b: &[T]) {
    // Build an IndexSet from B to preserve order and provide O(1) lookups
    let order_map: IndexSet<&T> = b.iter().collect();

    // Partition: items not in B first, then items in B sorted by B's order
    a.sort_by(|x, y| {
        let x_in_b = order_map.get_index_of(x);
        let y_in_b = order_map.get_index_of(y);

        match (x_in_b, y_in_b) {
            // Both not in B: maintain relative order (stable sort)
            (None, None) => Ordering::Equal,
            // x not in B, y in B: x comes first
            (None, Some(_)) => Ordering::Less,
            // x in B, y not in B: y comes first
            (Some(_), None) => Ordering::Greater,
            // Both in B: sort by their position in B
            (Some(i), Some(j)) => i.cmp(&j),
        }
    });
}

#[cfg(test)]
