use polars::prelude::*;
use std::error::Error;

/// Sum values in `sum_col` for rows where `predicate` returns true on values from `condition_col`.
///
/// - `df` : DataFrame to operate on.
/// - `condition_col` : name of the column to test the predicate on.
/// - `predicate` : closure that receives an `&AnyValue` (value from the condition column) and returns true for rows to include.
/// - `sum_col` : name of the numeric column to sum.
///
/// Returns the sum as f64. Non-numeric or null values in the sum column are skipped.
fn conditional_column_sum<F>(
    df: &DataFrame,
    condition_col: &str,
    predicate: F,
    sum_col: &str,
) -> Result<f64, PolarsError>
where
    F: Fn(&AnyValue) -> bool,
{
    let cond_series = df.column(condition_col)?;
    let sum_series = df.column(sum_col)?;
    let len = df.height();
    let mut total = 0f64;

    for i in 0..len {
        let cond_val = cond_series.get(i);
        if predicate(&cond_val) {
            match sum_series.get(i) {
                AnyValue::Null => continue,
                v => {
                    if let Some(n) = anyvalue_to_f64(v) {
                        total += n;
                    }
                }
            }
        }
    }

    Ok(total)
}

/// Helper to convert numeric AnyValue variants into f64 (returns None for non-numeric).
fn anyvalue_to_f64(v: AnyValue) -> Option<f64> {
    match v {
        AnyValue::Float64(f) => Some(f),
        AnyValue::Float32(f) => Some(f as f64),
        AnyValue::Int64(i) => Some(i as f64),
        AnyValue::Int32(i) => Some(i as f64),
        AnyValue::Int16(i) => Some(i as f64),
        AnyValue::Int8(i) => Some(i as f64),
        AnyValue::UInt64(u) => Some(u as f64),
        AnyValue::UInt32(u) => Some(u as f64),
        AnyValue::UInt16(u) => Some(u as f64),
        AnyValue::UInt8(u) => Some(u as f64),
        _ => None,
    }
}

