/// * `Result<f64, Box<dyn Error>>` - The sum of values or an error
fn conditional_column_sum(
    data: Vec<Vec<f64>>,
    headers: Vec<&str>,
    sum_column: &str,
    condition_column: &str,
    condition_value: f64,
    operator: &str,
) -> Result<f64, Box<dyn Error>> {
    // Convert data to Polars DataFrame
    let mut series_vec: Vec<Series> = Vec::new();

    for (i, header) in headers.iter().enumerate() {
        let col_data: Vec<f64> = data.iter().map(|row| row[i]).collect();
        series_vec.push(Series::new(header, col_data));
    }

    let df = DataFrame::new(series_vec)?;

    // Build the filter condition based on the operator
    let condition = match operator {
        "eq" => col(condition_column).eq(lit(condition_value)),
        "neq" => col(condition_column).neq(lit(condition_value)),
        "gt" => col(condition_column).gt(lit(condition_value)),
        "gte" => col(condition_column).gte(lit(condition_value)),
        "lt" => col(condition_column).lt(lit(condition_value)),
        "lte" => col(condition_column).lte(lit(condition_value)),
