use itertools::Itertools;

/// Generate three new sequences from an input sequence by subtracting each of the values 1, 0, and –1
/// from the elements at odd positions and replacing the elements at even positions with zero.
///
/// # Arguments
///
/// * `input_sequence` - The input sequence of numbers.
