```rust
use polars::prelude::*;

/// Convert a list-of-lists into a DataFrame using `headers` as the column names.
///
/// - `headers` is a slice of values convertible to &str (column names).
/// - `rows` is a slice of vectors; each inner vector is treated as a row.
///   If a row is shorter than the number of headers, the missing cells become nulls.
///
/// Returns a Polars DataFrame or an error if DataFrame construction fails.
pub fn lists_to_table<H, S>(headers: &[H], rows: &[Vec<S>]) -> PolarsResult<DataFrame>
where
    H: AsRef<str>,
    S: AsRef<str>,
{
    let ncols = headers.len();
    let mut series_vec: Vec<Series> = Vec::with_capacity(ncols);

    for i in 0..ncols {
        let name = headers[i].as_ref();
        // For each column index, iterate all rows producing Option<&str>.
        // If a row doesn't have that column, we yield None -> becomes null in the column.
        let iter = rows.iter().map(move |row| row.get(i).map(|s| s.as_ref()));
        let ca = Utf8Chunked::new_from_opt_iter(name, iter);
        series_vec.push(ca.into_series());
    }

    DataFrame::new(series_vec)
}

fn main() -> PolarsResult<()> {
    // Example usage:
    let headers = vec!["id".to_string(), "name".to_string(), "score".to_string()];

    // Rows: notice the third row has only two entries -> score becomes null
    let rows = vec![
        vec!["1".to_string(), "Alice".to_string(), "9.5".to_string()],
        vec!["2".to_string(), "Bob".to_string(), "8.0".to_string()],
        vec!["3".to_string(), "Carol".to_string()], // missing score
    ];

    let df = lists_to_table(&headers, &rows)?;
    println!("{:?}", df);

    Ok(())
}
```

Notes:
- This implementation treats all values as strings; if you need typed columns (ints, floats, dates), you can:
  - parse/convert each column's Option<&str> iterator into the desired typed ChunkedArray (e.g., Int64Chunked::new_from_opt_iter),
  - or convert string columns after the DataFrame is created with df.with_column(df.column("score")?.utf8()?.cast(&DataType::Float64)?).
- Polars will produce columns of equal length; missing cells are represented as nulls.

