/// ];
/// let headers = vec!["ID".to_string(), "Value1".to_string(), "Value2".to_string()];
/// let table = lists_to_table(&data, &headers).unwrap();
/// ```
pub fn lists_to_table(
    data_lists: &[Vec<String>],
    headers: &[String],
) -> Result<Array2<f64>, String> {
    if data_lists.is_empty() {
        return Err("Data lists cannot be empty".to_string());
    }

    if headers.is_empty() {
        return Err("Headers cannot be empty".to_string());
    }

    // Validate that all data lists have the same length as headers
    for (i, list) in data_lists.iter().enumerate() {
        if list.len() != headers.len() {
            return Err(format!(
                "Data list {} has {} elements, but headers have {} elements",
                i,
                list.len(),
                headers.len()
            ));
        }
    }

    // Create a mapping from header names to column indices
    let header_map: HashMap<&str, usize> = headers
        .iter()
        .enumerate()
        .map(|(i, h)| (h.as_str(), i))
        .collect();

    let num_rows = data_lists.len();
    let num_cols = headers.len();

    // Initialize the 2D array with zeros
    let mut table = Array2::<f64>::zeros((num_rows, num_cols));

    // Fill the table
    for (row_idx, list) in data_lists.iter().enumerate() {
        for (col_idx, value) in list.iter().enumerate() {
            // Parse the string value to f64, defaulting to 0.0 if parsing fails
            let parsed_value: f64 = value.parse().unwrap_or(0.0);
            table[[row_idx, col_idx]] = parsed_value;
