use std::collections::HashMap;
use indexmap::IndexMap;
use std::hash::Hash;

/// Reorders elements by frequency (most frequent first), retaining all elements.
/// For equal frequencies, groups are ordered by first occurrence in the input.
///
/// Takes any IntoIterator of T and returns a Vec<T> with elements reordered.
/// T must be Eq + Hash + Clone.
///
/// Example:
/// let input = vec!["a", "b", "a", "c", "b", "a"];
/// let out = reorder_by_frequency(input);
/// // out might be ["a","a","a","b","b","c"]
pub fn reorder_by_frequency<T, I>(input: I) -> Vec<T>
where
    I: IntoIterator<Item = T>,
    T: Eq + Hash + Clone,
{
    // Collect input so we can index and sort
    let items: Vec<T> = input.into_iter().collect();

    // Count frequencies and record first-seen index for each distinct value
    let mut counts: HashMap<T, usize> = HashMap::new();
    let mut first_seen: IndexMap<T, usize> = IndexMap::new();

    for (idx, item) in items.iter().enumerate() {
        counts.entry(item.clone()).and_modify(|c| *c += 1).or_insert(1);
        first_seen.entry(item.clone()).or_insert(idx);
    }

    // Make a mutable copy to sort
    let mut sorted = items;

    // Stable sort by (frequency desc, first_seen asc)
    sorted.sort_by(|a, b| {
        let ca = counts.get(a).copied().unwrap_or(0);
        let cb = counts.get(b).copied().unwrap_or(0);
        // frequency descending:
        match cb.cmp(&ca) {
            std::cmp::Ordering::Equal => {
                // tie-break: earlier first-seen value comes first
                let fa = first_seen.get(a).copied().unwrap_or(usize::MAX);
                let fb = first_seen.get(b).copied().unwrap_or(usize::MAX);
                fa.cmp(&fb)
            }
            other => other,
        }
    });

    sorted
}

fn main() {
    let input = vec!["apple", "banana", "apple", "orange", "banana", "apple", "kiwi"];
    let out = reorder_by_frequency(input);
    println!("{:?}", out);
    // Expected output: ["apple","apple","apple","banana","banana","orange","kiwi"]
}
```

Notes
- This function clones values (T: Clone) because it needs to both count and return owned values; for large or non-cloneable types you can adapt to operate on references by changing signatures.
