use indexmap::IndexMap;

/// Reorders elements of a collection based on their frequency of occurrence.
/// Elements with higher frequencies appear first, maintaining relative order
/// for elements with the same frequency.
///
/// # Arguments
/// * `items` - A slice of comparable, hashable items
///
/// # Returns
/// A Vec containing all elements reordered by frequency (descending)
///
/// # Example
/// ```
/// let nums = vec![1, 2, 2, 3, 3, 3, 1, 1];
/// let result = reorder_by_frequency(nums);
/// assert_eq!(result, vec![3, 3, 3, 1, 1, 1, 2, 2]);
/// ```
fn reorder_by_frequency<T: std::hash::Hash + Eq + Clone>(
    items: &[T],
) -> Vec<T> {
    // Count frequencies while preserving insertion order
    let mut frequency_map: IndexMap<T, usize> = IndexMap::new();

    for item in items {
        frequency_map
            .entry(item.clone())
            .and_modify(|count| *count += 1)
            .or_insert(1);
    }

    // Create a vec of (item, frequency) tuples
    let mut freq_pairs: Vec<(T, usize)> = frequency_map
        .into_iter()
        .map(|(item, freq)| (item, freq))
        .collect();

    // Sort by frequency (descending), stable sort preserves order for equal frequencies
    freq_pairs.sort_by(|a, b| b.1.cmp(&a.1));

    // Expand back to original elements based on their frequencies
    freq_pairs
        .into_iter()
        .flat_map(|(item, freq)| std::iter::repeat(item).take(freq))
        .collect()
}

