use polars::prelude::*;
use std::collections::HashSet;

/// Count distinct combinations of values across the columns named in `lst0` within `df0`.
///
/// Returns a PolarsResult<usize> with the count, or an error if any column in `lst0` is not present.
///
/// Behavior:
/// - If `lst0` is empty:
///     - returns 1 if df0 has at least one row (the empty tuple),
///     - returns 0 if df0 has zero rows.
/// - Null values are treated as distinct values (their string form participates in the combination key).
pub fn count_distinct_combinations(
    df0: &DataFrame,
    lst0: &[&str],
) -> PolarsResult<usize> {
    // Validate columns exist
    for &col in lst0 {
        if df0.find_idx_by_name(col).is_none() {
            return Err(PolarsError::NotFound(
                format!("Column '{}' not found in DataFrame", col).into(),
            ));
        }
    }

    let n_rows = df0.height();

    // Special-case empty column list
    if lst0.is_empty() {
        return Ok(if n_rows > 0 { 1 } else { 0 });
    }

    let mut seen = HashSet::new();

    // Build a string key per row by concatenating the stringified cell values with a separator.
    // Use a control char as separator to reduce accidental collisions from normal data.
    let sep = "\u{1F}"; // unit separator

    for row_idx in 0..n_rows {
        let mut parts = Vec::with_capacity(lst0.len());
        for &col in lst0 {
            // safe because we validated column exists
            let s = df0.column(col)?;
            let av = s.get(row_idx);
            // Format AnyValue to string; this yields stable representations for nulls and values.
            parts.push(av.to_string());
        }
        let key = parts.join(sep);
        seen.insert(key);
    }

    Ok(seen.len())
}
