use std::collections::HashSet;

/// Counts the number of distinct combinations of values for specified columns
/// 
/// # Arguments
/// * `df0` - A Polars DataFrame
/// * `lst0` - A vector of column names to consider for combinations
///
/// # Returns
/// * `Result<usize>` - Number of distinct combinations, or an error
fn count_distinct_combinations(
    df0: &DataFrame,
    lst0: Vec<&str>,
) -> PolarsResult<usize> {
    // Select only the specified columns
    let selected = df0.select(&lst0)?;

    // Convert to rows and collect unique combinations using a HashSet
    let mut combinations = HashSet::new();

    for row_result in selected.iter_rows() {
        let row = row_result?;
        combinations.insert(row);
    }

    Ok(combinations.len())
}

