use polars::prelude::*;

/// Simple value type for filter comparisons
#[derive(Debug, Clone)]
pub enum Value {
    Int(i64),
    Float(f64),
    Str(String),
    Bool(bool),
}

/// Supported comparison operators
#[derive(Debug, Clone, Copy)]
pub enum Operator {
    Eq,
    Ne,
    Lt,
    Lte,
    Gt,
    Gte,
    IsNull,
    IsNotNull,
}

/// One filter condition: column, operator, optional right-hand value
#[derive(Debug, Clone)]
pub struct FilterCond {
    pub column: String,
    pub op: Operator,
    pub value: Option<Value>,
}

impl FilterCond {
    pub fn new(column: impl Into<String>, op: Operator, value: Option<Value>) -> Self {
        Self {
            column: column.into(),
            op,
            value,
        }
    }
}

/// Apply a series of filter conditions (conjoined with AND) to df and return a new DataFrame.
/// Returns a Polars Result (Ok(filtered_df) or an error).
pub fn apply_filters(df: &DataFrame, conds: &[FilterCond]) -> PolarsResult<DataFrame> {
    // Convert a single FilterCond into a Polars Expr
    fn cond_to_expr(c: &FilterCond) -> Expr {
        let col_name = c.column.clone();
        match c.op {
            Operator::Eq => match &c.value {
                Some(Value::Int(i)) => col(&col_name).eq(lit(*i)),
                Some(Value::Float(f)) => col(&col_name).eq(lit(*f)),
                Some(Value::Str(s)) => col(&col_name).eq(lit(s.clone())),
                Some(Value::Bool(b)) => col(&col_name).eq(lit(*b)),
                None => col(&col_name).is_null(),
            },
            Operator::Ne => match &c.value {
                Some(Value::Int(i)) => col(&col_name).neq(lit(*i)),
                Some(Value::Float(f)) => col(&col_name).neq(lit(*f)),
                Some(Value::Str(s)) => col(&col_name).neq(lit(s.clone())),
                Some(Value::Bool(b)) => col(&col_name).neq(lit(*b)),
                None => col(&col_name).is_not_null(),
            },
            Operator::Lt => match &c.value {
                Some(Value::Int(i)) => col(&col_name).lt(lit(*i)),
                Some(Value::Float(f)) => col(&col_name).lt(lit(*f)),
                _ => panic!("Lt operator requires numeric value"),
            },
            Operator::Lte => match &c.value {
                Some(Value::Int(i)) => col(&col_name).lt_eq(lit(*i)),
                Some(Value::Float(f)) => col(&col_name).lt_eq(lit(*f)),
                _ => panic!("Lte operator requires numeric value"),
            },
            Operator::Gt => match &c.value {
                Some(Value::Int(i)) => col(&col_name).gt(lit(*i)),
                Some(Value::Float(f)) => col(&col_name).gt(lit(*f)),
                _ => panic!("Gt operator requires numeric value"),
            },
            Operator::Gte => match &c.value {
                Some(Value::Int(i)) => col(&col_name).gt_eq(lit(*i)),
                Some(Value::Float(f)) => col(&col_name).gt_eq(lit(*f)),
                _ => panic!("Gte operator requires numeric value"),
            },
            Operator::IsNull => col(&col_name).is_null(),
            Operator::IsNotNull => col(&col_name).is_not_null(),
        }
    }

    // If no conditions provided, return a clone of the original df
    if conds.is_empty() {
        return Ok(df.clone());
    }

    // Build the combined expression by AND-ing all condition expressions
    let mut expr_iter = conds.iter().map(cond_to_expr);
    let first_expr = expr_iter.next().expect("conds non-empty");
    let combined = expr_iter.fold(first_expr, |acc, e| acc.and(e));

    // Apply filter using lazy API for expression support
    let lf = df.clone().lazy().filter(combined);
    let out = lf.collect()?; // collect back to DataFrame
    Ok(out)
}

// Example usage
