    if !df.column(group_by_col).is_ok() {
        return Err(PolarsError::ColumnNotFound(group_by_col.to_string()));
    }

    // Get all numeric columns (excluding the group column)
    let numeric_cols: Vec<String> = df
        .columns()
        .iter()
        .filter(|col| col != group_by_col)
        .filter(|col| df.column(col).unwrap().dtype() == &DataType::Float64 || df.column(col).unwrap().dtype() == &DataType::Int64)
