use polars::prelude::*;
use std::collections::{HashMap, HashSet};

/// Group the columns of `df` by `labels` and compute the element-wise sum for each label group.
///
/// - `df` must have the same number of columns as `labels.len()`.
/// - All columns will be cast to Float64 before summation.
///
/// Returns a new DataFrame whose columns are the unique labels (in first-seen order)
/// and whose values are the sum (row-wise) of all columns with that label.
pub fn group_columns_sum(df: &DataFrame, labels: &[&str]) -> PolarsResult<DataFrame> {
    assert_eq!(
        df.width(),
        labels.len(),
        "labels length must match number of columns in df"
    );

    // Accumulate Series sums by label
    let mut groups: HashMap<String, Series> = HashMap::new();

    for (idx, lbl) in labels.iter().enumerate() {
        // Get column series by index and clone it
        let mut s = df.get_columns()[idx].clone();

        // Cast to Float64 to ensure uniform numeric type for addition
        if s.dtype() != &DataType::Float64 {
            s = s.cast(&DataType::Float64)?;
        }

        let key = lbl.to_string();
        groups
            .entry(key)
            .and_modify(|acc| {
                // element-wise add; the + operator on &Series returns PolarsResult<Series>
                *acc = (&*acc + &s).expect("series addition failed");
            })
            .or_insert(s);
    }

    // Preserve first-seen order of labels
    let mut seen = HashSet::new();
    let mut ordered_labels: Vec<String> = Vec::new();
    for &lbl in labels {
        if seen.insert(lbl.to_string()) {
            ordered_labels.push(lbl.to_string());
        }
    }

    // Build output Series vector in the desired order and rename each to the label
    let mut out_series: Vec<Series> = Vec::with_capacity(ordered_labels.len());
    for lbl in ordered_labels {
        let mut s = groups
            .get(&lbl)
            .expect("label present in order should exist in groups")
            .clone();
        s.rename(&lbl);
        out_series.push(s);
    }

    DataFrame::new(out_series)
}

