/// ```
pub fn group_columns_and_sum(
    data: &[Vec<f64>],
    column_labels: &[&str],
) -> HashMap<String, Vec<f64>> {
    if data.is_empty() || column_labels.is_empty() {
        return HashMap::new();
    }

    // Validate input dimensions
    let num_cols = column_labels.len();
    for row in data {
        assert_eq!(
            row.len(),
            num_cols,
            "Each row must have the same number of columns as labels"
        );
    }

    // Create a mapping from label to column indices
    let mut label_to_indices: HashMap<&str, Vec<usize>> = HashMap::new();
    for (idx, &label) in column_labels.iter().enumerate() {
        label_to_indices.entry(label).or_default().push(idx);
    }

    // Compute sums for each group
    let mut result: HashMap<String, Vec<f64>> = HashMap::new();

    for (label, indices) in &label_to_indices {
        let mut sums = vec![0.0; data.len()];

        for (row_idx, row) in data.iter().enumerate() {
            for &col_idx in indices {
                sums[row_idx] += row[col_idx];
            }
        }

        result.insert(label.to_string(), sums);
    }

    result
}

