use itertools::sorted;

/// Sorts a collection of collections by the second element of each inner collection.
/// Each inner collection must have at least two elements.
/// Returns a new Vec with elements sorted in ascending order by their second component.
///
/// # Panics
/// Panics if any inner collection has fewer than 2 elements.
