use std::collections::BinaryHeap;
use std::cmp::Reverse;

/// Determine the indices of the N highest values in a list.
///
/// Args:
///     values: The input list of values.
///     n: The number of highest values to find.
///
/// Returns:
///     A vector of indices corresponding to the N highest values in the input list.
pub fn highest_n_indices(values: Vec<f64>, n: usize) -> Vec<usize> {
    let mut heap = BinaryHeap::new();

    // Push the values and their indices onto the heap
    for (i, &val) in values.iter().enumerate() {
        heap.push((Reverse(val), i));
    }

    // Pop the N highest values from the heap and collect their indices
    let mut indices = Vec::new();
    for _ in 0..n {
        if let Some((_, index)) = heap.pop() {
            indices.push(index);
        } else {
            break;
        }
    }

    indices
}

fn main() {
    let values = vec![10.0, 20.0, 30.0, 40.0, 50.0];
    let n = 3;

    let indices = highest_n_indices(values, n);
    println!("Indices of the {} highest values: {:?}", n, indices);
}
```

