use itertools::Itertools;
use num_traits::{One, Zero};
use std::ops::{Add, Mul};

/// Sum of products of all unique k-element subsets of `values`.
///
/// - If k == 0, returns 1 (the empty product).
/// - If k > values.len(), returns 0.
/// - Works for numeric types that implement Copy, Mul, Add, Zero, and One.
///
/// Example:
/// let s = sum_products_of_k(&[1, 2, 3], 2); // returns 1*2 + 1*3 + 2*3 = 11
pub fn sum_products_of_k<T>(values: &[T], k: usize) -> T
where
    T: Copy + Mul<Output = T> + Add<Output = T> + Zero + One,
{
    if k > values.len() {
        return T::zero();
    }

    // iterate over all combinations of references, copy to T, compute product, add up
    let mut total = T::zero();
    for comb in values.iter().combinations(k) {
        let prod = comb.into_iter().copied().fold(T::one(), |acc, x| acc * x);
        total = total + prod;
    }
    total
}

