use itertools::izip;
use std::ops::Add;

/// Iterate two sequences of 2-element tuples in parallel and append the element-wise
/// sum of each tuple pair to `out`.
///
/// Both input slices may be different lengths; iteration stops at the shorter one.
/// T must implement Add and Copy (or Clone; here we use Copy for brevity).
fn append_elementwise_sum<T>(a: &[(T, T)], b: &[(T, T)], out: &mut Vec<(T, T)>)
where
    T: Add<Output = T> + Copy,
{
