use polars::prelude::*;
use std::collections::HashMap;

/// Maps categorical values in a DataFrame column to unique integer indices
/// 
/// # Arguments
/// * `df` - A mutable reference to the DataFrame
/// * `col_name` - The name of the column to encode
/// 
/// # Returns
/// * `Result<DataFrame>` - DataFrame with categorical values replaced by indices
/// 
/// # Example
/// ```
/// let df = df!("col0" => &["apple", "banana", "apple", "cherry"]).unwrap();
/// let result = encode_categorical(df, "col0").unwrap();
/// ```
fn encode_categorical(mut df: DataFrame, col_name: &str) -> PolarsResult<DataFrame> {
    // Extract the column as strings
    let series = df.column(col_name)?;
    let str_series = series.str()?;

    // Create a mapping of unique categories to integer indices
    let mut category_map: HashMap<String, u32> = HashMap::new();
    let mut next_index: u32 = 0;

    // Build the mapping and encode values in a single pass
    let encoded: Vec<u32> = str_series
        .iter()
        .map(|opt_val| {
            opt_val.map(|val| {
                *category_map.entry(val.to_string()).or_insert_with(|| {
                    let idx = next_index;
                    next_index += 1;
                    idx
                })
            })
        })
        .collect();

    // Replace the original column with encoded integers
    let encoded_series = Series::new(
        col_name,
        encoded.iter().map(|&x| x as u32).collect::<Vec<_>>(),
    );

    df.replace(col_name, encoded_series)?;

    Ok(df)
}

fn main() -> PolarsResult<()> {
