- For each column, compute the column's min, max and null-count using a LazyFrame aggregation.
- Drop a column only when (a) min == 0 and max == 0 (i.e. all non-null values are zero) and (b) there are no nulls (we treat null ≠ 0; if you want to treat nulls as zeros, change the null-check logic).

Cargo.toml (include Polars >= 2024 release — adjust exact version as appropriate):
- polars = "0.36"  # example; use a 2024+ release

Function (copy into your project; examples follow):

```rust
use polars::prelude::*;

/// Drop columns that contain only zeros across every record.
/// 
/// Behavior & assumptions:
/// - A column is dropped iff:
///     * its min == 0 and its max == 0 (i.e. all non-null values are zero)
///     * AND its null count == 0 (we treat null as NOT equal to zero)
/// - Non-numeric columns will be kept.
/// - If the DataFrame has zero rows, nothing is dropped.
///
/// Returns a new DataFrame with the zero-only columns removed.
pub fn drop_all_zero_columns(mut df: DataFrame) -> PolarsResult<DataFrame> {
    // If no rows, we do not drop anything (ambiguous semantics otherwise).
    if df.height() == 0 {
        return Ok(df);
    }

    // Collect column names
    let names: Vec<String> = df.get_columns().iter().map(|s| s.name().to_string()).collect();

    // Build aggregation expressions: for each column compute max, min, and null_count.
    let mut exprs: Vec<Expr> = Vec::with_capacity(names.len() * 3);
    for name in &names {
        exprs.push(col(name).max().alias(&format!("{}_max", name)));
        exprs.push(col(name).min().alias(&format!("{}_min", name)));
        exprs.push(col(name).null_count().alias(&format!("{}_nulls", name)));
    }

    // Execute aggregations (one-row DataFrame containing the aggregated values).
    let agg = df.lazy().select(exprs).collect()?;

    // Helper: check if an AnyValue is numerically zero.
    fn any_is_zero(av: &AnyValue) -> bool {
        match av {
            AnyValue::Int8(v) => *v == 0,
            AnyValue::Int16(v) => *v == 0,
            AnyValue::Int32(v) => *v == 0,
            AnyValue::Int64(v) => *v == 0,
            AnyValue::UInt8(v) => *v == 0,
            AnyValue::UInt16(v) => *v == 0,
            AnyValue::UInt32(v) => *v == 0,
            AnyValue::UInt64(v) => *v == 0,
            AnyValue::Float32(v) => *v == 0.0,
            AnyValue::Float64(v) => *v == 0.0,
            // Null or other variants are not treated as zero here.
            _ => false,
        }
    }

    // Decide which columns to keep.
    let mut keep: Vec<String> = Vec::with_capacity(names.len());
    for name in names {
        let max_col_name = format!("{}_max", &name);
        let min_col_name = format!("{}_min", &name);
        let nulls_col_name = format!("{}_nulls", &name);

        // Get the aggregated series and their single-row AnyValue.
        let max_series = agg.column(&max_col_name)?;
        let min_series = agg.column(&min_col_name)?;
        let null_series = agg.column(&nulls_col_name)?;

        let max_val = max_series.get(0);
        let min_val = min_series.get(0);
        let null_val = null_series.get(0);

        // interpret null count (null_val) as zero if it's numeric 0
        let null_count_is_zero = match null_val {
            AnyValue::UInt32(v) => v == 0,
            AnyValue::UInt64(v) => v == 0,
            AnyValue::Int32(v) => v == 0,
            AnyValue::Int64(v) => v == 0,
            // fallback: if null_count isn't numeric, keep the column
            _ => false,
        };

        // Determine whether both min and max are zero numerically.
        let both_zero = any_is_zero(&max_val) && any_is_zero(&min_val);

        // Only drop when both_zero AND null_count == 0.
        if both_zero && null_count_is_zero {
            // drop: do not push to keep
        } else {
            keep.push(name);
        }
    }

    // Select only kept columns and return.
    let keep_refs: Vec<&str> = keep.iter().map(|s| s.as_str()).collect();
    let out = df.select(&keep_refs)?;
    Ok(out)
}
```

