use polars::prelude::*;

/// Deletes all columns from a DataFrame that contain only zero values.
/// 
/// # Arguments
/// * `df` - A Polars DataFrame
/// 
/// # Returns
/// A new DataFrame with all-zero columns removed
/// 
/// # Example
/// ```
/// use polars::prelude::*;
/// 
/// let df = df! {
///     "a" => &[1, 2, 3],
///     "b" => &[0, 0, 0],
///     "c" => &[4, 5, 6],
///     "d" => &[0.0, 0.0, 0.0],
/// }.unwrap();
/// 
/// let result = remove_zero_columns(df).unwrap();
/// assert_eq!(result.shape().1, 2); // Only 2 columns remain
/// ```
fn remove_zero_columns(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut cols_to_keep = Vec::new();

    for col_name in df.get_column_names() {
        let column = df.column(col_name)?;

        // Check if all values are zero
        let all_zeros = match column.dtype() {
            DataType::Int64 | DataType::Int32 | DataType::Int16 | DataType::Int8 => {
                column
                    .i64()?
                    .into_iter()
                    .all(|val| val.map_or(false, |v| v == 0))
            }
            DataType::Float64 | DataType::Float32 => {
                column
                    .f64()?
                    .into_iter()
                    .all(|val| val.map_or(false, |v| v == 0.0))
            }
            DataType::UInt64 | DataType::UInt32 | DataType::UInt16 | DataType::UInt8 => {
                column
                    .u64()?
                    .into_iter()
                    .all(|val| val.map_or(false, |v| v == 0))
            }
            _ => false, // Non-numeric columns are kept
        };

        if !all_zeros {
            cols_to_keep.push(col_name.to_string());
        }
    }

    df.select(cols_to_keep)
}

fn main() -> PolarsResult<()> {
    // Example usage
    let df = df! {
        "name" => &["Alice", "Bob", "Charlie"],
        "zeros_int" => &[0, 0, 0],
        "score" => &[95, 87, 92],
        "zeros_float" => &[0.0, 0.0, 0.0],
        "count" => &[5, 10, 8],
    }?;

    println!("Original DataFrame:");
    println!("{}", df);

    let result = remove_zero_columns(df)?;

    println!("\nAfter removing all-zero columns:");
    println!("{}", result);

    Ok(())
}
