use hashbrown::HashMap;

/// Assigns a unique integer to each distinct value in the order that the values first appear in the list.
///
/// # Arguments
///
/// * `values` - A list of values.
///
/// # Returns
///
/// A vector of tuples, where each tuple contains a value and its corresponding unique integer.
fn assign_unique_integers<T: Eq + std::hash::Hash>(values: Vec<T>) -> Vec<(T, usize)> {
    let mut map = HashMap::new();
    let mut result = Vec::new();
    let mut counter = 0;

    for value in values {
        if !map.contains_key(&value) {
            map.insert(value.clone(), counter);
            counter += 1;
        }
        result.push((value, *map.get(&value).unwrap()));
    }

    result
}

fn main() {
    let values = vec!["apple", "banana", "apple", "orange", "banana", "grape"];
    let result = assign_unique_integers(values);
    println!("{:?}", result);
}
```

