# Rust Function for Unique Value Assignment

```rust
use indexmap::IndexMap;

/// Assigns a unique integer to each distinct value in the order they first appear.
/// 
/// # Arguments
/// * `values` - A slice of comparable values
/// 
/// # Returns
/// A vector where each element corresponds to the unique ID of the input value
/// 
/// # Example
/// ```
/// let input = vec!["apple", "banana", "apple", "cherry", "banana"];
/// let result = assign_unique_ids(&input);
/// assert_eq!(result, vec![0, 1, 0, 2, 1]);
/// ```
fn assign_unique_ids<T: Clone + Eq + std::hash::Hash>(values: &[T]) -> Vec<usize> {
    let mut id_map: IndexMap<T, usize> = IndexMap::new();
    let mut next_id = 0;

    values
        .iter()
        .map(|value| {
            *id_map.entry(value.clone()).or_insert_with(|| {
                let id = next_id;
                next_id += 1;
                id
            })
        })
        .collect()
}

fn main() {
