use polars::prelude::*;

/// Replace missing values in `target_column` with values from `source_column`
/// 
/// # Arguments
/// * `df` - The DataFrame to modify
/// * `target_column` - Column name with missing values to fill
/// * `source_column` - Column name to take replacement values from
///
/// # Returns
/// Result containing the modified DataFrame
fn replace_missing_values(
    mut df: DataFrame,
    target_column: &str,
    source_column: &str,
) -> PolarsResult<DataFrame> {
    // Get both columns
    let target = df.column(target_column)?.clone();
    let source = df.column(source_column)?.clone();

