use polars::prelude::*;
use std::error::Error;

/// Compute the Pearson correlation coefficient between "var0" and "var1" in `df0`.
/// Returns an error if columns are missing, lengths differ, or there are insufficient paired values.
fn correlation_var0_var1(df0: &DataFrame) -> Result<f64, Box<dyn Error>> {
    // Get columns and cast to Float64
    let s0 = df0.column("var0")?.cast(&DataType::Float64)?;
    let s1 = df0.column("var1")?.cast(&DataType::Float64)?;

    // Downcast to Float64 chunked arrays
    let a0 = s0.f64().ok_or("failed to downcast var0 to Float64")?;
    let a1 = s1.f64().ok_or("failed to downcast var1 to Float64")?;

    if a0.len() != a1.len() {
        return Err("columns have unequal lengths".into());
    }

    // Accumulate paired non-null values
    let mut n = 0usize;
    let mut sum_x = 0.0;
    let mut sum_y = 0.0;
    let mut sum_x2 = 0.0;
    let mut sum_y2 = 0.0;
    let mut sum_xy = 0.0;

    for i in 0..a0.len() {
        match (a0.get(i), a1.get(i)) {
            (Some(x), Some(y)) => {
                n += 1;
                sum_x += x;
                sum_y += y;
                sum_x2 += x * x;
                sum_y2 += y * y;
                sum_xy += x * y;
            }
            _ => { /* skip pairs with any null */ }
        }
    }

    if n < 2 {
        return Err("not enough paired (non-null) values to compute correlation".into());
    }

    let n_f = n as f64;
    let mean_x = sum_x / n_f;
    let mean_y = sum_y / n_f;

    // Using population moments; same denominator for covariance and variances
    let cov = (sum_xy / n_f) - (mean_x * mean_y);
    let var_x = (sum_x2 / n_f) - (mean_x * mean_x);
    let var_y = (sum_y2 / n_f) - (mean_y * mean_y);

    // Guard against tiny negative rounding artifacts
    let var_x = if var_x < 0.0 && var_x.abs() < 1e-12 { 0.0 } else { var_x };
    let var_y = if var_y < 0.0 && var_y.abs() < 1e-12 { 0.0 } else { var_y };

    if var_x == 0.0 || var_y == 0.0 {
        return Err("zero variance in one of the variables; correlation undefined".into());
    }

    Ok(cov / (var_x.sqrt() * var_y.sqrt()))
}

// Example usage:
fn main() -> Result<(), Box<dyn Error>> {
    // Build a small example DataFrame named df0
    let df0 = DataFrame::new(vec![
        Series::new("var0", &[1.0_f64, 2.0, 3.0, 4.0, 5.0]),
        Series::new("var1", &[2.0_f64, 4.0, 6.0, 8.0, std::f64::NAN]), // NAN will be treated as null after cast
    ])?;

    let corr = correlation_var0_var1(&df0)?;
    println!("Pearson correlation between var0 and var1 = {:.6}", corr);

    Ok(())
}
```

