/// ];
/// let sorted = sort_items(&items);
/// assert_eq!(sorted[0]["weight"], 1);
/// assert_eq!(sorted[1]["weight"], 2);
/// assert_eq!(sorted[2]["weight"], 2);
/// ```
pub fn sort_items(items: &[Value]) -> Vec<Value> {
    let mut sorted: Vec<_> = items.to_vec();

    // Custom comparator using serde_json::Value's numeric comparison
    sorted.sort_by(|a, b| {
        // Compare weights first
        let weight_a = a["weight"].as_f64().unwrap_or(0.0);
        let weight_b = b["weight"].as_f64().unwrap_or(0.0);
        match weight_a.partial_cmp(&weight_b) {
