    let df = CsvReader::new(cursor)
        .has_header(has_header)
        .finish()?;

    // For each Series (column), check the null count
    let result = df
        .get_columns()
        .iter()
        .map(|s| (s.name().to_string(), s.null_count() > 0))
        .collect();

    Ok(result)
}

