use polars::prelude::*;
use chrono::NaiveDate;

/// Convert the column "var0" of `df0` to a Date32 (days since 1970-01-01).
/// - `fmt` is a strftime-style format string used to parse the input strings (e.g. "%Y-%m-%d").
/// - On parse errors or null input values, the resulting entries will be null.
/// - Returns an error if the column "var0" does not exist or is not string/utf8 convertible.
///
/// Example:
/// let df_out = convert_var0_to_date(df_in, "%Y-%m-%d")?;
pub fn convert_var0_to_date(mut df0: DataFrame, fmt: &str) -> PolarsResult<DataFrame> {
    // Ensure column exists
    if !df0.get_column_names().iter().any(|c| c == "var0") {
        return Err(PolarsError::NotFound("column 'var0' not found in DataFrame".into()));
    }

    // If already a date type, nothing to do
    match df0.column("var0")?.dtype() {
        DataType::Date32 | DataType::Date64 => return Ok(df0),
        _ => {}
    }

    // Get the column as Utf8Chunked (error if not utf8/string)
    let s = df0.column("var0")?;
    let utf8 = s.utf8().map_err(|_| {
        PolarsError::ComputeError("column 'var0' is not a utf8/string column and cannot be parsed as date".into())
    })?;

    // Epoch for Date32 (days since 1970-01-01)
    let epoch = NaiveDate::from_ymd_opt(1970, 1, 1)
        .ok_or_else(|| PolarsError::ComputeError("invalid epoch date".into()))?;

    // Parse each string into an Option<i32> (days since epoch). On parse error produce None.
    let parsed_days: Vec<Option<i32>> = utf8.into_iter().map(|opt_str| {
        opt_str.and_then(|s| {
            NaiveDate::parse_from_str(s, fmt)
                .ok()
                .map(|d| (d.signed_duration_since(epoch).num_days() as i32))
        })
    }).collect();

    // Create an Int32 series from the parsed days and cast it to Date32
    let int_series = Series::new("var0", parsed_days);
    let date_series = int_series.cast(&DataType::Date32)?;

    // Replace the column in the DataFrame
    df0.replace("var0", date_series)?;

    Ok(df0)
}

