```rust
use polars::prelude::*;

/// Imputes missing values in a 2D dataset with the average of their corresponding column.
/// 
/// # Arguments
/// * `data` - A Polars DataFrame with numeric columns
/// 
/// # Returns
/// * A DataFrame with missing values replaced by column averages
/// 
/// # Example
/// ```
/// use polars::prelude::*;
/// 
/// let df = df! {
///     "a" => [1.0, f64::NAN, 3.0],
///     "b" => [4.0, 5.0, f64::NAN],
/// }.unwrap();
/// 
/// let imputed = impute_with_column_mean(df).unwrap();
/// println!("{}", imputed);
/// ```
fn impute_with_column_mean(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut result = df.clone();

    for col_name in result.get_column_names() {
        let series = result.column(col_name)?;

        // Calculate the mean of the column
        let mean = series.mean();

        if let Some(mean_value) = mean {
            // Replace null/NaN values with the mean
            let filled = series.fill_null(FillNullStrategy::Mean)?;
            result = result.with_column(filled)?;
        }
    }

    Ok(result)
}

fn main() -> PolarsResult<()> {
    // Example usage with sample data
    let df = df!(
        "column_a" => [Some(1.0), None, Some(3.0), Some(5.0)],
        "column_b" => [Some(10.0), Some(20.0), None, Some(40.0)],
        "column_c" => [None, Some(100.0), Some(200.0), Some(300.0)],
    )?;

