use tabled::{Table, Tabled};
use std::collections::HashMap;

// Define a simple labeled 2D table structure
#[derive(Debug, Tabled)]
struct LabeledTable<T> {
    #[tabled(rename = "Row")]
    rows: Vec<String>,
    #[tabled(rename = "Col")]
    cols: Vec<String>,
    #[tabled(rename = "Value")]
    data: Vec<Vec<T>>,
}

impl<T> LabeledTable<T> {
    /// Creates a new labeled 2D table
    pub fn new(rows: Vec<String>, cols: Vec<String>, data: Vec<Vec<T>>) -> Self {
        Self { rows, cols, data }
    }

    /// Retrieves the value at the intersection of row and column labels
    pub fn get(&self, row_label: &str, col_label: &str) -> Option<&T> {
        // Find row index
        let row_idx = self.rows.iter().position(|r| r == row_label)?;
        // Find column index
        let col_idx = self.cols.iter().position(|c| c == col_label)?;

        // Check bounds and return value
        self.data.get(row_idx)?.get(col_idx)
    }
}

