use indexmap::IndexMap;
use std::hash::Hash;

/// Reorder `lst0` so that tuples follow the order specified by `lst1`.
///
/// - `lst0` is a Vec of (K, V) tuples.
/// - `lst1` is any IntoIterator of keys (owned K values) that defines the desired ordering.
/// - Keys not present in `lst1` are appended after the specified keys, preserving their original order.
///
/// Example:
/// let lst0 = vec![("b", 2), ("a", 1), ("b", 3), ("c", 4)];
/// let lst1 = vec!["a", "b"];
/// let out = reorder_by_ordering(lst0, lst1);
/// // out == [("a",1), ("b",2), ("b",3), ("c",4)]
pub fn reorder_by_ordering<K, V, I>(lst0: Vec<(K, V)>, lst1: I) -> Vec<(K, V)>
where
    K: Eq + Hash + Clone,
    I: IntoIterator<Item = K>,
{
    // Map key -> list of values (preserve insertion order of keys)
    let mut map: IndexMap<K, Vec<V>> = IndexMap::new();

    for (k, v) in lst0 {
        map.entry(k).or_insert_with(Vec::new).push(v);
    }

    let mut result: Vec<(K, V)> = Vec::new();
    let mut seen: IndexMap<K, ()> = IndexMap::new(); // used to ignore duplicate keys in lst1

    // First, emit keys in the order given by lst1
    for key in lst1 {
        if seen.contains_key(&key) {
            continue; // skip duplicates in lst1
        }
        seen.insert(key.clone(), ());
        if let Some(vals) = map.shift_remove(&key) {
            for v in vals {
                result.push((key.clone(), v));
            }
        }
    }

    // Then append remaining keys (in the original insertion order from lst0)
    for (k, vals) in map.into_iter() {
        for v in vals {
            result.push((k.clone(), v));
        }
    }

    result
}

fn main() {
