        ("b".to_string(), 2),
        ("a".to_string(), 1),
        ("b".to_string(), 3),
        ("c".to_string(), 4),
    ];
    let lst1 = vec!["a".to_string(), "b".to_string()];
    let out = reorder_by_ordering(lst0, lst1);
    println!("{:?}", out);
    // Prints: [("a", 1), ("b", 2), ("b", 3), ("c", 4)]
}
```

