use indexmap::IndexMap;

/// Reorders a sequence of tuples according to a specified order sequence.
///
/// # Arguments
/// * `lst0` - A vector of tuples (key, value) to be reordered
/// * `lst1` - A vector defining the desired order of keys
///
/// # Returns
/// A new vector of tuples reordered according to lst1
///
/// # Example
/// ```
/// let tuples = vec![("a", 1), ("b", 2), ("c", 3)];
/// let order = vec!["c", "a", "b"];
/// let result = reorder_by_sequence(tuples, order);
/// assert_eq!(result, vec![("c", 3), ("a", 1), ("b", 2)]);
/// ```
fn reorder_by_sequence<K: Eq + std::hash::Hash + Clone, V: Clone>(
    lst0: Vec<(K, V)>,
    lst1: Vec<K>,
) -> Vec<(K, V)> {
    // Create a map for O(1) lookup of tuples by key
    let mut map: IndexMap<K, V> = lst0.into_iter().collect();

    // Reorder according to lst1, preserving only keys that exist in both sequences
    lst1.into_iter()
        .filter_map(|key| {
            map.shift_remove(&key).map(|value| (key, value))
        })
        .collect()
}

