/// # Arguments
///
/// * `tree`: The trained decision tree object.
/// * `feature_names`: The list of feature names.
///
/// # Returns
///
/// A vector of strings representing the decision rules in a human-readable form.
fn extract_decision_rules(tree: &DecisionTreeClassifier, feature_names: &[String]) -> Vec<String> {
    let mut rules = Vec::new();
    let tree = tree.tree();

    // Iterate over all nodes in the tree
    for node in tree.nodes() {
