            continue;
        }

        // Get the feature index and threshold for the current node
        let feature_idx = node.feature();
        let threshold = node.threshold();

        // Get the feature name from the feature_names list
        let feature_name = &feature_names[feature_idx as usize];

        // Get the left and right child node indices
        let left_child = node.left_child();
        let right_child = node.right_child();

        // Recursively generate rules for the left and right child nodes
        let left_rule = generate_rule(tree, left_child, feature_names);
        let right_rule = generate_rule(tree, right_child, feature_names);

        // Create the decision rule for the current node
        let rule = format!("If {} <= {}, then {} else {}", feature_name, threshold, left_rule, right_rule);

        rules.push(rule);
    }

    rules
}

