        format!("Class {}", node.value())
    } else {
        // If the node is not a leaf node, recursively generate rules for its children
        let feature_idx = node.feature();
        let threshold = node.threshold();
        let feature_name = &feature_names[feature_idx as usize];
        let left_child = node.left_child();
        let right_child = node.right_child();

        let left_rule = generate_rule(tree, left_child, feature_names);
        let right_rule = generate_rule(tree, right_child, feature_names);

        format!("If {} <= {}, then {} else {}", feature_name, threshold, left_rule, right_rule)
    }
}

