    feature_names0: &[String],
) -> Vec<DecisionRule> {
    let mut rules = Vec::new();
    let mut current_conditions: Vec<String> = Vec::new();

    // Recursively traverse the tree
    traverse_tree(
        tree0,
        feature_names0,
        &mut current_conditions,
        &mut rules,
        0, // start at root node
    );

