/// Recursive helper to traverse the decision tree
fn traverse_tree(
    tree: &linfa_trees::DecisionTree<f64, usize>,
    feature_names: &[String],
    current_conditions: &mut Vec<String>,
    rules: &mut Vec<DecisionRule>,
    node_id: usize,
) {
    // Get node information from the tree
    let node = tree.get_node(node_id);

    match node {
        linfa_trees::TreeNode::Internal(internal) => {
            // Get feature name and threshold
            let feature_name = &feature_names[internal.feature];
            let threshold = internal.threshold;

            // Left branch: feature <= threshold
            let left_condition = format!("{} <= {:.4}", feature_name, threshold);
            current_conditions.push(left_condition);
            traverse_tree(tree, feature_names, current_conditions, rules, internal.left_child);
            current_conditions.pop();

            // Right branch: feature > threshold
            let right_condition = format!("{} > {:.4}", feature_name, threshold);
            current_conditions.push(right_condition);
            traverse_tree(tree, feature_names, current_conditions, rules, internal.right_child);
            current_conditions.pop();
        }
        linfa_trees::TreeNode::Leaf(leaf) => {
            // Create a rule from the current path
            let rule = DecisionRule {
                conditions: current_conditions.clone(),
                prediction: leaf.value as f64,
                leaf_id: node_id,
            };
            rules.push(rule);
        }
    }
