use itertools::Itertools;

fn swap_first_two<T: Clone>(list: Vec<T>) -> Vec<T> {
    if list.is_empty() {
        return list;
    }

    list.into_iter()
        .enumerate()
        .map(|(i, item)| {
            match i {
                0 => list.get(1).cloned().unwrap_or(item),
                1 => list.get(0).cloned().unwrap_or(item),
                _ => item,
            }
        })
        .collect()
