///
/// - `df`: input DataFrame (consumed).
/// - `split_col`: name of the column to split/expand (must be a string/Utf8 column).
/// - `delimiter`: the delimiter to split on (passed to the string split operation).
/// - `order`: final column order (slice of column names).
///
/// Returns a new DataFrame or a Polars error.
pub fn split_expand_and_reorder(
    df: DataFrame,
    split_col: &str,
    delimiter: &str,
    order: &[&str],
) -> PolarsResult<DataFrame> {
    // Basic validation: split_col exists
    if !df.get_column_names().iter().any(|&c| c == split_col) {
        return Err(PolarsError::NotFound(
            format!("split column '{}' not found in DataFrame", split_col),
        ));
    }

    // Optionally validate the requested final order columns exist in the input DataFrame
    // (they will also be present after the explosion if they exist initially).
    for &col_name in order {
        if !df.get_column_names().iter().any(|&c| c == col_name) {
            return Err(PolarsError::NotFound(
                format!("requested column '{}' in order not found in DataFrame", col_name),
            ));
        }
    }

