```rust
use polars::prelude::*;

/// Splits and expands entries in a column, then rearranges columns to a specified order.
///
/// # Arguments
/// * `df` - The input DataFrame
/// * `str0` - The name of the column to split
/// * `var1` - The delimiter to use for splitting
/// * `str1` - A vector of column names in the desired output order
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - The transformed DataFrame or an error
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "name" => ["Alice,Bob", "Charlie"],
///     "age" => [25, 30],
/// }?;
///
/// let result = split_and_rearrange(
///     df,
///     "name",
///     ",",
///     vec!["age", "name"],
/// )?;
/// ```
pub fn split_and_rearrange(
    df: DataFrame,
    str0: &str,
    var1: &str,
    str1: Vec<&str>,
) -> Result<DataFrame, PolarsError> {
    // Step 1: Split the specified column and expand rows
    let split_df = df
        .clone()
        .lazy()
        .with_columns([col(str0)
            .str()
            .split(var1)
            .alias(&format!("{}_split", str0))])
        .unnest(&format!("{}_split", str0))
        .collect()?;

    // Step 2: Get all columns except the original split column
    let mut cols_to_keep: Vec<&str> = split_df
        .get_column_names()
        .into_iter()
        .filter(|&col_name| col_name != str0)
        .collect();

    // Step 3: Validate that all requested columns exist
    for col_name in &str1 {
        if !cols_to_keep.contains(col_name) && *col_name != str0 {
            return Err(PolarsError::ColumnNotFound(
                (*col_name).to_string().into(),
            ));
        }
    }

    // Step 4: Rearrange columns according to str1
    let mut final_col_order: Vec<&str> = str1.clone();

    // Add any remaining columns that weren't in str1
    for col in cols_to_keep {
        if !final_col_order.contains(&col) {
            final_col_order.push(col);
        }
    }

    // Step 5: Select columns in the specified order
    let result = split_df.select(final_col_order)?;

    Ok(result)
}

