/// );
///
/// let result = compare_columns(&df, "var0", "var1").unwrap();
/// assert_eq!(result, &[true, true, false]);
/// ```
pub fn compare_columns(df0: &DataFrame, var0: &str, var1: &str) -> Result<Series<bool>, Box<dyn Error>> {
    // Check if columns exist
    if !df0.column(var0).is_ok() || !df0.column(var1).is_ok() {
        return Err(format!("Columns '{}' or '{}' not found in DataFrame", var0, var1).into());
    }

    // Get the columns to compare
    let col0 = df0.column(var0)?.unwrap();
    let col1 = df0.column(var1)?.unwrap();

    // Ensure both columns have the same length
    if col0.len() != col1.len() {
        return Err(format!(
            "Columns '{}' and '{}' have different lengths ({} vs {})",
            var0,
            var1,
            col0.len(),
            col1.len()
        ).into());
    }

    // Compare the columns element-wise
    let result = col0.eq(&col1)?;

    Ok(result)
}
