    new_columns: HashMap<String, DataFrame>,
    priority_order: Vec<String>,
) -> Result<DataFrame, PolarsError> {
    // Collect all columns from base table and new columns
    let mut all_columns = base_table.columns().to_vec();
    let mut new_columns_colnames = new_columns.keys().cloned().collect::<Vec<_>>();

    // Add new columns to the base columns
    all_columns.extend(new_columns_colnames);

    // Create a mapping from column name to its DataFrame
    let mut col_to_df = HashMap::new();
    for col in base_table.columns() {
        col_to_df.insert(col.name().to_string(), col);
    }
    for (name, df) in new_columns {
        col_to_df.insert(name, df.column(&name).unwrap());
    }

    // Build the new DataFrame with specified order
    let mut new_columns = Vec::new();
    for col_name in priority_order {
        if let Some(col) = col_to_df.get(&col_name) {
            new_columns.push(col.clone());
