/// * `priority_cols` - A list of column names defining the desired priority order.
///
/// # Returns
///
/// A new DataFrame with the specified columns in the desired order, while maintaining
/// the relative positions of other columns.
pub fn preserve_column_order(base_df: &DataFrame, priority_cols: Vec<String>) -> DataFrame {
    // Get the column names of the base DataFrame
    let base_cols: Vec<String> = base_df.columns().iter().map(|col| col.name().to_string()).collect();

    // Split the column names into two vectors: one for priority columns and one for other columns
    let mut other_cols: Vec<String> = base_cols
