use polars::prelude::*;
use std::collections::HashMap;

/// Merges a base table with new columns while preserving a specified column order.
///
/// # Arguments
/// * `base_df` - The base DataFrame to which columns will be added
/// * `new_df` - DataFrame containing new columns to concatenate
/// * `priority_columns` - Ordered list of column names that should appear first in the result
///
/// # Returns
/// * `PolarsResult<DataFrame>` - Merged DataFrame with columns in the specified order
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let base = df![
///     "a" => [1, 2],
///     "b" => [3, 4],
///     "c" => [5, 6]
/// ].unwrap();
///
/// let new = df![
///     "x" => [7, 8],
///     "y" => [9, 10]
/// ].unwrap();
///
/// let result = merge_with_column_order(base, new, &["y", "x"]).unwrap();
/// // Result columns: y, x, a, b, c
/// ```
pub fn merge_with_column_order(
    base_df: DataFrame,
    new_df: DataFrame,
    priority_columns: &[&str],
) -> PolarsResult<DataFrame> {
    // Collect all columns from both DataFrames
    let base_columns: Vec<&str> = base_df.get_column_names().iter().map(|s| s.as_str()).collect();
    let new_columns: Vec<&str> = new_df.get_column_names().iter().map(|s| s.as_str()).collect();

    // Create a set of all columns for quick lookup
    let all_columns: Vec<&str> = base_columns.iter()
        .chain(new_columns.iter())
        .copied()
        .collect();

    // Track which columns have been placed
    let mut placed: HashMap<&str, bool> = HashMap::new();
    for col in &all_columns {
        placed.insert(col, false);
    }

    // Build the final column order
    let mut final_order: Vec<&str> = Vec::with_capacity(all_columns.len());

    // 1. Add priority columns in specified order
    for col in priority_columns {
        if all_columns.contains(col) && !placed[col] {
            final_order.push(col);
            placed.insert(col, true);
        }
    }

    // 2. Add remaining base columns in their original relative order
    for col in &base_columns {
        if !placed[col] {
            final_order.push(col);
            placed.insert(col, true);
        }
    }

    // 3. Add any remaining new columns (not in priority list) in their original relative order
    for col in &new_columns {
        if !placed[col] {
            final_order.push(col);
            placed.insert(col, true);
        }
    }

    // Merge the DataFrames horizontally
    let mut merged = base_df.hstack(&new_df.get_columns())?;

    // Reorder columns according to final_order
    let reordered_series: Vec<Series> = final_order
        .iter()
        .map(|col| merged.column(col).unwrap().clone())
        .collect();

    DataFrame::new(reordered_series)
}

