///     "b" => &[4, 5, 6],
///     "c" => &[7, 8, 9],
/// }.unwrap();
///
/// let new_col = Series::new("x", &[10, 11, 12]);
/// let priority = vec!["x", "a", "b", "c"];
///
/// let result = preserve_column_order(base, new_col, "x", Some(priority)).unwrap();
/// // Result columns: x, a, b, c
/// ```
fn preserve_column_order(
    mut base_df: DataFrame,
    new_series: Series,
    column_name: &str,
    priority_order: Option<Vec<&str>>,
) -> PolarsResult<DataFrame> {
    // Add the new column to the base dataframe
    base_df.with_column(new_series)?;

    // If no priority order is specified, return as-is
    let Some(priority) = priority_order else {
        return Ok(base_df);
    };

    // Get all current column names
    let current_columns: Vec<&str> = base_df.get_column_names();

    // Separate columns into priority-ordered and remaining
    let mut ordered_cols = Vec::new();
    let mut remaining_cols = current_columns.clone();

    // Add priority columns in order (if they exist)
    for col_name in priority {
        if current_columns.contains(&col_name) {
            ordered_cols.push(col_name);
            remaining_cols.retain(|&x| x != col_name);
        }
    }

    // Append remaining columns in their original relative order
    ordered_cols.extend(remaining_cols);

    // Select columns in the desired order
    base_df.select(ordered_cols)
}

