use ordered_float::OrderedFloat;

/// Sorts a list of tuples in descending order based on the second element.
///
/// # Examples
/// ```
/// use ordered_float::OrderedFloat;
///
/// let lst0 = vec![
///     (1, 3.14),
///     (2, 2.71),
///     (3, 1.41),
/// ];
/// let sorted = sort_by_second_descending(lst0);
/// assert_eq!(sorted, vec![(1, 3.14), (2, 2.71), (3, 1.41)]);
/// ```
pub fn sort_by_second_descending<T, U>(lst0: Vec<(T, U)>) -> Vec<(T, U)>
where
    U: Ord + Into<OrderedFloat<f64>>,
{
    let mut sorted = lst0;
    sorted.sort_by(|a, b| {
        OrderedFloat::from(b.1).partial_cmp(&OrderedFloat::from(a.1))
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    sorted
}
