```rust
use polars::prelude::*;

/// Convert df0 grouped by `var0` into a new table with a hierarchical (multi-level)
/// index represented by two columns: (var0, "__orig_index").
///
/// - The first level is the grouping key `var0`.
/// - The second level is the original row index (integers 0..n-1).
/// - Rows are sorted by `var0` so groups are contiguous.
///
/// Returns a new DataFrame with `var0` and "__orig_index" moved to the front.
pub fn group_to_hierarchical_index(df0: &DataFrame, var0: &str) -> PolarsResult<DataFrame> {
    // Clone the input DataFrame (Polars DataFrame is cheap to clone for this use).
    let mut df = df0.clone();

    // Create original index column
    let n = df.height();
    let orig_idx: Vec<i64> = (0..n as i64).collect();
    let s_idx = Series::new("__orig_index", orig_idx);

    // Attach the original index column
    df = df.with_column(s_idx)?;

    // Sort by the grouping key so group members become contiguous
    df = df.sort(var0, false)?;

    // Reorder columns so that var0 and "__orig_index" are the first two columns
    let all_names: Vec<String> = df.get_columns().iter().map(|s| s.name().to_string()).collect();
    let mut order = Vec::with_capacity(all_names.len());
    order.push(var0.to_string());
    order.push("__orig_index".to_string());
    for name in all_names {
        if name != var0 && name != "__orig_index" {
            order.push(name);
        }
    }

    // Collect columns in the new order and build the resulting DataFrame
    let cols = order
        .iter()
        .map(|n| df.column(n.as_str()).unwrap().clone())
        .collect::<Vec<Series>>();

    DataFrame::new(cols)
}
