    // Build the output DataFrame
    let mut output_columns = Vec::new();

    // Create the hierarchical index columns
    let group_index: Vec<AnyValue> = result_rows.iter().map(|row| row[0].clone()).collect();
    let row_index: Vec<AnyValue> = result_rows.iter().map(|row| row[1].clone()).collect();

    output_columns.push(Series::new(var0, group_index));
    output_columns.push(Series::new("_row_index", row_index));

    // Add the remaining columns
    for (col_idx, col_name) in other_columns.iter().enumerate() {
        let values: Vec<AnyValue> = result_rows.iter()
            .map(|row| row[col_idx + 2].clone())
            .collect();
        output_columns.push(Series::new(col_name, values));
    }

    // Create the final DataFrame
    let result_df = DataFrame::new(output_columns)?;

    // Set the hierarchical index
    let result_df = result_df
        .lazy()
        .with_column(
            // Create a struct column for the hierarchical index
            when(col(var0).is_not_null())
                .then(
                    struct_([col(var0), col("_row_index")])
                )
                .otherwise(lit(Null))
                .alias("__hierarchical_index")
        )
        .drop(["_row_index"])
        .collect()?;

    Ok(result_df)
