Code:

```rust
use rayon::prelude::*;

/// Sum the digits of each digit-only text entry in `entries`.
///
/// Returns `Ok(Vec<u32>)` with one sum per input string on success.
/// Returns `Err(String)` if any input contains a non-digit character (the error
/// message includes the offending entry index and content).
pub fn sum_digits_per_entry(entries: &[String]) -> Result<Vec<u32>, String> {
    // Iterate in parallel over entries, validating and computing the sum of digits.
    entries
        .par_iter()
        .enumerate()
        .map(|(idx, s)| {
            // Work on bytes for speed since inputs are expected to be ASCII digits.
            let mut sum: u32 = 0;
            for &b in s.as_bytes() {
                if !(b'0'..=b'9').contains(&b) {
                    return Err(format!("Entry {} is not digit-only: {:?}", idx, s));
                }
                sum += (b - b'0') as u32;
            }
            Ok(sum)
        })
        // Collect will short-circuit on the first Err encountered and return it.
        .collect()
}

fn main() {
    let inputs = vec![
        "12345".to_string(),
        "0001".to_string(),
        "9876543210".to_string(),
    ];

    match sum_digits_per_entry(&inputs) {
        Ok(sums) => {
            println!("Sums: {:?}", sums); // Sums: [15, 1, 45]
        }
        Err(e) => {
            eprintln!("Error: {}", e);
        }
    }
}

