/// let result = combine_lists(&lists, &sequence);
/// assert_eq!(result, vec![1, 4, 2, 6, 5, 7, 3, 8, 9]);
/// ```
pub fn combine_lists<T: Clone>(lists: &[Vec<T>], sequence: &[usize]) -> Vec<T> {
    // Create iterators for each list and track their positions
    let mut iterators: Vec<_> = lists.iter().map(|list| list.iter()).collect();

    // Track how many elements we've taken from each list
    let mut taken_counts = vec![0usize; lists.len()];

    // Collect results following the sequence
    sequence
        .iter()
        .filter_map(|&list_idx| {
            // Get the current position in the specified list
            let current_count = &mut taken_counts[list_idx];

            // Try to get the next element from this list
            iterators[list_idx].nth(0).map(|item| {
                *current_count += 1;
                item.clone()
            })
        })
        .collect()
}

