/// let result = combine_by_sequence(lists, sequence);
/// assert_eq!(result, vec![1, 10, 2, 100, 20, 3, 200, 300]);
/// ```
fn combine_by_sequence<T: Clone>(
    mut lists: Vec<Vec<T>>,
    sequence: Vec<usize>,
) -> Vec<T> {
    let mut iterators: Vec<_> = lists.into_iter().map(|l| l.into_iter()).collect();

    sequence
        .into_iter()
        .filter_map(|idx| {
            if idx < iterators.len() {
                iterators[idx].next()
            } else {
                None
            }
        })
        .collect()
}

fn main() {
    // Example 1: Basic interleaving
    let lists = vec![
        vec![1, 2, 3],
        vec![10, 20],
        vec![100, 200, 300],
    ];
    let sequence = vec![0, 1, 0, 2, 1, 0, 2, 2];
    let result = combine_by_sequence(lists, sequence);
    println!("Example 1: {:?}", result);
    // Output: [1, 10, 2, 100, 20, 3, 200, 300]

    // Example 2: Alternating pattern
    let lists = vec![
        vec!['a', 'b', 'c'],
        vec!['x', 'y', 'z'],
    ];
    let sequence = vec![0, 1, 0, 1, 0, 1];
    let result = combine_by_sequence(lists, sequence);
    println!("Example 2: {:?}", result);
    // Output: ['a', 'x', 'b', 'y', 'c', 'z']

    // Example 3: Single list, custom order
    let lists = vec![
        vec![5, 10, 15, 20],
    ];
    let sequence = vec![0, 0, 0, 0];
    let result = combine_by_sequence(lists, sequence);
    println!("Example 3: {:?}", result);
    // Output: [5, 10, 15, 20]

    // Example 4: Three lists with repeated indices
    let lists = vec![
        vec!["red", "blue"],
        vec!["green"],
        vec!["yellow", "purple"],
    ];
    let sequence = vec![0, 0, 1, 2, 2, 0, 1];
    let result = combine_by_sequence(lists, sequence);
    println!("Example 4: {:?}", result);
    // Output: ["red", "blue", "green", "yellow", "purple", "red", "green"] 
    // (note: last "green" is skipped as that iterator is exhausted)
}
```

## How It Works

1. **Converts input vectors into iterators** - Each list becomes a consumable iterator
2. **Follows the sequence** - For each index in the sequence, it calls `next()` on the corresponding iterator
3. **Handles edge cases** - Invalid indices or exhausted iterators gracefully return `None` which is filtered out
4. **Generic over types** - Works with any cloneable type (i, strings, custom structs, etc.)

## Cargo.toml Dependency
```toml
[dependencies]
itertools = "0.12"  # 2024+
```

The function is efficient, type-safe, and handles all edge cases like out-of-bounds indices or attempting to draw from exhausted iterators.

