use nalgebra::{SVector, Vector2};
use newton_raphson::{Jacobian, NewtonRaphson, RootFindingConfig};

/// Compute roots of two coupled nonlinear equations using Newton-Raphson method
///
/// # Arguments
/// * `f` - Function that takes a 2D vector and returns a 2D vector of equation values
/// * `initial_guess` - Starting point [x0, y0] for the root finding
/// * `tolerance` - Convergence tolerance (e.g., 1e-10)
/// * `max_iterations` - Maximum number of iterations before giving up
///
/// # Returns
/// * `Ok(([x, y], iterations))` if converged
/// * `Err(String)` if failed to converge
pub fn solve_coupled_equations<F>(
    f: F,
    initial_guess: [f64; 2],
    tolerance: f64,
    max_iterations: usize,
) -> Result<([f64; 2], usize), String>
where
    F: Fn([f64; 2]) -> [f64; 2],
{
    // Convert to nalgebra vectors for the solver
    let f_nalgebra = |x: &SVector<f64, 2>| -> SVector<f64, 2> {
        let result = f([x[0], x[1]]);
        Vector2::new(result[0], result[1])
    };

    // Compute Jacobian numerically using central differences
    let jacobian = |x: &SVector<f64, 2>| -> nalgebra::SMatrix<f64, 2, 2> {
        let h = 1e-8;
        let fx = f_nalgebra(x);

        let mut jac = nalgebra::SMatrix::<f64, 2, 2>::zeros();

        for i in 0..2 {
            let mut x_plus = *x;
            x_plus[i] += h;
            let fx_plus = f_nalgebra(&x_plus);

            let mut x_minus = *x;
            x_minus[i] -= h;
            let fx_minus = f_nalgebra(&x_minus);

            for j in 0..2 {
                jac[(j, i)] = (fx_plus[j] - fx_minus[j]) / (2.0 * h);
            }
        }

        jac
    };

    // Configure the solver
    let config = RootFindingConfig {
        tolerance,
        max_iterations,
        ..Default::default()
    };

    // Create Newton-Raphson solver
    let solver = NewtonRaphson::new(f_nalgebra, jacobian, config);

    // Initial guess as nalgebra vector
    let x0 = Vector2::new(initial_guess[0], initial_guess[1]);

    // Solve
    match solver.solve(&x0) {
        Ok(solution) => {
            let iterations = solution.iterations;
            let root = [solution.root[0], solution.root[1]];
            Ok((root, iterations))
        }
        Err(e) => Err(format!("Newton-Raphson failed: {}", e)),
    }
}

