use polars::prelude::*;
use std::cmp::Ordering;

/// Segment the entries in the "str0" column of `df0` into intervals defined by `lst0`.
///
/// - `df0`: input DataFrame (must have a UTF8 column named "str0").
/// - `lst0`: slice of f64 boundaries defining the bin edges (need at least 2 values).
///
/// Returns a new DataFrame with an added column "str0_interval" (Utf8) containing interval labels.
/// Non-parsable strings become null in the output column.
pub fn segment_str0_intervals(df0: &DataFrame, lst0: &[f64]) -> PolarsResult<DataFrame> {
    // Validate boundaries
    if lst0.len() < 2 {
        return Err(PolarsError::ComputeError(
            "lst0 must contain at least two boundary values".into(),
        ));
    }

    // Acquire the "str0" column as Utf8
    let s = df0.column("str0")?.utf8()?;

    // Copy and sort boundaries (we sort to guarantee monotonicity)
    let mut boundaries = lst0.to_vec();
    boundaries.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
    let n = boundaries.len();

    // Build labels vector: Vec<Option<String>>
    let mut labels: Vec<Option<String>> = Vec::with_capacity(s.len());

    for opt_str in s.into_iter() {
        match opt_str {
            None => {
                // original was null
                labels.push(None);
            }
            Some(text) => match text.parse::<f64>() {
                Ok(v) if v.is_finite() => {
                    // Find the rightmost boundary index i such that v >= boundaries[i].
                    // Use binary_search_by on boundaries: if Ok(i) -> exact match index i.
                    // If Err(i): insertion point, so the containing lower boundary is i-1 (if i > 0).
                    let pos = match boundaries.binary_search_by(|b| b.partial_cmp(&v).unwrap_or(Ordering::Equal)) {
                        Ok(i) => i,
                        Err(0) => usize::MAX, // v < first boundary
                        Err(i) => i - 1,
                    };

                    if pos == usize::MAX {
                        // v < first boundary
                        labels.push(Some(format!("< {}", boundaries[0])));
                    } else if pos < n - 1 {
                        // between boundaries[pos] and boundaries[pos+1): [a, b)
                        labels.push(Some(format!("[{}, {})", boundaries[pos], boundaries[pos + 1])));
                    } else {
                        // pos == n-1 -> v >= last boundary
                        labels.push(Some(format!(">= {}", boundaries[n - 1])));
                    }
                }
                _ => {
                    // parse error or infinite value -> null
                    labels.push(None);
                }
            },
        }
    }

    // Convert Vec<Option<String>> into an Utf8Chunked then Series
    let utf = Utf8Chunked::from_opt_iter("str0_interval", labels.into_iter());
    let interval_series = utf.into_series();

    // Add the new column to df0 (returns a new DataFrame)
    let out_df = df0.with_column(interval_series)?;

    Ok(out_df)
}
```

