use polars::prelude::*;
use chrono::NaiveDate;
use std::error::Error;

/// Convert the "Date" column of df0 from "DD-MM-YYYY" strings into native datetimes.
/// - df0: input DataFrame (consumed)
/// - col: name of the date column (e.g. "Date")
/// Returns a new DataFrame with the column replaced by a Datetime (milliseconds) column.
/// Invalid or unparsable strings and nulls are kept as nulls.
pub fn convert_date_column(mut df0: DataFrame, col: &str) -> PolarsResult<DataFrame> {
    // Extract the UTF8 column
    let utf8_col = df0.column(col)?.utf8()?;

    // Parse each entry into milliseconds since epoch (i64), preserving None for null/invalid
    let parsed: Vec<Option<i64>> = utf8_col
        .into_no_null_iter()
        .map(|opt_s| {
            // opt_s: Option<&str> in an iterator that yields None for nulls
            match opt_s {
                Some(s) => match NaiveDate::parse_from_str(s, "%d-%m-%Y") {
                    Ok(date) => {
                        // interpret as midnight of that date (00:00:00) and convert to millis
                        let dt_millis = date.and_hms_opt(0, 0, 0)
                            .map(|ndt| ndt.timestamp_millis());
                        dt_millis
                    }
                    Err(_) => None, // unparsable -> null
                },
                None => None, // original null stays null
            }
        })
        .collect();

    // Build a Series from parsed millis and cast to Datetime type
    let s = Series::new(col, parsed);
    let s_dt = s.cast(&DataType::Datetime(TimeUnit::Milliseconds, None))?;

    // Replace column in DataFrame (with_column will replace if name already exists)
    df0 = df0.with_column(s_dt)?;

    Ok(df0)
}

