use regex::Regex;
use std::collections::HashMap;

/// Token representing an alphanumeric run extracted from a key.
#[derive(Debug, Clone, Eq, PartialEq)]
enum Token {
    Alpha(String), // lowercased
    Num(String),   // numeric digits with leading zeros trimmed (but "0" kept)
}

/// Sort keys of `data_mapping` according to the sequence of letter and digit runs
/// in each key. Non-letter/non-digit characters are ignored (they are simply not
/// part of the extracted runs).
///
/// Returns a Vec<String> of sorted keys.
pub fn sorted_keys_by_alnum<V>(data_mapping: &HashMap<String, V>) -> Vec<String> {
    // Regex finds runs of letters or digits
    let re = Regex::new(r"[A-Za-z]+|\d+").expect("regex should compile");

    // Parse key into tokens
    let parse = |key: &str| -> Vec<Token> {
        re.find_iter(key)
            .map(|m| {
                let s = m.as_str();
                if s.chars().next().unwrap().is_ascii_digit() {
                    // Trim leading zeros for magnitude comparison, but keep "0" if all zeros
                    let trimmed = s.trim_start_matches('0');
                    let digits = if trimmed.is_empty() { "0".to_owned() } else { trimmed.to_owned() };
                    Token::Num(digits)
                } else {
                    Token::Alpha(s.to_ascii_lowercase())
                }
            })
            .collect()
    };

    // Precompute tokens for each key to avoid re-parsing in comparator
    let mut keys_and_tokens: Vec<(String, Vec<Token>)> = data_mapping
        .keys()
        .cloned()
        .map(|k| {
            let t = parse(&k);
            (k, t)
        })
        .collect();

    // Comparator for tokens
    let cmp_tokens = |a: &Vec<Token>, b: &Vec<Token>| -> std::cmp::Ordering {
        use std::cmp::Ordering;
        let mut i = 0usize;
        while i < a.len() && i < b.len() {
            match (&a[i], &b[i]) {
                (Token::Alpha(sa), Token::Alpha(sb)) => {
                    let ord = sa.cmp(sb);
                    if ord != Ordering::Equal {
                        return ord;
                    }
                }
                (Token::Num(na), Token::Num(nb)) => {
                    // Compare by length (more digits -> larger numeric value), then lexicographically
                    if na.len() != nb.len() {
                        return na.len().cmp(&nb.len());
                    }
                    let ord = na.cmp(nb);
                    if ord != Ordering::Equal {
                        return ord;
                    }
                }
                // If types differ, decide that a numeric run comes before an alpha run
                // (choose whichever ordering you prefer; change as needed)
                (Token::Num(_), Token::Alpha(_)) => return Ordering::Less,
                (Token::Alpha(_), Token::Num(_)) => return Ordering::Greater,
            }
            i += 1;
        }
        // All shared tokens equal; shorter token list sorts first
        a.len().cmp(&b.len())
    };

    // Sort using tokens and use original key as final tie-breaker (stable)
    keys_and_tokens.sort_by(|(ka, ta), (kb, tb)| {
        let ord = cmp_tokens(ta, tb);
        if ord != std::cmp::Ordering::Equal {
            ord
        } else {
            ka.cmp(kb)
        }
    });

    // Return sorted keys
    keys_and_tokens.into_iter().map(|(k, _)| k).collect()
}

