    #[derive(tabled::Tabled)]
    struct Row {
        #[tabled(rename = "List1")]
        left: String,
        #[tabled(rename = "List2")]
        right: String,
    }

    let max_len = std::cmp::max(lst0.len(), lst1.len());
    let mut rows: Vec<Row> = Vec::with_capacity(max_len);

    for i in 0..max_len {
