            lst0[i].to_string()
        } else {
            String::new()
        };
        let right = if i < lst1.len() {
            lst1[i].to_string()
        } else {
            String::new()
        };
        rows.push(Row { left, right });
    }

    Table::new(rows).to_string()
}
