use itertools::Itertools;
use std::cmp::Ordering;

/// Reorder elements of lst0 based on the order defined by corresponding values in lst1.
/// 
/// Elements in lst0 are sorted according to the values in lst1 at the same index.
/// If lst1 contains duplicate values, the original relative order from lst0 is preserved (stable sort).
/// 
/// # Arguments
/// * `lst0` - A mutable slice of elements to reorder
/// * `lst1` - A slice of ordering values corresponding to elements in lst0
/// 
/// # Panics
/// Panics if lst0 and lst1 have different lengths
/// 
/// # Example
/// ```
/// let mut items = vec!["apple", "banana", "cherry"];
/// let order = vec![3, 1, 2];
/// reorder_by(&mut items, &order);
/// assert_eq!(items, vec!["banana", "cherry", "apple"]);
/// ```
pub fn reorder_by<T, U>(lst0: &mut [T], lst1: &[U])
where
    U: Ord,
{
    assert_eq!(
        lst0.len(),
        lst1.len(),
        "lst0 and lst1 must have the same length"
    );

    // Create indices and sort them based on lst1 values
    let mut indices: Vec<usize> = (0..lst0.len()).collect();
    indices.sort_by(|&i, &j| lst1[i].cmp(&lst1[j]));

    // Apply the permutation to lst0
    let mut temp = Vec::with_capacity(lst0.len());
    for &idx in &indices {
        // SAFETY: We're swapping elements within the same slice
        // and idx is guaranteed to be within bounds
        unsafe {
            let ptr = lst0.as_mut_ptr();
            temp.push(ptr.add(idx).read());
        }
    }

    // Copy back the reordered elements
    for (i, item) in temp.into_iter().enumerate() {
        lst0[i] = item;
    }
}

/// Alternative implementation using zip and sort for better readability
/// when you want to keep the original lst0 and create a new one
pub fn reorder_by_immutable<T: Clone, U: Ord>(lst0: &[T], lst1: &[U]) -> Vec<T> {
    assert_eq!(
        lst0.len(),
        lst1.len(),
        "lst0 and lst1 must have the same length"
    );

    let mut pairs: Vec<(usize, &T, &U)> = lst0
        .iter()
        .zip(lst1.iter())
        .enumerate()
        .map(|(i, (item, order))| (i, item, order))
        .collect();

    // Stable sort by the ordering values
    pairs.sort_by(|a, b| a.2.cmp(b.2));

    pairs.into_iter().map(|(_, item, _)| item.clone()).collect()
}

