/// println!("{}", result);
/// ```
fn fill_missing_with_column_mean(df: DataFrame) -> Result<DataFrame, PolarsError> {
    df.lazy()
        .map_elements(
            |s| {
                // Calculate mean for each series (column)
                let mean = s.mean();

                // Fill null values with the mean
                s.fill_null(FillNullStrategy::Mean)
                    .unwrap_or_else(|_| {
                        // Fallback: manually fill with computed mean
                        if let Some(m) = mean {
                            s.fill_null_with_value(m)
                        } else {
                            s
                        }
                    })
            },
            GetOutput::from_type(DataType::Float64),
        )
        .collect()
}

