///     "B" => &["x", "y", "x", "z"],
///     "C" => &[true, false, true, false]
/// );
///
/// let result = remove_duplicate_rows(&df, &["A", "B"]);
/// ```
pub fn remove_duplicate_rows(df: &DataFrame, columns: &[&str]) -> Result<DataFrame> {
    // Create a new DataFrame with only the specified columns
    let subset_df = df.clone().lazy().select(columns.to_vec())?.collect()?;

    // Collect the unique rows based on the specified columns
    let unique_rows = subset_df
        .rows()
        .into_iter()
        .map(|row| {
            let mut row_values = Vec::new();
            for col in columns {
                let value = row.get(*col).unwrap();
                row_values.push(value);
            }
            row_values
        })
        .collect::<HashSet<_>>();

    // Filter the original DataFrame to keep only rows that are unique in the specified columns
    let filtered_df = df.lazy()
        .with_column(
            lit(1),
            expr("true"),
            None,
        )
        .filter(
