- headers: Vec<String> — the column names in order
- rows: Vec<Vec<String>> — each row is a Vec of strings (same column order as headers)
- key_columns: &[&str] — the columns to consider when deciding duplicates

The function keeps the first row seen for each unique combination of the specified columns and drops later duplicates. It uses only the Rust standard library so it is easy to compile and embed into your project.

Code:

```rust
use std::collections::{HashMap, HashSet};

/// Remove rows that are duplicates with respect to the values in `key_columns`.
///
/// - `headers`: column names in order.
/// - `rows`: rows, each row must be ordered according to `headers`.
/// - `key_columns`: column names to consider as the key for duplicate detection.
/// 
/// Returns `Err(String)` if any requested key column is not present in `headers`.
/// On success returns a vector of rows where only the first row for each distinct
/// combination of key column values is kept.
pub fn remove_duplicate_rows_by_columns(
    headers: &[String],
    rows: Vec<Vec<String>>,
    key_columns: &[&str],
) -> Result<Vec<Vec<String>>, String> {
    // Build header name -> index map
    let mut index_of: HashMap<&str, usize> = HashMap::with_capacity(headers.len());
    for (i, h) in headers.iter().enumerate() {
        index_of.insert(h.as_str(), i);
    }

    // Validate requested key columns exist, collect their indices
    let mut key_indices: Vec<usize> = Vec::with_capacity(key_columns.len());
    for &col in key_columns {
        match index_of.get(col) {
            Some(&idx) => key_indices.push(idx),
            None => {
                return Err(format!("Requested key column '{}' not found in headers", col));
            }
        }
    }

    // Quick return: if no key columns specified, nothing to deduplicate
    if key_indices.is_empty() {
        return Ok(rows);
    }

    // Use a HashSet to track seen keys. We serialize selected values with a delimiter
    // that is unlikely to appear in normal cell content.
    // If you need to handle arbitrary binary data, consider using a Vec<Vec<String>>
    // with a custom Hash impl. For typical textual tables this is fine.
    let delimiter = '\x1f'; // unit separator, unlikely in normal text
    let mut seen: HashSet<String> = HashSet::new();
    let mut out: Vec<Vec<String>> = Vec::with_capacity(rows.len());

    for row in rows.into_iter() {
        // For safety: if a row is shorter than headers, treat missing as empty string.
        let mut key_parts = String::new();
        for (i, &col_idx) in key_indices.iter().enumerate() {
            if col_idx < row.len() {
                key_parts.push_str(&row[col_idx]);
            }
            // even if missing, leave it empty between delimiters
            if i + 1 < key_indices.len() {
                key_parts.push(delimiter);
            }
        }

        if seen.insert(key_parts) {
            // first time seeing this combination -> keep the row
            out.push(row);
        } else {
            // duplicate -> drop
        }
    }

    Ok(out)
}

#[cfg(test)]
