        let rows = vec![vec!["1".into(), "2".into()], vec!["1".into(), "2".into()]];
        let res = remove_duplicate_rows_by_columns(&headers, rows.clone(), &[]).unwrap();
        // No deduplication when no keys specified
        assert_eq!(res, rows);
