    }

    // Select only the specified columns for duplicate checking
    let subset = df.select(columns)?;

    // Find unique rows based on the subset
    let unique = subset.unique(Some(columns), UniqueKeepStrategy::First)?;

    // Get the indices of unique rows
    let unique_indices = unique
        .lazy()
        .with_row_index("__index__", None)
        .collect()?
        .column("__index__")?
        .u32()?
        .into_iter()
        .map(|v| v.unwrap() as usize)
        .collect::<Vec<_>>();

    // Filter original DataFrame to keep only unique rows
    let result = df
        .lazy()
        .with_row_index("__index__", None)
        .filter(col("__index__").is_in(lit(Series::new("", &unique_indices))))
        .select(df.get_column_names().iter().map(|c| col(c)))
        .collect()?;

    Ok(result)
}

// Alternative implementation using group_by for better performance on large datasets
pub fn remove_duplicate_rows_fast(df: &DataFrame, columns: &[&str]) -> Result<DataFrame, PolarsError> {
    // Validate columns exist
    for col in columns {
        if !df.get_column_names().contains(col) {
            return Err(PolarsError::ComputeError(
                format!("Column '{}' not found in DataFrame", col).into(),
            ));
        }
    }

    // Use group_by to find first occurrence of each unique combination
    let result = df
        .lazy()
        .with_row_index("__index__", None)
        .group_by(columns)
        .agg([col("__index__").first()])
        .sort(
            [col("__index__")],
            SortMultipleOptions::default().with_order_descending(false),
        )
        .select([col("__index__")])
        .collect()?;

    let indices = result
        .column("__index__")?
        .u32()?
        .into_iter()
        .map(|v| v.unwrap() as usize)
        .collect::<Vec<_>>();

    let filtered = df
        .lazy()
        .with_row_index("__index__", None)
        .filter(col("__index__").is_in(lit(Series::new("", &indices))))
        .select(df.get_column_names().iter().map(|c| col(c)))
        .collect()?;

    Ok(filtered)
}

