use polars::prelude::*;

/// Removes rows from a DataFrame that contain duplicate values 
/// across the specified columns.
///
/// # Arguments
/// * `df` - The input DataFrame
/// * `subset` - A vector of column names to check for duplicates
/// * `keep` - Which duplicate to keep: "first", "last", or "none"
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with duplicates removed
fn remove_duplicates(
    df: &DataFrame,
