```rust
use indexmap::IndexMap;

/// Removes mappings whose "link" entry matches any value in the exclusion list
/// 
/// # Arguments
/// * `mappings` - A vector of IndexMaps, each representing a mapping
/// * `exclude_links` - A list of link values to exclude
/// 
/// # Returns
/// A new vector of mappings with excluded ones removed
fn filter_mappings_by_link(
    mappings: Vec<IndexMap<String, String>>,
    exclude_links: &[String],
) -> Vec<IndexMap<String, String>> {
    mappings
        .into_iter()
        .filter(|mapping| {
            mapping
                .get("link")
                .map_or(true, |link| !exclude_links.contains(link))
        })
        .collect()
}

// Example usage and tests
fn main() {
    let mut mapping1 = IndexMap::new();
    mapping1.insert("name".to_string(), "Item A".to_string());
    mapping1.insert("link".to_string(), "https://example.com/a".to_string());

    let mut mapping2 = IndexMap::new();
    mapping2.insert("name".to_string(), "Item B".to_string());
    mapping2.insert("link".to_string(), "https://example.com/b".to_string());

    let mut mapping3 = IndexMap::new();
    mapping3.insert("name".to_string(), "Item C".to_string());
    mapping3.insert("link".to_string(), "https://example.com/c".to_string());

    let mappings = vec![mapping1, mapping2, mapping3];
    let exclude_links = vec![
        "https://example.com/b".to_string(),
        "https://example.com/d".to_string(),
    ];

    let filtered = filter_mappings_by_link(mappings, &exclude_links);

    println!("Filtered mappings count: {}", filtered.len());
    for (i, mapping) in filtered.iter().enumerate() {
        println!("Mapping {}: {:?}", i + 1, mapping);
    }
}
```

**Add to your `Cargo.toml`:**
```toml
[dependencies]
indexmap = "2.0"
```

## Key Features:

- **`IndexMap`**: Maintains insertion order while providing O(1) lookups (useful for structured mapping data)
- **Filtering Logic**: Uses `.filter()` with `.get("link")` to safely check for the "link" entry
- **`map_or(true, ...)`**: Returns `true` if no "link" entry exists, keeping those mappings; filters out only mappings with matching links
- **`.contains()`**: Checks if the link value is in the exclusion list

This approach is efficient (O(n*m) where n is mappings and m is exclusion list size) and handles edge cases like missing "link" entries gracefully.

