```rust
use polars::prelude::*;
use chrono::{DateTime, NaiveDate, NaiveDateTime, TimeZone, Utc, Duration};
use polars::datatypes::TimeUnit;

/// Reformat date-time values in column `col_name` of DataFrame `df0`
/// to the pattern `format_str` (strftime-style), returning a new DataFrame.
///
/// - `df0`: ownership of the DataFrame is taken and returned with the modified column.
/// - `col_name`: name of the column to reformat.
/// - `format_str`: chrono/strftime style format string, e.g. "%Y-%m-%d %H:%M:%S %Z".
///
/// Returns an Err(PolarsError) if the column does not exist or if replacing the column fails.
pub fn reformat_datetime_column(
    mut df0: DataFrame,
    col_name: &str,
    format_str: &str,
) -> PolarsResult<DataFrame> {
    // Get series; return error if missing
    let series = df0
        .column(col_name)
        .map_err(|_| polars::prelude::PolarsError::NotFound(
            format!("column '{}' not found", col_name).into()
        ))?
        .clone();

    // Helper: attempt to parse a &str into DateTime<Utc> using several common patterns
    fn parse_str_to_dt(s: &str) -> Option<DateTime<Utc>> {
        // Try RFC3339 / ISO8601 first
        if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
            return Some(dt.with_timezone(&Utc));
        }
        // Try a few common layouts (you can extend these as needed)
        let patterns = &[
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d %H:%M:%S%.f", // fractional seconds
            "%Y-%m-%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
        ];
        for p in patterns {
            if let Ok(ndt) = NaiveDateTime::parse_from_str(s, p) {
                return Some(DateTime::<Utc>::from_utc(ndt, Utc));
            }
            if let Ok(nd) = NaiveDate::parse_from_str(s, p) {
                let ndt = nd.and_hms_opt(0, 0, 0)?;
                return Some(DateTime::<Utc>::from_utc(ndt, Utc));
            }
        }
        None
    }

    // Helper: convert integer epoch-like i64 to DateTime<Utc>.
    fn dt_from_epoch_i64(v: i64) -> Option<DateTime<Utc>> {
        let abs = v.abs() as i128;
        // approximate thresholds (seconds, milliseconds, microseconds, nanoseconds)
        // sec ~ 1e9, ms ~ 1e12, µs ~ 1e15, ns ~ 1e18
        let (secs, nanos): (i64, i32) = if abs >= 1_000_000_000_000_000_000i128 {
            // nanoseconds
            let secs = (v / 1_000_000_000) as i64;
            let nanos = (v % 1_000_000_000) as i32;
            (secs, nanos.abs())
        } else if abs >= 1_000_000_000_000_000i128 {
            // microseconds
            let secs = (v / 1_000_000) as i64;
            let nanos = ((v % 1_000_000) * 1000) as i32;
            (secs, nanos.abs())
        } else if abs >= 1_000_000_000_000i128 {
            // milliseconds
            let secs = (v / 1_000) as i64;
            let nanos = ((v % 1_000) * 1_000_000) as i32;
            (secs, nanos.abs())
        } else {
            // seconds
            let secs = v as i64;
            (secs, 0)
        };
        // Build DateTime<Utc>
        Utc.timestamp_opt(secs, nanos as u32).single()
    }

    // Helper: float -> DateTime (seconds with fractional)
    fn dt_from_epoch_f64(f: f64) -> Option<DateTime<Utc>> {
        if !f.is_finite() {
            return None;
        }
        let secs = f.trunc() as i64;
        let frac = (f.fract().abs() * 1e9).round() as u32;
        Utc.timestamp_opt(secs, frac).single()
    }

    // Iterate over series values, produce Vec<Option<String>> of formatted datetimes
    let mut out_strings: Vec<Option<String>> = Vec::with_capacity(series.len());

    for idx in 0..series.len() {
        let formatted_opt: Option<String> = match series.get(idx) {
            AnyValue::Utf8(s) => {
                s.and_then(|ss| parse_str_to_dt(ss))
                    .map(|dt| dt.format(format_str).to_string())
            }
            AnyValue::Int64(v) => dt_from_epoch_i64(v).map(|dt| dt.format(format_str).to_string()),
            AnyValue::UInt64(v) => {
                // safe to cast to i64 when within range
                let v_i64 = v as i64;
                dt_from_epoch_i64(v_i64).map(|dt| dt.format(format_str).to_string())
            }
            AnyValue::Float64(f) => {
                if let Some(v) = f {
                    dt_from_epoch_f64(v).map(|dt| dt.format(format_str).to_string())
                } else {
                    None
                }
            }
            AnyValue::Date(days_opt) => {
                // AnyValue::Date uses i32 days since epoch (1970-01-01)
                if let Some(days) = days_opt {
                    let base = NaiveDate::from_ymd_opt(1970, 1, 1).unwrap();
                    if let Some(nd) = base.checked_add_signed(Duration::days(days as i64)) {
                        let ndt = nd.and_hms_opt(0, 0, 0)?;
                        Some(DateTime::<Utc>::from_utc(ndt, Utc).format(format_str).to_string())
                    } else {
                        None
                    }
                } else {
                    None
                }
            }
            AnyValue::Datetime(v_opt, tu_opt, _tz) => {
                // v_opt: Option<i64>, tu_opt: Option<TimeUnit>
                match (v_opt, tu_opt) {
                    (Some(v), Some(tu)) => {
                        // convert v according to time unit to DateTime<Utc>
                        let dt_opt = match tu {
                            TimeUnit::Nanoseconds => {
                                let secs = v / 1_000_000_000;
                                let nanos = (v % 1_000_000_000).abs() as u32;
                                Utc.timestamp_opt(secs, nanos).single()
                            }
                            TimeUnit::Microseconds => {
                                let secs = v / 1_000_000;
                                let nanos = ((v % 1_000_000) * 1000).abs() as u32;
                                Utc.timestamp_opt(secs, nanos).single()
                            }
                            TimeUnit::Milliseconds => {
                                let secs = v / 1_000;
                                let nanos = ((v % 1_000) * 1_000_000).abs() as u32;
                                Utc.timestamp_opt(secs, nanos).single()
                            }
                        };
                        dt_opt.map(|dt| dt.format(format_str).to_string())
                    }
                    _ => None,
                }
            }
            // Null / other types -> null in output
            _ => None,
        };
        out_strings.push(formatted_opt);
    }

    // Convert Vec<Option<String>> to Vec<Option<&str>> so Series::new accepts it
    let out_owned: Vec<Option<String>> = out_strings;
    let out_refs: Vec<Option<&str>> = out_owned.iter().map(|o| o.as_deref()).collect();

    // Build new Utf8 Series and replace the column
    let new_series = Series::new(col_name, out_refs);
    // with_column consumes self and returns a Result<DataFrame>
    df0.with_column(new_series)
}

