```rust
use chrono::{DateTime, FixedOffset, NaiveDate, NaiveDateTime, NaiveTime, Utc};
use std::error::Error;

/// Simple row type with two string fields col0 (date) and col1 (time).
/// - col0 expected like "YYYY-MM-DD"
/// - col1 may be "HH:MM", "HH:MM:SS", "HH:MM:SS.sss", or include offset like "HH:MM:SS+01:00" or "HH:MM:SSZ"
#[derive(Debug, Clone)]
pub struct Row {
    pub col0: String,
    pub col1: String,
}

/// Combine the col0 (date) and col1 (time) fields for every row into a DateTime<Utc>.
/// Returns a Vec<DateTime<Utc>> or an error if any row fails to parse.
///
/// Parsing rules:
/// - If col1 contains 'Z' or a plus/minus offset, the function attempts to parse the combined
///   "dateTtime" as an RFC3339-like datetime (preserving offset then converting to UTC).
/// - Otherwise it tries to parse time as HH:MM[:SS][.fraction] and combines with the date,
///   treating the result as UTC.
///
/// Example:
/// let rows = vec![ Row { col0: "2024-04-10".into(), col1: "13:45:30".into() } ];
/// let datetimes = combine_col0_col1_to_datetimes(&rows)?;
pub fn combine_col0_col1_to_datetimes(rows: &[Row]) -> Result<Vec<DateTime<Utc>>, Box<dyn Error>> {
    let mut out = Vec::with_capacity(rows.len());

    for r in rows {
        let date_str = r.col0.trim();
        let time_str = r.col1.trim();

        // First, parse the date portion (strict YYYY-MM-DD)
        let date = NaiveDate::parse_from_str(date_str, "%Y-%m-%d")
            .map_err(|e| format!("failed to parse date '{}' : {}", date_str, e))?;

        // Try to detect an explicit offset in the time string.
        // If time contains 'Z' or '+' or '-' followed by digits, attempt to parse as a full offset datetime.
        let combined = format!("{}T{}", date_str, time_str);

        let datetime_utc = if time_str.contains('Z')
            || time_str.contains('+')
            || // look for a trailing offset like "-05:00" (simple heuristic)
               (time_str.rfind('-').map_or(false, |i| i > 0 && time_str[i..].chars().any(|c| c.is_ascii_digit())))
        {
            // Try parsing as RFC3339-like full datetime with offset
            // chrono provides parse_from_rfc3339 which is strict, try that first.
            if let Ok(dt_fixed) = DateTime::parse_from_rfc3339(&combined) {
                dt_fixed.with_timezone(&Utc)
            } else {
                // Fallback: try a format with optional fractional seconds and offset like "%Y-%m-%dT%H:%M:%S%.f%:z"
                // Note: parse_from_str requires exact format; try this and propagate helpful errors if it fails.
                match DateTime::parse_from_str(&combined, "%Y-%m-%dT%H:%M:%S%.f%:z") {
                    Ok(dt_fixed) => dt_fixed.with_timezone(&Utc),
                    Err(e) => {
                        // Provide context in error
                        return Err(format!(
                            "failed to parse combined datetime with offset '{}' : {}",
                            combined, e
                        )
                        .into());
                    }
                }
            }
        } else {
            // No explicit offset: parse time as NaiveTime with a few common formats, then combine as UTC.
            // Try several time formats in decreasing specificity.
            let time_formats = ["%H:%M:%S%.f", "%H:%M:%S", "%H:%M"];

            let mut parsed_time: Option<NaiveTime> = None;
            for fmt in &time_formats {
                match NaiveTime::parse_from_str(time_str, fmt) {
                    Ok(t) => {
                        parsed_time = Some(t);
                        break;
                    }
                    Err(_) => {}
                }
            }

            let time = parsed_time.ok_or_else(|| {
                format!(
                    "failed to parse time '{}' for date '{}'; expected HH:MM[:SS][.frac] or with offset",
                    time_str, date_str
                )
            })?;

            let naive_dt = NaiveDateTime::new(date, time);
            DateTime::<Utc>::from_utc(naive_dt, Utc)
        };

        out.push(datetime_utc);
    }

    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_combine_basic() {
        let rows = vec![
            Row { col0: "2024-04-10".into(), col1: "13:45".into() },
            Row { col0: "2024-04-10".into(), col1: "13:45:30".into() },
            Row { col0: "2024-04-10".into(), col1: "13:45:30.123".into() },
            Row { col0: "2024-04-10".into(), col1: "13:45:30+02:00".into() }, // with offset
            Row { col0: "2024-04-10".into(), col1: "13:45:30Z".into() }, // UTC Z
        ];

        let out = combine_col0_col1_to_datetimes(&rows).expect("parse should succeed");

        assert_eq!(out[0].to_rfc3339(), "2024-04-10T13:45:00+00:00");
        assert_eq!(out[1].to_rfc3339(), "2024-04-10T13:45:30+00:00");
        assert_eq!(out[2].to_rfc3339(), "2024-04-10T13:45:30.123+00:00");
        // offset +02:00 converts to UTC by subtracting offset
        assert_eq!(out[3].to_rfc3339(), "2024-04-10T11:45:30+00:00");
        assert_eq!(out[4].to_rfc3339(), "2024-04-10T13:45:30+00:00");
    }

    #[test]
    fn test_bad_date() {
        let rows = vec![Row { col0: "2024-13-01".into(), col1: "10:00".into() }];
        let err = combine_col0_col1_to_datetimes(&rows).unwrap_err();
        assert!(err.to_string().contains("failed to parse date"));
    }

    #[test]
