///
/// # Example
/// ```ignore
/// use arrow::array::{StringArray, TimestampNanosecondArray};
/// use arrow::datatypes::{DataType, Field, Schema};
/// use arrow::record_batch::RecordBatch;
/// use std::sync::Arc;
