///     Arc::new(dates),
///     Arc::new(times),
/// ]).unwrap();
///
/// let result = combine_date_time(&batch).unwrap();
/// ```
pub fn combine_date_time(
    batch: &RecordBatch,
) -> Result<Arc<TimestampNanosecondArray>, ArrowError> {
    // Extract col0 (date) and col1 (time) columns
    let date_array = batch
        .column_by_name("col0")
        .ok_or_else(|| ArrowError::SchemaError("Missing col0 column".to_string()))?;

    let time_array = batch
        .column_by_name("col1")
        .ok_or_else(|| ArrowError::SchemaError("Missing col1 column".to_string()))?;

    // Downcast to StringArray
    let dates = date_array
        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or_else(|| ArrowError::CastError("col0 is not a string array".to_string()))?;

    let times = time_array
        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or_else(|| ArrowError::CastError("col1 is not a string array".to_string()))?;

    // Validate arrays have same length
    if dates.len() != times.len() {
        return Err(ArrowError::SchemaError(
            "col0 and col1 have different lengths".to_string(),
        ));
    }

    // Build timestamp array
    let mut timestamps: Vec<i64> = Vec::with_capacity(dates.len());

    for i in 0..dates.len() {
        let date_str = dates.value(i);
        let time_str = times.value(i);

        // Parse date and time strings
        let datetime_str = format!("{} {}", date_str, time_str);
        let naive_dt = NaiveDateTime::parse_from_str(&datetime_str, "%Y-%m-%d %H:%M:%S")
            .map_err(|e| {
                ArrowError::ParseError(format!(
                    "Failed to parse datetime '{}': {}",
                    datetime_str, e
                ))
            })?;

        // Convert to nanoseconds since epoch
        timestamps.push(naive_dt.and_utc().timestamp_nanos_opt().unwrap_or(0));
    }

    // Create and return the timestamp array
    Ok(Arc::new(TimestampNanosecondArray::from(timestamps)))
}

