/// - Drops named candidate index columns ("index", "Index", "__index_level_0__", "row_nr", "row_number") if present.
/// - Otherwise, if an integer column exactly equals 0..n-1 it is treated as an index and dropped.
/// - Otherwise does nothing (Polars DataFrame already has an implicit RangeIndex).
pub fn reset_index(df0: &mut DataFrame) -> PolarsResult<()> {
    // Common exported index column names from other libraries (pandas, etc.)
    const CANDIDATES: &[&str] = &["index", "Index", "__index_level_0__", "row_nr", "row_number"];

    // 1) Drop any obvious index-name column.
    for &name in CANDIDATES {
        if df0.get_column_names().contains(&name) {
            df0.drop_in_place(name)?;
            return Ok(());
        }
    }

    // 2) If not found, try to detect an integer column that equals 0..n-1 exactly.
    let nrows = df0.height();
    if nrows == 0 {
