/// Splits text at commas, except those inside double-quote pairs.
/// Returns a Vec of string slices (no allocations for the segments themselves).
pub fn split_csv<'a>(text: &'a str) -> Vec<&'a str> {
    let mut segments = Vec::new();
    let mut start = 0;
    let mut in_quotes = false;
    let mut chars = text.char_indices().peekable();

    while let Some((i, ch)) = chars.next() {
        match ch {
            '"' => {
                // Toggle quote state
                in_quotes = !in_quotes;
