            ',' if !in_quotes => {
                // Found a separator outside quotes
                segments.push(&text[start..i]);
                start = i + 1; // Skip the comma
            }
            _ => {}
        }
    }

    // Push the final segment (or empty string if text ends with comma)
    segments.push(&text[start..]);

    segments
}

