# Rust Function for Comma-Separated Text Parsing (Respecting Quoted Strings)

Here's a self-contained function using the **`nom`** parser combinator library (v7.1.3+, 2024):

```rust
use nom::{
    branch::alt,
    bytes::complete::{tag, take_until},
    character::complete::char,
    multi::many0,
    sequence::delimited,
    IResult,
};

/// Separates input text into segments at commas, ignoring commas within double quotes.
/// Returns a Vec of string segments (trimmed of whitespace).
fn split_respecting_quotes(input: &str) -> Result<Vec<String>, String> {
    let (_, segments) = parse_segments(input).map_err(|e| e.to_string())?;
    Ok(segments)
}

/// Parser for a quoted string (content between double quotes)
fn quoted_string(input: &str) -> IResult<&str, &str> {
    delimited(char('"'), take_until("\""), char('"'))(input)
}

/// Parser for unquoted content (anything except comma or quote)
fn unquoted_content(input: &str) -> IResult<&str, &str> {
    nom::bytes::complete::is_not(",\"")(input)
}

/// Parser for a single segment (may contain quoted strings and unquoted content)
fn segment(input: &str) -> IResult<&str, String> {
    let (rest, parts) = many0(alt((
        |i| quoted_string(i).map(|(r, s)| (r, s)),
        |i| unquoted_content(i).map(|(r, s)| (r, s)),
    )))(input)?;

    let combined = parts.join("");
    Ok((rest, combined))
}

/// Parser for all segments separated by commas
fn parse_segments(input: &str) -> IResult<&str, Vec<String>> {
    let (rest, first) = segment(input)?;
    let (rest, mut others) = many0(|i| {
        let (r, _) = char(',')(i)?;
        segment(r)
    })(rest)?;

    let mut result = vec![first.trim().to_string()];
    result.extend(others.into_iter().map(|s| s.trim().to_string()));

    Ok((rest, result))
}

fn main() {
    let test_cases = vec![
        r#"apple, banana, "cherry, date", elderberry"#,
        r#""hello, world", foo, "bar, baz", qux"#,
        r#"a,"b,c",d"#,
        r#"simple, comma, separated, values"#,
    ];

    for test in test_cases {
        match split_respecting_quotes(test) {
            Ok(segments) => {
                println!("Input:  {}", test);
                println!("Output: {:?}\n", segments);
            }
            Err(e) => println!("Error parsing '{}': {}\n", test, e),
        }
    }
}
```

