use polars::prelude::*;

/// Reorders the rows of a DataFrame according to the specified list of row indices.
///
/// # Arguments
/// * `df` - The input DataFrame to be reordered.
/// * `lst0` - A list of row indices defining the new order.
///
/// # Returns
/// A new DataFrame with rows reordered according to `lst0`.
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "A" => &[1, 2, 3, 4],
///     "B" => &["x", "y", "z", "w"]
/// ).unwrap();
///
/// let lst0 = vec![2, 0, 3, 1];
/// let reordered = reorder_rows(df, lst0).unwrap();
/// println!("{:?}", reordered);
/// ```
pub fn reorder_rows(df: DataFrame, lst0: Vec<usize>) -> Result<DataFrame, PolarsError> {
    // Validate that lst0 contains all row indices
    let expected_len = df.height();
    if lst0.len() != expected_len {
        return Err(PolarsError::ComputeError(
            "Length of lst0 must match number of rows in DataFrame".into(),
        ));
    }

    // Check for duplicate indices
    if lst0.len() != lst0.iter().collect::<HashSet<_>>().len() {
        return Err(PolarsError::ComputeError(
            "lst0 contains duplicate indices".into(),
        ));
    }

    // Check that all indices are valid
    for &idx in &lst0 {
        if idx >= expected_len {
            return Err(PolarsError::ComputeError(format!(
                "Index {} is out of bounds for DataFrame with {} rows",
                idx, expected_len
            )));
        }
    }

    // Create a new DataFrame with rows reordered
    let reordered = df.lazy()
        .filter(col("__index__").is_in(&lst0))
        .sort("__index__", false)
        .collect()?;

    Ok(reordered)
}

