use polars::prelude::*;
use serde_json::Value;

/// Converts a Polars DataFrame into a list of dictionaries (JSON-serializable).
///
/// # Arguments
/// * `df` - A Polars DataFrame to convert
///
/// # Returns
/// A `Vec<HashMap<String, Value>>` where each inner map represents a row
/// with column names as keys and values as JSON-serializable types.
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use std::collections::HashMap;
/// use serde_json::Value;
///
/// fn main() -> Result<(), Box<dyn std::error::Error>> {
///     let df = df!(
///         "A" => &[1, 2, 3],
///         "B" => &["x", "y", "z"],
///         "C" => &[1.1, 2.2, 3.3]
///     )?;
///
///     let rows = dataframe_to_dicts(&df)?;
///     println!("{:#?}", rows);
///     Ok(())
/// }
/// ```
pub fn dataframe_to_dicts(df: &DataFrame) -> Result<Vec<HashMap<String, Value>>, Box<dyn std::error::Error>> {
    let mut result = Vec::with_capacity(df.height());

    for row in df.iter_rows()? {
        let mut row_dict = HashMap::new();

        for (col_name, col) in df.get_column_names().iter().zip(df.get_columns()) {
            let value = match col.dtype() {
                DataType::Int64 => Value::from(row.get(col_name)?),
                DataType::Float64 => Value::from(row.get(col_name)?),
                DataType::String => Value::String(row.get(col_name)?.to_string()),
                DataType::Boolean => Value::Bool(row.get(col_name)?),
                DataType::Utf8 => Value::String(row.get(col_name)?.to_string()),
                DataType::Date => {
                    // Convert Date to string (ISO format)
                    let date = row.get::<Date>(col_name)?;
                    Value::String(date.to_string())
                }
                DataType::Datetime(_, _) => {
                    // Convert Datetime to string (ISO format)
                    let datetime = row.get::<Datetime>(col_name)?;
                    Value::String(datetime.to_string())
                }
                DataType::List(_) => {
                    // Convert List to Vec<Value>
                    let list = row.get::<List>(col_name)?;
                    let mut vec = Vec::with_capacity(list.len());
                    for item in list.iter() {
                        vec.push(Value::from(item));
                    }
                    Value::Array(vec)
                }
                _ => {
                    // Fallback for other types (convert to string)
                    Value::String(row.get(col_name)?.to_string())
                }
            };

            row_dict.insert(col_name.to_string(), value);
        }

        result.push(row_dict);
    }

    Ok(result)
}
