/// Convert a polars::DataFrame into a Vec of row-wise HashMaps (column name -> serde_json::Value).
/// Handles common primitive types and falls back to string serialization for other/complex types.
///
/// Example usage:
/// let df = DataFrame::new(vec![
///     Series::new("id", &[1, 2, 3]),
///     Series::new("name", &["alice", "bob", "carol"]),
///     Series::new("score", &[Some(4.5), None, Some(3.2)]),
/// ])?;
///
/// let rows = df_to_vec_maps(&df);
pub fn df_to_vec_maps(df: &DataFrame) -> Vec<HashMap<String, JsonValue>> {
    let height = df.height();
    let cols = df.get_columns();
    let mut out: Vec<HashMap<String, JsonValue>> = Vec::with_capacity(height);

    for row_idx in 0..height {
        let mut map: HashMap<String, JsonValue> = HashMap::with_capacity(cols.len());
        for series in cols.iter() {
            let key = series.name().to_string();
            let any = series.get(row_idx);

            let json_val = match any {
                AnyValue::Null => JsonValue::Null,
                AnyValue::Boolean(b) => JsonValue::Bool(b),

                // UTF8 string variants
                AnyValue::Utf8(s) => JsonValue::String(s.to_string()),
                AnyValue::Utf8Owned(s) => JsonValue::String(s),

