                AnyValue::Int64(n) => JsonValue::from(n),
                AnyValue::Int32(n) => JsonValue::from(n),
                AnyValue::Int16(n) => JsonValue::from(n),
                AnyValue::Int8(n) => JsonValue::from(n),

