                }
                AnyValue::Float32(f) => {
                    JsonNumber::from_f64(f as f64).map(JsonValue::Number).unwrap_or(JsonValue::Null)
                }

                // Dates / times / durations — represent as strings (human readable)
                AnyValue::Date32(v) => JsonValue::String(format!("{}", v)),
                AnyValue::Date64(v) => JsonValue::String(format!("{}", v)),
                AnyValue::Time64(v, _) => JsonValue::String(format!("{}", v)),
                AnyValue::Duration(v, _) => JsonValue::String(format!("{}", v)),

