                AnyValue::List(s) => {
                    // try to serialize inner list elements (simple strategy)
                    let mut arr = Vec::with_capacity(s.len());
                    for i in 0..s.len() {
                        let inner = s.get(i);
                        // simple conversion for nested elements
                        let v = match inner {
                            AnyValue::Null => JsonValue::Null,
                            AnyValue::Boolean(b) => JsonValue::Bool(b),
                            AnyValue::Utf8(st) => JsonValue::String(st.to_string()),
                            AnyValue::Utf8Owned(st) => JsonValue::String(st),
                            AnyValue::Int64(n) => JsonValue::from(n),
                            AnyValue::Int32(n) => JsonValue::from(n),
                            AnyValue::UInt64(u) => JsonValue::from(u),
                            AnyValue::UInt32(u) => JsonValue::from(u),
                            AnyValue::Float64(f) => {
                                JsonNumber::from_f64(f).map(JsonValue::Number).unwrap_or(JsonValue::Null)
                            }
                            AnyValue::Float32(f) => {
                                JsonNumber::from_f64(f as f64).map(JsonValue::Number).unwrap_or(JsonValue::Null)
                            }
                            other => JsonValue::String(other.to_string()),
                        };
                        arr.push(v);
                    }
                    JsonValue::Array(arr)
                }

                AnyValue::Struct(_) => JsonValue::String(any.to_string()),

                // Fallback for any other variant
                other => JsonValue::String(other.to_string()),
            };

            map.insert(key, json_val);
        }
        out.push(map);
    }

    out
}
```

Notes:
- This returns serde_json::Value so the row maps can be serialized easily to JSON, sent over the wire, or inspected dynamically.
- The function handles the common scalar types and attempts a reasonable fallback for complex types (lists/structs -> string or nested array). If you need exact typed Rust values (e.g., i32 vs i64) instead of JSON values, you can swap JsonValue with an enum or AnyValue wrapping.
- For very large DataFrames, building a Vec<HashMap<...>> will allocate memory proportional to the DataFrame size; consider streaming or lazy serialization if memory is a concern.

