```rust
use polars::prelude::*;

/// Compute the weighted average of `col_values` using weights from `col_weights`
/// in the provided DataFrame.
///
/// Returns:
/// - Ok(Some(avg)) when at least one valid (finite) weight exists,
/// - Ok(None) when there are no valid weights (or total weight is zero),
/// - Err(...) if columns are missing or cannot be cast to Float64.
pub fn weighted_average(
    df: &DataFrame,
    col_values: &str,
    col_weights: &str,
) -> PolarsResult<Option<f64>> {
    // Get columns (returns error if column doesn't exist)
    let vals_s = df.column(col_values)?.cast(&DataType::Float64)?;
    let wts_s = df.column(col_weights)?.cast(&DataType::Float64)?;

    // Safe to unwrap since we casted to Float64
    let vals = vals_s.f64().expect("cast to Float64 produced non-f64 series");
    let wts = wts_s.f64().expect("cast to Float64 produced non-f64 series");

    let mut sum_vw: f64 = 0.0;
    let mut sum_w: f64 = 0.0;

    // Iterate through all rows; skip rows where either value/weight is null/NaN/Inf
    let len = vals.len().min(wts.len());
    for i in 0..len {
        if let (Some(v), Some(w)) = (vals.get(i), wts.get(i)) {
            if v.is_finite() && w.is_finite() {
                sum_vw += v * w;
                sum_w += w;
            }
        }
    }

    if sum_w == 0.0 {
        // No valid (finite) weights or total weight zero -> undefined average
        Ok(None)
    } else {
        Ok(Some(sum_vw / sum_w))
    }
}

