use polars::prelude::*;

/// Computes the weighted average of values in a column using corresponding weights from another column.
///
/// # Arguments
/// * `df` - A reference to a Polars DataFrame
/// * `col_values` - The name of the column containing the values to average
/// * `col_weights` - The name of the column containing the weights
///
/// # Returns
/// * `Result<f64>` - The weighted average, or an error if columns don't exist or have incompatible types
///
/// # Formula
/// weighted_average = Σ(value_i * weight_i) / Σ(weight_i)
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use weighted_average::weighted_average;
///
/// let df = df!(
///     "values" => &[10.0, 20.0, 30.0],
///     "weights" => &[1.0, 2.0, 3.0],
/// ).unwrap();
///
/// let result = weighted_average(&df, "values", "weights").unwrap();
/// assert!((result - 23.333333333333332).abs() < 1e-10);
/// ```
pub fn weighted_average(
    df: &DataFrame,
    col_values: &str,
    col_weights: &str,
) -> Result<f64, PolarsError> {
    // Validate that both columns exist
    if !df.get_column_names().contains(&col_values.to_string()) {
        return Err(PolarsError::ColumnNotFound(
            col_values.to_string().into(),
        ));
    }
    if !df.get_column_names().contains(&col_weights.to_string()) {
        return Err(PolarsError::ColumnNotFound(
            col_weights.to_string().into(),
        ));
    }

    // Calculate weighted sum: Σ(value * weight)
    let weighted_sum = df
        .lazy()
        .with_column(
            (col(col_values) * col(col_weights)).alias("weighted_value")
        )
        .select([col("weighted_value").sum()])
        .collect()?
        .column("weighted_value")?
        .f64()?
        .get(0)
        .unwrap_or(0.0);

    // Calculate sum of weights: Σ(weight)
    let weight_sum = df
        .lazy()
        .select([col(col_weights).sum()])
        .collect()?
        .column(col_weights)?
        .f64()?
        .get(0)
        .unwrap_or(0.0);

    // Handle division by zero
    if weight_sum == 0.0 {
        return Ok(0.0);
    }

    Ok(weighted_sum / weight_sum)
}

