Rust code:
```rust
use polars::prelude::*;

/// Replace every string cell in `df` that consists only of whitespace
/// with the designated missing-value indicator:
/// - If `missing` is `None`, those cells become true nulls.
/// - If `Some(s)`, those cells will be replaced with the string `s`.
///
/// Only Utf8 (string) columns are affected; other column types are left unchanged.
///
/// Returns a Result indicating success or a Polars error.
pub fn replace_whitespace_with_missing(
    df: &mut DataFrame,
    missing: Option<&str>,
) -> PolarsResult<()> {
    // Clone existing columns, transform them, and rebuild the DataFrame.
    // Cloning Series is cheap-ish (shared buffer) in Polars.
    let old_cols = df.get_columns().clone();

    let mut new_cols: Vec<Series> = Vec::with_capacity(old_cols.len());
    for s in old_cols.iter() {
        if matches!(s.dtype(), DataType::Utf8) {
            // Work with Utf8Chunked to iterate over string values.
            let ca = s.utf8()?;
            // Build an owned Vec<Option<String>> where whitespace-only -> missing.
            let new_vals: Vec<Option<String>> = ca
                .into_iter()
                .map(|opt| match opt {
                    None => None,
                    Some(v) => {
                        if v.trim().is_empty() {
                            // If missing is Some(marker) use it, otherwise produce None (null)
                            missing.map(|m| m.to_string())
                        } else {
                            Some(v.to_string())
                        }
                    }
                })
                .collect();
            // Create a new Series with the same name.
            let new_ser = Series::new(s.name(), new_vals);
            new_cols.push(new_ser);
        } else {
            // Non-string column: keep as-is
            new_cols.push(s.clone());
        }
    }

    // Replace the DataFrame contents atomically by creating a new DataFrame.
    let new_df = DataFrame::new(new_cols)?;
    *df = new_df;
    Ok(())
}

fn main() -> PolarsResult<()> {
    // Example DataFrame containing some whitespace-only strings
    let df0 = df![
        "id" => &[1, 2, 3, 4],
        "name" => &["Alice", "   ", "\t\n", "Bob"],
