                                            buf.push(Some(replacement));
                                        } else {
                                            buf.push(Some(s));
                                        }
                                    }
                                    None => buf.push(None),
                                }
                            });
                        replaced.into_series()
                    }
                    None => {
                        // Replace with null values
                        let replaced: StringChunked = str_series
                            .apply_to_buffer(|value, buf| {
