use polars::prelude::*;

/// Remove all rows from `df0` where the column `var0` equals `var1`,
/// then reset the row indices so they form a consecutive sequence (0..n-1).
///
/// - `df0`: DataFrame to operate on (moved in, returned modified).
/// - `var0`: column name to compare.
/// - `var1`: literal value to filter out (treated as a string literal; comparison will work for Utf8 columns).
///
/// Returns a new DataFrame with the matching rows removed and an "index" column containing 0..n-1.
///
/// Note: This example uses a string literal for `var1`. If your column is numeric, you can
/// adapt by changing the literal (e.g., lit(42)) or by using the LazyFrame API with a typed literal.
pub fn drop_rows_where_equals_string(
    df0: DataFrame,
    var0: &str,
    var1: &str,
) -> PolarsResult<DataFrame> {
    // Ensure column exists
    if !df0.get_column_names().iter().any(|c| c == var0) {
        return Err(PolarsError::NotFound(
            format!("column '{}' not found", var0).into(),
        ));
    }

    // Build a lazy filter expression: keep rows where column != var1
    let lf = df0.lazy().filter(col(var0).neq(lit(var1)));

    // Collect into a physical DataFrame
    let filtered = lf.collect()?;

    // Add a consecutive row index column named "index" starting at 0
    // with_row_count returns a new DataFrame with the index inserted as the first column
    let with_index = filtered.with_row_count("index", Some(0))?;

    Ok(with_index)
}

