use smallvec::SmallVec;

/// Efficiently removes elements from an ordered collection where the predicate returns true.
/// Optimized for cases where only a small number of elements need to be removed.
/// 
/// # Arguments
/// * `collection` - A mutable reference to a Vec or SmallVec
/// * `predicate` - A function that returns true for elements to remove
///
/// # Returns
/// The number of elements removed
///
/// # Example
/// ```
/// let mut numbers = vec![1, 2, 3, 4, 5, 6];
/// let removed = remove_small_elements(&mut numbers, |x| *x % 2 == 0);
/// assert_eq!(removed, 3);
/// assert_eq!(numbers, vec![1, 3, 5]);
/// ```
pub fn remove_small_elements<T, P>(collection: &mut Vec<T>, predicate: P) -> usize
where
    P: Fn(&T) -> bool,
{
    // For small removals, use a two-pointer approach that's cache-friendly
    // and avoids unnecessary shifts for elements that stay
    let len = collection.len();
    let mut write_idx = 0;
    let mut removed_count = 0;

    for read_idx in 0..len {
        // Safety: We're reading within bounds and writing to positions <= read_idx
        if predicate(&collection[read_idx]) {
            removed_count += 1;
        } else {
            if write_idx != read_idx {
                // Only move when necessary (elements were removed before this one)
                collection[write_idx] = std::mem::take(&mut collection[read_idx]);
            }
            write_idx += 1;
        }
    }

    // Truncate the vector to remove the remaining elements
    collection.truncate(write_idx);
    removed_count
}

/// Alternative version using SmallVec for stack allocation of small collections
pub fn remove_small_elements_smallvec<T, P, const N: usize>(
    collection: &mut SmallVec<[T; N]>,
    predicate: P,
) -> usize
where
    P: Fn(&T) -> bool,
{
    let len = collection.len();
    let mut write_idx = 0;
    let mut removed_count = 0;

    for read_idx in 0..len {
        if predicate(&collection[read_idx]) {
            removed_count += 1;
        } else {
            if write_idx != read_idx {
                collection[write_idx] = std::mem::take(&mut collection[read_idx]);
            }
            write_idx += 1;
        }
    }

    collection.truncate(write_idx);
    removed_count
}

