use polars::prelude::*;
use std::collections::HashSet;

/// Reorder columns of `df0` using names in `var0` and the order defined by `var1`.
///
/// - `var0`: list of column names to consider (subset of df0).
/// - `var1`: defines the preferred ordering among names in `var0`.
///
/// Returns a new DataFrame with columns reordered as:
/// 1) columns in var1 (if present in df0 and var0),
/// 2) remaining columns from var0 (preserving var0 order),
/// 3) remaining columns from df0 that are not in var0 (preserving original df0 order).
///
/// Any names in var1 not present in df0 (or not in var0) are ignored.
///
/// Example usage:
/// let df_reordered = reorder_columns_by_lists(&df0, &["a", "b", "c"], &["c", "a"])?;
pub fn reorder_columns_by_lists(
    df0: &DataFrame,
    var0: &[&str],
    var1: &[&str],
) -> PolarsResult<DataFrame> {
    // Track which names we have already placed
    let mut used: HashSet<String> = HashSet::new();
    let mut cols_out: Vec<Series> = Vec::with_capacity(df0.width());

    // Make a quick set for var0 membership checks
    let var0_set: HashSet<&str> = var0.iter().copied().collect();

    // 1) Add columns listed in var1, but only if they're in var0 and exist in df0
    for &name in var1 {
        if !var0_set.contains(name) {
            // skip names not in var0 (per requirement)
            continue;
        }
        if let Ok(s) = df0.column(name) {
            cols_out.push(s.clone());
            used.insert(name.to_string());
        }
    }

    // 2) Add remaining names from var0 (preserve var0 order)
    for &name in var0 {
        if used.contains(name) {
            continue;
        }
        if let Ok(s) = df0.column(name) {
            cols_out.push(s.clone());
            used.insert(name.to_string());
        }
    }

    // 3) Append any remaining columns from df0 that were not in var0 (preserve original order)
    for s in df0.get_columns() {
        let nm = s.name();
        if !used.contains(nm) {
            cols_out.push(s.clone());
            used.insert(nm.to_string());
        }
    }

    // Build new DataFrame from the ordered series
    DataFrame::new(cols_out)
}
