```rust
use indexmap::IndexMap;
use serde_json::{Map, Value};

/// Transform a Vec of maps into an IndexMap keyed by each map's `key_field` entry.
///
/// Each input map must contain `key_field` with a string value. That string becomes the key
/// in the resulting IndexMap and the corresponding value is the original map with the
/// `key_field` removed.
///
/// Returns Err on missing key_field, wrong type for key_field, or duplicate keys.
pub fn list_to_map_by_key(
    lst0: Vec<Map<String, Value>>,
    key_field: &str,
) -> Result<IndexMap<String, Map<String, Value>>, String> {
    let mut out: IndexMap<String, Map<String, Value>> = IndexMap::new();

    for mut m in lst0 {
        // Remove the key_field from the map so the value stored doesn't include it.
        match m.remove(key_field) {
            Some(Value::String(k)) => {
                if out.contains_key(&k) {
                    return Err(format!("duplicate key encountered: {}", k));
                }
                out.insert(k, m);
            }
            Some(other) => {
                return Err(format!(
                    "expected '{}' to be a string, found: {:?}",
                    key_field, other
                ))
            }
            None => {
                return Err(format!("missing '{}' field in map: {:?}", key_field, m));
            }
        }
    }

    Ok(out)
}

