use rand::Rng;

fn kmeans(arr0: &[f64], num_clusters: usize, max_iterations: usize) -> Vec<usize> {
    if num_clusters == 0 || arr0.is_empty() {
        panic!("Number of clusters must be greater than 0 and array must not be empty.");
    }

    let mut rng = rand::thread_rng();
    let mut centroids: Vec<f64> = (0..num_clusters)
        .map(|_| arr0[rng.gen_range(0..arr0.len())])
        .collect();

    let mut labels = vec![0; arr0.len()];
    let mut prev_labels = vec![0; arr0.len()];

    for _ in 0..max_iterations {
        // Assign labels to each point
        for (i, &point) in arr0.iter().enumerate() {
            labels[i] = centroids
                .iter()
                .enumerate()
                .min_by(|(_, &c1), (_, &c2)| {
                    c1.abs_diff(point).partial_cmp(&c2.abs_diff(point)).unwrap()
                })
                .map(|(idx, _)| idx)
                .unwrap();
        }

        // If labels haven't changed, break early
        if labels == prev_labels {
            break;
        }

        // Update centroids
        centroids = (0..num_clusters)
            .map(|cluster| {
                let points_in_cluster: Vec<f64> = arr0
                    .iter()
                    .enumerate()
                    .filter_map(|(i, &point)| if labels[i] == cluster { Some(point) } else { None })
                    .collect();
                if points_in_cluster.is_empty() {
                    arr0[rng.gen_range(0..arr0.len())]
                } else {
                    points_in_cluster.iter().sum::<f64>() / points_in_cluster.len() as f64
                }
            })
            .collect();

        prev_labels = labels.clone();
    }

    labels
}

fn main() {
