/// * `arr0` - Input 1D array of f64 values to cluster.
/// * `k` - Number of clusters to form.
/// * `max_iter` - Maximum number of iterations (default: 100).
/// * `seed` - Random seed for reproducibility (default: None).
///
/// # Returns
/// A vector of cluster labels (0..k-1) for each element in `arr0`.
pub fn kmeans_1d_cluster(
    arr0: &[f64],
    k: usize,
    max_iter: usize,
    seed: Option<u64>,
) -> Vec<usize> {
