use rand::{rngs::StdRng, Rng, SeedableRng};

/// Partition a 1-D data sequence `arr0` into `k` clusters using k-means (k-means++ init).
/// Returns a Vec<usize> of labels (0..k-1) corresponding to each element in arr0.
///
/// Parameters:
/// - arr0: slice of f64 data points
/// - k: desired number of clusters (if k > arr0.len(), k will be truncated to arr0.len())
/// - max_iters: maximum number of k-means iterations
/// - tol: convergence tolerance (stop when centroid moves <= tol)
/// - seed: optional RNG seed for reproducible results (None => non-deterministic)
///
/// Notes:
/// - If arr0 is empty or k == 0, an empty Vec is returned.
/// - Handles empty clusters by reinitializing their centroids to random data points.
pub fn kmeans_1d(
    arr0: &[f64],
    k: usize,
    max_iters: usize,
    tol: f64,
    seed: Option<u64>,
) -> Vec<usize> {
    if arr0.is_empty() || k == 0 {
        return Vec::new();
    }

    let n = arr0.len();
    let k = k.min(n);

    // RNG
    let mut rng: StdRng = match seed {
        Some(s) => StdRng::seed_from_u64(s),
        None => StdRng::from_entropy(),
    };

    // k-means++ initialization
    let mut centroids: Vec<f64> = Vec::with_capacity(k);
    let first_idx = rng.gen_range(0..n);
    centroids.push(arr0[first_idx]);

    while centroids.len() < k {
        // compute squared distances to nearest centroid
        let mut d2: Vec<f64> = arr0
            .iter()
            .map(|&x| {
                centroids
                    .iter()
                    .map(|&c| (x - c) * (x - c))
                    .fold(f64::INFINITY, f64::min)
            })
            .collect();

        let sum: f64 = d2.iter().sum();
        if !(sum > 0.0) {
            // all points coincide (or numerical degenerate): pick a random point
            let idx = rng.gen_range(0..n);
            centroids.push(arr0[idx]);
            continue;
        }

        // sample by cumulative probability proportional to d2
        let mut cumulative = 0.0;
        let r = rng.gen_range(0.0..sum);
        let mut chosen = 0;
        for (i, &val) in d2.iter().enumerate() {
            cumulative += val;
            if r <= cumulative {
                chosen = i;
                break;
            }
        }
        centroids.push(arr0[chosen]);
    }

    // labels and main loop
    let mut labels = vec![0usize; n];

    for _iter in 0..max_iters {
        let mut changed = false;

        // assignment step (use absolute distance for 1-D)
        for i in 0..n {
            let mut best_j = 0;
            let mut best_d = (arr0[i] - centroids[0]).abs();
            for j in 1..centroids.len() {
                let d = (arr0[i] - centroids[j]).abs();
                if d < best_d {
                    best_d = d;
                    best_j = j;
                }
            }
            if labels[i] != best_j {
                labels[i] = best_j;
                changed = true;
            }
        }

        // update centroids
        let k_actual = centroids.len();
        let mut sums = vec![0.0f64; k_actual];
        let mut counts = vec![0usize; k_actual];

        for i in 0..n {
            let l = labels[i];
            sums[l] += arr0[i];
            counts[l] += 1;
        }

        let mut max_move = 0.0;
        for j in 0..k_actual {
            if counts[j] > 0 {
                let newc = sums[j] / counts[j] as f64;
                max_move = max_move.max((centroids[j] - newc).abs());
                centroids[j] = newc;
            } else {
                // empty cluster -> reinitialize to random data point
                let idx = rng.gen_range(0..n);
                max_move = max_move.max((centroids[j] - arr0[idx]).abs());
                centroids[j] = arr0[idx];
            }
        }

        if !changed || max_move <= tol {
            break;
        }
    }

    labels
}

fn main() {
    let arr0 = [0.1, 0.2, 0.15, 5.0, 5.2, 4.9, 10.0, 9.8];
    let labels = kmeans_1d(&arr0, 3, 100, 1e-6, Some(42));
    println!("labels: {:?}", labels);
}
