fn calculate_time_difference(df: &DataFrame) -> Result<DataFrame> {
    // Ensure the DataFrame has the correct columns
    let col0 = df.column("col0")?;
    let col1 = df.column("col1")?;

    // Parse times and calculate differences
    let time_diff: Result<Vec<String>> = col0
        .utf8()?
        .into_iter()
        .zip(col1.utf8()?.into_iter())
        .map(|(a, b)| match (a, b) {
