use polars::prelude::*;
use chrono::NaiveTime;
use chrono::format::ParseError;

/// Parse a time string in a few common formats into NaiveTime.
/// Accepts "HH:MM", "HH:MM:SS", or "HH:MM:SS.sss..." (fractional seconds).
fn parse_time_flexible(s: &str) -> Result<NaiveTime, ParseError> {
    // Try common patterns in order
    if let Ok(t) = NaiveTime::parse_from_str(s, "%H:%M:%S%.f") {
        return Ok(t);
    }
    if let Ok(t) = NaiveTime::parse_from_str(s, "%H:%M:%S") {
        return Ok(t);
    }
    if let Ok(t) = NaiveTime::parse_from_str(s, "%H:%M") {
        return Ok(t);
    }
    // fallback: let chrono attempt a general parse (rarely needed)
    NaiveTime::parse_from_str(s, "%H:%M:%S")
}

/// Add a column "diff_h_m" to df0 containing the difference (col1 - col0)
/// formatted as "[-]HH:MM". Returns a new DataFrame.
///
/// Expects col0 and col1 to be Utf8 (string) columns representing time-of-day.
/// Nulls in either input result in null in output for that row.
pub fn add_time_diff_col(
    df0: &DataFrame,
    col0: &str,
    col1: &str,
) -> PolarsResult<DataFrame> {
    // Ensure the columns exist
    let s0 = df0.column(col0)?;
    let s1 = df0.column(col1)?;

    // We require the inputs to be Utf8 (strings). Return an error otherwise.
    let s0_utf8 = s0.utf8().map_err(|_| PolarsError::ComputeError(
        format!("Column '{}' must be Utf8 (string) with times like 'HH:MM' or 'HH:MM:SS'", col0).into()
    ))?;
    let s1_utf8 = s1.utf8().map_err(|_| PolarsError::ComputeError(
        format!("Column '{}' must be Utf8 (string) with times like 'HH:MM' or 'HH:MM:SS'", col1).into()
    ))?;

    let n = df0.height();
    let mut out: Vec<Option<String>> = Vec::with_capacity(n);

    for i in 0..n {
        match (s0_utf8.get(i), s1_utf8.get(i)) {
            (Some(a_str), Some(b_str)) => {
                // Parse both times
                match (parse_time_flexible(a_str), parse_time_flexible(b_str)) {
                    (Ok(t0), Ok(t1)) => {
                        let dur = t1.signed_duration_since(t0);
                        let total_seconds = dur.num_seconds();
                        let negative = total_seconds < 0;
                        let secs_abs = total_seconds.abs();
                        let hours = secs_abs / 3600;
                        let minutes = (secs_abs % 3600) / 60;
                        let formatted = if negative {
                            format!("-{:02}:{:02}", hours, minutes)
                        } else {
                            format!("{:02}:{:02}", hours, minutes)
                        };
                        out.push(Some(formatted));
                    }
                    _ => {
                        // Parsing failed for at least one element -> null
                        out.push(None);
                    }
                }
            }
            _ => {
                // Any nulls -> result null
                out.push(None);
            }
        }
    }

    let series = Series::new("diff_h_m", out);
    let mut new_df = df0.clone();
    new_df.with_column(series)?;
    Ok(new_df)
}

