pub fn calculate_time_difference(df0: DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Ensure both columns exist and are string type
    let col0 = df0.column("col0")?.str()?;
    let col1 = df0.column("col1")?.str()?;

