        .into_iter()
        .zip(col1.into_iter())
        .map(|(t0, t1)| {
            match (t0, t1) {
                (Some(t0_str), Some(t1_str)) => {
                    // Parse time strings (format: HH:MM:SS)
                    let parts0: Vec<&str> = t0_str.split(':').collect();
                    let parts1: Vec<&str> = t1_str.split(':').collect();

                    if parts0.len() == 3 && parts1.len() == 3 {
                        let h0: i32 = parts0[0].parse().unwrap_or(0);
                        let m0: i32 = parts0[1].parse().unwrap_or(0);
                        let s0: i32 = parts0[2].parse().unwrap_or(0);

                        let h1: i32 = parts1[0].parse().unwrap_or(0);
                        let m1: i32 = parts1[1].parse().unwrap_or(0);
                        let s1: i32 = parts1[2].parse().unwrap_or(0);

                        // Convert to total minutes
                        let total_min0 = h0 * 60 + m0 + s0 / 60;
                        let total_min1 = h1 * 60 + m1 + s1 / 60;

                        // Calculate difference (handling day wrap-around)
                        let diff_min = if total_min1 >= total_min0 {
                            total_min1 - total_min0
                        } else {
                            // Next day scenario
                            (24 * 60 - total_min0) + total_min1
                        };

                        let hours = diff_min / 60;
                        let minutes = diff_min % 60;

