                    }
                }
                _ => "Missing data".to_string(),
            }
        })
        .collect();

    // Create new column and add to DataFrame
    let time_diff_series = Series::new("time_diff", time_diffs);
    let result = df0.hstack(&[time_diff_series])?;

    Ok(result)
