use polars::prelude::*;

fn replace_values_in_column(
    df: &mut DataFrame,
    col_name: &str,
    old_value: &str,
    new_value: &str,
) -> PolarsResult<()> {
    // Get the column
    let col = df.column(col_name)?;

    // Replace all occurrences of old_value with new_value
    let replaced = col
        .str()?
        .to_lowercase()
        .equal(old_value)?
        .if_then_else(
