/// Group `df` by `group_col` and, for each group, return the row(s) that have the maximum value in `value_col`.
/// Ties are preserved (if multiple rows in a group share the max, all are returned).
///
/// Returns a DataFrame containing the original columns for the selected rows.
///
/// Example:
/// let out = group_by_max_rows(&df, "group", "score")?;
pub fn group_by_max_rows(df: &DataFrame, group_col: &str, value_col: &str) -> PolarsResult<DataFrame> {
    // Ensure the requested columns exist
    if df.find_idx_by_name(group_col).is_none() {
        return Err(PolarsError::NotFound(format!("group column '{}' not found", group_col).into()));
    }
    if df.find_idx_by_name(value_col).is_none() {
        return Err(PolarsError::NotFound(format!("value column '{}' not found", value_col).into()));
    }

    // Compute per-group maxima (GroupBy::max computes max for all columns where applicable)
    let max_df = df.groupby([group_col])?.max()?;

    // Join original df to the aggregated max by the group column.
    // Provide a suffix for aggregated columns to avoid name collisions.
    let suffix = "_max";
    let joined = df.join(&max_df, [group_col], [group_col], JoinType::Inner, Some(suffix))?;

    // The aggregated max column name will be value_col + suffix
    let max_col = format!("{}{}", value_col, suffix);

    // Build a boolean mask selecting rows where value_col == value_col_max
    let left_series = joined.column(value_col)?;
    let right_series = joined.column(&max_col)?;
    let mask = left_series.equal(right_series)?;

    // Filter joined rows to keep only those where the value equals the group max
    let mut result = joined.filter(&mask)?;

    // Drop the auxiliary aggregated max column before returning
    // (optional; keeps output columns the same as the original df)
    let _ = result.drop_in_place(&max_col);

    Ok(result)
}

Example usage in main:

fn main() -> PolarsResult<()> {
    // Build an example DataFrame
    let s_group = Series::new("group", &["A", "A", "B", "B", "C"]);
    let s_score = Series::new("score", &[10i32, 15, 15, 12, 7]);
    let df = DataFrame::new(vec![s_group, s_score])?;

    // Group by "group" and get rows with max "score"
    let top_rows = group_by_max_rows(&df, "group", "score")?;
    println!("{}", &top_rows);

    Ok(())
}

