use polars::prelude::*;
use std::error::Error;

/// Groups a DataFrame by a specified column and returns the row with the maximum value
/// in another specified column for each group.
///
/// # Arguments
/// * `df` - The input DataFrame
/// * `group_col` - The name of the column to group by
/// * `max_col` - The name of the column to find the maximum value in
///
/// # Returns
/// * `Result<DataFrame, Box<dyn Error>>` - A DataFrame containing the rows with maximum values per group
///
/// # Example
/// ```
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "group" => &["A", "A", "B", "B", "C"],
///     "value" => &[10, 20, 15, 25, 30],
///     "other" => &[1, 2, 3, 4, 5]
/// ).unwrap();
///
/// let result = group_by_max(&df, "group", "value").unwrap();
/// println!("{:?}", result);
/// ```
pub fn group_by_max(df: &DataFrame, group_col: &str, max_col: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Validate that the specified columns exist
    if !df.get_column_names().contains(&group_col) {
        return Err(format!("Column '{}' not found in DataFrame", group_col).into());
    }
    if !df.get_column_names().contains(&max_col) {
        return Err(format!("Column '{}' not found in DataFrame", max_col).into());
    }

    // Get all column names except the group and max columns
    let other_cols: Vec<&str> = df.get_column_names()
        .iter()
        .filter(|&&col| col != group_col && col != max_col)
        .copied()
        .collect();

    // Find the index of the maximum value for each group
    let max_indices = df
        .group_by([group_col])?
        .agg([
            // Get the index of the maximum value in the specified column
            col(max_col).arg_max().alias("_max_idx"),
        ])?
        .sort(
            [group_col],
            SortMultipleOptions::default().with_order_descending(false),
        )?;

    // Extract the indices and get the corresponding rows
    let idx_col = max_indices.column("_max_idx")?;
    let indices: Vec<usize> = idx_col.u32()?
        .into_iter()
        .map(|opt| opt.unwrap() as usize)
        .collect();

    // Select the rows at those indices
    let result = df.select(
        [col(group_col), col(max_col)]
            .into_iter()
            .chain(other_cols.iter().map(|&col| col(col)))
            .collect::<Vec<_>>()
    )?;

    // Filter to get only the rows with maximum values per group
    let result = result
        .filter(
            &result
                .column(group_col)?
                .iter()
                .enumerate()
                .map(|(i, _)| indices.contains(&i))
                .collect::<BooleanChunked>()
        )?;

    Ok(result)
}

