/// Sorts `dict0` by its values (ascending).
/// Returns (keys_in_sorted_order, var0_mapping_key_to_index).
///
/// K must be Hash + Eq + Clone; V must be Ord + Clone.
pub fn sort_keys_by_values<K, V>(
    dict0: &HashMap<K, V>,
) -> (Vec<K>, IndexMap<K, usize>)
where
    K: Eq + std::hash::Hash + Clone,
    V: Ord + Clone,
{
    // Collect pairs (key, value) as owned values so we can sort.
    let mut pairs: Vec<(K, V)> = dict0.iter().map(|(k, v)| (k.clone(), v.clone())).collect();

    // Sort by value ascending. For equal values, the order among equals will be
    // whatever stable order the sort produces (we don't additionally sort by key).
    pairs.sort_by(|a, b| a.1.cmp(&b.1));

    // Extract the ordered keys.
    let keys: Vec<K> = pairs.iter().map(|(k, _)| k.clone()).collect();

    // Build var0 mapping each key to its index in `keys`.
    let mut var0: IndexMap<K, usize> = IndexMap::with_capacity(keys.len());
    for (idx, key) in keys.iter().cloned().enumerate() {
        var0.insert(key, idx);
    }

    (keys, var0)
