    K: std::hash::Hash + Eq,
    V: Ord,
{
    // Collect key-value pairs and sort by value
    let mut sorted_pairs: Vec<(&K, &V)> = dict0.iter().collect();
    sorted_pairs.sort_by(|a, b| a.1.cmp(b.1));

    // Extract sorted keys
    let sorted_keys: Vec<&K> = sorted_pairs.iter().map(|(k, _)| *k).collect();

    // Create mapping from key to its index in the sorted sequence
    let mut var0: IndexMap<&K, usize> = IndexMap::new();
    for (index, key) in sorted_keys.iter().enumerate() {
        var0.insert(key, index);
    }

    (sorted_keys, var0)
}

// Example usage
