fn replace_nth_occurrence_simple(
    sentence: &str,
    target: &str,
    replacement: &str,
    n: usize,
) -> Option<String> {
    let mut count = 0;
    let mut result = String::new();
    let mut start = 0;

    while let Some(pos) = sentence[start..].find(target) {
        let actual_pos = start + pos;
        count += 1;

        // Check word boundaries
        let before = actual_pos.checked_sub(1).and_then(|i| sentence.as_bytes().get(i));
        let after = sentence.as_bytes().get(actual_pos + target.len());

        let is_word_boundary = before.map_or(true, |&b| !b.is_ascii_alphanumeric())
            && after.map_or(true, |&b| !b.is_ascii_alphanumeric());

        if is_word_boundary {
            if count == n {
                result.push_str(&sentence[start..actual_pos]);
                result.push_str(replacement);
                start = actual_pos + target.len();
                result.push_str(&sentence[start..]);
                return Some(result);
            }
        }

        start = actual_pos + 1;
    }

    None
}
