use polars::prelude::*;

/// Check whether `var` is present in each list in column `list_col` of `df`.
/// Appends a boolean column named `out_col` to a clone of `df` and returns it.
///
/// - Expects `list_col` to be a List column (inner values preferably Utf8).
/// - If a row's list is null, the result for that row will be `false`.
/// - If inner values are not Utf8, the function compares by stringifying inner values.
///
/// Returns PolarsResult<DataFrame>.
pub fn list_contains_str(
    df: &DataFrame,
    list_col: &str,
    var: &str,
    out_col: &str,
) -> PolarsResult<DataFrame> {
    // Get the list column
    let list_series = df.column(list_col)?;
    if !list_series.is_list() {
        return Err(PolarsError::Other(
            format!("Column '{}' is not a List type", list_col).into(),
        ));
    }

    // Get the ListChunked
    let lists = list_series.list()?;

    // Prepare boolean results (one per row)
    let mut contains_flags: Vec<bool> = Vec::with_capacity(lists.len());

    // Iterate over each row's inner Series (Option<Series>)
    for opt_inner in lists.into_iter() {
        match opt_inner {
            None => {
                // Null list -> treat as not containing the value
                contains_flags.push(false);
            }
            Some(inner_series) => {
                // Try to treat inner series as Utf8 (strings)
                match inner_series.utf8() {
                    Ok(utf) => {
                        // iterate possibly-null strings and check equality
                        let mut found = false;
                        for opt_str in utf.into_iter() {
                            if let Some(s) = opt_str {
                                if s == var {
                                    found = true;
                                    break;
                                }
                            }
                        }
                        contains_flags.push(found);
                    }
                    Err(_) => {
                        // Inner type isn't Utf8. Fall back to stringifying inner values.
                        // This is slightly slower but robust for heterogeneous inner types.
                        let mut found = false;
                        for v in inner_series.iter() {
                            // Series::iter yields AnyValue; compare string form.
                            if v.to_string() == var {
                                found = true;
                                break;
                            }
                        }
                        contains_flags.push(found);
                    }
                }
            }
        }
    }

    // Create boolean Series and append to a clone of the DataFrame
    let bool_series = Series::new(out_col, contains_flags);
    let mut out_df = df.clone();
    out_df.with_column(bool_series)?;
    Ok(out_df)
}

