//
// A single self-contained function that reorders the elements of `lst0` so they follow
// the order given by the already-sorted `lst1`. It is optimized for the case where
// `lst1` (the reference) may be very large by choosing between per-item binary searches
// (cheap when lst0 is small) and building a lookup table (cheap when many lookups are needed).
//
// Behavior:
// - Elements of lst0 that appear in lst1 are emitted first, in the order defined by lst1.
//   If lst1 contains duplicates, the first occurrence in lst1 defines the position.
// - Elements of lst0 not present in lst1 are appended after the matched elements in their
//   original relative order.
//
// Complexity:
// - If m = len(lst0), n = len(lst1):
//   - Uses binary search for each element when m * log2(n) < n (rough heuristic).
//     Cost ~ O(m log n) and no extra memory proportional to n.
//   - Otherwise builds a HashMap<&T, usize> over lst1 and does O(m) lookups.
//     Cost ~ O(n + m) time and O(n) extra references in the map.

use hashbrown::HashMap;
use std::hash::Hash;

/// Reorder elements of `lst0` so they follow the ordering defined by sorted `lst1`.
///
/// Constraints:
/// - `lst1` must be sorted (ascending) according to the same `Ord` implementation.
/// - `T` must implement `Ord`, `Eq`, `Hash`, and `Clone`.
pub fn reorder_by_reference<T>(lst0: &[T], lst1: &[T]) -> Vec<T>
where
    T: Ord + Eq + Hash + Clone,
{
    if lst0.is_empty() {
        return Vec::new();
    }
    if lst1.is_empty() {
        return lst0.to_vec();
    }

    let n = lst1.len();
    let m = lst0.len();

    // Heuristic: if looking up each element via binary search is cheaper than building
    // a full hash-map of lst1, do binary searches. Otherwise build a HashMap.
    let log2_n = ((n as f64).log2().ceil() as usize).max(1);
    if m * log2_n < n {
        // Binary-search approach: create (index_in_lst1, element) pairs for matches,
        // collect unmatched elements separately, sort matched pairs by index, and
        // then produce the result.
        let mut pairs: Vec<(usize, T)> = Vec::with_capacity(m);
        let mut unmatched: Vec<T> = Vec::new();

        for item in lst0.iter() {
            // find first position in lst1 where value >= item
            let idx = lst1.partition_point(|x| x < item);
            if idx < n && &lst1[idx] == item {
                pairs.push((idx, item.clone()));
            } else {
                unmatched.push(item.clone());
            }
        }

        // sort by index in lst1 so they follow lst1's ordering
        pairs.sort_by_key(|p| p.0);

        let mut res = Vec::with_capacity(m);
        res.extend(pairs.into_iter().map(|(_, v)| v));
        res.extend(unmatched);
        res
    } else {
        // Build a lookup table (HashMap<&T, usize>) mapping references to their first
        // index in lst1. We store &T keys to avoid cloning all of lst1 (important when lst1 is huge).
        let mut map: HashMap<&T, usize> = HashMap::with_capacity(n);
        for (i, v) in lst1.iter().enumerate() {
            // Keep the first index if duplicates exist in lst1.
            map.entry(v).or_insert(i);
        }

        let mut pairs: Vec<(usize, T)> = Vec::with_capacity(m);
        let mut unmatched: Vec<T> = Vec::new();

        for item in lst0.iter() {
            if let Some(&idx) = map.get(item) {
                pairs.push((idx, item.clone()));
            } else {
                unmatched.push(item.clone());
            }
        }

        pairs.sort_by_key(|p| p.0);

        let mut res = Vec::with_capacity(m);
        res.extend(pairs.into_iter().map(|(_, v)| v));
        res.extend(unmatched);
        res
    }
}

