    let mut result: Vec<T> = Vec::with_capacity(lst0.len());

    // Add elements that were found in lst1, in the order defined by lst1
    result.extend(found.into_iter().map(|(_, item)| item.clone()));

    // Add elements not found in lst1, preserving their original relative order
    result.extend(not_found.into_iter().cloned());

    result
