```rust
use polars::prelude::*;

fn rename_columns(df0: DataFrame, dict0: Option<&std::collections::HashMap<String, String>>, lst0: Option<&[String]>) -> Result<DataFrame> {
    match (dict0, lst0) {
        (Some(mapping), None) => {
            // Rename columns using the provided mapping
            let mut df = df0.clone();
            for (old_name, new_name) in mapping {
                df = df.rename(old_name, new_name)?;
            }
            Ok(df)
        },
        (None, Some(new_order)) => {
            // Rename columns according to the order specified in the sequence
            if new_order.len() != df0.width() {
                return Err(PolarsError::ComputeError(format!("Length of new order list ({}) does not match number of columns ({}).", new_order.len(), df0.width()).into()));
            }

            let mut schema = Schema::new();
            for (old_name, new_name) in df0.get_column_names().iter().zip(new_order.iter()) {
                if let Some(dtype) = df0.schema().get(old_name) {
                    schema.with_column(new_name.clone(), dtype.clone());
                } else {
                    return Err(PolarsError::SchemaMisMatch(format!("Column name {} not found in DataFrame.", old_name).into()));
                }
            }

            let mut df = df0.clone();
            df = df.select(&schema.get_fields().iter().map(|f| f.name()).collect::<Vec<_>>())?;
            df.set_schema(schema)?;
            Ok(df)
        },
        _ => Err(PolarsError::ComputeError("Either dict0 or lst0 must be provided.".into())),
    }
}

