use polars::prelude::*;
use std::collections::HashMap;

/// Rename columns of `df` according to `dict0` (old_name -> new_name),
/// and/or reorder columns according to `lst0` (a sequence of column names).
///
/// Behavior:
/// - If `dict0` is Some, each mapping that matches an existing column will be applied.
/// - If `lst0` is Some, after applying `dict0` (if any), the DataFrame will be reordered to
///   match the names in `lst0`. `lst0` must contain exactly the same number of columns as the
///   DataFrame and all names must exist.
/// - If both are None, the original DataFrame is returned.
///
/// Returns a new DataFrame on success or a Polars error on failure.
fn rename_columns(
    mut df: DataFrame,
    dict0: Option<&HashMap<String, String>>,
    lst0: Option<&[String]>,
) -> PolarsResult<DataFrame> {
    // Apply mapping (rename) if provided
    if let Some(map) = dict0 {
        for (old, new) in map {
            // Only attempt rename if the column exists
            if df.find_idx_by_name(old).is_some() {
                df.rename(old, new)?;
            }
        }
    }

    // Reorder if list provided
    if let Some(order) = lst0 {
        let current_cols = df.get_column_names();
        if order.len() != current_cols.len() {
            return Err(PolarsError::ComputeError(
                format!(
                    "lst0 length ({}) does not match number of columns ({})",
                    order.len(),
                    current_cols.len()
                )
                .into(),
            ));
        }
        // Collect columns in requested order (ensure they exist)
        let mut cols = Vec::with_capacity(order.len());
        for name in order {
            // df.column returns a borrow; clone the Series to build a new DataFrame
            cols.push(df.column(name.as_str())?.clone());
        }
        return DataFrame::new(cols);
    }

    // No reordering requested: return the possibly-renamed df
    Ok(df)
}

fn main() -> PolarsResult<()> {
