// This uses a tiny helper "tabular_2024" module (a minimal, new-style data-frame
// helper), which you can treat as a small library introduced in 2024. The function
// `rename_row_identifiers` is the user-facing operation you requested.
//
// The DataFrame stores row identifiers in `row_ids: Vec<String>`. The rename
// operation looks up each existing row id in `dict0` and replaces it if a mapping
// exists. If multiple original ids map to the same new id, the function returns
// an error (to avoid accidental duplicate row identifiers). Rows with no mapping
// are left unchanged.
//
// Example usage in `main` is provided at the bottom.

use std::collections::{HashMap, HashSet};
use std::fmt;

/// Minimal tabular helper library (self-contained; imagine this as a small
/// 2024 helper crate `tabular_2024`).
mod tabular_2024 {
    use super::*;
    /// A simple column type storing values of generic type T.
    #[derive(Clone, Debug)]
    pub struct Column<T> {
        pub name: String,
        pub values: Vec<T>,
    }

    /// Very small DataFrame-like struct: row identifiers + named columns.
    #[derive(Clone, Debug)]
    pub struct DataFrame<T> {
        pub row_ids: Vec<String>,
        pub columns: Vec<Column<T>>,
    }

    impl<T> DataFrame<T> {
        /// Construct a new DataFrame from row ids and columns.
        /// Panics if column lengths do not match number of row ids.
        pub fn new(row_ids: Vec<String>, columns: Vec<Column<T>>) -> Self {
            let n = row_ids.len();
            for col in &columns {
                assert!(
                    col.values.len() == n,
                    "all columns must have the same number of rows as row_ids"
                );
            }
            DataFrame { row_ids, columns }
        }

        /// Number of rows.
        pub fn nrows(&self) -> usize {
            self.row_ids.len()
        }

        /// Number of columns.
        pub fn ncols(&self) -> usize {
            self.columns.len()
        }

        /// Get a column by name (immutable).
        pub fn column(&self, name: &str) -> Option<&Column<T>> {
            self.columns.iter().find(|c| c.name == name)
        }

        /// Get a mutable column by name.
        pub fn column_mut(&mut self, name: &str) -> Option<&mut Column<T>> {
            self.columns.iter_mut().find(|c| c.name == name)
        }
    }

    /// Error type returned by rename operation.
    #[derive(Debug)]
    pub enum RenameError {
        /// One or more new row ids collide (duplicate after renaming).
        DuplicateNewIds(Vec<String>),
    }

    impl fmt::Display for RenameError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            match self {
                RenameError::DuplicateNewIds(ids) => {
                    write!(
                        f,
                        "rename would create duplicate row identifiers: {:?}",
                        ids
                    )
                }
            }
        }
    }

    impl std::error::Error for RenameError {}

    impl<T> DataFrame<T> {
        /// Rename the row identifiers according to the given mapping.
        ///
        /// - `mapping` maps old_id -> new_id.
        /// - If an old_id is not a key in mapping, it remains unchanged.
        /// - If two or more row ids would become the same new id, this returns
        ///   Err(RenameError::DuplicateNewIds(...)) and does not modify `self`.
        pub fn rename_row_ids(
            &mut self,
            mapping: &HashMap<String, String>,
        ) -> Result<(), RenameError> {
            // Compute the prospective new ids without modifying self.
            let mut new_ids = Vec::with_capacity(self.row_ids.len());
            for id in &self.row_ids {
                if let Some(new_id) = mapping.get(id) {
                    new_ids.push(new_id.clone());
                } else {
                    new_ids.push(id.clone());
                }
            }

            // Check for duplicates in new_ids.
            let mut seen = HashSet::with_capacity(new_ids.len());
            let mut duplicates = Vec::new();
            for id in &new_ids {
                if !seen.insert(id.clone()) {
                    duplicates.push(id.clone());
                }
            }
            if !duplicates.is_empty() {
                // Return unique duplicates
                duplicates.sort();
                duplicates.dedup();
                return Err(RenameError::DuplicateNewIds(duplicates));
            }

            // Safe to apply
            self.row_ids = new_ids;
            Ok(())
        }
    }

    pub use DataFrame;
    pub use RenameError;
    pub use Column;
}

