/// - Ok(()) if rename succeeded (and df0 is updated).
/// - Err(RenameError) if the rename would cause duplicate row identifiers (no change made).
pub fn rename_row_identifiers<T>(
    df0: &mut DataFrame<T>,
    dict0: &HashMap<String, String>,
) -> Result<(), RenameError> {
