///
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "lst0" => &["A", "A", "B", "B", "A"],
///     "lst1" => &["X", "Y", "X", "Y", "X"],
///     "value" => &[1, 2, 3, 4, 5]
/// ).unwrap();
///
/// let result = group_and_count(&df, "lst0", "lst1").unwrap();
/// println!("{:?}", result);
/// ```
pub fn group_and_count(
    df: &DataFrame,
    group_col0: &str,
    group_col1: &str,
) -> Result<DataFrame, Box<dyn Error>> {
    // Validate that the columns exist
    if !df.get_column_names().contains(&group_col0) {
        return Err(format!("Column '{}' not found in DataFrame", group_col0).into());
    }
    if !df.get_column_names().contains(&group_col1) {
        return Err(format!("Column '{}' not found in DataFrame", group_col1).into());
    }

    // Group by the two columns and count
    let result = df
        .lazy()
        .group_by([col(group_col0), col(group_col1)])
        .agg([len().alias("count")])
        .collect()?;

    Ok(result)
}

