use polars::prelude::*;

/// Deduplicates a DataFrame by keeping only the row with maximum C value for each unique (A, B) combination.
///
/// # Arguments
/// * `df` - Input DataFrame containing columns A, B, and C
///
/// # Returns
/// A new DataFrame with duplicates removed based on the specified criteria
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df![
///     "A" => &[1, 1, 2, 2],
///     "B" => &["x", "y", "x", "y"],
///     "C" => &[10, 20, 15, 5]
/// ]?;
///
/// let result = deduplicate_max_c(df)?;
/// ```
pub fn deduplicate_max_c(df: DataFrame) -> Result<DataFrame, PolarsError> {
    // Create a temporary DataFrame with the unique (A, B) combinations and their max C values
    let grouped = df
        .lazy()
        .group_by([col("A"), col("B")])
        .agg([col("C").max()])
        .collect()?;

    // Join the original DataFrame with this grouped result to find matching rows
    let result = df
        .lazy()
        .join(
            grouped.lazy(),
            [col("A"), col("B")],
            [col("A"), col("B")],
            JoinType::Inner,
        )
        .filter(col("C").eq(col("C").alias("C_max")))
        .drop("C_max")
        .collect()?;

    Ok(result)
}

