use polars::prelude::*;

/// Deduplicate `df0` by columns "A" and "B", keeping the row with the maximum "C"
/// for each unique (A, B) combination.
/// 
/// Returns a new DataFrame with duplicates removed. If multiple rows tie for max C,
/// the first encountered (after sorting) is kept.
/// 
/// Errors if required columns are missing or sorting/uniquing fails.
pub fn dedup_keep_max_c(mut df0: DataFrame) -> PolarsResult<DataFrame> {
    // Ensure required columns exist (gives a clearer error)
    for col in &["A", "B", "C"] {
        if !df0.get_column_names().contains(col) {
            return Err(PolarsError::NotFound(
                format!("required column '{}' not found in DataFrame", col).into(),
            ));
        }
    }

    // Sort by "C" in descending order so the max-C rows come first.
    // DataFrame::sort takes (by_column, reverse) where reverse = true means descending.
    let sorted = df0.sort("C", true)?;

    // Keep the first row for each unique (A, B) combination.
    // unique_stable preserves the order and UniqueKeepStrategy::First keeps the first occurrence.
    let deduped = sorted.unique_stable(Some(&["A", "B"]), UniqueKeepStrategy::First)?;

    Ok(deduped)
}

fn main() -> PolarsResult<()> {
    // Example usage:
    // Construct a small DataFrame
    let a = Series::new("A", &["x", "x", "y", "y", "x"]);
    let b = Series::new("B", &["u", "u", "v", "v", "u"]);
    let c = Series::new("C", &[10i32, 15, 5, 7, 15]); // note duplicate max for (x,u) -> 15 twice
    let other = Series::new("other", &["r1", "r2", "r3", "r4", "r5"]);

    let df = DataFrame::new(vec![a, b, c, other])?;

    println!("Original:\n{}", &df);

    let result = dedup_keep_max_c(df)?;

    println!("\nDeduplicated (keep max C per (A,B)):\n{}", &result);

    Ok(())
}
```

Notes and behavior:
- This keeps the entire row corresponding to the maximum C. If two rows have identical max C for the same (A,B), the first encountered after sorting is kept (stable).
- Sorting then unique-stable is usually faster and simpler than group-then-join when you want to preserve entire rows rather than only aggregated columns.
- Adjust the polars crate version to a 2024+ release available in your environment; the shown version is an example.

