fn remove_duplicates_keep_max(
    df: DataFrame,
    group_cols: &[&str],
    max_col: &str,
) -> Result<DataFrame, PolarsError> {
    // Sort by group columns and max_col in descending order
    // Then drop duplicates keeping the first occurrence (which has the max value)
    df.sort(
        &[group_cols[0].to_string()],
        SortMultipleOptions::default()
            .with_order_by_columns(vec![
                group_cols[0].to_string(),
                max_col.to_string(),
            ])
            .with_maintain_order(false),
    )?
    .unique_stable(Some(group_cols), UniqueKeepStrategy::Last)
}

// Alternative, more explicit implementation:
fn remove_duplicates_keep_max_explicit(
    df: DataFrame,
    group_cols: Vec<&str>,
    max_col: &str,
) -> Result<DataFrame, PolarsError> {
    df.lazy()
        .sort(
            &group_cols,
            vec![SortOptions {
                descending: true,
                nulls_last: true,
                multithreaded: true,
                in_place: false,
                maintain_order: false,
            }],
        )
        .sort(
            &vec![max_col.to_string()],
            vec![SortOptions {
                descending: true,
                nulls_last: true,
                multithreaded: true,
                in_place: false,
                maintain_order: false,
            }],
        )
        .unique_stable(Some(group_cols), UniqueKeepStrategy::Last)
        .collect()
}

