use ahash::AHashSet;
use serde_json::{Map, Value};

/// Filter `lst0` (Vec of JSON-like maps) by removing any item whose "var0"
/// value appears in `lst1`. Returns a new Vec with the retained items.
///
/// Behavior:
/// - If an item in lst0 has no "var0" key, it is kept.
/// - Comparison is done by serializing the values to JSON strings, so equality
///   works across numbers/strings/objects/arrays consistently with serde_json.
/// - Uses ahash::AHashSet for fast membership testing.
///
/// Example:
/// let lst0 = vec![
///     json!({"var0": 1, "other": "a"}).as_object().unwrap().clone(),
///     json!({"var0": 2, "other": "b"}).as_object().unwrap().clone(),
///     json!({"other": "c"}).as_object().unwrap().clone(),
/// ];
/// let lst1 = vec![json!(2)];
/// let filtered = filter_remove_var0_in_list(lst0, &lst1);
/// // filtered contains the items with var0 == 1 and the one with no var0.
pub fn filter_remove_var0_in_list(
    lst0: Vec<Map<String, Value>>,
    lst1: &[Value],
) -> Vec<Map<String, Value>> {
    // Build a set of JSON-serialized representations of values in lst1.
    // serde_json::Value does not implement Hash, so we use the string form as a stable key.
    let mut remove_set: AHashSet<String> = AHashSet::with_capacity(lst1.len());
    for v in lst1 {
        // to_string produces valid JSON text for the value
        remove_set.insert(v.to_string());
    }

    lst0
        .into_iter()
        .filter(|item| {
            match item.get("var0") {
                Some(v) => {
                    // If var0 serializes to something in remove_set, filter it OUT.
                    !remove_set.contains(&v.to_string())
                }
                None => true, // keep items that don't have var0
            }
        })
        .collect()
}

