            json!({"var0": 2, "other": "b"}).as_object().unwrap().clone(),
            json!({"var0": "2", "other": "str2"}).as_object().unwrap().clone(),
            json!({"other": "no_var0"}).as_object().unwrap().clone(),
            json!({"var0": {"x": 1}, "other": "obj"}).as_object().unwrap().clone(),
