use std::collections::HashMap;

/// Sorts a collection of records (HashMap) according to the order defined by a reference sequence.
/// 
/// # Arguments
/// * `dict0` - A vector of HashMaps representing records
/// * `lst0` - A reference sequence defining the sort order
/// * `var0` - The key in each record whose value determines sort position
///
/// # Returns
/// A sorted vector of records ordered by their position in lst0
pub fn sort_records_by_reference<K, V>(
    dict0: Vec<HashMap<K, String>>,
    lst0: &[String],
    var0: &K,
) -> Vec<HashMap<K, String>>
where
    K: std::hash::Hash + Eq + Clone,
{
    // Create a position map for O(1) lookup
    let position_map: HashMap<&String, usize> = lst0
        .iter()
        .enumerate()
        .map(|(idx, val)| (val, idx))
        .collect();

    // Sort records based on the position of their var0 value in lst0
    let mut sorted = dict0;
    sorted.sort_by_key(|record| {
        record
            .get(var0)
            .and_then(|val| position_map.get(&val).copied())
            .unwrap_or(usize::MAX) // Items not in lst0 go to the end
    });

    sorted
}

