use polars::prelude::*;
use serde_json::{Map, Number, Value};

/// Convert a Polars AnyValue into serde_json::Value (best-effort).
fn anyvalue_to_json(av: AnyValue) -> Value {
    match av {
        AnyValue::Null => Value::Null,
        AnyValue::Boolean(b) => Value::Bool(b),
        AnyValue::Utf8(s) => Value::String(s.to_string()),
        AnyValue::Utf8Owned(s) => Value::String(s),
        AnyValue::Int8(i) => Value::Number(Number::from(i)),
        AnyValue::Int16(i) => Value::Number(Number::from(i)),
        AnyValue::Int32(i) => Value::Number(Number::from(i)),
        AnyValue::Int64(i) => Value::Number(Number::from(i)),
        AnyValue::UInt8(u) => Value::Number(Number::from(u)),
        AnyValue::UInt16(u) => Value::Number(Number::from(u)),
        AnyValue::UInt32(u) => Value::Number(Number::from(u)),
        AnyValue::UInt64(u) => {
            // Number::from(u64) exists
            Value::Number(Number::from(u))
        }
        AnyValue::Float32(f) => {
            Number::from_f64(f as f64).map(Value::Number).unwrap_or(Value::Null)
        }
        AnyValue::Float64(f) => Number::from_f64(f).map(Value::Number).unwrap_or(Value::Null),
        AnyValue::Date(d) => Value::Number(Number::from(d)), // days since epoch
        AnyValue::Datetime(ts, _unit, _tz) => {
            // Represent datetime as number (timestamp) for simplicity
            Value::Number(Number::from(ts))
        }
        AnyValue::Duration(v, _unit) => Value::Number(Number::from(v)),
        AnyValue::Time(t) => Value::Number(Number::from(t)),
        // Lists, Structs etc. fallback to string representation:
        other => Value::String(format!("{other}")),
    }
}

/// Transform a polars DataFrame into a serde_json::Value "dictionary" according to orientation.
///
/// df: reference to polars::prelude::DataFrame
/// orient: one of "dict", "list", "records", "index", "split"
///
/// Returns serde_json::Value (Object or Array) representing the transformed dictionary.
pub fn df_to_dict(df: &DataFrame, orient: &str) -> serde_json::Value {
    let nrows = df.height();
    let cols = df.get_columns();
    let col_names: Vec<String> = cols.iter().map(|s| s.name().to_string()).collect();

    match orient {
        "list" => {
            // { column -> [values...] }
            let mut obj = Map::new();
            for s in cols {
                let mut arr = Vec::with_capacity(nrows);
                for i in 0..nrows {
                    let v = s.get(i);
                    arr.push(anyvalue_to_json(v));
                }
                obj.insert(s.name().to_string(), Value::Array(arr));
            }
            Value::Object(obj)
        }
        "records" => {
            // [ {col: value, ...}, ... ] one entry per row
            let mut rows: Vec<Value> = Vec::with_capacity(nrows);
            for i in 0..nrows {
                let mut map = Map::with_capacity(col_names.len());
                for s in cols {
                    let v = s.get(i);
                    map.insert(s.name().to_string(), anyvalue_to_json(v));
                }
                rows.push(Value::Object(map));
            }
            Value::Array(rows)
        }
        "index" => {
            // { index -> { col -> value } }
            let mut outer = Map::new();
            for i in 0..nrows {
                let mut inner = Map::with_capacity(col_names.len());
                for s in cols {
                    let v = s.get(i);
                    inner.insert(s.name().to_string(), anyvalue_to_json(v));
                }
                outer.insert(i.to_string(), Value::Object(inner));
            }
            Value::Object(outer)
        }
        "split" => {
            // { "index": [0,1,...], "columns": [...], "data": [[row...], ...] }
            let index_arr: Vec<Value> = (0..nrows).map(|i| Value::Number(Number::from(i))).collect();
            let cols_arr: Vec<Value> = col_names.iter().map(|c| Value::String(c.clone())).collect();
            let mut data: Vec<Value> = Vec::with_capacity(nrows);
            for i in 0..nrows {
                let mut row: Vec<Value> = Vec::with_capacity(col_names.len());
                for s in cols {
                    row.push(anyvalue_to_json(s.get(i)));
                }
                data.push(Value::Array(row));
            }
            let mut out = Map::new();
            out.insert("index".to_string(), Value::Array(index_arr));
            out.insert("columns".to_string(), Value::Array(cols_arr));
            out.insert("data".to_string(), Value::Array(data));
            Value::Object(out)
        }
        // default and "dict": map column -> { index -> value }
        _ => {
            let mut outer = Map::new();
            for s in cols {
                let mut inner = Map::with_capacity(nrows);
                for i in 0..nrows {
                    inner.insert(i.to_string(), anyvalue_to_json(s.get(i)));
                }
                outer.insert(s.name().to_string(), Value::Object(inner));
            }
            Value::Object(outer)
        }
    }
}

