pub fn transform_dataset_to_dict(
    df0: DataFrame,
    var0: &str,
) -> Result<HashMap<String, Vec<Option<f64>>>, PolarsError> {
    let mut result: HashMap<String, Vec<Option<f64>>> = HashMap::new();

    match var0 {
        "columns" => {
            // Iterate over each column and convert to vector
            for col_name in df0.get_column_names() {
                let series = df0.column(col_name)?;
                let values: Vec<Option<f64>> = series
                    .f64()?
                    .into_iter()
                    .map(|v| v)
                    .collect();
                result.insert(col_name.to_string(), values);
            }
        }
        "rows" => {
            // Convert each row to a vector and use row index as key
            let height = df0.height();
            let columns: Vec<&Series> = df0.get_columns().iter().collect();

            for row_idx in 0..height {
                let mut row_values: Vec<Option<f64>> = Vec::with_capacity(columns.len());

                for col in &columns {
                    let value = col.f64()?.get(row_idx);
                    row_values.push(value);
                }

                result.insert(row_idx.to_string(), row_values);
            }
        }
        _ => {
            return Err(PolarsError::ComputeError(
                format!("Invalid orientation: {}. Use 'columns' or 'rows'", var0).into(),
            ));
        }
    }

    Ok(result)
}

