```rust
use polars::prelude::*;
use std::collections::HashMap;

/// Transform a 2D Polars DataFrame into a HashMap according to the specified orientation.
/// 
/// # Arguments
/// * `df` - A Polars DataFrame to transform
/// * `orientation` - How to organize the data:
///   - "columns" or "col": Each column name maps to a vector of values
///   - "rows" or "row": Each row index maps to a HashMap of column_name -> value
///   - "records": Vector of row HashMaps with column names as keys
///   - "list": Each column name maps to a vector of values (alias for "columns")
///
/// # Returns
/// Result containing the transformed HashMap or an error message
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use std::collections::HashMap;
///
/// let df = df! {
///     "A" => &[1, 2, 3],
///     "B" => &[4, 5, 6],
/// }.unwrap();
///
/// let result = transform_df_to_dict(&df, "columns").unwrap();
/// ```
pub fn transform_df_to_dict(
    df: &DataFrame,
    orientation: &str,
) -> PolarsResult<HashMap<String, Vec<String>>> {
    match orientation.to_lowercase().as_str() {
        "columns" | "col" | "list" => {
            // Each column name maps to a vector of string values
            let mut result: HashMap<String, Vec<String>> = HashMap::new();

            for col_name in df.get_column_names() {
                let series = df.column(col_name)?;
                let values: Vec<String> = series
                    .iter()
                    .map(|val| match val {
                        AnyValue::Null => "null".to_string(),
                        other => other.to_string(),
                    })
                    .collect();
                result.insert(col_name.to_string(), values);
            }
            Ok(result)
        }
        _ => Err(PolarsError::ComputeError(
            format!("Unknown orientation: '{}'. Use 'columns', 'col', 'list', 'rows', or 'row'.", orientation).into()
        )),
    }
}

// Alternative version that returns nested HashMaps for row-based orientation
pub fn transform_df_to_dict_rows(
    df: &DataFrame,
    orientation: &str,
) -> PolarsResult<Vec<HashMap<String, String>>> {
    match orientation.to_lowercase().as_str() {
        "rows" | "row" => {
            let col_names = df.get_column_names();
            let mut result: Vec<HashMap<String, String>> = Vec::new();

            for row_idx in 0..df.height() {
                let mut row_map: HashMap<String, String> = HashMap::new();

                for col_name in &col_names {
                    let series = df.column(col_name)?;
                    let value = series.get(row_idx);
                    let value_str = match value {
                        AnyValue::Null => "null".to_string(),
                        other => other.to_string(),
                    };
                    row_map.insert(col_name.to_string(), value_str);
                }
                result.push(row_map);
            }
            Ok(result)
        }
        _ => Err(PolarsError::ComputeError(
            format!("Unknown orientation: '{}'. Use 'rows' or 'row'.", orientation).into()
        )),
    }
}

