```rust
use regex::Regex;

/// Extract the `n` words immediately before and after the first occurrence of `term` in `text`.
/// Returns (before, after), each being a Vec<Option<String>> of length `n`.
/// - `before[0]` is the word immediately before the term (closest),
///   `before[n-1]` is the nth word before (farthest).
/// - `after[0]` is the word immediately after the term (closest),
///   `after[n-1]` is the nth word after (farthest).
/// Matching is case-insensitive and uses simple Unicode word tokenization (letters, numbers, underscore).
///
/// Example:
/// let (before, after) = extract_neighbors("one two three FOUR five", "four", 2);
/// // before == [Some("three".into()), Some("two".into())]
/// // after  == [Some("five".into()), None]
pub fn extract_neighbors(text: &str, term: &str, n: usize) -> (Vec<Option<String>>, Vec<Option<String>>) {
    if n == 0 {
        return (Vec::new(), Vec::new());
    }

    // Token regex: sequences of Unicode letters or numbers or underscore.
    let word_re = Regex::new(r"[\p{L}\p{N}_]+").expect("valid regex");

    // Collect words (as Strings) in order
    let mut words: Vec<String> = Vec::new();
    for mat in word_re.find_iter(text) {
        words.push(mat.as_str().to_string());
    }

    // Lowercase the search term for case-insensitive matching
    let term_lower = term.to_lowercase();

    // Find index of the first match (case-insensitive)
    let mut match_index: Option<usize> = None;
    for (i, w) in words.iter().enumerate() {
        if w.to_lowercase() == term_lower {
            match_index = Some(i);
            break;
        }
    }

    // Prepare result vectors filled with None
    let mut before: Vec<Option<String>> = vec![None; n];
    let mut after: Vec<Option<String>> = vec![None; n];

    if let Some(idx) = match_index {
        // Fill before: closest first (k=1 -> idx-1)
        for k in 1..=n {
            if idx >= k {
                before[k - 1] = Some(words[idx - k].clone());
            } else {
                before[k - 1] = None;
            }
        }
        // Fill after: closest first (k=1 -> idx+1)
        for k in 1..=n {
            let pos = idx + k;
            if pos < words.len() {
                after[k - 1] = Some(words[pos].clone());
            } else {
                after[k - 1] = None;
            }
        }
    }

    (before, after)
}

fn main() {
    let text = "Hello, this is an example: quick brown fox jumps over the lazy dog.";
    let term = "fox";
    let n = 3;

    let (before, after) = extract_neighbors(text, term, n);

    println!("Text: {}", text);
    println!("Term: {:?}", term);
    println!("Before (closest->farthest): {:?}", before);
    println!("After  (closest->farthest): {:?}", after);

    // Examples with missing neighbors:
    let (b2, a2) = extract_neighbors("one two THREE", "one", 2);
    println!("Example 2 Before: {:?}, After: {:?}", b2, a2);
}
```

Notes:
- Tokenization uses a Unicode-aware regex that captures sequences of letters or digits (and underscores). Adjust the regex if you want a different notion of "word" (e.g., include apostrophes).
- The function searches the first occurrence of `term` (case-insensitive). If you want to handle multiple occurrences, the function can be adapted to return neighbors for every match.

