# Rust Function to Extract Words Around a Search Term

```rust
use regex::Regex;

fn extract_words_around(text: &str, search_term: &str, num_words: usize) -> (Vec<Option<String>>, Vec<Option<String>>) {
    // Split text into words
    let words: Vec<&str> = text.split_whitespace().collect();

    // Find the index of the search term
    let search_index = words.iter().position(|&word| {
        word.eq_ignore_ascii_case(search_term)
    });

    match search_index {
        Some(idx) => {
            // Extract words before
            let mut before = Vec::new();
            for i in (0..num_words).rev() {
                if idx > i {
                    before.push(Some(words[idx - i - 1].to_string()));
                } else {
                    before.push(None);
                }
            }
            before.reverse();

            // Extract words after
            let mut after = Vec::new();
            for i in 0..num_words {
                if idx + i + 1 < words.len() {
                    after.push(Some(words[idx + i + 1].to_string()));
                } else {
                    after.push(None);
                }
            }

            (before, after)
        }
        None => {
            // Search term not found, return all Nones
            let empty_vec = vec![None; num_words];
            (empty_vec.clone(), empty_vec)
        }
    }
}

