```rust
use itertools::Itertools;

/// Replaces each boolean in a list with an element from one of two lists.
/// 
/// - When the boolean is `true`, uses the element from `true_list`
/// - When the boolean is `false`, uses the element from `false_list`
///
/// # Arguments
/// * `conditions` - A list of boolean values
/// * `true_list` - Elements to use when condition is true
/// * `false_list` - Elements to use when condition is false
///
/// # Returns
/// A vector containing the selected elements based on conditions
///
/// # Panics
/// Panics if the lists have different lengths
fn conditional_select<T: Clone>(
    conditions: &[bool],
    true_list: &[T],
    false_list: &[T],
) -> Vec<T> {
    assert_eq!(
        conditions.len(),
        true_list.len(),
        "conditions and true_list must have the same length"
    );
    assert_eq!(
        conditions.len(),
        false_list.len(),
        "conditions and false_list must have the same length"
    );

    conditions
        .iter()
        .zip_eq(true_list.iter().zip_eq(false_list.iter()))
        .map(|(cond, (true_elem, false_elem))| {
            if *cond {
                true_elem.clone()
            } else {
                false_elem.clone()
            }
        })
        .collect()
}

fn main() {
    // Example 1: integers
    let conditions = vec![true, false, true, false];
    let true_list = vec![1, 2, 3, 4];
    let false_list = vec![10, 20, 30, 40];

    let result = conditional_select(&conditions, &true_list, &false_list);
