use polars::prelude::*;
use regex::Regex;

/// Removes rows from a DataFrame where `var0` column matches the regex pattern in `var1`,
/// then resets the row numbering to be sequential.
///
/// # Arguments
/// * `df` - Input DataFrame
/// * `var0` - Name of the column to filter
/// * `var1` - Regex pattern to match against `var0`
///
/// # Returns
/// A new DataFrame with matching rows removed and sequential row numbering
pub fn filter_and_reset_rows(df: DataFrame, var0: &str, var1: &str) -> Result<DataFrame, PolarsError> {
