        .into_iter()
        .map(|b| !b) // Invert to keep non-matching rows
        .collect::<Series>()?;

    // Filter the DataFrame
    let filtered_df = df.lazy().filter(&mask).collect()?;

    // Reset row numbering (Polars automatically handles this when collecting from lazy)
    Ok(filtered_df)
}

