/// - var0: column name to compare
/// - lst0: list of string values to test membership against
/// - op0: Op::In to keep rows where var0 is in lst0, Op::NotIn to keep rows where var0 is not in lst0
///
/// Returns a new DataFrame with the filtered rows or an error.
fn filter_by_list_utf8(
