use std::hash::Hash;

/// Zip two sequences of equal length into a mapping from keys to values.
/// Returns an error if lengths differ.
///
/// - `keys` and `values` are slices; keys must be Hash + Eq + Clone, values Clone.
/// - Returns an IndexMap preserving the input order of keys.
pub fn zip_to_map<K, V>(
    keys: &[K],
    values: &[V],
) -> Result<IndexMap<K, V>, &'static str>
where
    K: Eq + Hash + Clone,
    V: Clone,
{
    if keys.len() != values.len() {
        return Err("keys and values must have equal length");
    }

    let mut map = IndexMap::with_capacity(keys.len());
    for (k, v) in keys.iter().cloned().zip(values.iter().cloned()) {
        // If a key appears more than once, the last occurrence wins,
        // matching the typical behavior of HashMap/IndexMap insert.
        map.insert(k, v);
    }
    Ok(map)
}

