/// let keys = vec!["a", "b", "c"];
/// let values = vec![1, 2, 3];
/// let map = zip_to_map(keys, values);
/// assert_eq!(map.get("a"), Some(&1));
/// ```
fn zip_to_map<K: Eq + std::hash::Hash, V>(
    keys: impl IntoIterator<Item = K>,
    values: impl IntoIterator<Item = V>,
) -> HashMap<K, V> {
    let mut keys_iter = keys.into_iter();
    let mut values_iter = values.into_iter();
    let mut map = HashMap::new();

    loop {
        match (keys_iter.next(), values_iter.next()) {
            (Some(k), Some(v)) => {
                map.insert(k, v);
            }
            (None, None) => break,
            _ => panic!("Keys and values sequences have different lengths"),
        }
    }

    map
}

fn main() {
    // Example 1: String keys with integer values
    let keys = vec!["apple", "banana", "cherry"];
    let values = vec![1, 2, 3];
    let fruit_map = zip_to_map(keys, values);

    println!("Fruit map: {:?}", fruit_map);
    println!("apple -> {}", fruit_map.get("apple").unwrap());

    // Example 2: Integer keys with string values
    let ids = vec![1, 2, 3];
    let names = vec!["Alice", "Bob", "Charlie"];
    let people_map = zip_to_map(ids, names);

    println!("People map: {:?}", people_map);
    println!("ID 1 -> {}", people_map.get(&1).unwrap());

    // Example 3: Using iterators directly
    let colors = vec!["red", "green", "blue"];
    let hex_codes = vec!["#FF0000", "#00FF00", "#0000FF"];
    let color_map = zip_to_map(colors, hex_codes);

    println!("Color map: {:?}", color_map);
}

