        let values = vec![1, 2, 3];
        let map = zip_to_map(keys, values);

        assert_eq!(map.get("a"), Some(&1));
        assert_eq!(map.get("b"), Some(&2));
        assert_eq!(map.get("c"), Some(&3));
    }

    #[test]
    fn test_empty_sequences() {
        let keys: Vec<&str> = vec![];
        let values: Vec<i32> = vec![];
