use polars::prelude::*;
use regex::Regex;

/// Filter rows of `df0` so only those with `var0` matching the regex `var1` remain.
///
/// - `df0`: input DataFrame (borrowed).
/// - `var0`: column name containing strings.
/// - `var1`: regular expression pattern.
///
/// Returns a new filtered DataFrame or a Polars error.
pub fn filter_by_regex(df0: &DataFrame, var0: &str, var1: &str) -> PolarsResult<DataFrame> {
    // Ensure the column exists
    let series = df0.column(var0)?;

    // Ensure we have a Utf8 (string) series; cast if necessary
    let s_utf8 = if series.dtype() != &DataType::Utf8 {
        series.cast(&DataType::Utf8)?
    } else {
        series.clone()
    };

    // Get the Utf8Chunked view
    let ca = s_utf8.utf8()?;

    // Compile the regex; convert regex errors into a Polars error
    let re = Regex::new(var1).map_err(|e| {
        PolarsError::ComputeError(format!("Invalid regular expression '{}': {}", var1, e).into())
    })?;

    // Build a boolean mask: true when the string matches the regex, false otherwise.
    // Nulls -> treated as false (no match).
    let matches: Vec<bool> = ca.into_iter().map(|opt| opt.map_or(false, |v| re.is_match(v))).collect();
    let mask = BooleanChunked::new_from_slice(&format!("{}_mask", var0), &matches);

    // Apply the mask to the DataFrame and return the filtered result
    df0.filter(&mask)
}

