/// Simple in-memory table: headers and rows (each row is Vec<String>).
#[derive(Debug)]
pub struct DataTable {
    pub headers: Vec<String>,
    pub rows: Vec<Vec<String>>,
}

impl DataTable {
    /// Create a new DataTable given headers and rows.
    pub fn new(headers: Vec<String>, rows: Vec<Vec<String>>) -> Self {
        DataTable { headers, rows }
    }
}

/// Map each unique category in column `col0` of `df0` to an integer code and replace
/// the column values with the code (as string representation).
///
/// Returns a HashMap mapping original category -> code.
///
/// Example:
///   let mut dt = DataTable::new(vec!["col0".into(), "col1".into()], vec![vec!["a".into(), "x".into()], vec!["b".into(), "y".into()], vec!["a".into(), "z".into()]]);
///   let mapping = map_categories_to_codes(&mut dt, "col0")?;
///   // dt.rows[0][0] == "0", dt.rows[1][0] == "1", dt.rows[2][0] == "0"
pub fn map_categories_to_codes(
    df0: &mut DataTable,
    col0: &str,
) -> Result<HashMap<String, usize>, String> {
    // Find index of target column
    let col_idx = df0
        .headers
        .iter()
        .position(|h| h == col0)
        .ok_or_else(|| format!("Column '{}' not found in headers", col0))?;

    let mut mapping: HashMap<String, usize> = HashMap::new();
    let mut next_code: usize = 0;

    for row in df0.rows.iter_mut() {
        if col_idx >= row.len() {
            return Err(format!(
                "Row has fewer columns ({}) than header index {}",
                row.len(),
                col_idx
            ));
        }

        let cat = row[col_idx].clone();
        let code = if let Some(&existing) = mapping.get(&cat) {
            existing
        } else {
            let assigned = next_code;
            mapping.insert(cat.clone(), assigned);
            next_code += 1;
            assigned
        };

        // Replace original value with code as string
        row[col_idx] = code.to_string();
    }

    Ok(mapping)
}

// Example usage
fn main() -> Result<(), String> {
    let headers = vec!["col0".to_string(), "col1".to_string()];
    let rows = vec![
        vec!["apple".to_string(), "red".to_string()],
        vec!["banana".to_string(), "yellow".to_string()],
        vec!["apple".to_string(), "green".to_string()],
        vec!["cherry".to_string(), "red".to_string()],
    ];

    let mut df = DataTable::new(headers, rows);
    let map = map_categories_to_codes(&mut df, "col0")?;

    println!("Mapping: {:?}", map);
    println!("Transformed table: {:?}", df);

    Ok(())
}
