///         "c" => &[4, 5, 6],
///         "b" => &[7, 8, 9]
///     )?;
///
///     let sorted_df = reorder_columns_alphabetically(df)?;
///     println!("{:?}", sorted_df);
///     Ok(())
/// }
/// ```
pub fn reorder_columns_alphabetically<T: DataFrameOrLazyFrame>(
    df: T
) -> Result<DataFrame, Box<dyn std::error::Error>>
where
    T::Output: DataFrameOrLazyFrame,
{
    // Get column names and sort them alphabetically
    let columns = df.column_names()?;
    let mut sorted_columns: Vec<_> = columns.iter().collect();
    sorted_columns.sort();

    // Reorder the DataFrame/LazyFrame
    if let Some(lazy_df) = df.as_lazy() {
        // For LazyFrame, we can use select with the sorted columns
        let sorted_lazy_df = lazy_df.select(sorted_columns)?;
        Ok(sorted_lazy_df.collect()?)
    } else {
        // For DataFrame, we need to manually reorder
        let mut new_df = DataFrame::default();
        let mut column_map = HashMap::new();

        // Create a mapping from old column names to their new positions
        for (new_pos, old_name) in sorted_columns.iter().enumerate() {
            if let Some(old_pos) = df.column(old_name)?.index() {
                column_map.insert(old_pos, new_pos);
            }
        }

        // Reorder the columns
        let mut new_columns = Vec::with_capacity(df.column_count());
        for old_pos in 0..df.column_count() {
            if let Some(new_pos) = column_map.get(&old_pos) {
                new_columns.push(df.column(old_pos)?);
            }
        }

        // Create new DataFrame with sorted columns
        new_df = DataFrame::new(
            sorted_columns.iter().map(|s| s.as_str()).collect(),
            new_columns,
        )?;

        Ok(new_df)
    }
}
