use polars::prelude::*;

/// Sort `df0` by multiple columns.
/// 
/// `keys` is a slice of (column_name, ascending). The order in `keys` is the
/// primary-to-secondary sort order (keys[0] is the primary sort key).
///
/// Returns a new DataFrame with rows ordered according to the specified keys.
pub fn sort_df_by_cols(df0: &DataFrame, keys: &[(&str, bool)]) -> PolarsResult<DataFrame> {
    // Build expressions for the columns to sort by.
    let exprs: Vec<Expr> = keys.iter().map(|(name, _)| col(name)).collect();
    // Polars expects a `descending` boolean per column, so invert ascending.
    let descending: Vec<bool> = keys.iter().map(|(_, ascending)| !*ascending).collect();

    // Convert to a lazy frame, sort by expressions, then collect back to a DataFrame.
    df0.lazy()
        .sort_by_exprs(&exprs, &descending)
        .collect()
