use polars::prelude::*;
use std::error::Error;

/// Performs z-score normalization on each numeric column of a DataFrame.
///
/// Z-score normalization transforms each column so that it has:
/// - Mean = 0
/// - Standard deviation = 1
///
/// # Arguments
/// * `df` - Input DataFrame containing numeric columns to normalize
///
/// # Returns
/// Result containing the normalized DataFrame or an error
