///     "B" => &[10.0, 20.0, 30.0, 40.0]
/// ];
/// let normalized = z_score_normalize(df).unwrap();
/// ```
pub fn z_score_normalize(df: DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Create a new DataFrame to store results
    let mut normalized_df = df.clone();

    // Iterate through each column
    for col_name in df.get_column_names() {
        // Get the column as a Series
        let col = df.column(col_name)?;

        // Check if the column is numeric
        if let Ok(numeric_col) = col.f64() {
            // Calculate mean and standard deviation
            let mean = numeric_col.mean().unwrap_or(0.0);
            let stddev = numeric_col.std().unwrap_or(1.0);

            // Avoid division by zero
            if stddev == 0.0 {
                // If stddev is 0, set all values to 0 (or you could leave them unchanged)
                let zero_series = Series::new(col_name, &vec![0.0; numeric_col.len()]);
                normalized_df = normalized_df.with_column(zero_series, None)?;
                continue;
            }

            // Perform z-score normalization: (x - mean) / stddev
            let normalized_values: Vec<f64> = numeric_col
                .into_iter()
                .map(|x| (x.unwrap_or(0.0) - mean) / stddev)
                .collect();

            // Create new series with normalized values
            let normalized_series = Series::new(col_name, &normalized_values);
            normalized_df = normalized_df.with_column(normalized_series, None)?;
        }
    }

    Ok(normalized_df)
}

