Code:

```rust
use polars::prelude::*;

/// Z-score normalize each numeric column of `df`.
/// Numeric columns are cast to Float64, normalized and returned as Float64 columns.
/// Non-numeric columns are left unchanged.
/// Returns a new DataFrame.
pub fn zscore_normalize(df: &DataFrame) -> PolarsResult<DataFrame> {
    let mut out_cols: Vec<Series> = Vec::with_capacity(df.width());

    for s in df.get_columns() {
        // Try to cast to Float64; if cast fails (non-numeric), keep original column.
        let s_f64 = match s.cast(&DataType::Float64) {
            Ok(s2) => s2,
            Err(_) => {
                out_cols.push(s.clone());
                continue;
            }
        };

        // Get a reference to the Float64Chunked to iterate values (Option<f64> for nulls).
        let ca = s_f64.f64().expect("cast to Float64 gave non-f64 series");

        // Welford's online algorithm to compute mean and variance (ignoring nulls).
        let mut count: usize = 0;
        let mut mean: f64 = 0.0;
        let mut m2: f64 = 0.0;

        for opt in ca.into_iter() {
            if let Some(v) = opt {
                count += 1;
                let delta = v - mean;
                mean += delta / (count as f64);
                let delta2 = v - mean;
                m2 += delta * delta2;
            }
        }

        let variance = if count > 1 { m2 / (count as f64) } else { 0.0 };
        let std = variance.sqrt();

        // Build normalized values, preserving nulls. For std == 0 set normalized to 0.0.
        let mut normalized: Vec<Option<f64>> = Vec::with_capacity(ca.len());
        for opt in ca.into_iter() {
            match opt {
                Some(v) => {
                    if std == 0.0 {
                        normalized.push(Some(0.0));
                    } else {
                        normalized.push(Some((v - mean) / std));
                    }
                }
                None => normalized.push(None),
            }
        }

        let new_series = Series::new(s.name(), normalized);
        out_cols.push(new_series);
    }

    DataFrame::new(out_cols)
}

