pub fn zscore_normalize(df: &DataFrame) -> PolarsResult<DataFrame> {
    // Get column names and their data types
    let schema = df.schema();

    // Build a list of expressions for each column
    let mut expressions: Vec<Expr> = Vec::with_capacity(schema.len());

    for (name, dtype) in schema.iter() {
        // Check if the column is numeric (float or integer types)
        if dtype.is_float() || dtype.is_integer() {
            // Create z-score normalization expression:
            // (column - mean) / std
            let expr = col(name)
                .cast(DataType::Float64)  // Ensure float64 for computation
                .map(
                    |s| {
                        let series = s.f64()?;
                        let mean = series.mean().unwrap_or(0.0);
                        let std = series.std(1).unwrap_or(1.0);  // ddof=1 for sample std

                        // Handle edge case where std is 0 (constant column)
                        let result = if std == 0.0 {
                            // Return zeros for constant columns
                            Series::new(name, vec![0.0_f64; series.len()])
                        } else {
                            let normalized: Vec<f64> = series
                                .into_iter()
                                .map(|v| (v - mean) / std)
                                .collect();
                            Series::new(name, normalized)
                        };
                        Ok(result)
                    },
                    GetOutput::from_type(DataType::Float64),
                )
                .alias(name);

