                    .divide(&Series::new(col_name, vec![std_dev; col.len()]))?
            } else {
                // Handle zero variance case: set to 0
                Series::new(col_name, vec![0.0; col.len()])
            };

            normalized_cols.push(normalized);
        } else {
            // Keep non-numeric columns as-is
            normalized_cols.push(col.clone());
        }
    }

    DataFrame::new(normalized_cols)
}

