Function code:

```rust
use polars::prelude::*;

/// Replace every occurrence of `target` in column `column` of DataFrame `df` with `replacement`.
/// Returns an updated DataFrame or a Polars error if the column does not exist or is not Utf8 (string).
///
/// - df: input DataFrame (consumed and returned updated)
/// - target: value to replace (var0)
/// - column: column name to operate on (var1)
/// - replacement: new value to substitute (var2)
pub fn replace_in_column(
    df: DataFrame,
    target: &str,
    column: &str,
    replacement: &str,
) -> PolarsResult<DataFrame> {
    // Ensure column exists
    if !df.get_column_names().iter().any(|c| c == column) {
        return Err(PolarsError::NotFound(
            format!("Column '{}' not found in DataFrame", column).into(),
        ));
    }

    // Get the column and ensure it's Utf8 (string) type
    let series = df.column(column)?;
    if series.dtype() != &DataType::Utf8 {
        return Err(PolarsError::Other(
            format!("Column '{}' is not of Utf8 (string) type", column).into(),
        ));
    }

    // Map values: if equal to target, replace; preserve nulls
    let utf8 = series.utf8()?;
    let iter = utf8.into_iter().map(|opt| {
        opt.map(|v| if v == target { replacement } else { v })
    });

    // Build a new Utf8Chunked series from the mapped iterator
    let new_chunked = Utf8Chunked::new_from_opt_iter(column, iter);
    let new_series = new_chunked.into_series();

    // Return a new DataFrame with the replaced column
    df.with_column(new_series)
}
