use polars::prelude::*;

/// Return indices of rows that contain at least one NaN (in any Float32/Float64 column).
///
/// Behavior:
/// - Scans only floating-point columns (Float32 and Float64) for IEEE NaN.
/// - Does not treat nulls (missing values) as NaN. If you want to count nulls too,
///   adjust the logic to check is_null() as well.
///
/// Example:
/// let s1 = Series::new("a", &[1.0f64, f64::NAN, 3.0]);
/// let s2 = Series::new("b", &[Some(1.0f32), None, Some(f32::NAN)]);
/// let df = DataFrame::new(vec![s1, s2])?;
/// let idx = rows_with_nan(&df); // yields vec![1, 2]
pub fn rows_with_nan(df0: &DataFrame) -> Vec<usize> {
    let height = df0.height();
    if height == 0 {
        return Vec::new();
    }

    // boolean mask per-row: true if we've found a NaN in that row
    let mut mask = vec![false; height];

    for s in df0.get_columns() {
        match s.dtype() {
            DataType::Float64 => {
                if let Some(ca) = s.f64() {
                    // iterate Option<f64> for each row
                    for (i, opt_v) in ca.into_iter().enumerate() {
                        if let Some(v) = opt_v {
                            if v.is_nan() {
                                mask[i] = true;
                            }
                        }
                    }
                }
            }
            DataType::Float32 => {
                if let Some(ca) = s.f32() {
                    for (i, opt_v) in ca.into_iter().enumerate() {
                        if let Some(v) = opt_v {
                            if v.is_nan() {
                                mask[i] = true;
                            }
                        }
                    }
                }
            }
            _ => {
                // non-floating columns can't contain IEEE NaN; skip
            }
        }
    }

    // collect indices where mask is true
    mask.into_iter()
        .enumerate()
        .filter_map(|(i, b)| if b { Some(i) } else { None })
        .collect()
}

