/// * `columns_to_delete` - A slice of column indices to be deleted.
///
/// # Returns
///
/// * `Result<(), MatrixError>` - An empty result if successful, or an error if something goes wrong.
fn remove_columns(mat0: &mut Matrix<f64>, columns_to_delete: &[usize]) -> Result<(), MatrixError> {
    // Sort and deduplicate the columns to delete to avoid issues with repeated indices
    let mut sorted_unique_columns: Vec<usize> = columns_to_delete.to_vec();
