use sorted_map::SortedMap;
use std::collections::BTreeMap;

fn reorder_map_by_max_value<K, V>(input: &SortedMap<K, Vec<V>>) -> Vec<(K, Vec<V>)>
where
    K: Ord + Clone,
    V: Ord + Copy,
{
    let mut entries: Vec<(K, Vec<V>)> = input.iter().map(|(k, v)| (k.clone(), v.clone())).collect();

    entries.sort_unstable_by(|(_, seq1), (_, seq2)| {
        let max1 = seq1.iter().copied().max().unwrap_or(std::cmp::Ordering::Less);
        let max2 = seq2.iter().copied().max().unwrap_or(std::cmp::Ordering::Less);
        max2.cmp(&max1) // Sort in descending order
    });

    entries
}

fn main() {
