    map.insert("a", vec![1, 3, 5]);
    map.insert("b", vec![2, 4]);
    map.insert("c", vec![8, 1]);

    let sorted_entries = reorder_map_by_max_value(&map);

    for (key, values) in sorted_entries {
        println!("{}: {:?}", key, values);
    }
}
