Below is a self-contained Rust function that, given a polars DataFrame and the name of a categorical (utf8) column, replaces each category with a unique integer index (0-based). It returns the mapping from category string -> integer. This implementation is efficient (single pass over the column, pre-reserves memory) and uses the polars crate for DataFrame handling and a hash map for fast lookup.

Notes
- The function preserves nulls (they remain null in the integer column).
- Indices are assigned in first-seen order, starting at 0.
- You can adapt to 1-based indexing by starting next_idx at 1.
- Add polars to your Cargo.toml (use a 2024+ release if you prefer a newer polars).

Code

use polars::prelude::*;
use hashbrown::HashMap;

/// Replace the categorical strings in column `col` of `df` with integer indices (0-based).
/// Returns a HashMap mapping each category -> assigned index.
///
/// Example:
///   let mut df = df!("col0" => &["a", "b", "a", "c"])?; 
///   let mapping = encode_categories_to_indices(&mut df, "col0")?;
///   // df["col0"] now contains [0,1,0,2]
pub fn encode_categories_to_indices(
    df: &mut DataFrame,
    col: &str,
) -> PolarsResult<HashMap<String, i32>> {
    // Get the column as a Utf8Chunked; error if column missing or wrong dtype.
    let s = df.column(col)?;
    let ca = s.utf8()?;

    // Prepare map and output buffer
    let mut map: HashMap<String, i32> = HashMap::with_capacity(ca.len());
    let mut codes: Vec<Option<i32>> = Vec::with_capacity(ca.len());
    let mut next_idx: i32 = 0;

    // Single pass: assign index on first encounter, reuse on repeats
    for value_opt in ca.into_iter() {
        match value_opt {
            Some(v) => {
                if let Some(&idx) = map.get(v) {
                    codes.push(Some(idx));
                } else {
                    let idx = next_idx;
                    next_idx += 1;
                    map.insert(v.to_string(), idx);
                    codes.push(Some(idx));
                }
            }
            None => {
                // Preserve nulls
                codes.push(None);
            }
        }
    }

    // Build a new Int32Chunked from the optional integer codes and replace the column
    let new_ca = Int32Chunked::new_from_opt_slice(col, &codes);
    let new_series = new_ca.into_series();
    df.replace(col, new_series)?;

    Ok(map)
}

