/// Add a "max_value" column to `df0` where each row's max_value is the maximum
/// across the columns listed in `lst0`.
///
/// - `df0` is modified in-place (a new column is appended).
/// - `lst0` is a slice of column names to consider for the row-wise max.
/// - Returns an error if any listed column is missing or contains non-numeric data.
pub fn add_max_value_column(df0: &mut DataFrame, lst0: &[&str]) -> PolarsResult<()> {
    // Ensure columns exist
    for &col in lst0 {
        if df0.find_idx_by_name(col).is_none() {
            return Err(PolarsError::NotFound(
                format!("Column '{}' not found in DataFrame", col).into(),
            ));
        }
    }

    let height = df0.height();
    // Pre-allocate vector of Option<f64> (None -> Null)
    let mut max_vals: Vec<Option<f64>> = vec![None; height];

    // Helper to extract numeric value as f64 from AnyValue,
    // returns Err if value is non-numeric (except Null).
    fn anyvalue_to_f64(av: AnyValue) -> PolarsResult<Option<f64>> {
        use AnyValue::*;
        Ok(match av {
            Null => None,
            Float64(v) => Some(v),
            Float32(v) => Some(v as f64),
            Int64(v) => Some(v as f64),
            Int32(v) => Some(v as f64),
            Int16(v) => Some(v as f64),
            Int8(v) => Some(v as f64),
            UInt64(v) => Some(v as f64),
            UInt32(v) => Some(v as f64),
            UInt16(v) => Some(v as f64),
            UInt8(v) => Some(v as f64),
            Boolean(b) => Some(if b { 1.0 } else { 0.0 }),
            // For everything else (Utf8, List, Struct, etc.) treat as error:
            other => {
                return Err(PolarsError::ComputeError(
                    format!("Unsupported (non-numeric) value type encountered: {:?}", other).into(),
                ))
            }
        })
    }

    for &colname in lst0 {
        let series = df0.column(colname)?;
        // iterate rows
        for row_idx in 0..height {
            let av = series.get(row_idx);
            let maybe_val = anyvalue_to_f64(av)?;
            if let Some(v) = maybe_val {
                match max_vals[row_idx] {
                    Some(prev) => {
                        if v > prev {
                            max_vals[row_idx] = Some(v);
                        }
                    }
                    None => max_vals[row_idx] = Some(v),
                }
            }
            // if maybe_val is None (NULL), leave existing max as-is
        }
    }

    // Build a Float64 Series from Vec<Option<f64>>
    let max_series = Series::new("max_value", max_vals);
    df0.with_column(max_series)?;
    Ok(())
}

fn main() -> PolarsResult<()> {
