pub fn solve_coupled_equations<F>(
    f: F,
    x0: [f64; 2],
    max_iter: usize,
    tol: f64,
) -> (Option<[f64; 2]>, bool)
where
    F: Fn([f64; 2]) -> [f64; 2] + Copy,
{
