    let solver = NewtonSolver::new(system, x0, max_iter, tol);

    // Solve the system.
    let result = solver.solve();

    match result {
        Ok(solution) => (Some(solution.try_into().unwrap()), true),
        Err(_) => (None, false),
    }
}

