use polars::prelude::*;

/// Extract row identifiers from `input_table`'s index (or a canonical index-like column).
/// Returns a Vec<String> with the row identifiers in order.
///
/// Behavior:
/// - If the DataFrame has a column named one of: "index", "_index", "row_id", "id",
///   that column's values are returned (casted to strings).
/// - Otherwise, returns implicit integer row labels "0", "1", ..., as strings.
///
/// Errors propagate as PolarsResult errors (e.g., if casts fail).
pub fn extract_row_identifiers(input_table: &DataFrame) -> PolarsResult<Vec<String>> {
    // Common index column names to try
    let candidates = ["index", "_index", "row_id", "id"];

    // Look for a candidate column
    for &name in &candidates {
        if input_table.get_column_names().iter().any(|n| n == name) {
            let col = input_table.column(name)?;
            // Cast to Utf8 (string) and collect values, using empty string for nulls.
            let utf8 = col.cast(&DataType::Utf8)?.utf8()?;
            let ids: Vec<String> = utf8
                .into_iter()
                .map(|opt| opt.unwrap_or("").to_string())
                .collect();
            return Ok(ids);
        }
    }

    // No explicit index column found: return implicit integer row labels as strings.
    let nrows = input_table.height();
    Ok((0..nrows).map(|i| i.to_string()).collect())
}

