use itertools::izip;

/// Replace each boolean in `mask` with the element at the same index from `a` when true,
/// or from `b` when false.
/// Returns `None` if the three slices have different lengths.
pub fn choose_by_mask<T: Clone>(mask: &[bool], a: &[T], b: &[T]) -> Option<Vec<T>> {
    if !(mask.len() == a.len() && a.len() == b.len()) {
        return None;
    }
    Some(izip!(mask, a, b).map(|(m, x, y)| if m { x.clone() } else { y.clone() }).collect())
}

